RollbackClaimEnvironmentFn = Callable[..., Any]
FinalizeClaimEnvironmentFn = Callable[..., Any]
# Honest conversational root-close short-circuit. Invoked when a verified
# root-equivalent certificate exists, or when a newly accepted route-local
# helper (for example exact negative evidence) may make the verified helper set
# sufficient for the canonical root. The callback runs ONE conversational
# root-close turn: the model supplies the bridging proof and Lean verifies it --
# the harness never injects a closing tactic. Called with
# keyword args (root_statement, certificate_names, helper_blocks, pass_index,
# after_helper) and returns the verified root proof text, or None on failure.
ProveRootCloseFn = Callable[..., Awaitable[Optional[str]]]


def _falsification_event_verdict(
    prefix: str,
    report: FalsificationReport,
    *,
    promoted: bool,
) -> str:
    """Render the report's actual outcome without weakening the trust boundary."""

    if promoted:
        return f"{prefix}_refuted_by_audited_lean_certificate"
    if report.evidence_outcome is FalsificationOutcome.REFUTED:
        return f"{prefix}_falsification_counterexample_candidate_unpromoted"
    return f"{prefix}_falsification_{report.outcome.value}"


def _prove_mode_falsification_quantum_verdict(
    prefix: str,
    report: FalsificationReport,
    *,
    promoted: bool,
    skip_reason: str,
) -> str:
    """Describe whether the root quantum ran or why it was skipped."""

    if promoted and prefix == "root":
        return "root_disproved_by_audited_lean_certificate"
    skipped_suffixes = {
        "resume": "falsification_resume_no_op",
        "disabled": "falsification_disabled",
        "dossier_missing": "falsification_dossier_missing",
        "foreground_veto_spent": "falsification_veto_already_spent",
        "infrastructure_backoff": "falsification_infrastructure_backoff",
    }
    if skip_reason:
        suffix = skipped_suffixes.get(skip_reason, "falsification_unsupported")
        return f"{prefix}_{suffix}"
    return _falsification_event_verdict(prefix, report, promoted=promoted)


def _callable_accepts_keyword(func: Any, keyword: str) -> bool:
    """Return whether ``func`` advertises a keyword without invoking it.

    Capability detection must happen before an awaited Lean operation. Catching
    ``TypeError`` around that operation cannot distinguish an unsupported
    keyword from a backend/runtime defect raised after work has started.
    """

    try:
        parameters = inspect.signature(func).parameters
    except (TypeError, ValueError):
        return False
    if any(
        parameter.kind is inspect.Parameter.VAR_KEYWORD
        for parameter in parameters.values()
    ):
        return True
    parameter = parameters.get(str(keyword or ""))
    return parameter is not None and parameter.kind in {
        inspect.Parameter.POSITIONAL_OR_KEYWORD,
        inspect.Parameter.KEYWORD_ONLY,
    }


def _callable_is_declared_async(callback: Any) -> bool:
    """Return whether invoking ``callback`` necessarily starts async work."""

    if inspect.iscoroutinefunction(callback):
        return True
    call = getattr(callback, "__call__", None)
    return bool(call is not None and inspect.iscoroutinefunction(call))


def _close_unstarted_awaitable(awaitable: Any) -> None:
    """Close an awaitable that was rejected before it acquired authority."""

    close = getattr(awaitable, "close", None)
    if callable(close):
        close()


class _TheoryPromotionRollbackAuthority:
    """One-generation authority for restoring a staged dossier transaction.

    Revocation flips the generation before restoring the snapshot.  Reentrant
    or late cleanup therefore cannot overwrite work published after the
    transaction was fenced.  External theory rollback is admitted separately
    only when it is synchronous, so no external mutation tail can outlive this
    generation.
    """

    __slots__ = ("_active", "_generation", "_restore_snapshot")

    def __init__(self, restore_snapshot: Callable[[], None]) -> None:
        self._active = True
        self._generation = 0
        self._restore_snapshot = restore_snapshot

    @property
    def active(self) -> bool:
        return self._active

    @property
    def generation(self) -> int:
        return self._generation

    def revoke_and_restore(self) -> None:
        if not self._active:
            return
        self._active = False
        self._generation += 1
        self._restore_snapshot()

    def finalize(self) -> None:
        self._active = False
        self._generation += 1


async def _finish_cleanup_despite_cancellation(
    awaitable: Awaitable[Any],
    *,
    timeout_s: float = 15.0,
    cancel_grace_s: float = 0.25,
    revoke_authority: Optional[Callable[[], Any]] = None,
) -> Any:
    """Bound owned cleanup without granting a stuck tail parent authority.

    Cancellation-resistant cleanup must never turn a recoverable Mini action
    into a process kill or an infinite wait.  Callers whose awaitable can
    publish mutable state install a synchronous, idempotent revoker *before*
    starting the task.  Once the local grace expires the revoker fences that
    publication authority and the unauthorized tail is observed only to
    consume its eventual result.
    """

    timeout = max(0.001, float(timeout_s or 0.001))
    cancel_grace = max(0.0, float(cancel_grace_s or 0.0))
    cleanup_task = asyncio.ensure_future(awaitable)
    cancellation: Optional[asyncio.CancelledError] = None
    cleanup_timed_out = False
    deadline = asyncio.get_running_loop().time() + timeout
    while not cleanup_task.done():
        remaining = deadline - asyncio.get_running_loop().time()
        if remaining <= 0.0:
            cleanup_timed_out = True
            cleanup_task.cancel()
            grace_deadline = asyncio.get_running_loop().time() + cancel_grace
            while not cleanup_task.done():
                grace_remaining = grace_deadline - asyncio.get_running_loop().time()
                if grace_remaining <= 0.0:
                    break
                try:
                    await asyncio.wait({cleanup_task}, timeout=grace_remaining)
                except asyncio.CancelledError as exc:
                    cancellation = cancellation or exc
                    continue
            break
        try:
            await asyncio.wait_for(asyncio.shield(cleanup_task), remaining)
        except asyncio.TimeoutError:
            continue
        except asyncio.CancelledError as exc:
            cancellation = cancellation or exc
            continue

    if not cleanup_task.done():
        revoke_error: Optional[BaseException] = None
        if callable(revoke_authority):
            try:
                revoke_result = revoke_authority()
                if inspect.isawaitable(revoke_result):
                    close = getattr(revoke_result, "close", None)
                    if callable(close):
                        close()
                    raise TypeError("cleanup authority revoker must be synchronous")
            except BaseException as exc:
                revoke_error = exc

        def consume_detached_result(task: asyncio.Future[Any]) -> None:
            try:
                task.result()
            except BaseException:
                pass

        cleanup_task.add_done_callback(consume_detached_result)
        timeout_error = TimeoutError("owned cleanup exceeded its timeout")
        if revoke_error is not None:
            timeout_error.add_note(
                "cleanup authority revocation failed: "
                f"{type(revoke_error).__name__}: {revoke_error}"
            )
        if cancellation is not None:
            cancellation.add_note(str(timeout_error))
            if revoke_error is not None:
                cancellation.add_note(
                    "cleanup authority revocation failed: "
                    f"{type(revoke_error).__name__}: {revoke_error}"
                )
            raise cancellation
        raise timeout_error

    try:
        result = cleanup_task.result()
    except asyncio.CancelledError:
        if cancellation is not None:
            raise cancellation
        if cleanup_timed_out:
            raise TimeoutError("owned cleanup exceeded its timeout")
        raise
    except BaseException as cleanup_error:
        if cancellation is not None:
            cleanup_error.add_note(
                "caller cancellation was deferred until owned cleanup completed"
            )
        raise
    if cancellation is not None:
        if cleanup_timed_out:
            cancellation.add_note(
                "owned cleanup exceeded its timeout and completed before "
                "cancellation was delivered"
            )
        raise cancellation
    if cleanup_timed_out:
        raise TimeoutError("owned cleanup exceeded its timeout")
    return result


def _theory_promotion_rollback_error(
    failures: Sequence[BaseException],
) -> RuntimeError:
    first = failures[0] if failures else None
    detail = f": {type(first).__name__}: {first}" if first is not None else ""
    error = RuntimeError(
        f"theory promotion rollback failed after all cleanup phases ran{detail}"
    )
    for failure in failures:
        error.add_note(f"{type(failure).__name__}: {failure}")
    return error


# Production claim capacity across durable planner tranches. One tranche is
# planner_claim_tranche_size (6). 20 leaves room for a later root_assembly
# after several helper-only slices instead of filling a 4- or 6-claim cap
# and spending the clock proving a ladder with no terminal route.
PRODUCTION_MINI_RECURSIVE_MAX_CLAIMS = 20


@dataclass(frozen=True)
class MiniRecursiveConfig:
    passes: int = 1
    # 0 runs the complete recursive frontier in one invocation. A positive
    # value yields a durable partial result after this many committed passes,
    # allowing MiniSession to interleave formal-state search, retrieval, and
    # assembly before resuming the exact recursive driver state.
    pass_quantum: int = 0
    # Compatibility default for raw MiniRecursiveConfig() in tests. Production
    # factories and the CLI use PRODUCTION_MINI_RECURSIVE_MAX_CLAIMS so one
    # helper tranche cannot fill the campaign and force helper-only proving.
    max_claims: int = 4
    max_variants_per_claim: int = 2
    turns_per_claim: int = 3
    # Zero leaves recursive claims unbounded by default.  A positive explicit
    # value is a recoverable action-scheduling boundary shared by prove/refine
    # and preserved across nested-session resume; it must not terminate the
    # complete worker.
    recursive_child_max_elapsed_s: float = 0.0
    # Parent sessions may allow very large tool loops for root exploration.
    # A single recursive claim must not inherit that multiplicatively.
    recursive_child_max_tool_calls_per_turn: int = 10
    tactic_timeout_s: float = 20.0
    tactic_max_candidates: int = 48
    planner_temperature: float = 0.1
    # After a degenerate (empty/unparseable) planning response, the NEXT
    # planner call may escalate to a stronger model (the driver's
    # ``planner_escalation_client``). Bounded per driver invocation so a
    # degenerate strong model cannot burn unbounded premium spend.
    planner_escalation_max_calls: int = 3
    # One premium logical call previously inherited infinite request/operation
    # timeouts and the transport's multi-attempt retry policy, allowing several
    # failed calls to run for hours with unbounded cost. Bound both concrete
    # dispatch count and elapsed time;
    # the premium lane remains tighter than the ordinary composite pass.
    planner_escalation_provider_max_attempts: int = 2
    planner_escalation_request_timeout_s: float = 180.0
    planner_escalation_operation_timeout_s: float = 365.0
    # Planner calls are scheduling transactions even under the role-level
    # soft deadline policy. Numeric bounds remain available for deployments
    # that explicitly opt in, but production max-reasoning plans must not be
    # discarded merely because the provider has not returned within a fixed
    # wall interval.
    planner_deadlines_enabled: bool = False
    planner_provider_max_attempts: int = 2
    planner_request_timeout_s: float = 600.0
    planner_operation_timeout_s: float = 600.0
    planner_composite_timeout_s: float = 600.0
    planner_fallback_reserve_s: float = 120.0
    # MP-FU-001: reasoning-enabled deliberation phase feeding the
    # full-effort planner execution call. The DATACLASS default stays
    # False so raw test configs stay inert; PRODUCTION construction
    # (mini_prover/factory) enables it by default (operator decision
    # 2026-07-31), disable via --no-mini-planner-deliberation.
    planner_deliberation_enabled: bool = False
    planner_deliberation_max_calls: int = 3
    # Visible JSON floor for planner request kinds. Hidden-reasoning models
    # receive the provider envelope (GPT 32_768 / DeepSeek 96_000), not this
    # integer as a total cap. Kept for compatibility and telemetry labels.
    planner_max_output_tokens: int = 16384
    planner_deliberation_max_output_tokens: int = 32768
    # Legacy total-cap bump for max/xhigh JSON planning. Production dispatch
    # now uses MiniRequestEnvelopePolicy; this field remains for older tests
    # and operator-facing docs.
    planner_reasoning_json_output_tokens: int = 32768
    planner_claim_tranche_size: int = 6
    planner_visibility_claim_tranche_size: int = 4
    # Production planner responses must carry a machine disposition on every
    # claim.  The dataclass default remains compatibility-safe for embedded
    # callers that construct claims programmatically; production factories
    # enable this and parsed claims carry an immutable protocol version.
    planner_sanity_contract_required: bool = False
    # Planner lifecycle memory is a semantic inventory, not an append-only log
    # replay.  Keep whole evidence units and receipt omitted history.
    planner_context_max_chars: int = 98304
    # Compatibility-shaped integer flag: 0 disables; any positive value keeps
    # extending the pass frontier while each exhausted pass banks a fresh
    # verified helper. It is intentionally not a fixed continuation count.
    progress_continuation_passes: int = 0
    # A failed child route may be revisited only when it leaves behind a new
    # durable formal helper or a new bounded diagnostic-progress signature.
    # This is a retry ceiling per structural claim identity, not a blind fixed
    # prove/refine schedule: repeated signatures terminate immediately.
    claim_progress_retry_limit: int = 2
    mini_phase_temperatures: Any = None
    sample_temperature: Optional[float] = None
    # Max conversational root-close turns per recursive run (honest root
    # bridge from verified helpers). 0 disables the short-circuit.
    llm_root_close_max_attempts: int = 2
    # Route-incomplete post-helper root synthesis is a probe, not a nested
    # proof campaign. The production callback combines this strict total wall
    # with a one-provider-dispatch lane.
    llm_root_speculative_max_elapsed_s: float = 180.0
    falsification_enabled: bool = True
    falsification_max_checks: int = 32
    falsification_operation_timeout_s: float = DEFAULT_FALSIFICATION_OPERATION_TIMEOUT_S
    falsification_engine_timeout_s: float = DEFAULT_FALSIFICATION_ENGINE_TIMEOUT_S

    def __post_init__(self) -> None:
        try:
            speculative_wall_s = float(self.llm_root_speculative_max_elapsed_s)
        except (TypeError, ValueError) as exc:
            raise ValueError(
                "llm_root_speculative_max_elapsed_s must be finite and > 0"
            ) from exc
        if not math.isfinite(speculative_wall_s) or speculative_wall_s <= 0.0:
            raise ValueError(
                "llm_root_speculative_max_elapsed_s must be finite and > 0"
            )
        require_falsification_search_bound(
            self.falsification_max_checks,
            field="falsification_max_checks",
        )
        require_falsification_watchdog(
            self.falsification_operation_timeout_s,
            field="falsification_operation_timeout_s",
        )
        require_falsification_watchdog(
            self.falsification_engine_timeout_s,
            field="falsification_engine_timeout_s",
        )


