def _restore_mini_recursive_stats(
    stats: MiniRecursiveStats,
    raw_stats: Mapping[str, Any],
) -> None:
    """Restore stats while preserving route-close power across schema drift."""

    values = dict(raw_stats or {})
    for stat_name, stat_value in values.items():
        if hasattr(stats, stat_name):
            try:
                setattr(stats, stat_name, stat_value)
            except Exception:
                pass
    if "llm_root_speculative_assembly_attempts" not in values:
        # Legacy frames did not distinguish broad ordinary-helper synthesis
        # from route-authoritative assembly.  Treat their assembly subset as
        # speculative: ambiguity must not erase the authoritative reserve and
        # permanently starve a later decisive bridge after resume.
        stats.llm_root_speculative_assembly_attempts = min(
            max(0, int(stats.llm_root_close_attempts or 0)),
            max(0, int(stats.llm_root_assembly_attempts or 0)),
        )


def _reachable_provider_dispatch_attempts(
    configured_attempts: int,
    *,
    request_timeout_s: float,
    operation_timeout_s: float,
    composite_remaining_s: float,
) -> int:
    """Return an honest provider-attempt ceiling for the remaining window.

    A transport retry ceiling is meaningful only when every admitted attempt
    can receive its full request watchdog.  In particular, two attempts are
    not reachable when both the request and composite planner windows are 600
    seconds: the first request may consume the whole transaction.  Preserve
    the configured reasoning request and reduce only the advertised dispatch
    count instead of silently shortening the model's first reasoning window.
    """

    attempts = max(1, int(configured_attempts or 1))
    request_window = max(0.05, float(request_timeout_s or 0.05))
    available = max(
        0.05,
        min(
            float(operation_timeout_s or 0.05),
            float(composite_remaining_s or 0.05),
        ),
    )
    # The transport sleeps before a retry. Count an attempt as reachable only
    # when the operation can accommodate all preceding full request windows
    # plus conservative first-retry backoff/scheduler headroom.
    retry_headroom_s = 2.0
    reachable = 1
    while reachable < attempts:
        required = request_window * float(reachable + 1) + retry_headroom_s * float(
            reachable
        )
        if required > available:
            break
        reachable += 1
    return reachable


def _wall_clock_deadline(deadline_monotonic: Optional[float]) -> Optional[float]:
    """Translate a shared monotonic deadline at the provider-call boundary."""

    if deadline_monotonic is None:
        return None
    return time.time() + max(
        0.0,
        float(deadline_monotonic) - time.monotonic(),
    )


def _scoped_failure_reason_from_recursive_stats(stats: Any) -> str:
    """Return the scoped LLM blocker preserved in recursive stats, if any."""

    for count_attr, reason_attr in (
        ("child_scoped_failures", "last_child_failure_reason"),
        ("planner_scoped_failures", "last_planner_failure_reason"),
    ):
        try:
            count = int(getattr(stats, count_attr, 0) or 0)
        except Exception:
            count = 0
        reason = str(getattr(stats, reason_attr, "") or "").strip()
        if count > 0 and llm_failure_scope(reason) == "scoped":
            return reason
    return ""


def _recursive_helper_item_passes_quality_gate(
    item: Any,
    active_statement: str,
) -> bool:
    """Return whether a verified helper may be admitted from recursive work.

    Default-policy helpers are globally reusable side facts and may be salvaged
    from a child even when they are not the active target. ``render_policy``
    controls *reuse visibility*, not whether a freshly Lean-verified theorem
    proves its own exact statement. In particular, a conditional theorem can
    be unsafe as free-standing root context while still being a valid proof of
    a recursive claim whose contract is that same conditional theorem. Keep
    unknown policies fail-closed and require exact canonical identity for every
    non-default policy.
    """

    from .helper_quality import classify_auxiliary_statement_quality

    source = (
        str(item.get("source") or item.get("statement") or "").strip()
        if isinstance(item, Mapping)
        else str(getattr(item, "source", "") or "").strip()
    )
    statement = helper_decl_statement(source) if source else ""
    if not statement:
        statement = str(
            item.get("statement", "")
            if isinstance(item, Mapping)
            else getattr(item, "statement", "")
        ).strip()
    render_policy = str(
        (
            item.get("render_policy", "")
            if isinstance(item, Mapping)
            else getattr(item, "render_policy", "")
        )
        or ""
    ).strip()
    item_statement_key = canonical_dossier_statement_key(statement)
    active_statement_key = canonical_dossier_statement_key(active_statement)
    exact_active_statement = bool(
        str(statement or "").strip()
        and str(statement or "").strip() == str(active_statement or "").strip()
    )
    provenance_tags = {
        str(tag or "").strip()
        for tag in list(
            (
                item.get("provenance_tags", ())
                if isinstance(item, Mapping)
                else getattr(item, "provenance_tags", ())
            )
            or ()
        )
        if str(tag or "").strip()
    }
    exact_root_authority = bool(
        exact_active_statement
        and render_policy == "root_authoritative"
        and provenance_tags
        & {
            "root_authoritative_helper",
            "root_exact_certificate",
            "root_finalization_certificate",
        }
    )
    if (
        statement
        and not classify_auxiliary_statement_quality(
            statement
        ).auxiliary_target_admissible
        and not exact_root_authority
    ):
        return False
    if not render_policy:
        return True
    if not item_statement_key or item_statement_key != active_statement_key:
        return False
    return render_policy in {
        "advisory_requires_unproved_premise",
        "advisory_negative_evidence",
        "advisory_root_equivalent",
        "root_authoritative",
    }


@dataclass(frozen=True)
class MiniRecursiveResult:
    ok: bool
    proof: Optional[str]
    stats: MiniRecursiveStats
    plan_summaries: tuple[str, ...] = ()
    failure_reason: str = ""
    root_tactic_attempts: tuple[dict[str, Any], ...] = ()
    # Selects the provenance-correct finalization branch in
    # ``run_mini_recursive_attempt``. ``llm_root_close`` is the dedicated
    # conversational close; ``accepted_exact_root`` is a freshly Lean-accepted
    # recursive claim whose contract is the root itself.
    root_close_source: str = ""
    disproved: bool = False
    disproof_certificate: Optional[dict[str, Any]] = None
    # True only when the result was reconstructed from a durable terminal
    # driver receipt.  The session action uses this to undo the *new*
    # speculative pass reservation made solely to publish the already-paid
    # outcome after process restart.
    resumed_from_terminal_receipt: bool = False


def _mini_recursive_result_state_record(
    result: MiniRecursiveResult,
) -> dict[str, Any]:
    """Serialize a terminal recursive result without duplicating live stats."""

    return {
        "ok": bool(result.ok),
        "proof": result.proof,
        "failure_reason": str(result.failure_reason or ""),
        "root_tactic_attempts": [
            copy.deepcopy(item) for item in result.root_tactic_attempts
        ],
        "root_close_source": str(result.root_close_source or ""),
        "disproved": bool(result.disproved),
        "disproof_certificate": copy.deepcopy(result.disproof_certificate),
    }


def _mini_recursive_result_from_terminal_state_record(
    raw: Mapping[str, Any],
    *,
    stats: MiniRecursiveStats,
    plan_summaries: Sequence[str],
) -> MiniRecursiveResult:
    data = dict(raw or {})
    return MiniRecursiveResult(
        ok=bool(data.get("ok")),
        proof=str(data.get("proof") or "") or None,
        stats=stats,
        plan_summaries=tuple(str(item or "") for item in plan_summaries),
        failure_reason=str(data.get("failure_reason") or ""),
        root_tactic_attempts=tuple(
            copy.deepcopy(item)
            for item in list(data.get("root_tactic_attempts") or [])
            if isinstance(item, Mapping)
        ),
        root_close_source=str(data.get("root_close_source") or ""),
        disproved=bool(data.get("disproved")),
        disproof_certificate=copy.deepcopy(data.get("disproof_certificate")),
        resumed_from_terminal_receipt=True,
    )


@dataclass(frozen=True)
class ClaimProofResult:
    proof: Optional[str] = None
    invalid_reason: str = ""
    invalid_certificate: Optional[dict[str, Any]] = None
    giveup_cluster: str = ""
    giveup_match: str = ""
    terminal_failure_reason: str = ""
    terminal_failure_kind: str = ""
    child_llm_preamble: str = ""
    child_lean_preamble: str = ""
    theory_imported_bundle_ids: tuple[str, ...] = ()
    theory_snapshot: Any = None
    theory_context_hash: str = ""
    child_verified_helper_blocks: tuple[str, ...] = ()
    theory_promotion_commit: Any = None
    child_helper_merge_commit: Any = None
    required_child_helper_hashes: tuple[tuple[str, str], ...] = ()
    # Optional callback-reported evidence that a failed proof conversation
    # nevertheless advanced. The driver combines this with independently
    # observed verified-helper deltas and deduplicates ``progress_signature``
    # durably before granting another claim attempt.
    formal_progress: bool = False
    diagnostic_progress: bool = False
    progress_signature: str = ""
