@dataclass(frozen=True)
class SuspendedDependencyClaim:
    claim: MiniSubgoalClaim
    reasons: tuple[str, ...]
    pass_index: int
    verdict: str
    obligation_id: str = ""
    origin_plan_fingerprint: str = ""
    dependency_semantic_identities: tuple[tuple[str, str], ...] = ()


@dataclass(frozen=True)
class _ContractIdentityCoverage:
    service_available: bool = False
    root_elaborated: bool = False
    claim_elaborated: tuple[bool, ...] = ()
    # Exact executable propositions submitted for planner claims.  Planner
    # surfaces may intentionally omit root binders while their compiled first
    # variant closes over that context; repairs and evidence binding must use
    # the proposition Lean actually analyzed.
    claim_analysis_statements: tuple[str, ...] = ()
    support_elaborated: tuple[bool, ...] = ()
    support_structural_identities: tuple[str, ...] = ()
    support_proof_binder_structural_hashes: tuple[tuple[str, ...], ...] = ()
    support_conclusion_structural_hashes: tuple[str, ...] = ()
    # Index of the first active-target entry in the shared analyzer batch.
    # Consumers must READ this rather than re-deriving it from claim/support
    # counts: the rehydration path canonicalizes with no analysis statements
    # and then adjudicates with active targets, so a mirrored formula points
    # past the end of the batch and mints anchors that can never be satisfied.
    analysis_batch_start: int = -1
    analysis_elaborated: tuple[bool, ...] = ()
    analysis_structural_identities: tuple[str, ...] = ()
    # Each planner claim's Lean-certified same-batch equivalence anchors,
    # expressed as zero-based indices into the complete analyzer request
    # (root=0; claims follow; supports; then active targets).
    claim_defeq_indices: tuple[tuple[int, ...], ...] = ()
    claim_contract_defeq_indices: tuple[tuple[int, ...], ...] = ()
    claim_defeq_checked_indices: tuple[tuple[int, ...], ...] = ()
    claim_contract_defeq_checked_indices: tuple[tuple[int, ...], ...] = ()
    returncode: int = 0
    # Compact Lean elaboration diagnostics captured when one or more claims fail
    # to elaborate. Surfaced to the planner so a re-plan can repair the exact
    # type defect (unknown identifier, ℕ-vs-ℝ mismatch, missing Neg/abs, …)
    # instead of receiving only "did not elaborate as one Lean type".
    elaboration_diagnostics: str = ""
    # Zero-based planner claim index -> compact Lean diagnostic. Root is probe
    # 0, so claim i is sourced from batched probe i+1.
    per_claim_diagnostics: Mapping[int, str] = field(default_factory=dict)
    infrastructure_error: str = ""

    @property
    def usable(self) -> bool:
        return self.service_available and self.root_elaborated

    @property
    def complete(self) -> bool:
        return bool(
            self.usable and all(self.claim_elaborated) and all(self.support_elaborated)
        )


def _recursive_plan_state_record(plan: MiniSubgoalPlan) -> dict[str, Any]:
    return asdict(plan)


def _bind_plan_planner_receipt(
    plan: MiniSubgoalPlan,
) -> tuple[MiniSubgoalPlan, str]:
    """Bind a plan and all its claims to one full-SHA-256 provider receipt."""

    record = _recursive_plan_state_record(plan)
    # Receipt IDs cannot hash themselves. Omitting the field also keeps newly
    # generated IDs compatible with restored pre-field checkpoint records.
    for raw_claim in list(record.get("claims") or []):
        if isinstance(raw_claim, dict):
            raw_claim.pop("planner_receipt_id", None)
            raw_claim.pop("planner_receipt_claim_id", None)
            raw_claim.pop("planner_transformation_receipt_id", None)
    payload = json.dumps(
        record,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    )
    receipt_id = hashlib.sha256(payload.encode("utf-8")).hexdigest()
    bound_claims: list[MiniSubgoalClaim] = []
    for claim_index, claim in enumerate(plan.claims):
        claim_link_payload = json.dumps(
            {
                "receipt_id": receipt_id,
                "claim_index": claim_index,
                "obligation_id": str(claim.obligation_id or ""),
                "origin_plan_fingerprint": str(
                    claim.origin_plan_fingerprint or ""
                ),
            },
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
        )
        bound_claims.append(
            dataclass_replace(
                claim,
                planner_receipt_id=receipt_id,
                planner_receipt_claim_id=hashlib.sha256(
                    claim_link_payload.encode("utf-8")
                ).hexdigest(),
                planner_transformation_receipt_id="",
            )
        )
    bound_plan = dataclass_replace(plan, claims=tuple(bound_claims))
    return bound_plan, receipt_id


def _planner_claim_transformation_receipt_id(claim: MiniSubgoalClaim) -> str:
    """Bind an explicitly labeled controller statement transformation."""

    planner_receipt_id = str(claim.planner_receipt_id or "").strip()
    planner_receipt_claim_id = str(claim.planner_receipt_claim_id or "").strip()
    if not planner_receipt_id or not planner_receipt_claim_id:
        return ""
    payload = json.dumps(
        {
            "schema_version": 1,
            "planner_receipt_id": planner_receipt_id,
            "planner_receipt_claim_id": planner_receipt_claim_id,
            "obligation_id": str(claim.obligation_id or ""),
            "origin_plan_fingerprint": str(claim.origin_plan_fingerprint or ""),
            "statement": str(claim.statement or ""),
            "variants": [asdict(variant) for variant in claim.variants],
            "contract_identity_repaired": bool(claim.contract_identity_repaired),
            "root_assembly_statement_substituted": bool(
                claim.root_assembly_statement_substituted
            ),
        },
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    )
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def _resolve_planner_claim_receipt_id(
    claim: MiniSubgoalClaim,
    *,
    planner_plan_receipts: Mapping[str, MiniSubgoalPlan],
    planner_claim_receipt_ids: Mapping[str, str],
) -> str:
    """Resolve modern provenance exactly; use obligation fallback only for legacy."""

    def matches_receipted_source(
        active_claim: MiniSubgoalClaim,
        source_claim: MiniSubgoalClaim,
    ) -> bool:
        # These fields came from the compiled provider response (including
        # explicitly labeled parse-repair normalization) and are not rewritten
        # by downstream Lean analysis, filtering, or priority selection.
        planner_authored_fields = (
            "name",
            "role",
            "rationale",
            "invariant_refs",
            "sanity_check",
            "sanity_status",
            "sanity_contract_version",
            "counting_classification",
            "source_index",
            "obligation_id",
            "origin_plan_fingerprint",
            "controller_synthesized",
            "controller_role_restored",
        )
        if any(
            getattr(active_claim, field_name) != getattr(source_claim, field_name)
            for field_name in planner_authored_fields
        ):
            return False
        if active_claim.statement == source_claim.statement:
            return bool(
                active_claim.variants == source_claim.variants
                and active_claim.contract_identity_repaired
                == source_claim.contract_identity_repaired
                and active_claim.root_assembly_statement_substituted
                == source_claim.root_assembly_statement_substituted
                and active_claim.planner_transformation_receipt_id
                == source_claim.planner_transformation_receipt_id
            )
        # Statement repair/root substitution is a separately labeled
        # controller transformation in the selected-claim packet. An unlabeled
        # checkpoint substitution must never inherit the provider receipt.
        transformation_receipt_id = str(
            active_claim.planner_transformation_receipt_id or ""
        ).strip()
        return bool(
            (
                active_claim.contract_identity_repaired
                or active_claim.root_assembly_statement_substituted
            )
            and transformation_receipt_id
            and transformation_receipt_id
            == _planner_claim_transformation_receipt_id(active_claim)
        )

    claim_receipt_id = str(claim.planner_receipt_id or "").strip()
    if claim_receipt_id:
        source_plan = planner_plan_receipts.get(claim_receipt_id)
        claim_link_id = str(claim.planner_receipt_claim_id or "").strip()
        if source_plan is None or not claim_link_id:
            return ""
        return (
            claim_receipt_id
            if any(
                str(source_claim.planner_receipt_id or "").strip()
                == claim_receipt_id
                and str(source_claim.planner_receipt_claim_id or "").strip()
                == claim_link_id
                and str(source_claim.obligation_id or "").strip()
                == str(claim.obligation_id or "").strip()
                and matches_receipted_source(claim, source_claim)
                for source_claim in source_plan.claims
            )
            else ""
        )
    obligation_id = str(claim.obligation_id or "").strip()
    legacy_receipt_id = str(
        planner_claim_receipt_ids.get(obligation_id, "") or ""
    ).strip()
    if not re.fullmatch(r"[0-9a-f]{16}", legacy_receipt_id):
        return ""
    matching_legacy_receipts = [
        receipt_id
        for receipt_id, plan in planner_plan_receipts.items()
        if re.fullmatch(r"[0-9a-f]{16}", str(receipt_id or ""))
        and any(
            str(receipt_claim.obligation_id or "").strip() == obligation_id
            for receipt_claim in plan.claims
        )
    ]
    return (
        legacy_receipt_id
        if matching_legacy_receipts == [legacy_receipt_id]
        else ""
    )


def _prune_planner_receipt_registry(
    planner_plan_receipts: dict[str, MiniSubgoalPlan],
    planner_claim_receipt_ids: dict[str, str],
    *,
    live_claims: Sequence[MiniSubgoalClaim],
) -> None:
    """Retain only receipts reachable from checkpoint-live claims."""

    referenced_receipt_ids: set[str] = set()
    for claim in live_claims:
        receipt_id = _resolve_planner_claim_receipt_id(
            claim,
            planner_plan_receipts=planner_plan_receipts,
            planner_claim_receipt_ids=planner_claim_receipt_ids,
        )
        if receipt_id:
            referenced_receipt_ids.add(receipt_id)
    for receipt_id in tuple(planner_plan_receipts):
        if receipt_id not in referenced_receipt_ids:
            planner_plan_receipts.pop(receipt_id, None)
    for obligation_id, receipt_id in tuple(planner_claim_receipt_ids.items()):
        if receipt_id not in planner_plan_receipts:
            planner_claim_receipt_ids.pop(obligation_id, None)


def _recursive_plan_from_state_record(raw: Mapping[str, Any]) -> MiniSubgoalPlan:
    data = dict(raw or {})
    claims: list[MiniSubgoalClaim] = []
    for raw_claim in list(data.get("claims") or []):
        if not isinstance(raw_claim, Mapping):
            continue
        claim_data = dict(raw_claim)
        claim_data["dependencies"] = tuple(claim_data.get("dependencies") or ())
        claim_data["invariant_refs"] = tuple(claim_data.get("invariant_refs") or ())
        claim_data["contract_binder_sorts"] = tuple(
            claim_data.get("contract_binder_sorts") or ()
        )
        claim_data["contract_proof_binder_types"] = tuple(
            claim_data.get("contract_proof_binder_types") or ()
        )
        claim_data["contract_proof_binder_structural_hashes"] = tuple(
            claim_data.get("contract_proof_binder_structural_hashes") or ()
        )
        claim_data["dependency_semantic_identities"] = tuple(
            (str(item[0] or ""), str(item[1] or ""))
            for item in (claim_data.get("dependency_semantic_identities") or ())
            if isinstance(item, (list, tuple)) and len(item) == 2
        )
        claim_data["policy_risk_reasons"] = tuple(
            str(item or "")
            for item in list(claim_data.get("policy_risk_reasons") or ())
            if str(item or "").strip()
        )
        variant_fields = {item.name for item in fields(SubgoalVariant)}
        claim_fields = {item.name for item in fields(MiniSubgoalClaim)}
        variants: list[SubgoalVariant] = []
        for raw_variant in list(claim_data.get("variants") or []):
            if not isinstance(raw_variant, Mapping):
                continue
            try:
                variants.append(
                    SubgoalVariant(
                        **{
                            key: value
                            for key, value in {
                                **dict(raw_variant),
                                "contract_binder_sorts": tuple(
                                    raw_variant.get("contract_binder_sorts") or ()
                                ),
                                "contract_proof_binder_types": tuple(
                                    raw_variant.get("contract_proof_binder_types") or ()
                                ),
                                "contract_proof_binder_structural_hashes": tuple(
                                    raw_variant.get(
                                        "contract_proof_binder_structural_hashes"
                                    )
                                    or ()
                                ),
                            }.items()
                            if key in variant_fields
                        }
                    )
                )
            except TypeError:
                continue
        claim_data["variants"] = tuple(variants)
        filtered_claim = {
            key: value for key, value in claim_data.items() if key in claim_fields
        }
        if not str(filtered_claim.get("statement") or "").strip():
            continue
        filtered_claim.setdefault("name", "")
        try:
            claims.append(MiniSubgoalClaim(**filtered_claim))
        except TypeError:
            continue
    return MiniSubgoalPlan(
        root_statement=str(data.get("root_statement") or ""),
        claims=tuple(claims),
        strategy=str(data.get("strategy") or ""),
        notes=tuple(str(item or "") for item in list(data.get("notes") or [])),
        raw_response=str(data.get("raw_response") or ""),
        plan_complete=(
            data.get("plan_complete")
            if isinstance(data.get("plan_complete"), bool)
            else None
        ),
        answer_safe_preamble_used=bool(data.get("answer_safe_preamble_used")),
        root_contract_identity=str(data.get("root_contract_identity") or ""),
        root_contract_identity_statement_key=str(
            data.get("root_contract_identity_statement_key") or ""
        ),
        root_contract_identity_environment_hash=str(
            data.get("root_contract_identity_environment_hash") or ""
        ),
        root_contract_identity_evidence_receipt=str(
            data.get("root_contract_identity_evidence_receipt") or ""
        ),
        root_contract_display_statement=str(
            data.get("root_contract_display_statement") or ""
        ),
        root_contract_binder_sorts=tuple(data.get("root_contract_binder_sorts") or ()),
        root_contract_proof_binder_types=tuple(
            data.get("root_contract_proof_binder_types") or ()
        ),
        root_contract_proof_binder_structural_hashes=tuple(
            data.get("root_contract_proof_binder_structural_hashes") or ()
        ),
        root_contract_conclusion_structural_hash=str(
            data.get("root_contract_conclusion_structural_hash") or ""
        ),
        root_contract_telescope_evidence_receipt=str(
            data.get("root_contract_telescope_evidence_receipt") or ""
        ),
    )


def _restore_validated_planner_plan_receipts(
    raw_receipts: Mapping[str, Any],
) -> dict[str, MiniSubgoalPlan]:
    """Restore modern authenticated receipts and format-gated legacy receipts."""

    restored: dict[str, MiniSubgoalPlan] = {}
    for raw_receipt_id, raw_plan in dict(raw_receipts or {}).items():
        receipt_id = str(raw_receipt_id or "").strip()
        if not isinstance(raw_plan, Mapping):
            continue
        plan = _recursive_plan_from_state_record(raw_plan)
        if not (plan.claims or plan.raw_response):
            continue
        if re.fullmatch(r"[0-9a-f]{64}", receipt_id):
            rebound_plan, expected_id = _bind_plan_planner_receipt(plan)
            if expected_id != receipt_id:
                continue
            if any(
                str(claim.planner_receipt_id or "").strip()
                not in {"", receipt_id}
                for claim in plan.claims
            ):
                continue
            if any(
                str(original.planner_receipt_claim_id or "").strip()
                not in {"", rebound.planner_receipt_claim_id}
                for original, rebound in zip(plan.claims, rebound_plan.claims)
            ):
                continue
            if any(
                str(original.planner_transformation_receipt_id or "").strip()
                not in {"", rebound.planner_transformation_receipt_id}
                for original, rebound in zip(plan.claims, rebound_plan.claims)
            ):
                continue
            # Fill an absent claim field only after the plan payload has
            # authenticated against its modern receipt key.
            restored[receipt_id] = rebound_plan
            continue
        if re.fullmatch(r"[0-9a-f]{16}", receipt_id):
            # Historical checkpoint IDs were truncated hashes and claims had
            # no embedded receipt field. Preserve them as opaque local keys;
            # never mix a modern claim binding into this migration branch.
            if any(
                str(claim.planner_receipt_id or "").strip()
                for claim in plan.claims
            ):
                continue
            legacy_payload = json.dumps(
                dict(raw_plan),
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            )
            if text_hash(legacy_payload) != receipt_id:
                continue
            restored[receipt_id] = plan
    return restored


def _claim_proof_result_state_record(result: ClaimProofResult) -> dict[str, Any]:
    return {
        "proof": result.proof,
        "invalid_reason": result.invalid_reason,
        "invalid_certificate": copy.deepcopy(result.invalid_certificate),
        "giveup_cluster": result.giveup_cluster,
        "giveup_match": result.giveup_match,
        "terminal_failure_reason": result.terminal_failure_reason,
        "terminal_failure_kind": result.terminal_failure_kind,
        "child_llm_preamble": result.child_llm_preamble,
        "child_lean_preamble": result.child_lean_preamble,
        "theory_imported_bundle_ids": list(result.theory_imported_bundle_ids),
        "theory_snapshot": copy.deepcopy(result.theory_snapshot),
        "theory_context_hash": result.theory_context_hash,
        "child_verified_helper_blocks": list(result.child_verified_helper_blocks),
        "required_child_helper_hashes": [
            list(item) for item in result.required_child_helper_hashes
        ],
        "formal_progress": bool(result.formal_progress),
        "diagnostic_progress": bool(result.diagnostic_progress),
        "progress_signature": str(result.progress_signature or ""),
        "controller_projection_invalidated": bool(
            result.controller_projection_invalidated
        ),
    }


def _claim_proof_result_from_state_record(
    raw: Mapping[str, Any],
) -> ClaimProofResult:
    data = dict(raw or {})
    return ClaimProofResult(
        proof=str(data.get("proof") or "") or None,
        invalid_reason=str(data.get("invalid_reason") or ""),
        invalid_certificate=copy.deepcopy(data.get("invalid_certificate")),
        giveup_cluster=str(data.get("giveup_cluster") or ""),
        giveup_match=str(data.get("giveup_match") or ""),
        terminal_failure_reason=str(data.get("terminal_failure_reason") or ""),
        terminal_failure_kind=str(data.get("terminal_failure_kind") or ""),
        child_llm_preamble=str(data.get("child_llm_preamble") or ""),
        child_lean_preamble=str(data.get("child_lean_preamble") or ""),
        theory_imported_bundle_ids=tuple(
            str(item or "")
            for item in list(data.get("theory_imported_bundle_ids") or [])
            if str(item or "").strip()
        ),
        theory_snapshot=copy.deepcopy(data.get("theory_snapshot")),
        theory_context_hash=str(data.get("theory_context_hash") or ""),
        child_verified_helper_blocks=tuple(
            str(item or "")
            for item in list(data.get("child_verified_helper_blocks") or [])
            if str(item or "").strip()
        ),
        required_child_helper_hashes=tuple(
            (str(item[0]), str(item[1]))
            for item in list(data.get("required_child_helper_hashes") or [])
            if isinstance(item, (list, tuple)) and len(item) == 2
        ),
        formal_progress=bool(data.get("formal_progress", False)),
        diagnostic_progress=bool(data.get("diagnostic_progress", False)),
        progress_signature=str(data.get("progress_signature") or ""),
        controller_projection_invalidated=bool(
            data.get("controller_projection_invalidated", False)
        ),
    )


