def seed_verified_helpers(
    dst: Any,
    src: Any,
    *,
    reset_graph: bool = True,
) -> None:
    """Seed a child dossier with already-verified helper declarations only.

    B5 fix (2026-05-11): the default behavior (``reset_graph=True``)
    matches the historical contract — wipe ``dst.verified_helpers`` and
    ``dst.proof_graph`` so the child mirrors ``src``'s verified helpers
    exactly. The recursive-subgoal callsite (mini_recursive.py:393)
    relies on this: the child gets ONLY the parent's proved helpers,
    not the parent's exploration state.

    Pass ``reset_graph=False`` from callers that have intentionally
    seeded the child's proof_graph with a deep-copy of the parent's
    graph (e.g., the parallel-sample fan-out in mini_prover, which
    wants to inherit the parent's full graph state — attempt history,
    scratch nodes, transitions — and then top up with the verified-
    helper dict). Without this kwarg, the parallel-sample callsite was
    silently throwing away the clone immediately after constructing it.
    """

    dst.verified_helpers = {}
    # Fix 1 follow-up (2026-05-22): clear stale alias entries that
    # pointed at the now-emptied verified_helpers. The re-recording
    # loop below rebuilds the map organically via record_verified_helper.
    if hasattr(dst, "verified_helper_statement_aliases"):
        dst.verified_helper_statement_aliases = {}
    if hasattr(dst, "verified_helper_progress_deltas"):
        dst.verified_helper_progress_deltas = {}
    if hasattr(dst, "current_lean_environment_hash"):
        dst.current_lean_environment_hash = str(
            getattr(src, "current_lean_environment_hash", "") or ""
        )
    if hasattr(dst, "lean_environment_ancestor_hashes"):
        dst.lean_environment_ancestor_hashes = copy.deepcopy(
            getattr(src, "lean_environment_ancestor_hashes", {}) or {}
        )
    dst.superseded_verified_helper_hashes = copy.deepcopy(
        getattr(src, "superseded_verified_helper_hashes", {}) or {}
    )
    dst.verified_helper_source_hash_history = copy.deepcopy(
        getattr(src, "verified_helper_source_hash_history", {}) or {}
    )
    if reset_graph:
        reset_proof_graph = getattr(dst, "reset_proof_graph", None)
        if reset_proof_graph is not None:
            reset_proof_graph()
    from .proof_dossier import is_answer_unsafe_helper_source

    answer_safety_kwargs = {
        "opaque_mode": bool(getattr(dst, "opaque_mode", True)),
        "allow_official_answer_visibility": bool(
            getattr(dst, "allow_official_answer_visibility", False)
        ),
        "official_answer_payload_present": getattr(
            dst,
            "official_answer_payload_present",
            None,
        ),
    }
    source_helper_items = list((getattr(src, "verified_helpers", {}) or {}).items())
    for _name, item in dependency_ordered_verified_helper_items(source_helper_items):
        if is_answer_unsafe_helper_source(
            getattr(item, "source", ""),
            **answer_safety_kwargs,
        ):
            continue
        importer = getattr(dst, "record_imported_verified_helper", None)
        if importer is not None:
            importer(item)
        else:
            dst.verified_helpers[item.name] = clone_verified_helper(item)

    # Adversarial-review follow-up (2026-05-22):
    #   (a) Order preservation: re-recording rebuilds aliases in
    #       iteration-order of ``src.verified_helpers``. If that order
    #       differs from src's original insertion sequence (e.g., the
    #       dict was reassigned), the rebuilt alias direction can
    #       invert relative to src. REPLACE the alias map with src's
    #       authoritative one (filtered to surviving names) so the
    #       direction matches src regardless of rebuild order.
    #   (b) Mock-dossier path: the ``record_verified_helper is None``
    #       fallback above does a direct dict write that skips alias
    #       building entirely. The replacement also covers that path.
    if hasattr(dst, "verified_helper_statement_aliases") and hasattr(
        src, "verified_helper_statement_aliases"
    ):
        dst_names = set(getattr(dst, "verified_helpers", {}).keys())
        src_aliases = getattr(src, "verified_helper_statement_aliases", {}) or {}
        dst.verified_helper_statement_aliases = {
            req: canonical
            for req, canonical in src_aliases.items()
            if req in dst_names and canonical in dst_names
        }
        sync_helpers = getattr(dst, "_sync_legacy_helpers_to_graph", None)
        if callable(sync_helpers):
            sync_helpers()


def merge_failed_recursive_scratch(
    dst: Any,
    src: Any,
    *,
    max_records: int = 12,
) -> int:
    """Carry bounded failed-route memory out of a recursive child.

    Recursive children must not share mutable proof graphs with their parent.
    Compact scratch records are immutable search evidence, however: they retain
    the goal hash, safe declaration names and Lean diagnostic without retaining
    the rejected proof body.
    """

    dst_scratch = getattr(dst, "scratch", None)
    src_scratch = getattr(src, "scratch", None)
    if not isinstance(dst_scratch, list) or not isinstance(src_scratch, list):
        return 0
    record_limit = max(0, int(max_records or 0))
    if record_limit <= 0:
        return 0
    existing = {
        (
            str(getattr(item, "goal_key", "") or getattr(item, "goal_hash", "") or ""),
            str(getattr(item, "code_hash", "") or ""),
            bool(getattr(item, "ok", False)),
        )
        for item in dst_scratch
    }
    added = 0
    failed_scratch = [
        item for item in src_scratch if not bool(getattr(item, "ok", False))
    ]
    for item in failed_scratch[-record_limit:]:
        key = (
            str(getattr(item, "goal_key", "") or getattr(item, "goal_hash", "") or ""),
            str(getattr(item, "code_hash", "") or ""),
            False,
        )
        if key in existing:
            continue
        dst_scratch.append(copy.deepcopy(item))
        existing.add(key)
        added += 1
    prune_scratch = getattr(dst, "prune_scratch_records", None)
    if callable(prune_scratch):
        prune_scratch()
    if added:
        increment = getattr(dst, "increment_tool_metric", None)
        if callable(increment):
            increment("mini_recursive_failed_scratch_handoffs", added)
    return added


def _merge_new_verified_helpers(
    dst: Any,
    src: Any,
    *,
    renamed_identifiers: Optional[dict[str, str]] = None,
) -> list[str]:
    """Record verified helpers present in ``src`` but absent from ``dst``.

    Used to fold helper lemmas authored during a root-close turn -- which runs
    on a COPY of the dossier -- back into the shared dossier, so the durable
    replay set used at finalization/export is complete. Additive only: an
    existing ``dst`` helper of the same name is never superseded (the just
    authored orphan lemmas are necessarily fresh names). Returns the names
    merged.
    """

    importer = getattr(dst, "record_imported_verified_helper", None)
    recorder = getattr(dst, "record_verified_helper", None)
    if importer is None and recorder is None:
        return []
    from .utils import canonical_lean_identifier

    existing = set(getattr(dst, "verified_helpers", {}) or {})

    def registry_name(registry: Mapping[str, Any], raw_name: str) -> str:
        clean = str(raw_name or "").strip()
        if clean in registry:
            return clean
        canonical = canonical_lean_identifier(clean)
        return next(
            (
                str(candidate or "").strip()
                for candidate in registry
                if canonical_lean_identifier(str(candidate or "").strip()) == canonical
            ),
            "",
        )

    def ordered_renames() -> list[tuple[str, str]]:
        return sorted(
            renamed_collisions.items(),
            key=lambda pair: (-len(str(pair[0]).split(".")), -len(pair[0])),
        )

    from .proof_dossier import is_answer_unsafe_helper_source

    answer_safety_kwargs = {
        "opaque_mode": bool(getattr(dst, "opaque_mode", True)),
        "allow_official_answer_visibility": bool(
            getattr(dst, "allow_official_answer_visibility", False)
        ),
        "official_answer_payload_present": getattr(
            dst, "official_answer_payload_present", None
        ),
    }
    merged: list[str] = []
    renamed_collisions: dict[str, str] = {}
    source_registry = dict(getattr(src, "verified_helpers", {}) or {})
    staged_registry = dict(getattr(dst, "verified_helpers", {}) or {})
    incoming_decl_names = {
        str(helper_decl_name(getattr(helper, "source", "") or "") or "").strip()
        for helper in source_registry.values()
        if str(helper_decl_name(getattr(helper, "source", "") or "") or "").strip()
    }
    staged_items: list[tuple[str, Any, bool]] = []
    rejected_source_names: set[str] = set()
    preflight = getattr(dst, "preflight_imported_verified_helper", None)
    source_helper_items = list(source_registry.items())
    for source_registry_name, item in dependency_ordered_verified_helper_items(
        source_helper_items
    ):
        declared_dependencies = {
            str(dependency or "").strip()
            for dependency in (
                *list(getattr(item, "support_names", []) or []),
                *list(getattr(item, "replay_context_names", []) or []),
                *list(dict(getattr(item, "support_source_hashes", {}) or {})),
                *list(dict(getattr(item, "replay_context_source_hashes", {}) or {})),
            )
            if str(dependency or "").strip()
        }
        if declared_dependencies & rejected_source_names:
            rejected_source_names.add(str(source_registry_name or "").strip())
            continue
        source = getattr(item, "source", "") or ""
        for old_name, new_name in ordered_renames():
            source = _rename_helper_identifier(
                source,
                old_name,
                new_name,
            )
        # Use the decl name the dossier will actually store under (what
        # ``record_verified_helper`` derives from the source), not the src
        # label -- a hand-built ``src`` could set ``item.name`` inconsistently.
        name = (
            helper_decl_name(source) or str(getattr(item, "name", "") or "")
        ).strip()
        if not name:
            continue
        if is_answer_unsafe_helper_source(source, **answer_safety_kwargs):
            continue
        current_registry_name = registry_name(staged_registry, name)
        count_as_merged = True
        pending_collision: Optional[tuple[str, str]] = None
        if current_registry_name:
            current = staged_registry.get(current_registry_name)
            if (
                current is not None
                and str(getattr(current, "source_hash", "") or "").strip()
                == str(getattr(item, "source_hash", "") or "").strip()
            ):
                count_as_merged = False
            current_statement_key = canonical_dossier_statement_key(
                helper_decl_statement(getattr(current, "source", "") or "")
            )
            incoming_statement_key = canonical_dossier_statement_key(
                helper_decl_statement(source)
            )
            if (
                current_statement_key == incoming_statement_key
                and name != current_registry_name
            ):
                continue
            if current_statement_key == incoming_statement_key:
                # Rebinding a dependent to an existing theorem is sound only
                # after the incoming provider's environment/contract evidence
                # passes the same destination preflight. Never mutate here:
                # the complete bundle still has to validate.
                if (
                    callable(preflight)
                    and preflight(
                        item,
                        destination_helpers=staged_registry,
                    )
                    is None
                ):
                    rejected_source_names.add(str(source_registry_name or "").strip())
                    continue
                name = current_registry_name
                count_as_merged = bool(
                    str(getattr(current, "source_hash", "") or "").strip()
                    != str(getattr(item, "source_hash", "") or "").strip()
                )
            elif importer is None and recorder is None:
                continue
            else:
                old_name = name
                name = _fresh_helper_collision_name(
                    old_name,
                    reserved_names=(
                        set(staged_registry)
                        | incoming_decl_names
                        | set(renamed_collisions.values())
                    ),
                )
                source = _rename_helper_identifier(source, old_name, name)
                pending_collision = (old_name, name)
        support_names = [
            renamed_collisions.get(str(support or ""), str(support or ""))
            for support in list(getattr(item, "support_names", []) or [])
        ]
        replay_context_names = [
            renamed_collisions.get(str(replay or ""), str(replay or ""))
            for replay in list(getattr(item, "replay_context_names", []) or [])
        ]
        import_item = copy.deepcopy(item)
        import_item.name = name
        import_item.source = source
        import_item.source_hash = text_hash(source)
        import_item.support_names = support_names
        import_item.replay_context_names = replay_context_names
        receipts_valid = True
        for receipt_attr in (
            "support_source_hashes",
            "replay_context_source_hashes",
        ):
            rewritten_receipts: dict[str, str] = {}
            for dependency_name, source_hash in dict(
                getattr(item, receipt_attr, {}) or {}
            ).items():
                old_dependency_name = str(dependency_name or "").strip()
                source_dependency = source_registry.get(old_dependency_name)
                source_dependency_hash = str(
                    getattr(source_dependency, "source_hash", "") or ""
                ).strip()
                if (
                    source_dependency is None
                    or not source_dependency_hash
                    or source_dependency_hash != str(source_hash or "").strip()
                ):
                    receipts_valid = False
                    break
                mapped_name = renamed_collisions.get(
                    old_dependency_name,
                    old_dependency_name,
                )
                destination_dependency = staged_registry.get(
                    registry_name(staged_registry, mapped_name)
                )
                destination_dependency_hash = str(
                    getattr(destination_dependency, "source_hash", "") or ""
                ).strip()
                rewritten_receipts[mapped_name] = (
                    destination_dependency_hash or source_dependency_hash
                )
            setattr(import_item, receipt_attr, rewritten_receipts)
            if not receipts_valid:
                break
        if not receipts_valid:
            rejected_source_names.add(str(source_registry_name or "").strip())
            continue
        if (
            callable(preflight)
            and preflight(
                import_item,
                destination_helpers=staged_registry,
            )
            is None
        ):
            rejected_source_names.add(str(source_registry_name or "").strip())
            continue
        if pending_collision is not None:
            renamed_collisions[pending_collision[0]] = pending_collision[1]
        staged_registry[name] = import_item
        staged_items.append((name, import_item, count_as_merged))

    try:
        commit_snapshot = copy.deepcopy(getattr(dst, "__dict__", {}))
    except Exception:
        return []

    def abort_commit() -> list[str]:
        try:
            dst.__dict__.clear()
            dst.__dict__.update(copy.deepcopy(commit_snapshot))
        except BaseException as exc:
            raise RuntimeError(
                "verified-helper bundle rollback failed after partial commit"
            ) from exc
        return []

    # Commit only after every dependency receipt and destination preflight in
    # the bundle succeeds. This prevents an accepted provider from surviving a
    # rejected dependent.
    for name, import_item, count_as_merged in staged_items:
        source = str(getattr(import_item, "source", "") or "")
        support_names = list(getattr(import_item, "support_names", []) or [])
        replay_context_names = list(
            getattr(import_item, "replay_context_names", []) or []
        )
        try:
            if importer is not None:
                landed = importer(import_item)
            else:
                try:
                    landed = recorder(
                        source,
                        phase=getattr(import_item, "phase", ""),
                        turn_index=getattr(import_item, "turn_index", 0),
                        support_names=support_names,
                        replay_context_names=replay_context_names,
                        provenance_tags=list(
                            getattr(import_item, "provenance_tags", []) or []
                        ),
                        visibility_policy=str(
                            getattr(import_item, "visibility_policy", "") or ""
                        ),
                    )
                except TypeError:
                    landed = recorder(
                        source,
                        phase=getattr(import_item, "phase", ""),
                        turn_index=getattr(import_item, "turn_index", 0),
                        support_names=support_names,
                    )
        except Exception:
            return abort_commit()
        # Only count it merged once it has actually landed in ``dst`` -- the
        # recorder can reject a source whose decl name is unextractable.
        destination_registry = getattr(dst, "verified_helpers", {}) or {}
        destination_name = registry_name(destination_registry, name)
        destination_item = destination_registry.get(destination_name)
        if destination_item is not None and (
            importer is None
            or (
                str(getattr(destination_item, "name", "") or "").strip()
                == destination_name
                and str(getattr(destination_item, "source_hash", "") or "").strip()
                == str(getattr(import_item, "source_hash", "") or "").strip()
                and canonical_lean_identifier(
                    str(getattr(landed, "name", "") or "").strip()
                )
                == canonical_lean_identifier(destination_name)
            )
        ):
            if count_as_merged:
                merged.append(destination_name)
            existing.add(name)
        else:
            return abort_commit()
    if renamed_identifiers is not None:
        renamed_identifiers.update(renamed_collisions)
    return merged


def unique_dossier_helper_name(dossier: Any, suggested: str) -> str:
    base = re.sub(r"[^A-Za-z0-9_'.]", "_", str(suggested or "mini_helper"))
    base = re.sub(r"_+", "_", base).strip("_") or "mini_helper"
    base = re.sub(r"_solution", "_target", base, flags=re.IGNORECASE)
    if base[0].isdigit():
        base = f"mini_{base}"
    candidate = base[:96].rstrip("_") or "mini_helper"
    suffix = 2
    has_helper = getattr(dossier, "has_helper", None)
    while bool(has_helper(candidate) if has_helper is not None else False):
        tail = f"_{suffix}"
        candidate = base[: max(1, 96 - len(tail))].rstrip("_") + tail
        suffix += 1
    return candidate


def helper_decl_from_proof(name: str, statement: str, proof: str) -> str:
    proof_text = str(proof or "").strip()
    statement_text = str(statement or "").strip()
    if (
        proof_text == "by"
        or proof_text.startswith("by ")
        or proof_text.startswith("by\n")
    ):
        return f"theorem {name} : {statement_text} := {proof_text}"
    return f"theorem {name} : {statement_text} :=\n{proof_text}"


def render_answer_safe_helper_summary(
    helpers: Sequence[Any],
    *,
    suppress_solution_placeholders: bool = True,
    opaque_mode: bool = True,
    allow_official_answer_visibility: bool = False,
    official_answer_payload_present: Optional[bool] = None,
) -> str:
    """Summarize verified helper signatures without exposing theorem bodies."""

    effective_suppression = effective_solution_placeholder_suppression(
        suppress_solution_placeholders=suppress_solution_placeholders,
        opaque_mode=opaque_mode,
        allow_official_answer_visibility=allow_official_answer_visibility,
        official_answer_payload_present=official_answer_payload_present,
    )
    answer_safety_kwargs = {
        "suppress_solution_placeholders": effective_suppression,
        "opaque_mode": opaque_mode,
        "allow_official_answer_visibility": allow_official_answer_visibility,
        "official_answer_payload_present": official_answer_payload_present,
    }
    redact_solution_refs = effective_suppression
    rendered: list[str] = []
    seen: set[str] = set()
    for helper in helpers or ():
        text = str(getattr(helper, "source", None) or helper or "").strip()
        name = helper_decl_name(text) or str(getattr(helper, "name", "") or "").strip()
        if not name or name in seen:
            continue
        if is_answer_unsafe_statement_text(name, **answer_safety_kwargs):
            continue
        if is_answer_unsafe_helper_source(text, **answer_safety_kwargs):
            continue
        signature = helper_prompt_signature(
            text,
            name=name,
            redact_solution_refs=redact_solution_refs,
        )
        if is_answer_unsafe_statement_text(signature, **answer_safety_kwargs):
            continue
        seen.add(name)
        display_name = _prompt_safe_helper_name(
            name,
            redact_solution_refs=redact_solution_refs,
        )
        rendered.append(f"- `{display_name}`: `{signature}`")
    if not rendered:
        return "Verified helper names available: none."
    return "Verified helper statements available:\n" + "\n".join(rendered)


def _verified_helper_names(helpers: Sequence[Any]) -> set[str]:
    names: set[str] = set()
    for helper in helpers or ():
        text = str(getattr(helper, "source", None) or helper or "").strip()
        name = helper_decl_name(text) or str(getattr(helper, "name", "") or "").strip()
        if name:
            names.add(name)
    return names


def _missing_claim_dependencies(
    claim: MiniSubgoalClaim,
    *,
    proved_claim_names: set[str],
    helpers: Sequence[Any],
    extra_dependencies: Sequence[str] = (),
) -> list[str]:
    """Declared plan dependencies must be Lean-accepted before use.

    `_prioritize_claims` gives a topological-ish order, but ordering is not
    enough: if a prerequisite claim is type-rejected, sample-refuted, or
    exhausted, downstream assembly claims must wait for a replacement bridge.
    """

    helper_names = _verified_helper_names(helpers)
    missing: list[str] = []
    seen: set[str] = set()
    for dep in tuple(claim.dependencies or ()) + tuple(extra_dependencies or ()):
        name = str(dep or "").strip()
        if not name or name in seen:
            continue
        seen.add(name)
        if name in proved_claim_names or name in helper_names:
            continue
        missing.append(name)
    return missing


def _reusable_verified_helper_match(
    rendered_helper_blocks: Sequence[str],
    candidate_statements: Sequence[str],
    *,
    rendered_helper_identities: Sequence[str] = (),
    candidate_identities: Sequence[str] = (),
) -> tuple[str, str]:
    """Name of a RENDERED verified-helper block that already proves one of the
    candidate statements, else ``("", "")``.

    Used to bind a claim to an existing canonical helper instead of re-proving
    and storing a duplicate of the same lemma across passes.

    Matches against the actually-RENDERED/citable set (``get_helpers()`` /
    ``verified_helper_blocks()``), NOT the raw store: membership there is the
    guarantee that the reused helper is in the Lean context and citable at
    assembly. A helper can be render-policy-"visible" yet still be dropped from
    the rendered set (non-renderable generated dependency, answer-unsafe source
    or statement); binding a claim to such a helper would deadlock it (never
    citable, never re-proved because the reuse re-fires each pass). The rendered
    set has already applied every renderable + answer-safe filter, so any match
    here is safe. The comparison intentionally normalizes whitespace and
    binder/ascription-colon spacing only. Broader graph-surface
    canonicalization can merge statements that require elaboration to prove
    equivalent; a false reuse would then re-fire every pass and deadlock the
    claim. Raw whitespace comparison still missed equivalent forms such as
    ``(0:ℝ)`` and ``(0 : ℝ)`` and minted duplicate declarations across passes.

    Production callers supply receipt-bound helper and claim identities. Once
    either identity sequence is supplied, reuse fails closed unless both sides
    carry compatible Lean identities; surface equality is retained only for
    legacy identity-free callers.

    Only SUBSTANTIVE statements (len >= 16) are eligible: trivial/generic props
    (`True`, `False`, tiny equalities) are shared incidentally by role-distinct
    helpers, so reusing one for a different-role claim would wrongly skip that
    claim's own proving (and any replay-context upgrade it would perform). Same
    threshold as the render-time duplicate-statement alias collapse.
    """

    def exact_source_key(statement: Any) -> str:
        return " ".join(
            normalize_lean_colon_spacing_for_identity(str(statement or "")).split()
        )

    wanted = {
        normalized
        for statement in candidate_statements
        for normalized in (exact_source_key(statement),)
        if len(normalized) >= 16
    }
    if not wanted:
        wanted = set()
    trusted_candidates = tuple(
        (index, str(identity or "").strip())
        for index, identity in enumerate(candidate_identities or ())
        if index < len(candidate_statements)
        and has_lean_contract_identity(str(identity or "").strip())
    )
    require_identity_match = bool(rendered_helper_identities or candidate_identities)
    for block_index, block in enumerate(rendered_helper_blocks or ()):
        source = str(block or "")
        name = str(helper_decl_name(source) or "").strip()
        if not name:
            continue
        helper_identity = (
            str(rendered_helper_identities[block_index] or "").strip()
            if block_index < len(rendered_helper_identities)
            else ""
        )
        if has_lean_contract_identity(helper_identity):
            helper_parsed_identity = parse_lean_contract_identity(helper_identity)
            for candidate_index, candidate_identity in trusted_candidates:
                candidate_parsed_identity = parse_lean_contract_identity(
                    candidate_identity
                )
                if (
                    helper_parsed_identity is not None
                    and candidate_parsed_identity is not None
                    and helper_parsed_identity[0] == candidate_parsed_identity[0]
                ):
                    return name, str(candidate_statements[candidate_index] or "")
        if require_identity_match:
            continue
        block_statement = exact_source_key(helper_decl_statement(source))
        if block_statement in wanted:
            for candidate in candidate_statements:
                if exact_source_key(candidate) == block_statement:
                    return name, str(candidate or "").strip()
    return "", ""


def _reusable_verified_helper_name(
    rendered_helper_blocks: Sequence[str],
    candidate_statements: Sequence[str],
) -> str:
    return _reusable_verified_helper_match(
        rendered_helper_blocks,
        candidate_statements,
    )[0]


def _rendered_helper_bound_identities(
    rendered_helper_blocks: Sequence[str],
    helper_records: Sequence[Any],
) -> list[str]:
    """Bind rendered blocks to receipts by declaration name *and* statement."""

    identity_by_surface: dict[tuple[str, str], str] = {}
    for helper_record in helper_records or ():
        helper_source = str(getattr(helper_record, "source", "") or helper_record or "")
        helper_name = helper_decl_name(helper_source)
        helper_statement_key = canonical_dossier_statement_key(
            helper_decl_statement(helper_source)
        )
        helper_identity = verified_helper_bound_contract_identity(helper_record)
        if helper_name and helper_statement_key and helper_identity:
            identity_by_surface[(helper_name, helper_statement_key)] = helper_identity
    return [
        identity_by_surface.get(
            (
                helper_decl_name(block),
                canonical_dossier_statement_key(helper_decl_statement(block)),
            ),
            "",
        )
        for block in rendered_helper_blocks or ()
    ]


def _refresh_verified_helper_contract_evidence_from_support_analysis(
    *,
    dossier: Any,
    helper_records: Sequence[Any],
    rendered_helper_blocks: Sequence[str],
    support_statements: Sequence[str],
    coverage: _ContractIdentityCoverage,
) -> int:
    """Bind fresh same-batch Lean identities to replay-verified helpers.

    Proof-cache imports are replay checked in the destination environment but
    can legitimately arrive without historical contract-identity receipts.
    Recursive planning already elaborates every rendered helper statement in
    that same environment.  Preserve that evidence on the durable helper
    record so the receipt-bound reuse gate can recognize the helper instead of
    proving a same-statement alias.  Ambiguous statement-to-identity mappings
    and helpers not verified in the current environment fail closed.
    """

    refresh = getattr(dossier, "refresh_imported_verified_helper_evidence", None)
    environment_hash = str(
        getattr(dossier, "current_lean_environment_hash", "") or ""
    ).strip()
    if not callable(refresh) or not environment_hash:
        return 0

    rendered_helper_surfaces = {
        (
            str(helper_decl_name(block) or "").strip(),
            canonical_dossier_statement_key(helper_decl_statement(block)),
        )
        for block in rendered_helper_blocks or ()
        if str(helper_decl_name(block) or "").strip()
        and canonical_dossier_statement_key(helper_decl_statement(block))
    }

    identities_by_statement_key: dict[str, set[str]] = {}
    for statement, identity in zip(
        support_statements or (),
        coverage.support_structural_identities or (),
    ):
        statement_key = canonical_dossier_statement_key(statement)
        structural_identity = str(identity or "").strip()
        if statement_key and has_lean_contract_identity(structural_identity):
            identities_by_statement_key.setdefault(statement_key, set()).add(
                structural_identity
            )

    refreshed = 0
    for helper in helper_records or ():
        if (
            str(getattr(helper, "verification_environment_hash", "") or "").strip()
            != environment_hash
        ):
            continue
        source = str(getattr(helper, "source", "") or "")
        name = str(
            getattr(helper, "name", "") or helper_decl_name(source) or ""
        ).strip()
        statement_key = canonical_dossier_statement_key(helper_decl_statement(source))
        if (name, statement_key) not in rendered_helper_surfaces:
            continue
        identities = identities_by_statement_key.get(statement_key, set())
        if not name or len(identities) != 1:
            continue
        identity = next(iter(identities))
        if verified_helper_bound_contract_identity(helper) == identity:
            continue
        incoming = clone_verified_helper(helper)
        incoming.contract_identity = identity
        incoming.contract_identity_statement_key = statement_key
        incoming.contract_identity_environment_hash = environment_hash
        incoming.contract_identity_evidence_receipt = (
            make_lean_contract_evidence_receipt(
                identity,
                statement_key,
                environment_hash,
            )
        )
        if bool(refresh(name, incoming)):
            refreshed += 1
    return refreshed


def _ready_root_route_status(
    dossier: ProofDossier,
    root_statement: str,
) -> dict[str, Any]:
    """Return readiness for a proved dependency route without mutating it."""

    graph = getattr(dossier, "proof_graph", None)
    if graph is None:
        return {"ready": False, "verdict": "missing_proof_graph"}
    try:
        status = graph.ready_root_assembly_contract_status(
            target_statement=root_statement,
            mutate=False,
        )
    except Exception:
        return {"ready": False, "verdict": "root_route_status_error"}
    return dict(status or {})


def _root_close_ready_after_helper(
    dossier: ProofDossier,
    root_statement: str,
    accepted_statement: str,
    *,
    active_root_fallback: bool = False,
    active_target_statements: Sequence[str] = (),
) -> bool:
    """Whether a helper changed the terminal root-assembly frontier."""

    del active_root_fallback
    root_targets = tuple(
        dict.fromkeys(
            str(item or "").strip()
            for item in (root_statement, *active_target_statements)
            if str(item or "").strip()
        )
    )
    if any(
        graph_statement_root_equivalent(
            accepted_statement,
            target,
            active_target_statements=root_targets,
        )
        or graph_statement_is_root_bridge(accepted_statement, target)
        for target in root_targets
    ):
        return True
    accepted_key = canonical_dossier_statement_key(accepted_statement)
    if accepted_key == canonical_dossier_statement_key("False"):
        return True
    try:
        accepted_premises, accepted_conclusion, _accepted_bound_names = (
            graph_statement_premises_and_conclusion(accepted_statement)
        )
    except Exception:
        accepted_premises = ()
        accepted_conclusion = accepted_statement
    if not accepted_premises:
        accepted_conjuncts = (
            _split_top_level(
                str(accepted_conclusion or ""),
                "∧",
            )
            or ()
        )
        if len(accepted_conjuncts) >= 2 and any(
            graph_statement_root_equivalent(
                conjunct,
                target,
                active_target_statements=root_targets,
            )
            or graph_statement_is_root_bridge(conjunct, target)
            for conjunct in accepted_conjuncts
            for target in root_targets
        ):
            return True
    for target in root_targets:
        try:
            _premises, conclusion, _bound_names = (
                graph_statement_premises_and_conclusion(target)
            )
        except Exception:
            conclusion = target
        direct_parts = [
            conclusion,
            *(_split_top_level(str(conclusion or ""), "∨") or ()),
        ]
        if accepted_key and any(
            accepted_key == canonical_dossier_statement_key(part)
            for part in direct_parts
        ):
            return True
    return bool(_ready_root_route_status(dossier, root_statement).get("ready"))


def _compact_text(text: str, limit: int = 260) -> str:
    cap = max(40, int(limit or 260))
    return _prompt_safe_inline_text(text, limit=cap)


@lru_cache(maxsize=32)
def _runtime_source_sha256(path_text: str) -> str:
    """Return a stable source receipt without making telemetry authoritative."""

    try:
        return hashlib.sha256(Path(path_text).read_bytes()).hexdigest()
    except (OSError, ValueError):
        return ""


def _contract_identity_runtime_provenance(lean: Any) -> dict[str, Any]:
    """Identify the exact Python sources executing a contract operation."""

    controller_file = str(Path(__file__).resolve())
    try:
        source_file = inspect.getsourcefile(type(lean))
        lean_file = str(Path(source_file).resolve()) if source_file else ""
    except Exception:
        lean_file = ""
    return {
        "python_executable": str(sys.executable or ""),
        "controller_module_file": controller_file,
        "controller_source_sha256": _runtime_source_sha256(controller_file),
        "lean_module_file": lean_file,
        "lean_source_sha256": _runtime_source_sha256(lean_file) if lean_file else "",
    }


def _compact_lean_diagnostic_text(text: str, limit: int = 260) -> str:
    cap = max(40, int(limit or 260))
    return _prompt_safe_lean_diagnostic_text(text, limit=cap)


def _compact_presanitized_text(text: str, limit: int = 260) -> str:
    """Compact text whose fragments were already sanitized individually.

    Per-fragment sanitization is not closed under composition: callers join
    fragments with template punctuation, and a solution reference split across
    that boundary matches nothing in either half while the joined string spells
    it out. Re-check the COMPOSED string for answer references so the split-span
    rules see the text the planner will actually read.

    Only the answer-leak class is re-applied, deliberately. The whole inline
    sanitizer would also re-hide identifiers the caller already vetted and
    intends to show — which is the reason this function exists apart from
    ``_compact_text``. Redacted placeholders do not match the answer patterns,
    so the pass is idempotent on already-clean fragments.
    """

    cap = max(40, int(limit or 260))
    compact = " ".join(str(text or "").split())
    compact = _redact_split_solution_refs_for_prompt(
        _redact_solution_refs_for_prompt(compact)
    )
    # The prompt-control class needs the same join-level treatment. Probed
    # safe against the constraint that motivated the narrowing: the vetted
    # case `unknown identifier '«x-y»'` is returned byte-identical by this
    # redactor, so it costs nothing that the narrowing was protecting.
    compact = _redact_split_prompt_control_text(compact)
    if len(compact) > cap:
        compact = compact[: max(0, cap - 3)].rstrip() + "..."
    return compact


def _add_planner_feedback(
    items: list[str],
    text: str,
    *,
    limit: int = 12,
    prompt_safe: bool = False,
) -> None:
    compact = (
        _compact_presanitized_text(text, 700)
        if prompt_safe
        else _compact_text(text, 700)
    )
    if not compact or compact in items:
        return
    items.append(compact)
    cap = max(1, int(limit or 12))
    # Root-route feedback is a controller contract, not an ordinary rolling
    # diagnostic.  Keep its newest typed entry visible even when a large batch
    # of per-claim Lean failures would otherwise evict it from the FIFO.
    contract_prefixes = (
        "[ROOT_ROUTE_CONTRACT]",
        "[DECOMPOSITION_CONTRACT]",
    )
    route_items = [item for item in items if item.startswith(contract_prefixes)]
    ordinary = [item for item in items if not item.startswith(contract_prefixes)]
    kept_route = [
        matches[-1]
        for prefix in contract_prefixes
        for matches in ([item for item in route_items if item.startswith(prefix)],)
        if matches
    ]
    ordinary_cap = max(0, cap - len(kept_route))
    kept_ordinary = ordinary[-ordinary_cap:] if ordinary_cap else []
    items[:] = kept_ordinary + kept_route


def _add_root_route_feedback(items: list[str], text: str) -> None:
    _add_planner_feedback(items, f"[ROOT_ROUTE_CONTRACT] {text}")


def _add_decomposition_feedback(items: list[str], text: str) -> None:
    _add_planner_feedback(items, f"[DECOMPOSITION_CONTRACT] {text}")


def _unique_nonempty_names(values: Sequence[Any]) -> tuple[str, ...]:
    seen: set[str] = set()
    names: list[str] = []
    for value in values or ():
        name = str(value or "").strip()
        if not name or name in seen:
            continue
        seen.add(name)
        names.append(name)
    return tuple(names)


def _root_route_removed_by_filters(
    *,
    compiled_declared_root_names: Sequence[str],
    compiled_route_identities: AbstractSet[str],
    current_route_identities: AbstractSet[str],
    mismatched_root_names: Sequence[str],
    current_root_route: bool,
    declared_route_names_removed_by_filters: Sequence[str] = (),
) -> bool:
    """Return whether filtering eliminated every executable terminal route."""

    if not compiled_declared_root_names or current_root_route:
        return False
    return bool(
        declared_route_names_removed_by_filters
        or compiled_route_identities - current_route_identities
        or mismatched_root_names
    )


def _declared_root_route_names_removed_by_filters(
    compiled_plan: MiniSubgoalPlan,
    filtered_plan: MiniSubgoalPlan,
    *,
    satisfied_dependency_names: AbstractSet[str] = frozenset(),
) -> tuple[str, ...]:
    """Return declared-root route nodes removed by authoritative filters.

    Surface policy and structural-quality filters run before Lean contract
    identities are attached.  If one of those filters rejects a prerequisite,
    its fixed-point dependency rejection can also remove the declared terminal
    claim.  An identity-set delta cannot witness that loss: neither removed
    claim ever reached canonicalization.  Preserve the compiled declaration as
    the authority for this narrow receipt instead.

    Helper-only plans deliberately return no names.  A dependency already
    supplied by verified support is also not a removed route obligation.
    """

    claims_by_name = {
        str(claim.name or "").strip(): claim
        for claim in compiled_plan.claims
        if str(claim.name or "").strip()
    }
    pending = [
        str(claim.name or "").strip()
        for claim in compiled_plan.claims
        if str(claim.role or "").strip().lower() == "root_assembly"
        and str(claim.name or "").strip()
    ]
    if not pending:
        return ()
    route_names: list[str] = []
    seen: set[str] = set()
    while pending:
        name = pending.pop()
        if not name or name in seen:
            continue
        seen.add(name)
        route_names.append(name)
        claim = claims_by_name.get(name)
        if claim is None:
            continue
        pending.extend(
            dependency_name
            for dependency in tuple(claim.dependencies or ())
            for dependency_name in (str(dependency or "").strip(),)
            if dependency_name in claims_by_name
        )
    surviving_names = {
        str(claim.name or "").strip()
        for claim in filtered_plan.claims
        if str(claim.name or "").strip()
    }
    satisfied_names = {
        str(name or "").strip()
        for name in satisfied_dependency_names
        if str(name or "").strip()
    }
    return tuple(
        name
        for name in route_names
        if name not in surviving_names and name not in satisfied_names
    )


def _plan_has_complete_resolved_root_route(
    plan: MiniSubgoalPlan,
    *,
    active_target_statements: Sequence[str] = (),
    active_target_contract_identities: Sequence[str] = (),
    verified_support_statements: Sequence[str] = (),
    verified_support_structural_identities: Sequence[str] = (),
    verified_support_proof_binder_structural_hashes: Sequence[Sequence[str]] = (),
    verified_support_conclusion_structural_hashes: Sequence[str] = (),
    satisfied_dependency_names: AbstractSet[str] = frozenset(),
) -> bool:
    """Return whether executable resolved claims cover the active frontier."""

    # This predicate runs before the ordinary dependency-contract filter when
    # deciding whether an unresolved alternative may be sidelined.  Root
    # equivalence alone is insufficient there: e.g. ``A → root`` has the same
    # proof-erased contract profile as ``root`` but is not an executable route
    # unless ``A`` is available.  Apply the exact production dependency gate
    # without telemetry/suspension side effects, then use its surviving claims
    # as the only candidates for completeness.
    executable_plan = _filter_plan_dependency_contract(
        plan,
        pass_index=-1,
        record_event=None,
        stats=MiniRecursiveStats(),
        planner_feedback=[],
        verified_support_statements_override=tuple(
            str(statement or "")
            for statement in verified_support_statements
            if str(statement or "").strip()
        ),
        verified_support_structural_identities_override=tuple(
            str(identity or "").strip()
            for identity in verified_support_structural_identities
        ),
        verified_support_proof_binder_structural_hashes_override=tuple(
            tuple(str(value or "").strip() for value in values)
            for values in verified_support_proof_binder_structural_hashes
        ),
        verified_support_conclusion_structural_hashes_override=tuple(
            str(value or "").strip()
            for value in verified_support_conclusion_structural_hashes
        ),
        route_anchor_identities=active_target_contract_identities,
    )
    executable_claims = tuple(executable_plan.claims)
    available_names = {
        str(claim.name or "").strip()
        for claim in executable_claims
        if str(claim.name or "").strip()
    }
    satisfied_names = {
        str(name or "").strip()
        for name in satisfied_dependency_names
        if str(name or "").strip()
    }
    # The dependency-contract filter validates proposition premises but treats
    # unknown declared names as possible dossier helpers.  Completeness has the
    # actual verified-helper name set, so close that intentional abstraction
    # gap here and propagate an absent/filtered dependency through consumers.
    unresolved_names = {
        str(claim.name or "").strip()
        for claim in executable_claims
        if any(
            str(dependency or "").strip()
            and str(dependency or "").strip() not in available_names
            and str(dependency or "").strip() not in satisfied_names
            for dependency in claim.dependencies
        )
    }
    changed = True
    while changed:
        changed = False
        for claim in executable_claims:
            name = str(claim.name or "").strip()
            if not name or name in unresolved_names:
                continue
            if any(
                str(dependency or "").strip() in unresolved_names
                for dependency in claim.dependencies
            ):
                unresolved_names.add(name)
                changed = True
    executable_claims = tuple(
        claim
        for claim in executable_claims
        if str(claim.name or "").strip() not in unresolved_names
    )

    targets = tuple(
        str(statement or "").strip()
        for statement in active_target_statements
        if str(statement or "").strip()
    )
    if not targets:
        return bool(
            _plan_root_assembly_claim_names(
                plan,
                candidate_claims=executable_claims,
                satisfied_dependency_names=frozenset(satisfied_names),
            )
        )
    # Contract identities are positional evidence.  A compacted/partial tuple
    # cannot safely be zipped onto a multi-goal frontier: if only goal 2 has a
    # receipt, ``(goal_2_identity,)`` must never be interpreted as goal 1's
    # identity.  Incomplete evidence therefore falls back to the corresponding
    # target's own surface match; callers that have sparse durable evidence must
    # first restore positions with
    # ``_merge_positional_active_target_contract_identities``.
    identities = tuple(active_target_contract_identities)
    identities_are_positional = len(identities) == len(targets)
    for index, target in enumerate(targets):
        target_identity = str(
            identities[index] if identities_are_positional else ""
        ).strip()
        if not _plan_root_assembly_claim_names(
            plan,
            candidate_claims=executable_claims,
            satisfied_dependency_names=frozenset(satisfied_names),
            active_target_statements=(target,),
            active_target_contract_identities=(
                (target_identity,)
                if has_lean_contract_identity(target_identity)
                else ()
            ),
        ):
            return False
    return True


_LEAN_NEGATED_TARGET_RE = re.compile(r"(?:¬|Not\b)", re.IGNORECASE)
_NAT_EXPECTED_ANGLE_CONSTRUCTOR_RE = re.compile(
    r"Invalid\s+[`']?⟨\.\.\.⟩[`']?\s+notation.*?"
    r"expected\s+type\s+[`']?(?:ℕ|Nat)[`']?",
    re.IGNORECASE | re.DOTALL,
)
_ANGLE_CONSTRUCTOR_PAIR_RE = re.compile(r"⟨\s*([^,⟨⟩]+?)\s*,\s*[^⟨⟩]*?\s*⟩")
_APPLICATION_ARGUMENT_LEFT_DELIMS = set("([{,;:→=<>+-*/^|&!~")


def _lean_compact_key(text: Any) -> str:
    return re.sub(r"\s+", "", str(text or ""))


def _repair_claim_statement_after_type_rejection(
    statement: str,
    diagnostic: str,
) -> tuple[str, str]:
    """Return a mechanically repaired claim statement after type rejection.

    This is deliberately narrow and still Lean-validated by the caller. It
    addresses a common LLM formalization slip: using subtype/``Fin``
    constructor syntax ``⟨n, h⟩`` where the expected argument type is plain
    ``ℕ``. The replacement removes only the proof component and retries with
    the first component as the natural-number term.
    """

    candidates = _repair_claim_statement_candidates_after_type_rejection(
        statement,
        diagnostic,
    )
    return candidates[0] if candidates else ("", "")


def _repair_claim_statement_candidates_after_type_rejection(
    statement: str,
    diagnostic: str,
) -> list[tuple[str, str]]:
    """Return grouped Lean-validated-by-caller statement repair candidates."""

    if not _NAT_EXPECTED_ANGLE_CONSTRUCTOR_RE.search(str(diagnostic or "")):
        return []
    raw = str(statement or "")
    if "⟨" not in raw or "⟩" not in raw:
        return []

    matches = list(_ANGLE_CONSTRUCTOR_PAIR_RE.finditer(raw))
    groups: dict[str, list[re.Match[str]]] = {}
    group_order: list[str] = []
    for match in matches:
        key = _application_group_key(raw, match.start())
        if not key:
            continue
        if key not in groups:
            groups[key] = []
            group_order.append(key)
        groups[key].append(match)

    candidates: list[tuple[str, str]] = []
    seen: set[str] = set()
    candidate_spans: list[set[tuple[int, int]]] = [
        {(match.start(), match.end())}
        for match in matches
        if _application_group_key(raw, match.start())
    ]
    candidate_spans.extend(
        {(match.start(), match.end()) for match in groups.get(key) or []}
        for key in group_order
        if len(groups.get(key) or []) > 1
    )
    for match_spans in candidate_spans:
        if not match_spans:
            continue

        def repl(match: re.Match[str]) -> str:
            if (match.start(), match.end()) not in match_spans:
                return match.group(0)
            return _angle_constructor_value_replacement(match)

        repaired = _ANGLE_CONSTRUCTOR_PAIR_RE.sub(repl, raw)
        repaired = " ".join(repaired.split()).strip()
        if not repaired or repaired == raw or repaired in seen:
            continue
        seen.add(repaired)
        candidates.append((repaired, "nat_expected_angle_constructor_elim"))

    return candidates


def _application_group_key(raw: str, angle_start: int) -> str:
    idx = angle_start
    while idx > 0 and raw[idx - 1].isspace():
        idx -= 1
    if idx <= 0:
        return ""
    left = raw[idx - 1]
    if left in _APPLICATION_ARGUMENT_LEFT_DELIMS:
        return ""
    if left in "')]}" or _is_lean_identifier_char(left):
        end = idx
        start = end
        while start > 0 and _is_lean_identifier_char(raw[start - 1]):
            start -= 1
        return raw[start:end].strip() or left
    return ""


def _is_lean_identifier_char(ch: str) -> bool:
    return ch == "_" or ch == "'" or ch.isalnum()


def _angle_constructor_value_replacement(match: re.Match[str]) -> str:
    value = str(match.group(1) or "").strip()
    if re.fullmatch(r"(?:[^\W\d_]|_)[\w'.]*", value, flags=re.UNICODE):
        return value
    return f"({value})"


def _iter_recursive_child_tool_evidence(conv: Any) -> list[tuple[str, dict, str]]:
    """Return executed tool calls as ``(name, args, result_text)`` triples."""

    pending: dict[str, tuple[str, dict]] = {}
    evidence: list[tuple[str, dict, str]] = []
    for msg in list(getattr(conv, "history", []) or []):
        if not isinstance(msg, dict):
            continue
        role = msg.get("role")
        if role == "assistant":
            for tool_call in list(msg.get("tool_calls") or []):
                if not isinstance(tool_call, dict):
                    continue
                tcid = str(tool_call.get("id", "") or "").strip()
                fn = tool_call.get("function") or {}
                name = str(fn.get("name", "") or "").strip()
                raw_args = str(fn.get("arguments", "{}") or "{}")
                try:
                    args = json.loads(raw_args)
                except Exception:
                    args = {}
                if tcid:
                    pending[tcid] = (name, args if isinstance(args, dict) else {})
        elif role == "tool":
            tcid = str(msg.get("tool_call_id", "") or "").strip()
            if not tcid:
                continue
            name, args = pending.get(tcid, ("", {}))
            evidence.append((name, args, str(msg.get("content", "") or "")))
    return evidence


def _accepted_try_lean_negates_statement(code: Any, statement: str) -> bool:
    code_text = str(code or "")
    statement_text = str(statement or "").strip()
    if not code_text.strip() or not statement_text:
        return False
    cleaned_code = strip_lean_comments(code_text)
    if _checked_evidence_code_has_ambient_context(cleaned_code):
        return False
    if _checked_evidence_code_has_proof_placeholder(cleaned_code):
        return False
    if not (
        _LEAN_NEGATED_TARGET_RE.search(cleaned_code)
        or "∃" in cleaned_code
        or re.search(r"\bexists\b", cleaned_code)
        or re.search(r"\bExists\b", cleaned_code)
        or ("False" in cleaned_code and ("→" in cleaned_code or "->" in cleaned_code))
    ):
        return False
    statement_key = _lean_compact_key(statement_text)
    if not statement_key:
        return False
    return any(
        _checked_evidence_target_refutes_statement(
            target, statement_text, statement_key
        )
        for target in _iter_checked_lean_target_headers(cleaned_code)
    )


def _checked_evidence_target_refutes_statement(
    target: Any,
    statement_text: str,
    statement_key: str,
) -> bool:
    return bool(
        _lean_target_negates_statement(target, statement_key, statement_text)
        or _lean_target_implication_to_false_refutes_statement(target, statement_text)
        or _lean_counterexample_target_refutes_statement(target, statement_text)
    )


def _checked_evidence_code_has_ambient_context(code: str) -> bool:
    """Reject scratch evidence that can prove negations from ambient state.

    Checked invalidity evidence must be a closed proof of the target shape.
    Local syntax/extensions can change the meaning of the statement under test,
    just like local hypotheses/constants can manufacture a negation.
    """

    raw = str(code or "")
    blocked_keywords = {
        "abbrev",
        "axiom",
        "axioms",
        "class",
        "constant",
        "constants",
        "def",
        "declare_syntax_cat",
        "elab",
        "elab_rules",
        "end",
        "export",
        "include",
        "inductive",
        "infix",
        "infixl",
        "infixr",
        "instance",
        "local",
        "macro",
        "macro_rules",
        "mixfix",
        "namespace",
        "noncomputable",
        "notation",
        "omit",
        "postfix",
        "prefix",
        "reserve",
        "scoped",
        "section",
        "structure",
        "syntax",
        "term_elab",
        "universe",
        "universes",
        "variable",
        "variables",
    }
    index = 0
    while index < len(raw):
        skip_to = _lean_surface_lexical_skip_end(raw, index)
        if skip_to is not None:
            index = skip_to
            continue
        for keyword in blocked_keywords:
            if _surface_keyword_at(raw, index, keyword):
                return True
        index += 1
    return False


def _checked_evidence_code_has_proof_placeholder(code: str) -> bool:
    """Reject warning-accepted Lean evidence that depends on placeholders."""

    raw = str(code or "")
    blocked_keywords = {"admit", "sorry", "sorryAx", "syntheticSorry"}
    index = 0
    while index < len(raw):
        skip_to = _lean_surface_lexical_skip_end(raw, index)
        if skip_to is not None:
            index = skip_to
            continue
        for keyword in blocked_keywords:
            if _surface_identifier_atom_at(raw, index, keyword):
                return True
        index += 1
    return False


def _checked_evidence_result_has_proof_placeholder_warning(result_text: Any) -> bool:
    """Lean accepts placeholder-backed declarations with a warning."""

    lowered = str(result_text or "").lower()
    return bool(
        "declaration uses 'sorry'" in lowered
        or 'declaration uses "sorry"' in lowered
        or "declaration uses sorry" in lowered
    )


def _surface_identifier_atom_at(text: str, index: int, token: str) -> bool:
    raw = str(text or "")
    atom = str(token or "")
    if not atom or not raw.startswith(atom, index):
        return False
    before_ok = index == 0 or not (raw[index - 1].isalnum() or raw[index - 1] in "_'")
    after = index + len(atom)
    after_ok = after >= len(raw) or not (raw[after].isalnum() or raw[after] in "_'")
    return before_ok and after_ok


def _lean_target_negates_statement(
    target: Any,
    statement_key: str,
    statement_text: str = "",
) -> bool:
    target_text = _strip_balanced_outer_parens(str(target or ""))
    target_key = _lean_compact_key(target_text)
    if not target_key or not statement_key:
        return False
    if (
        target_key == f"¬({statement_key})"
        or target_key == f"¬{statement_key}"
        or target_key == f"Not({statement_key})"
        or target_key == f"Not{statement_key}"
    ):
        return True
    negated_inner = _top_level_negated_inner(target_text)
    return bool(
        negated_inner
        and statement_text
        and _contract_alpha_matches(negated_inner, statement_text)
    )


def _lean_target_implication_to_false_refutes_statement(
    target: Any,
    statement_text: str,
) -> bool:
    target_text = _strip_balanced_outer_parens(str(target or ""))
    parts = _split_top_level_implications(target_text)
    if len(parts) != 2:
        return False
    premise, conclusion = parts
    return bool(
        _strip_balanced_outer_parens(conclusion) == "False"
        and statement_text
        and _contract_alpha_matches(premise, statement_text)
    )


def _strip_leading_exists_binders_with_names_and_premises(
    text: str,
) -> tuple[str, tuple[str, ...], tuple[str, ...]]:
    body, names, premises, _proof_binder_names = _strip_leading_exists_binder_analysis(
        text
    )
    return body, names, premises


def _exists_binder_chunk_analysis(
    binder_chunk: str,
) -> tuple[tuple[str, ...], tuple[str, ...], tuple[str, ...]]:
    names: list[str] = []
    premises: list[str] = []
    proof_binder_names: list[str] = []
    for binder_group in _binder_group_chunks(binder_chunk):
        explicit_names = list(_binder_names_from_chunk(binder_group))
        relation_names = list(lean_relation_binder_bound_names(binder_group))
        group_premises = list(_binder_premises_from_chunk(binder_group))
        names.extend(explicit_names)
        names.extend(relation_names)
        premises.extend(group_premises)
        if explicit_names and group_premises:
            proof_binder_names.extend(explicit_names[-len(group_premises) :])
    return (
        tuple(dict.fromkeys(names)),
        tuple(dict.fromkeys(premises)),
        tuple(dict.fromkeys(proof_binder_names)),
    )


def _strip_leading_exists_binder_analysis(
    text: str,
) -> tuple[str, tuple[str, ...], tuple[str, ...], tuple[str, ...]]:
    s = _strip_balanced_outer_parens(str(text or "").strip())
    names: list[str] = []
    premises: list[str] = []
    proof_binder_names: list[str] = []
    while True:
        (
            prefix_body,
            prefix_names,
            prefix_premises,
            prefix_proof_binder_names,
        ) = _strip_prefix_exists_fun_analysis(s)
        if prefix_body:
            names.extend(prefix_names)
            premises.extend(prefix_premises)
            proof_binder_names.extend(prefix_proof_binder_names)
            s = prefix_body
            continue
        quantifier_match = re.match(r"^(?:∃|exists\b)\s*", s)
        if quantifier_match is None:
            break
        comma = _find_top_level_comma(s)
        if comma < 0:
            break
        binder_chunk = s[quantifier_match.end() : comma]
        chunk_names, chunk_premises, chunk_proof_names = _exists_binder_chunk_analysis(
            binder_chunk
        )
        names.extend(chunk_names)
        premises.extend(chunk_premises)
        proof_binder_names.extend(chunk_proof_names)
        s = _strip_balanced_outer_parens(s[comma + 1 :])
    return (
        s,
        tuple(dict.fromkeys(names)),
        tuple(dict.fromkeys(premises)),
        tuple(dict.fromkeys(proof_binder_names)),
    )


def _strip_prefix_exists_fun(text: str) -> tuple[str, tuple[str, ...], tuple[str, ...]]:
    body, names, premises, _proof_binder_names = _strip_prefix_exists_fun_analysis(text)
    return body, names, premises


def _strip_prefix_exists_fun_surface(text: str) -> tuple[str, str]:
    """Return the raw binder telescope and body of `Exists (fun ... => ...)`."""

    raw = _strip_balanced_outer_parens(str(text or "").strip())
    if not raw.startswith("Exists"):
        return "", ""
    tail = raw[len("Exists") :].strip()
    if _surface_starts_with_keyword(tail, "fun"):
        inner = tail
    elif tail.startswith("("):
        end = _matching_surface_group_index(tail, 0)
        if end < 0 or tail[end + 1 :].strip():
            return "", ""
        inner = _strip_balanced_outer_parens(tail[1:end].strip())
    else:
        return "", ""
    if not _surface_starts_with_keyword(inner, "fun"):
        return "", ""
    arrow = _alias_lambda_arrow_index(inner, 0)
    if arrow < 0:
        return "", ""
    binder_chunk = inner[len("fun") : arrow].strip()
    body = _strip_balanced_outer_parens(inner[arrow + 2 :].strip())
    return binder_chunk, body


def _strip_prefix_exists_fun_analysis(
    text: str,
) -> tuple[str, tuple[str, ...], tuple[str, ...], tuple[str, ...]]:
    binder_chunk, body = _strip_prefix_exists_fun_surface(text)
    if not binder_chunk or not body:
        return "", (), (), ()
    names, premises, proof_binder_names = _exists_binder_chunk_analysis(binder_chunk)
    return body, names, premises, proof_binder_names


def _strip_leading_exists_binders_with_names(text: str) -> tuple[str, tuple[str, ...]]:
    s, names, _premises = _strip_leading_exists_binders_with_names_and_premises(text)
    return s, names


def _strip_leading_lean_negation(text: str) -> str:
    """Return the inner of a top-level ``¬``/``Not`` negation, else ``""``.

    Handles ``¬P``, ``Not P`` and ``Not(P)`` uniformly — the ``Not`` keyword
    followed by ``(`` or whitespace, not a longer identifier like ``Nothing``.
    """

    compact = str(text or "").strip()
    if compact.startswith("¬"):
        return compact[1:].strip()
    if compact.startswith("Not"):
        rest = compact[3:]
        if not rest or not (rest[0].isalnum() or rest[0] in "_'"):
            return rest.strip()
    return ""


def _top_level_negated_inner(text: str) -> str:
    compact = _strip_balanced_outer_parens(str(text or "").strip())
    inner = _strip_leading_lean_negation(compact)
    if not inner:
        return ""
    raw_inner = inner.strip()
    if raw_inner.startswith("("):
        group_end = _matching_surface_group_index(raw_inner, 0)
        if group_end == len(raw_inner) - 1:
            return _strip_balanced_outer_parens(raw_inner)
    # Lean negation binds more tightly than these connectives. Thus `¬ P ∨ Q`
    # negates only P, while `¬ (P ∨ Q)` (handled above) negates the group.
    # Do not widen an ungrouped prefix negation to the remaining formula.
    if (
        len(_split_top_level_conjunctions(raw_inner)) > 1
        or len(_split_top_level_disjunctions(raw_inner)) > 1
        or len(_split_top_level_implications(raw_inner)) > 1
        or len(_split_top_level_iffs(raw_inner)) > 1
    ):
        return ""
    return _strip_balanced_outer_parens(raw_inner)


def _split_top_level_relation(
    text: str,
    operators: Sequence[str] = (
        "!=",
        "<=",
        ">=",
        "≠",
        "≤",
        "≥",
        "∉",
        "∈",
        "∤",
        "∣",
        "=",
        "<",
        ">",
    ),
) -> tuple[str, str, str]:
    raw = _strip_balanced_outer_parens(str(text or "").strip())
    depth = 0
    index = 0
    ordered_operators = tuple(sorted(operators, key=len, reverse=True))
    while index < len(raw):
        skip_to = _lean_surface_lexical_skip_end(raw, index)
        if skip_to is not None:
            index = skip_to
            continue
        ch = raw[index]
        if ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE:
            depth += 1
        elif ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE.values():
            depth = max(0, depth - 1)
        elif depth == 0:
            for operator in ordered_operators:
                if not raw.startswith(operator, index):
                    continue
                if operator == "=" and index > 0 and raw[index - 1] in "!<>:":
                    continue
                left = raw[:index].strip()
                right = raw[index + len(operator) :].strip()
                if left and right:
                    return left, operator, right
        index += 1
    return "", "", ""


def _relations_are_negations(
    candidate: str,
    conclusion: str,
    *,
    candidate_bound_names: Sequence[str] = (),
    conclusion_bound_names: Sequence[str] = (),
) -> bool:
    candidate_left, candidate_operator, candidate_right = _split_top_level_relation(
        candidate
    )
    conclusion_left, conclusion_operator, conclusion_right = _split_top_level_relation(
        conclusion
    )
    if not candidate_operator or not conclusion_operator:
        return False
    canonical_operator = {
        "≠": "!=",
        "≤": "<=",
        "≥": ">=",
    }
    conclusion_operator = canonical_operator.get(
        conclusion_operator, conclusion_operator
    )
    candidate_operator = canonical_operator.get(candidate_operator, candidate_operator)
    complements = {
        "=": "!=",
        "!=": "=",
        "<": ">=",
        ">=": "<",
        "<=": ">",
        ">": "<=",
        "∈": "∉",
        "∉": "∈",
        "∣": "∤",
        "∤": "∣",
    }
    reverse_operator = {
        "<": ">",
        ">": "<",
        "<=": ">=",
        ">=": "<=",
        "=": "=",
        "!=": "!=",
    }
    expected_complement = complements.get(conclusion_operator)
    if expected_complement not in {
        candidate_operator,
        reverse_operator.get(candidate_operator),
    }:
        return False

    def sides_match(left_a: str, right_a: str, left_b: str, right_b: str) -> bool:
        return bool(
            _contract_alpha_matches(
                left_a,
                left_b,
                left_bound_names=candidate_bound_names,
                right_bound_names=conclusion_bound_names,
            )
            and _contract_alpha_matches(
                right_a,
                right_b,
                left_bound_names=candidate_bound_names,
                right_bound_names=conclusion_bound_names,
            )
        )

    if candidate_operator == expected_complement and sides_match(
        candidate_left,
        candidate_right,
        conclusion_left,
        conclusion_right,
    ):
        return True
    # Order comparisons may be written with their operands reversed, e.g.
    # ``10 < n`` is the negation of ``n ≤ 10``. Membership and divisibility
    # are directional predicates and must never be reversed this way.
    return bool(
        reverse_operator.get(candidate_operator) == expected_complement
        and sides_match(
            candidate_left,
            candidate_right,
            conclusion_right,
            conclusion_left,
        )
    )


def _formula_alpha_matches_any(
    formula: str,
    candidates: Sequence[str],
    *,
    formula_bound_names: Sequence[str],
    candidate_bound_names: Sequence[str],
) -> bool:
    return any(
        _contract_alpha_matches(
            formula,
            candidate,
            left_bound_names=formula_bound_names,
            right_bound_names=candidate_bound_names,
        )
        or _relations_are_equivalent(
            formula,
            candidate,
            left_bound_names=formula_bound_names,
            right_bound_names=candidate_bound_names,
        )
        for candidate in candidates
    )


def _relations_are_equivalent(
    left: str,
    right: str,
    *,
    left_bound_names: Sequence[str] = (),
    right_bound_names: Sequence[str] = (),
) -> bool:
    left_lhs, left_op, left_rhs = _split_top_level_relation(
        left,
        operators=(
            "!=",
            "≠",
            "<=",
            ">=",
            "≤",
            "≥",
            "∉",
            "∈",
            "∤",
            "∣",
            "=",
            "<",
            ">",
        ),
    )
    right_lhs, right_op, right_rhs = _split_top_level_relation(
        right,
        operators=(
            "!=",
            "≠",
            "<=",
            ">=",
            "≤",
            "≥",
            "∉",
            "∈",
            "∤",
            "∣",
            "=",
            "<",
            ">",
        ),
    )
    if not left_op or not right_op:
        return False
    # Canonicalize Unicode/ASCII spellings so ``≤``≡``<=`` etc., then compare by
    # direction.  Every relation matches itself same-direction (the old set only
    # covered ``=``/``≠``), and each strict/loose pair has a reverse partner.
    _rel_canon = {"≤": "<=", "≥": ">=", "≠": "!="}
    _rel_reverse = {
        "<": ">",
        ">": "<",
        "<=": ">=",
        ">=": "<=",
        "=": "=",
        "!=": "!=",
    }
    left_canon = _rel_canon.get(left_op, left_op)
    right_canon = _rel_canon.get(right_op, right_op)
    same_direction = {
        (op, op) for op in ("=", "!=", "<", ">", "<=", ">=", "∈", "∉", "∣", "∤")
    }
    reverse_direction = {(op, rev) for op, rev in _rel_reverse.items()}
    if (left_canon, right_canon) in same_direction:
        if _contract_alpha_matches(
            left_lhs,
            right_lhs,
            left_bound_names=left_bound_names,
            right_bound_names=right_bound_names,
        ) and _contract_alpha_matches(
            left_rhs,
            right_rhs,
            left_bound_names=left_bound_names,
            right_bound_names=right_bound_names,
        ):
            return True
    if (left_canon, right_canon) in reverse_direction:
        return bool(
            _contract_alpha_matches(
                left_lhs,
                right_rhs,
                left_bound_names=left_bound_names,
                right_bound_names=right_bound_names,
            )
            and _contract_alpha_matches(
                left_rhs,
                right_lhs,
                left_bound_names=left_bound_names,
                right_bound_names=right_bound_names,
            )
        )
    return False


def _formula_implies_false_negates(
    candidate: str,
    conclusion: str,
    *,
    candidate_bound_names: Sequence[str],
    conclusion_bound_names: Sequence[str],
) -> bool:
    parts = _split_top_level_implications(str(candidate or ""))
    if len(parts) != 2:
        return False
    premise, false_conclusion = parts
    return bool(
        _strip_balanced_outer_parens(false_conclusion) == "False"
        and _contract_alpha_matches(
            premise,
            conclusion,
            left_bound_names=candidate_bound_names,
            right_bound_names=conclusion_bound_names,
        )
    )


def _flatten_conjunction_formulas(text: str) -> tuple[str, ...]:
    body = _strip_balanced_outer_parens(str(text or "").strip())
    if not body:
        return ()
    parts = _split_top_level_conjunctions(body)
    if len(parts) <= 1 and (not parts or parts[0] == body):
        return (body,)
    flattened: list[str] = []
    for part in parts:
        flattened.extend(_flatten_conjunction_formulas(part))
    return tuple(item for item in flattened if item)


def _counterexample_body_refutes_statement(
    target_body: str,
    *,
    premises: Sequence[str],
    conclusion: str,
    target_bound_names: Sequence[str],
    statement_bound_names: Sequence[str],
    target_premises: Sequence[str] = (),
) -> bool:
    conjuncts = _flatten_conjunction_formulas(target_body)
    normalized_conclusion = _strip_balanced_outer_parens(conclusion)
    positive_candidates = list(conjuncts)
    for premise in target_premises:
        positive_candidates.extend(_flatten_conjunction_formulas(premise))

    def evidence_proves(formula: str, facts: Sequence[str]) -> bool:
        normalized = _strip_balanced_outer_parens(formula)
        if _formula_alpha_matches_any(
            normalized,
            facts,
            formula_bound_names=statement_bound_names,
            candidate_bound_names=target_bound_names,
        ):
            return True
        conjunction = tuple(_split_top_level_conjunctions(normalized))
        if len(conjunction) > 1:
            return all(evidence_proves(part, facts) for part in conjunction)
        disjunction = tuple(_split_top_level_disjunctions(normalized))
        return bool(
            len(disjunction) > 1
            and any(evidence_proves(part, facts) for part in disjunction)
        )

    def atomic_refutation(formula: str, facts: Sequence[str]) -> bool:
        return any(
            bool(
                (
                    (inner := _top_level_negated_inner(fact))
                    and _contract_alpha_matches(
                        inner,
                        formula,
                        left_bound_names=target_bound_names,
                        right_bound_names=statement_bound_names,
                    )
                )
                or _relations_are_negations(
                    fact,
                    formula,
                    candidate_bound_names=target_bound_names,
                    conclusion_bound_names=statement_bound_names,
                )
                or _formula_implies_false_negates(
                    fact,
                    formula,
                    candidate_bound_names=target_bound_names,
                    conclusion_bound_names=statement_bound_names,
                )
            )
            for fact in facts
        )

    def evidence_refutes(formula: str, facts: Sequence[str]) -> bool:
        normalized = _strip_balanced_outer_parens(formula)
        # A disjunctive witness fact is usable only if every possible branch
        # refutes the conclusion. This recursively implements the Boolean
        # polarity contract without pretending to know which branch holds.
        for index, fact in enumerate(facts):
            branches = tuple(_split_top_level_disjunctions(fact))
            if len(branches) > 1:
                remaining = [*facts[:index], *facts[index + 1 :]]
                return all(
                    evidence_refutes(
                        normalized,
                        [*remaining, *_flatten_conjunction_formulas(branch)],
                    )
                    for branch in branches
                )
        if any(
            bool(
                (
                    (inner := _top_level_negated_inner(fact))
                    and _contract_alpha_matches(
                        inner,
                        normalized,
                        left_bound_names=target_bound_names,
                        right_bound_names=statement_bound_names,
                    )
                )
                or _formula_implies_false_negates(
                    fact,
                    normalized,
                    candidate_bound_names=target_bound_names,
                    conclusion_bound_names=statement_bound_names,
                )
            )
            for fact in facts
        ):
            # Exact negation of the whole formula outranks decomposition:
            # `¬(A ∧ B)` refutes the conjunction even if neither `¬A` nor
            # `¬B` is separately available. Prefix precedence is enforced by
            # `_top_level_negated_inner` before reaching this branch.
            return True
        if normalized == "False":
            return True
        iff_parts = tuple(_split_top_level_iffs(normalized))
        if len(iff_parts) == 2:
            left, right = iff_parts
            return bool(
                (evidence_proves(left, facts) and evidence_refutes(right, facts))
                or (evidence_proves(right, facts) and evidence_refutes(left, facts))
            )
        implication = tuple(_split_top_level_implications(normalized))
        if len(implication) == 2:
            premise, consequent = implication
            # A witness refutes A → B exactly when its facts establish A
            # and refute B. The `B = False` case is naturally included.
            return bool(
                evidence_proves(premise, facts) and evidence_refutes(consequent, facts)
            )
        disjunction = tuple(_split_top_level_disjunctions(normalized))
        if len(disjunction) > 1:
            return all(evidence_refutes(part, facts) for part in disjunction)
        conjunction = tuple(_split_top_level_conjunctions(normalized))
        if len(conjunction) > 1:
            return any(evidence_refutes(part, facts) for part in conjunction)
        negated_inner = _top_level_negated_inner(normalized)
        if negated_inner:
            return evidence_proves(negated_inner, facts)
        return atomic_refutation(normalized, facts)

    if not evidence_refutes(normalized_conclusion, positive_candidates):
        return False
    for premise in premises:
        if not evidence_proves(premise, positive_candidates):
            return False
    return True


def _canonical_nonproof_parameter_profile(statement: str) -> tuple[str, ...]:
    """Return a surface parameter profile with standard Lean aliases unified."""

    from .mini_lean_extract import (
        _strip_lean_comments,
        _strip_lean_comments_and_strings,
    )

    aliases = {"ℕ": "Nat", "ℤ": "Int", "ℚ": "Rat", "ℝ": "Real"}
    alias_pattern = re.compile(r"(?<![\w'.«»])([ℕℤℚℝ])(?![\w'.«»])")
    masked_statement = _mask_lean_quoted_identifiers(
        _strip_lean_comments_and_strings(statement)
    )

    def replace_alias(match: re.Match[str]) -> str:
        if masked_statement[match.start() : match.end()] != match.group(0):
            return match.group(0)
        return aliases[match.group(1)]

    statement = alias_pattern.sub(
        replace_alias,
        statement,
    )
    statement = _strip_lean_comments(statement)

    def canonicalize(marker: str) -> str:
        numeric_sort = re.fullmatch(r"Sort(\d+)", marker)
        if numeric_sort is not None:
            level = int(numeric_sort.group(1))
            if level == 0:
                return "Prop"
            return "Type" if level == 1 else f"Type{level - 1}"
        numeric_type = re.fullmatch(r"Type(\d+)", marker)
        if numeric_type is not None and int(numeric_type.group(1)) == 0:
            return "Type"
        parenthesized_type = re.fullmatch(r"Type\((.+)\)", marker)
        if parenthesized_type is not None:
            level = _strip_balanced_outer_parens(parenthesized_type.group(1))
            return canonicalize(f"Type{level}")
        successor_sort = re.fullmatch(r"Sort\((.+)\+1\)", marker)
        if successor_sort is not None:
            level = _strip_balanced_outer_parens(successor_sort.group(1))
            return canonicalize(f"Type{level}")
        return marker

    return tuple(
        canonicalize(marker)
        for marker in graph_statement_nonproof_parameter_profile(statement)
    )


def _lean_counterexample_target_refutes_statement(
    target: Any,
    statement: str,
    *,
    allow_inferred_relation_binders: bool = False,
) -> bool:
    premises, conclusion, statement_bound_names = _statement_premises_and_conclusion(
        str(statement or "")
    )
    if not conclusion or not statement_bound_names:
        return False
    target_profile_tail = _strip_balanced_outer_parens(str(target or ""))
    target_profile_prefixes: list[str] = []
    target_profile_has_inferred_relation_binder = False
    while True:
        quantifier_match = re.match(
            r"^(?:∃|exists\b)\s*",
            target_profile_tail,
        )
        if quantifier_match is not None:
            comma = _find_top_level_comma(target_profile_tail)
            if comma < 0:
                break
            binder_chunk = target_profile_tail[quantifier_match.end() : comma]
            next_tail = target_profile_tail[comma + 1 :]
        else:
            binder_chunk, next_tail = _strip_prefix_exists_fun_surface(
                target_profile_tail
            )
            if not binder_chunk or not next_tail:
                break
        if _top_level_colon_index(binder_chunk) < 0 and lean_relation_binder_premise(
            binder_chunk
        ):
            # `∃ n > 0, ...` leaves `n`'s type to Lean inference, so it
            # cannot contribute a surface domain marker. Treat that missing
            # marker as unknown rather than as a mismatch; explicit Int/Nat
            # (and other known-domain) mismatches remain fail-closed below.
            target_profile_has_inferred_relation_binder = True
        target_profile_prefixes.append(f"∀ {binder_chunk}, ")
        target_profile_tail = _strip_balanced_outer_parens(next_tail)
    target_profile_statement = "".join(target_profile_prefixes) + target_profile_tail

    target_parameter_profile = _canonical_nonproof_parameter_profile(
        target_profile_statement
    )
    statement_parameter_profile = _canonical_nonproof_parameter_profile(
        str(statement or "")
    )
    if target_parameter_profile != statement_parameter_profile:
        if not (
            allow_inferred_relation_binders
            and target_profile_has_inferred_relation_binder
            and not target_parameter_profile
        ):
            return False
    if (
        allow_inferred_relation_binders
        and target_profile_has_inferred_relation_binder
        and not target_parameter_profile
    ):
        if graph_statement_explicit_arity(
            target_profile_statement,
            exclude_proof_binders=True,
        ) != len(statement_parameter_profile):
            return False
    target_body, target_bound_names, target_premises = (
        _strip_leading_exists_binders_with_names_and_premises(str(target or ""))
    )
    if not target_bound_names or not target_body:
        return False
    if _counterexample_body_refutes_statement(
        target_body,
        premises=premises,
        conclusion=conclusion,
        target_bound_names=target_bound_names,
        statement_bound_names=statement_bound_names,
        target_premises=target_premises,
    ):
        return True
    return False


def _top_level_body_separator_index(text: str) -> int:
    raw = str(text or "")
    depth = 0
    index = 0
    while index < len(raw):
        skip_to = _lean_surface_lexical_skip_end(raw, index)
        if skip_to is not None:
            index = skip_to
            continue
        ch = raw[index]
        if ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE:
            depth += 1
        elif ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE.values():
            depth = max(0, depth - 1)
        elif depth == 0 and raw.startswith(":=", index):
            return index
        index += 1
    return len(raw)


def _last_top_level_colon_index(text: str) -> int:
    raw = str(text or "")
    depth = 0
    last = -1
    index = 0
    while index < len(raw):
        skip_to = _lean_surface_lexical_skip_end(raw, index)
        if skip_to is not None:
            index = skip_to
            continue
        ch = raw[index]
        if ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE:
            depth += 1
        elif ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE.values():
            depth = max(0, depth - 1)
        elif ch == ":" and depth == 0:
            last = index
        index += 1
    return last


def _lean_declaration_prefix_has_parameters(prefix: str) -> bool:
    raw = str(prefix or "").strip()
    if not raw:
        return False
    match = re.match(r"^(example|lemma|theorem)\b(?P<tail>[\s\S]*)$", raw)
    if match is None:
        return True
    keyword = str(match.group(1) or "")
    tail = str(match.group("tail") or "").strip()
    if keyword in {"lemma", "theorem"}:
        name_match = re.match(r"(?:«[^»]+»|[A-Za-z_][A-Za-z0-9_'.]*)", tail)
        if name_match is None:
            return True
        tail = tail[name_match.end() :].strip()
    return bool(tail)


def _iter_surface_keyword_positions(text: str, keyword: str) -> tuple[int, ...]:
    raw = str(text or "")
    positions: list[int] = []
    index = 0
    while index < len(raw):
        skip_to = _lean_surface_lexical_skip_end(raw, index)
        if skip_to is not None:
            index = skip_to
            continue
        if _surface_keyword_at(raw, index, keyword):
            positions.append(index)
            index += len(keyword)
            continue
        index += 1
    return tuple(positions)


def _iter_checked_lean_target_headers(code: Any) -> tuple[str, ...]:
    raw = str(code or "")
    targets: list[str] = []
    declaration_positions = sorted(
        {
            *list(_iter_surface_keyword_positions(raw, "example")),
            *list(_iter_surface_keyword_positions(raw, "lemma")),
            *list(_iter_surface_keyword_positions(raw, "theorem")),
        }
    )
    for start in declaration_positions:
        header_end = _top_level_body_separator_index(raw[start:])
        header = raw[start : start + header_end]
        colon = _top_level_colon_index(header)
        if colon < 0 or _lean_declaration_prefix_has_parameters(header[:colon]):
            continue
        target = header[colon + 1 :].strip()
        if target:
            targets.append(target)
    return tuple(targets)


def _recursive_claim_invalidity_has_checked_evidence(
    conv: Any,
    statement: str,
    *,
    dossier: Any = None,
) -> bool:
    """Accept child invalidation only with an accepted Lean negation check."""

    for name, args, result_text in _iter_recursive_child_tool_evidence(conv):
        if name not in {"try_lean", "certify_counterexample"}:
            continue
        accepted_prefix = (
            "try_lean accepted."
            if name == "try_lean"
            else "certify_counterexample accepted."
        )
        if not str(result_text or "").lstrip().startswith(accepted_prefix):
            continue
        if _checked_evidence_result_has_proof_placeholder_warning(result_text):
            continue
        if name == "certify_counterexample":
            certificate_match = re.search(
                r"\bcertificate=([0-9a-f]{64})\b",
                str(result_text or ""),
            )
            certificate_hash = certificate_match.group(1) if certificate_match else ""
            target_environment_hash = str(
                getattr(dossier, "current_lean_environment_hash", "") or ""
            ).strip()
            authorities = dict(
                getattr(dossier, "mini_authoritative_negations", {}) or {}
            )
            if (
                certificate_hash
                and target_environment_hash
                and any(
                    isinstance(authority, Mapping)
                    and str(authority.get("certificate_hash") or "").strip()
                    == certificate_hash
                    and str(authority.get("statement") or "").strip()
                    == str(statement or "").strip()
                    and str(authority.get("target_environment_hash") or "").strip()
                    == target_environment_hash
                    for authority in authorities.values()
                )
            ):
                return True
            continue
        if _accepted_try_lean_negates_statement(args.get("code", ""), statement):
            return True
    return False


def _negation_proof_body_for_statement(
    cleaned: str,
    statement_text: str,
    statement_key: str,
) -> str:
    """Return the proof body of the declaration whose target directly negates
    the statement, bounded to that single declaration.

    A multi-declaration block (e.g. a helper ``lemma h : … := …`` followed by
    ``example : ¬goal := …``) must NOT read the negation body from the first
    top-level ``:=`` in the whole block — that splices the helper's body onto the
    negation proof and yields a malformed, uncertifiable body.
    """

    declaration_positions = sorted(
        {
            *_iter_surface_keyword_positions(cleaned, "example"),
            *_iter_surface_keyword_positions(cleaned, "lemma"),
            *_iter_surface_keyword_positions(cleaned, "theorem"),
        }
    )
    for position, start in enumerate(declaration_positions):
        end = (
            declaration_positions[position + 1]
            if position + 1 < len(declaration_positions)
            else len(cleaned)
        )
        decl = cleaned[start:end]
        header_end = _top_level_body_separator_index(decl)
        if header_end >= len(decl) or not decl.startswith(":=", header_end):
            continue
        header = decl[:header_end]
        colon = _top_level_colon_index(header)
        if colon < 0 or _lean_declaration_prefix_has_parameters(header[:colon]):
            continue
        target = header[colon + 1 :].strip()
        if not _lean_target_negates_statement(target, statement_key, statement_text):
            continue
        body = decl[header_end + 2 :].strip()
        if body:
            return body
    return ""


def _recursive_claim_negation_proof_candidates(
    conv: Any,
    statement: str,
) -> tuple[str, ...]:
    """Extract closed direct-negation proof bodies from accepted child checks."""

    proofs: list[str] = []
    statement_text = str(statement or "").strip()
    for name, args, result_text in _iter_recursive_child_tool_evidence(conv):
        code = str(args.get("code") or "").strip()
        if name not in {"try_lean", "certify_counterexample"} or not code:
            continue
        accepted_prefix = (
            "try_lean accepted."
            if name == "try_lean"
            else "certify_counterexample accepted."
        )
        if not str(result_text or "").lstrip().startswith(accepted_prefix):
            continue
        cleaned = strip_lean_comments(code).strip()
        if name == "certify_counterexample" and cleaned.lstrip().startswith("by"):
            proofs.append(cleaned)
            continue
        if not _accepted_try_lean_negates_statement(code, statement):
            continue
        from ensemble_prover.mini_session.child_goal_falsification import (
            counterexample_negation_proof_from_declaration,
        )

        body = counterexample_negation_proof_from_declaration(
            cleaned,
            statement_text,
        )
        if body:
            proofs.append(body)
    return tuple(dict.fromkeys(proofs))


def _render_recursive_child_obligation_contract(
    *,
    statement: str,
    helper_name: str,
) -> str:
    safe_helper = _prompt_safe_helper_name(helper_name)
    return (
        "Typed recursive proof obligation. Prove the formal target currently "
        "shown in the Lean signature; use the original theorem only as "
        "orientation for why this obligation matters. The controller has "
        "already treated this statement as the active Lean target. A missing "
        "library declaration, local bridge fact, automation step, or hard "
        "local calculation is a proof obligation, not evidence that the "
        "target is false or not provable. "
        "Unchecked prose refutations are treated as failed proof attempts and "
        "do not invalidate the parent planner claim. Return a `Checked defect` "
        "only after this same child transcript contains an accepted "
        "`certify_counterexample` result or an accepted `try_lean` proof of a "
        "concrete counterexample or a negation of the current target. Prefer "
        "the target-bound `certify_counterexample` tool for "
        "this; it checks a bare proof as `¬ current_target` and can promote a "
        "complete concrete witness. Otherwise keep repairing the proof route "
        "or pivot to another "
        "Lean-executable proof of this exact target. "
        f"Submit a bare `by ...` proof body or one `example : {statement} := by ...` "
        f"block for `{safe_helper}`; do not redeclare the current helper as "
        f"`theorem {safe_helper}` or `lemma {safe_helper}`. Any verified helper "
        "declarations from the dossier are supplied as already-proved named "
        "facts. If the "
        "helper contains Fin indices, finite sums, or integer-valued indexed "
        "arithmetic, cast indices explicitly before normalization or "
        "ring/omega reasoning; do not let numerals or subtraction live at type "
        "Fin n. Do not submit a Lean block whose only content is an unproved "
        "`have`/`suffices` bridge with comments saying it is missing; local "
        "bridge targets are useful only when the submitted proof actually "
        "closes them. If the proof needs two or more independent bridge facts, "
        "or a direct attempt has exposed a stable unsolved goal, stop rebuilding "
        "the whole proof: call `try_skeleton` with the partial `by ...` proof. "
        "Leave each unfinished bridge as a Lean hole so Lean-validated residual "
        "obligations become durable scheduler work with an assembly route. "
        "Fully proved named helper declarations are also allowed and will be "
        "checked before use. Do not emit prose-only helper plans or sorry-stub "
        "theorem declarations; decomposition must cross a Lean validation "
        "boundary."
    )


_RECURSIVE_CLAIM_INVALIDITY_PATTERNS: tuple[tuple[re.Pattern[str], str], ...] = (
    (
        re.compile(
            r"\b(?:helper(?:\s+statement)?|claim(?:\s+statement)?|target|statement)\s+"
            r"(?:is|looks|seems)\s+(?!not\b)[^.;,\n]{0,80}\bfalse\b",
            re.IGNORECASE,
        ),
        "child_reported_false_claim",
    ),
    (
        re.compile(
            r"\b(?:helper(?:\s+statement)?|claim(?:\s+statement)?|target|statement|obligation|this|it)\s+"
            r"(?:is|looks|seems|appears)?\s*(?!not\b)"
            r"(?:false|invalid)(?:\s+(?:as\s+)?(?:stated|a\s+mathematical\s+claim))?\b",
            re.IGNORECASE,
        ),
        "child_reported_false_as_stated",
    ),
    (
        re.compile(
            r"\b(?:helper(?:\s+(?:target|statement))?|claim(?:\s+statement)?|target|statement|obligation|it|this)\s+"
            r"(?:is|looks|seems|appears)\s+not\s+(?:mathematically\s+)?"
            r"(?:correct|valid)\s+as\s+stated\b",
            re.IGNORECASE,
        ),
        "child_reported_false_as_stated",
    ),
    (
        re.compile(
            r"\b(?:helper(?:\s+statement)?|claim(?:\s+statement)?|target|statement|it|this)\s+"
            r"(?:is|looks|seems|was)?\s*(?!not\b)[^.;,\n]{0,80}"
            r"\bover-?generali[sz](?:ed|ation)\b",
            re.IGNORECASE,
        ),
        "child_reported_overgeneralized_claim",
    ),
    (
        re.compile(
            r"\bcould\s+not\s+find\s+(?:a\s+)?(?:lean\s+)?proof\s+because\s+false\b",
            re.IGNORECASE,
        ),
        "child_reported_false_claim",
    ),
    (
        re.compile(
            r"\bno,\s*(?:the\s+)?(?:helper|claim|target|statement|obligation)\s+false\b",
            re.IGNORECASE,
        ),
        "child_reported_false_claim",
    ),
    (
        re.compile(
            r"\b(?:helper|claim|target|statement|obligation)\s+(?:false|invalid)\b",
            re.IGNORECASE,
        ),
        "child_reported_false_claim",
    ),
    (
        re.compile(r"\bcounterexample\b", re.IGNORECASE),
        "child_reported_counterexample",
    ),
    (
        re.compile(
            r"\b(?:helper|claim|target|statement|obligation|goal)\s+does\s+not\s+hold\b",
            re.IGNORECASE,
        ),
        "child_reported_target_refuted",
    ),
    (
        re.compile(
            r"\b(?:helper|claim|target|statement|obligation|goal)\b[^.;\n]{0,120}"
            r"\bnot\s+true\s+in\s+general\b",
            re.IGNORECASE,
        ),
        "child_reported_target_refuted",
    ),
    (
        re.compile(
            r"\b(?:helper|claim|target|statement|obligation|goal)\b[^.;\n]{0,80}"
            r"\bnot\s+derivable\b",
            re.IGNORECASE,
        ),
        "child_reported_target_not_derivable",
    ),
    (
        re.compile(
            r"\b(?:which|that|this)\s+is\s+false\s+in\s+general\b",
            re.IGNORECASE,
        ),
        "child_reported_false_claim",
    ),
    (
        re.compile(
            r"\b(?:refutes?|contradicts?)\s+(?:it|this|the\s+(?:helper|claim|target|statement|obligation))\b",
            re.IGNORECASE,
        ),
        "child_reported_target_refuted",
    ),
    (
        re.compile(
            r"\b(?:helper(?:\s+statement)?|claim(?:\s+statement)?|target|statement|obligation|goal|it|this)\s+"
            r"(?:is|looks|seems|appears|was)?\s*(?:too\s+strong|stronger\s+than|"
            r"stronger\s+than\s+what\s+is\s+true|needs\s+to\s+be\s+weakened)\b",
            re.IGNORECASE,
        ),
        "child_reported_claim_too_strong",
    ),
)


_NEGATED_CLAIM_INVALIDITY_RE = re.compile(
    r"\b(?:not|n't)\s+(?:actually\s+)?"
    r"\b(?:false|invalid|overgenerali[sz](?:ed|ation)|missing|lacks?|"
    r"needs|requires|too\s+strong|counterexample|refutes?)\b",
    re.IGNORECASE,
)


_COGNITIVE_NEGATED_CLAIM_INVALIDITY_RE = re.compile(
    r"\b(?:do|does|did|would|can|could|should|will|may|might)"
    r"(?:\s+(?:not|n't)|n't)\s+"
    r"(?:think|believe|see|conclude|say|mean|certify|"
    r"confirm|establish|verify)\b[^.;\n]{0,140}"
    r"\b(?:false|invalid|overgenerali[sz](?:ed|ation)|missing|lacks?|"
    r"needs|requires|too\s+strong|valid|correct)\b",
    re.IGNORECASE,
)
_CAUSAL_POSITIVE_CLAIM_INVALIDITY_RE = re.compile(
    r"\b(?:because|since|as)\b[^.;\n]{0,140}"
    r"\b(?:false|invalid|not\s+(?:valid|correct)|counterexample)\b",
    re.IGNORECASE,
)
_UNCERTIFIED_CLAIM_INVALIDITY_RE = re.compile(
    r"\b(?:cannot|can't|can\s+not|could\s+not|couldn't)\s+"
    r"(?:certify|confirm|establish|verify)\b[^.;\n]{0,160}"
    r"\b(?:false|invalid|overgenerali[sz](?:ed|ation)|counterexample)\b",
    re.IGNORECASE,
)


_NO_REASON_CLAIM_INVALIDITY_RE = re.compile(
    r"\bno\s+(?:reason|evidence|indication|basis)\s+(?:to\s+)?"
    r"(?:think|believe|conclude|say)\b[^.\n]{0,100}"
    r"\b(?:false|invalid|overgenerali[sz](?:ed|ation)|missing|lacks?|needs|requires|too\s+strong|hold|counterexample|refutes?)\b",
    re.IGNORECASE,
)


_SPECULATIVE_CLAIM_INVALIDITY_RE = re.compile(
    r"\b(?:whether|check(?:ing)?\s+(?:whether|if)|test(?:ing)?\s+(?:whether|if)|"
    r"determine\s+(?:whether|if)|investigate\s+(?:whether|if)|"
    r"unclear\s+(?:whether|if)|not\s+sure\s+(?:whether|if)|"
    r"will\s+check|going\s+to\s+check|need\s+to\s+check)\b",
    re.IGNORECASE,
)


_SUBTARGET_CLAIM_INVALIDITY_PREFIX_RE = re.compile(
    r"\b(?:local|auxiliary|intermediate)\s+$",
    re.IGNORECASE,
)
_SUBTARGET_CLAIM_INVALIDITY_DIRECT_RE = re.compile(
    r"\b(?:subhelper|sublemma|local\s+helper|auxiliary\s+helper|intermediate\s+helper)"
    r"\s*(?::|-|,)?\s*(?:the\s+)?$",
    re.IGNORECASE,
)
_SUBTARGET_COUNTEREXAMPLE_RE = re.compile(
    r"\b(?:local\s+)?(?:subhelper|sublemma|local\s+helper|auxiliary\s+helper|intermediate\s+helper)"
    r"[^.;,\n]{0,80}\bcounterexample\b",
    re.IGNORECASE,
)
_CURRENT_TARGET_INVALIDITY_LEAD_RE = re.compile(
    r"^\s*(?:the\s+)?(?:target|claim|obligation|goal)\b|^\s*this\s+claim\b",
    re.IGNORECASE,
)
_COUNTEREXAMPLE_RETRACTION_RE = re.compile(
    r"\b(?:no\s+(?:concrete\s+)?counterexamples?\b|not\s+(?:a\s+)?counterexamples?\b|"
    r"cannot\s+find\s+(?:a\s+)?counterexample\b|can't\s+find\s+(?:a\s+)?counterexample\b|"
    r"could\s+not\s+find\s+(?:a\s+)?counterexample\b)",
    re.IGNORECASE,
)
_CLAIM_INVALIDITY_RETRACTION_AFTER_RE = re.compile(
    r"\b(?:cannot|can't|can\s+not|could\s+not)\s+"
    r"(?:certify|confirm|establish|verify)\b[^.;\n]{0,160}"
    r"\b(?:false|invalid|over-?generali[sz](?:ed|ation)|counterexample)\b"
    r"|\b(?:statement|claim|helper|target)\s+might\s+still\s+be\s+true\b"
    r"|\b(?:might|may)\s+still\s+be\s+true\b",
    re.IGNORECASE,
)
_CLAIM_INVALIDITY_SCOPE_NAME_STOPWORDS = {
    "a",
    "an",
    "and",
    "as",
    "because",
    "but",
    "claim",
    "false",
    "for",
    "from",
    "goal",
    "has",
    "helper",
    "holds",
    "is",
    "it",
    "may",
    "might",
    "not",
    "obligation",
    "still",
    "statement",
    "target",
    "that",
    "the",
    "this",
    "true",
    "valid",
    "was",
}


def _claim_invalidity_suffix_scopes_to_other_target(text: str) -> bool:
    raw = str(text or "")
    if re.search(
        r"\b(?:different|another|other)\s+"
        r"(?:local\s+|auxiliary\s+|intermediate\s+)?"
        r"(?:helper|claim|target|statement|obligation|goal)\b",
        raw,
        flags=re.IGNORECASE,
    ):
        return True
    for match in re.finditer(
        r"\b(?:local\s+|auxiliary\s+|intermediate\s+)?"
        r"(?:helper|claim|target|statement|obligation|goal)\s+"
        r"(?P<name>[A-Za-z_][A-Za-z0-9_'.]*|«[^»]+»)\b",
        raw,
        flags=re.IGNORECASE,
    ):
        name = str(match.group("name") or "").strip("«»").lower()
        if name and name not in _CLAIM_INVALIDITY_SCOPE_NAME_STOPWORDS:
            return True
    return False


def _normalize_claim_proof_result(raw: Any) -> ClaimProofResult:
    if isinstance(raw, ClaimProofResult):
        return raw
    if isinstance(raw, str) and raw.strip():
        return ClaimProofResult(proof=raw)
    return ClaimProofResult()


def _child_giveup_from_conversation(conv: Any, proof: Optional[str]) -> dict[str, str]:
    """Extract give-up/off-ramp telemetry from a failed proof-only child."""

    cluster = str(getattr(conv, "_last_giveup_cluster", "") or "").strip()
    if cluster:
        return {
            "cluster": cluster,
            "match": str(getattr(conv, "_last_giveup_match", "") or ""),
        }

    content = str(getattr(conv, "_last_llm_content", "") or "")
    if not content:
        for message in reversed(list(getattr(conv, "history", []) or [])):
            if (
                isinstance(message, dict)
                and message.get("role") == "assistant"
                and str(message.get("content", "") or "").strip()
            ):
                content = str(message.get("content", "") or "")
                break
    if not content and not proof:
        return {}
    try:
        from .mini_prover import _classify_giveup_signal

        classified = _classify_giveup_signal(
            content,
            proof,
            require_structural_collapse=False,
        )
    except Exception:
        classified = None
    if not classified:
        return {}
    return {
        "cluster": str(classified.get("cluster") or ""),
        "match": str(classified.get("match") or ""),
    }


def _retire_ordinary_provider_state_for_role_handoff(conv: Any) -> dict[str, Any]:
    """Retire only role-bound provider residue that carries no paid work.

    A mini-recursive prove and refine pass use distinct MiniSessions over the
    same Conversation. Ordinary provider retry state is bound to the prove
    role and cannot be inherited by the fresh refine action. Durable tool
    replay and banked finalizer content have stronger owners; leave those
    untouched so their owner can drain or diagnose them instead of silently
    discarding paid work at a role boundary.
    """

    raw_state = getattr(conv, "_provider_call_quantum_state", None)
    if not isinstance(raw_state, Mapping) or not raw_state:
        return {"retired": False, "protected": False, "reason": "no_state"}
    protected_reasons = []
    disposition = str(
        raw_state.get("pending_tool_replay_disposition") or ""
    ).strip()
    if disposition == "durable_progress_cutpoint":
        protected_reasons.append("durable_progress_cutpoint")
    if list(raw_state.get("pending_tool_replay") or ()):
        protected_reasons.append("pending_tool_replay")
    if bool(raw_state.get("pending_tool_replay_is_paid_retry")):
        protected_reasons.append("paid_tool_replay")
    if bool(raw_state.get("banked_mixed_finalizer_pending")) or str(
        raw_state.get("banked_mixed_final_content") or ""
    ).strip():
        protected_reasons.append("banked_mixed_finalizer")
    if protected_reasons:
        return {
            "retired": False,
            "protected": True,
            "reason": ",".join(dict.fromkeys(protected_reasons)),
        }
    delattr(conv, "_provider_call_quantum_state")
    if hasattr(conv, "_provider_turn_repair_cycle_identity"):
        delattr(conv, "_provider_turn_repair_cycle_identity")
    return {
        "retired": True,
        "protected": False,
        "reason": "ordinary_prove_lane_retired_before_refine",
    }


def _invalidity_match_scoped_to_subtarget(
    negation_context: str,
    local_match_start: int,
    match_text: str,
) -> bool:
    matched = str(match_text or "").strip()
    if _CURRENT_TARGET_INVALIDITY_LEAD_RE.search(matched):
        return False
    prefix = str(negation_context or "")[: max(0, local_match_start)]
    return bool(
        _SUBTARGET_CLAIM_INVALIDITY_PREFIX_RE.search(prefix)
        or _SUBTARGET_CLAIM_INVALIDITY_DIRECT_RE.search(prefix[-80:])
    )


def _claim_invalidity_context_is_negated_or_speculative(
    text: str,
    match: re.Match[str],
) -> bool:
    negation_start = max(
        text.rfind(".", 0, match.start()),
        text.rfind("\n", 0, match.start()),
        text.rfind(";", 0, match.start()),
    )
    negation_start = 0 if negation_start < 0 else negation_start + 1
    negation_end_candidates = [
        idx
        for idx in (
            text.find(".", match.end()),
            text.find("\n", match.end()),
            text.find(";", match.end()),
        )
        if idx >= 0
    ]
    negation_end = (
        min(negation_end_candidates) if negation_end_candidates else len(text)
    )
    negation_context = text[negation_start:negation_end]
    local_match_start = max(0, match.start() - negation_start)
    negation_clause_context = negation_context
    local_contrast_prefix = negation_context[:local_match_start]
    contrast_cut = -1
    if re.match(
        r"^\s*(?:even\s+though|although|though)\b",
        local_contrast_prefix,
        re.IGNORECASE,
    ):
        comma_index = local_contrast_prefix.rfind(",")
        if comma_index >= 0:
            contrast_cut = comma_index + 1
        else:
            for negated_match in _NEGATED_CLAIM_INVALIDITY_RE.finditer(
                local_contrast_prefix
            ):
                contrast_cut = negated_match.end()
    for candidate in re.finditer(
        r"(?:,\s*|\s+)(?:but|however|whereas|although|though|yet|nevertheless|nonetheless)\s+",
        local_contrast_prefix,
        flags=re.IGNORECASE,
    ):
        if contrast_cut < 0:
            contrast_cut = candidate.end()
    if contrast_cut >= 0:
        negation_clause_context = negation_context[contrast_cut:]
    speculative_start = max(
        text.rfind(".", 0, match.start()),
        text.rfind("\n", 0, match.start()),
        text.rfind(";", 0, match.start()),
        text.rfind(",", 0, match.start()),
    )
    speculative_start = 0 if speculative_start < 0 else speculative_start + 1
    prefix = text[max(speculative_start, match.start() - 100) : match.start()]
    suffix = text[match.end() : negation_end]
    full_suffix = text[match.end() : min(len(text), match.end() + 500)]
    cross_sentence_retraction = bool(
        _CLAIM_INVALIDITY_RETRACTION_AFTER_RE.search(full_suffix)
        and not _claim_invalidity_suffix_scopes_to_other_target(full_suffix)
    )
    return bool(
        _SUBTARGET_COUNTEREXAMPLE_RE.search(negation_context)
        or _invalidity_match_scoped_to_subtarget(
            negation_context,
            local_match_start,
            match.group(0),
        )
        or _COUNTEREXAMPLE_RETRACTION_RE.search(negation_clause_context)
        or _CLAIM_INVALIDITY_RETRACTION_AFTER_RE.search(suffix)
        or cross_sentence_retraction
        or _NEGATED_CLAIM_INVALIDITY_RE.search(negation_clause_context)
        or (
            _COGNITIVE_NEGATED_CLAIM_INVALIDITY_RE.search(negation_clause_context)
            and not _CAUSAL_POSITIVE_CLAIM_INVALIDITY_RE.search(negation_clause_context)
        )
        or _UNCERTIFIED_CLAIM_INVALIDITY_RE.search(negation_clause_context)
        or _NO_REASON_CLAIM_INVALIDITY_RE.search(negation_clause_context)
        or _SPECULATIVE_CLAIM_INVALIDITY_RE.search(prefix)
    )


def _recursive_claim_invalidity_texts(conv: Any) -> list[str]:
    texts: list[str] = []
    seen: set[str] = set()

    def add(text: Any) -> None:
        value = str(text or "").strip()
        if value and value not in seen:
            seen.add(value)
            texts.append(value)

    for attr in (
        "_last_no_proof_llm_response",
        "_last_rejected_llm_response",
        "_last_llm_content",
        "last_llm_content",
    ):
        add(getattr(conv, attr, ""))
    for text in list(getattr(conv, "_no_proof_llm_responses", []) or ())[-8:]:
        add(text)
    history = list(getattr(conv, "history", []) or [])
    for msg in reversed(history[-12:]):
        if msg.get("role") == "assistant":
            add(msg.get("content", ""))
    return texts


def _detect_recursive_claim_invalidity(
    conv: Any,
    statement: str,
    *,
    require_checked_evidence: bool = False,
    dossier: Any = None,
) -> str:
    """Detect when a child prover invalidates the planned helper itself.

    This is intentionally scoped to recursive helper conversations. In the
    production path, prose is not trusted as negative evidence: callers pass
    ``require_checked_evidence=True`` so a claim is invalidated only when the
    same child transcript contains an accepted Lean negation check.
    """

    statement_hint = _compact_text(statement, 180)
    checked_evidence = (
        _recursive_claim_invalidity_has_checked_evidence(
            conv,
            statement,
            dossier=dossier,
        )
        if require_checked_evidence
        else True
    )
    for text in _recursive_claim_invalidity_texts(conv):
        for pattern, reason in _RECURSIVE_CLAIM_INVALIDITY_PATTERNS:
            for match in pattern.finditer(text):
                if _claim_invalidity_context_is_negated_or_speculative(text, match):
                    continue
                if not checked_evidence:
                    continue
                detail = _compact_text(match.group(0), 160)
                if statement_hint:
                    return f"{reason}: {detail}; target={statement_hint}"
                return f"{reason}: {detail}"
    return ""


def _invalidated_statement_key(statement: str) -> str:
    return canonical_dossier_statement_key(statement)


def _durable_root_solution_for_statement(dossier: Any, root_statement: str) -> str:
    """Return a durable already-solved proof for ``root_statement`` if available."""

    if dossier is None:
        return ""
    candidate_root = str(root_statement or "").strip()
    if not candidate_root:
        return ""
    dossier_root = str(getattr(dossier, "root_statement", "") or "").strip()
    final_proof = str(getattr(dossier, "final_proof", "") or "").strip()
    if final_proof and dossier_root:
        if graph_statement_root_equivalent(dossier_root, candidate_root):
            return final_proof
    return ""


def _record_durable_root_short_circuit(
    *,
    stats: MiniRecursiveStats,
    record_event: Optional[RecordEvent],
    pass_index: int,
    after_helper: str,
    root_statement: str,
    proof: str,
) -> None:
    stats.durable_root_short_circuits += 1
    proof_text = str(proof or "")
    _record(
        record_event,
        {
            "phase": "mini_recursive_durable_root_short_circuit",
            "pass_index": pass_index,
            "after_helper": str(after_helper or ""),
            "statement": str(root_statement or ""),
            "proof_hash": hashlib.sha256(proof_text.encode("utf-8")).hexdigest()[:16]
            if proof_text
            else "",
            "verdict": "root_already_solved",
        },
    )


def _claim_variant_root_equivalent_suppression_reason(
    claim: MiniSubgoalClaim,
    variant: SubgoalVariant,
    *,
    root_statement: str,
    active_target_statements: Sequence[str] = (),
) -> str:
    root = str(root_statement or "").strip()
    statement = str(getattr(variant, "statement", "") or "").strip()
    if not root or not statement:
        return ""
    active_targets = tuple(
        str(item or "").strip()
        for item in list(active_target_statements or ())
        if str(item or "").strip()
    )
    if not graph_statement_root_equivalent(
        statement,
        root,
        active_target_statements=active_targets,
    ):
        return ""
    raw = normalize_subgoal_statement(str(getattr(claim, "statement", "") or ""))
    raw_is_root_equivalent = bool(
        raw
        and graph_statement_root_equivalent(
            raw,
            root,
            active_target_statements=active_targets,
        )
    )
    if raw_is_root_equivalent:
        return ""
    if tuple(getattr(claim, "dependencies", ()) or ()):
        return "root_equivalent_variant_with_dependencies"
    if str(getattr(variant, "mode", "") or "") != "raw":
        return "contextual_variant_collapsed_to_root"
    return ""


def _format_planner_feedback(items: Sequence[str]) -> str:
    kept = [str(item or "").strip() for item in items if str(item or "").strip()]
    if not kept:
        return ""
    lines = [
        "Recent recursive-controller feedback from earlier failed or rejected helper attempts:",
        "- Use this as negative evidence; do not repeat sample-refuted, type-rejected, or exhausted claims verbatim.",
        "- If a final/root assembly failed because a prerequisite bridge was missing, plan that bridge as its own Lean-checkable claim before retrying the root.",
    ]
    contract_prefixes = (
        "[ROOT_ROUTE_CONTRACT]",
        "[DECOMPOSITION_CONTRACT]",
    )
    route_items = [item for item in kept if item.startswith(contract_prefixes)]
    ordinary = [item for item in kept if not item.startswith(contract_prefixes)]
    latest_contract_items = [
        matches[-1]
        for prefix in contract_prefixes
        for matches in ([item for item in route_items if item.startswith(prefix)],)
        if matches
    ]
    ordinary_cap = max(0, 8 - len(latest_contract_items))
    rendered = ordinary[-ordinary_cap:] if ordinary_cap else []
    rendered.extend(latest_contract_items)
    for item in rendered:
        lines.append(f"- {item}")
    # Per-item sanitization is not closed under this join either: "\n- " is
    # pure punctuation, so an answer reference or control phrase split across
    # two adjacent items reads clean in both halves and spelled out in the
    # rendered block the planner receives.
    return _prompt_safe_composed_prompt_block("\n".join(lines))


_LEAN_NAME_SEGMENT_FOR_SOLUTION_RE = r"(?:«[^»]*»|(?:[^\W\d]|_)[\w']*)"
_LEAN_SOLUTION_SEGMENT_RE = (
    r"(?:«[^»]*_solution[^»]*»|"
    r"(?:[^\W\d]|_)[\w']*_solution[\w']*)"
)
_SOLUTION_NAME_RE = re.compile(
    rf"(?:{_LEAN_NAME_SEGMENT_FOR_SOLUTION_RE}\.)*"
    rf"{_LEAN_SOLUTION_SEGMENT_RE}"
)


def _solution_names_in_text(text: str) -> tuple[str, ...]:
    seen: set[str] = set()
    names: list[str] = []
    for match in _SOLUTION_NAME_RE.finditer(str(text or "")):
        name = match.group(0).strip()
        if not name or name in seen:
            continue
        seen.add(name)
        names.append(name)
    return tuple(names)


def _materialized_solution_name_visible(preamble: str, name: str) -> bool:
    """Whether *name* has one authoritative materialized preamble definition.

    Comment/string-aware (Sol audit 2026-07-29 F1): declaration-looking text
    inside comments or strings never counts, and a duplicated top-level name
    is ambiguous — fail closed.
    """

    from .mini_lean_extract import _top_level_declaration_registry

    blocks, ambiguous = _top_level_declaration_registry(str(preamble or ""))
    return _materialized_solution_name_visible_in_registry(
        blocks,
        ambiguous,
        name,
    )


def _materialized_solution_name_visible_in_registry(
    blocks: Mapping[str, str],
    ambiguous: AbstractSet[str],
    name: str,
) -> bool:
    """Registry-backed materialization check for batched callers.

    Parsing a full Lean preamble is linear in its size. Planner rendering can
    reference many solution names, so reparsing once per name makes prompt
    construction quadratic in the aggregate answer payload. Callers that
    already need the declaration registry use this helper to preserve the
    exact fail-closed predicate with one parse.
    """

    ident = str(name or "").strip()
    if ident.startswith("_root_."):
        ident = ident[len("_root_.") :]
    if not ident:
        return False
    if ident in ambiguous:
        return False
    block = str(blocks.get(ident) or "")
    if not block:
        return False
    from .mini_lean_extract import _first_preamble_declaration_header

    header = _first_preamble_declaration_header(block)
    if header is None or header.kind not in {
        "def",
        "abbrev",
        "theorem",
        "lemma",
    }:
        return False
    return bool(
        re.search(
            r"(?::=|\bwhere\b)",
            _strip_comments_and_strings_for_materialization(block),
        )
    )


def _strip_comments_and_strings_for_materialization(block: str) -> str:
    from .mini_lean_extract import _strip_lean_comments_and_strings

    return _strip_lean_comments_and_strings(str(block or ""))


def _visible_answer_definitions_for_planner(
    preamble: str,
    *,
    root_statement: str,
    opaque_mode: bool,
    allow_official_answer_visibility: bool,
    official_answer_payload_present: Optional[bool],
    limit: int = 2000,
) -> str:
    """Bounded materialized official-answer definitions for the planner.

    In visible-answer mode the LLM preamble contains the materialized solution
    definition (e.g.
    ``fun i ↦ i - 2``), but the planner prompt carried only a sanitized
    helper/import summary, so the planner honestly reported the witness
    values as unavailable and could not plan the root. Fail-closed: anything
    short of the full strict visibility capability (non-opaque, explicitly
    allowed, payload positively present) returns the empty string, so the
    opaque planner never sees the values or the identifier.
    """

    from .proof_dossier import official_answer_visible_to_llm

    if not official_answer_visible_to_llm(
        opaque_mode=opaque_mode,
        allow_official_answer_visibility=allow_official_answer_visibility,
        official_answer_payload_present=official_answer_payload_present,
    ):
        return ""
    source = str(preamble or "")
    if not source:
        return ""
    from .mini_lean_extract import (
        _LEAN_QUALIFIED_NAME_RE,
        _first_preamble_declaration_header,
        _split_lean_qualified_name,
        _strip_lean_comments,
        _strip_lean_comments_and_strings,
        _top_level_elaboration_context_issues,
        _top_level_declaration_registry_with_opens,
    )

    blocks, ambiguous, opens_by_name, block_positions = (
        _top_level_declaration_registry_with_opens(source)
    )
    names: list[str] = []
    for raw_name in _solution_names_in_text(str(root_statement or "")):
        name = (
            raw_name[len("_root_.") :] if raw_name.startswith("_root_.") else raw_name
        )
        if not _materialized_solution_name_visible_in_registry(
            blocks,
            ambiguous,
            name,
        ):
            suffix_matches = [
                candidate
                for candidate in blocks
                if candidate.endswith(f".{name}")
                and _materialized_solution_name_visible_in_registry(
                    blocks,
                    ambiguous,
                    candidate,
                )
            ]
            name = suffix_matches[0] if len(suffix_matches) == 1 else name
        if name not in names and _materialized_solution_name_visible_in_registry(
            blocks,
            ambiguous,
            name,
        ):
            names.append(name)
    if not names:
        return ""
    closure_omitted: list[str] = []

    def record_omitted(name: str) -> None:
        if name not in closure_omitted:
            closure_omitted.append(name)

    def resolve_dependency(dep: str, owner: str) -> str:
        """Resolve *dep* referenced from *owner* to a registry key.

        Qualified references match directly; unqualified references resolve
        against the owner's enclosing namespaces innermost-first, then the
        lexical ``open`` targets in effect at the owner's declaration (Sol
        audit 2026-07-29 R2/S3).
        """

        dep = str(dep or "").strip()
        self_spelling = dep[len("_root_.") :] if dep.startswith("_root_.") else dep
        if owner == self_spelling or owner.endswith(f".{self_spelling}"):
            return owner
        owner_position = block_positions.get(owner, len(source))

        def eligible(candidate: str) -> bool:
            return (
                candidate in blocks
                and block_positions.get(candidate, len(source)) < owner_position
            )

        if dep.startswith("_root_."):
            rooted = dep[len("_root_.") :]
            if eligible(rooted):
                return rooted
            dep = rooted
        prefix = owner.rsplit(".", 1)[0] if "." in owner else ""
        while True:
            candidate = f"{prefix}.{dep}" if prefix else dep
            if eligible(candidate):
                return candidate
            if not prefix:
                break
            prefix = prefix.rsplit(".", 1)[0] if "." in prefix else ""
        for opened in opens_by_name.get(owner, ()):  # lexical opens
            opened_name = (
                opened[len("_root_.") :] if opened.startswith("_root_.") else opened
            )
            candidate = f"{opened_name}.{dep}"
            if eligible(candidate):
                return candidate
        # Structures/classes generate constructors and projections that do
        # not appear as separate registry declarations.  Resolve a qualified
        # generated member to its longest preceding owning declaration.
        dep_parts = _split_lean_qualified_name(dep)
        for end_index in range(len(dep_parts) - 1, 0, -1):
            generated_owner = ".".join(dep_parts[:end_index])
            generated_prefix = owner.rsplit(".", 1)[0] if "." in owner else ""
            while True:
                candidate = (
                    f"{generated_prefix}.{generated_owner}"
                    if generated_prefix
                    else generated_owner
                )
                if eligible(candidate):
                    return candidate
                if not generated_prefix:
                    break
                generated_prefix = (
                    generated_prefix.rsplit(".", 1)[0]
                    if "." in generated_prefix
                    else ""
                )
            for opened in opens_by_name.get(owner, ()):
                opened_name = (
                    opened[len("_root_.") :] if opened.startswith("_root_.") else opened
                )
                candidate = f"{opened_name}.{generated_owner}"
                if eligible(candidate):
                    return candidate
        # Honest-incompleteness accounting: the name exists in the registry
        # under SOME scope we could not resolve, or is ambiguous — record it
        # instead of silently claiming the closure is complete.
        if dep in ambiguous:
            record_omitted(dep)
            return ""
        for known in blocks:
            if known == dep or known.endswith(f".{dep}"):
                record_omitted(known)
                return ""
        return ""

    # Bounded transitive dependency closure (Sol audit 2026-07-29 F2): an
    # indirect definition like ``abbrev X_solution := officialWitness`` is
    # useless to the planner without ``officialWitness``. Walk identifiers in
    # the comment-stripped bodies to other unambiguous top-level preamble
    # declarations, depth-first so dependencies render before their users.
    ordered: list[str] = []
    visiting: set[str] = set()
    dependencies_by_name: dict[str, tuple[str, ...]] = {}

    def visit(name: str, depth: int) -> None:
        if name in ordered or name in visiting:
            return
        if depth > 4:
            # Depth exhaustion is an OMISSION, not silent completeness.
            record_omitted(name)
            return
        block = str(blocks.get(name) or "")
        if not block:
            if name in ambiguous:
                record_omitted(name)
            return
        visiting.add(name)
        body = _strip_lean_comments_and_strings(block)
        direct_dependencies: list[str] = []
        for match in _LEAN_QUALIFIED_NAME_RE.finditer(body):
            dep = resolve_dependency(match.group(0), name)
            if dep and dep != name:
                if dep not in direct_dependencies:
                    direct_dependencies.append(dep)
                visit(dep, depth + 1)
        dependencies_by_name[name] = tuple(direct_dependencies)
        visiting.discard(name)
        ordered.append(name)

    resolved_names = [name for name in names if name in blocks]
    # Source-level dependency scanning cannot see arguments synthesized by
    # typeclass inference.  Preserve every preceding local/global instance as
    # part of each answer root's executable context, then let the ordinary
    # transitive walk pull in its class/constructor dependencies.  This is
    # deliberately conservative until the registry consumes elaborated Exprs.
    declaration_headers = {
        name: _first_preamble_declaration_header(str(block or ""))
        for name, block in blocks.items()
    }
    local_instance_names = {
        name
        for name, header in declaration_headers.items()
        if header is not None
        and header.kind == "instance"
        and "local" in header.modifiers
    }
    implicit_environment_names = [
        name
        for name, header in declaration_headers.items()
        if header is not None
        and name not in local_instance_names
        and (header.kind == "instance" or header.has_attributes)
    ]
    for root_name in resolved_names:
        root_position = block_positions.get(root_name, -1)
        implicit_context: list[str] = []
        for context_name in implicit_environment_names:
            context_position = block_positions.get(context_name, -1)
            if root_position >= 0 and 0 <= context_position < root_position:
                visit(context_name, 0)
                implicit_context.append(context_name)
        visit(root_name, 0)
        if implicit_context:
            dependencies_by_name[root_name] = tuple(
                dict.fromkeys(
                    (
                        *dependencies_by_name.get(root_name, ()),
                        *implicit_context,
                    )
                )
            )
    # Notation, macros, attributes/options, and restricted opens shape
    # elaboration without leaving ordinary identifiers in the declaration
    # body.  If any such command precedes a required answer, retain the
    # declaration but make the completeness claim fail closed.
    root_positions = [block_positions.get(name, -1) for name in resolved_names]
    latest_root_position = max(root_positions, default=-1)
    for declaration_name in ordered:
        declaration_block = str(blocks.get(declaration_name) or "")
        declaration_scan = _strip_lean_comments_and_strings(declaration_block)
        if re.search(r"(?<![\w'])by(?![\w'])", declaration_scan):
            # Tactic elaboration can synthesize dependencies absent from the
            # surface source (`exact?`, `apply?`, `library_search`, custom
            # tactics, and tactic extensions).  This applies transitively:
            # any selected dependency or ambient declaration can hide one.
            # A lexical closure cannot prove itself complete in that case.
            record_omitted("context:tactic_elaboration")
    for context_name in implicit_environment_names:
        context_block = str(blocks.get(context_name) or "")
        context_header = declaration_headers.get(context_name)
        if (
            block_positions.get(context_name, len(source)) < latest_root_position
            and context_header is not None
            and context_header.has_attributes
            and re.search(
                r"(?s)^\s*@\[.*?\b(?:local|scoped)\b",
                context_block,
            )
        ):
            # Per-declaration namespace wrappers intentionally prevent ambient
            # state leakage, so local/scoped attributes cannot be reproduced
            # across independently rendered blocks.
            record_omitted("context:local_attribute")
    for local_instance_name in local_instance_names:
        if (
            latest_root_position >= 0
            and 0 <= block_positions.get(local_instance_name, -1) < latest_root_position
        ):
            record_omitted("context:local_instance")
    for issue_position, issue_name in _top_level_elaboration_context_issues(source):
        if latest_root_position >= 0 and issue_position < latest_root_position:
            record_omitted(issue_name)
    if not ordered:
        return ""
    # Re-elaboration is environment-order-sensitive: later instances and
    # attributes can change the meaning of identical surface syntax.  DFS
    # order follows root-statement order, which is not authoritative and can
    # move an earlier answer past a later instance.  Every registered
    # dependency originates in the same preamble, so render the selected
    # closure in original source order.
    ordered.sort(
        key=lambda item: (
            block_positions.get(item, len(source)),
            item,
        )
    )
    # Sol audit 2026-07-29 R3/S4: sanitize each declaration INDIVIDUALLY
    # (never truncating), then pack complete sanitized blocks under ONE
    # aggregate hard limit — required solutions first, then dependencies —
    # rendering admitted blocks in topological order. Anything that does not
    # fit is omitted whole behind an explicit marker; the header never claims
    # concrete values when anything was omitted.
    budget = max(200, int(limit or 0))
    aggregate_budget = max(budget, 4000)
    sanitized_by_name: dict[str, str] = {}
    for name in ordered:
        block = str(blocks.get(name) or "").strip()
        if not block:
            continue
        header = declaration_headers.get(name)
        if header is not None and header.kind in {
            "axiom",
            "constant",
            "opaque",
        }:
            record_omitted(name)
            continue
        comment_free = _strip_lean_comments(block)
        sanitized = _prompt_safe_inline_text(
            comment_free,
            limit=len(block) + 8,
            redact_solution_refs=False,
            preserve_safe_lean_identifiers=True,
            preserve_quoted_identifier_whitespace=True,
            preserve_layout=True,
            truncate=False,
        ).strip()
        semantic_source = _normalize_prompt_layout(comment_free)
        # Prompt sanitation is allowed to remove comments and normalize
        # whitespace, but it must never fabricate a different Lean
        # declaration. String redaction, prompt-control redaction, or an
        # unsafe identifier therefore omits the whole block and makes the
        # section explicitly incomplete.
        if not sanitized or sanitized != semantic_source:
            record_omitted(name)
            continue
        header_match = _first_preamble_declaration_header(comment_free)
        declared_name = (
            str(header_match.group(1) or "").strip() if header_match is not None else ""
        )
        qualified_parts = _split_lean_qualified_name(name)
        declared_parts = _split_lean_qualified_name(declared_name)
        rooted_declaration = declared_name.startswith("_root_.")
        if rooted_declaration:
            namespace_parts: list[str] = []
        elif (
            declared_parts
            and len(declared_parts) <= len(qualified_parts)
            and qualified_parts[-len(declared_parts) :] == declared_parts
        ):
            namespace_parts = qualified_parts[: -len(declared_parts)]
        else:
            # A comment asserting the intended FQN is not executable Lean.
            # If the lexical registry identity cannot be reconstructed from
            # the declaration head, omit the declaration rather than minting
            # a same-spelled root declaration.
            record_omitted(name)
            continue
        wrapper_lines: list[str] = []
        if "." in name:
            safe_display_name = _prompt_safe_inline_text(
                name,
                limit=len(name) + 8,
                redact_solution_refs=False,
                preserve_safe_lean_identifiers=True,
                preserve_quoted_identifier_whitespace=True,
                truncate=False,
            ).strip()
            if safe_display_name != name:
                record_omitted(name)
                continue
            wrapper_lines.append(
                f"-- authoritative fully qualified name: {safe_display_name}"
            )
        if namespace_parts:
            namespace_name = ".".join(namespace_parts)
            safe_namespace = _prompt_safe_inline_text(
                namespace_name,
                limit=len(namespace_name) + 8,
                redact_solution_refs=False,
                preserve_safe_lean_identifiers=True,
                preserve_quoted_identifier_whitespace=True,
                truncate=False,
            ).strip()
            if safe_namespace != namespace_name:
                record_omitted(name)
                continue
            wrapper_lines.append(f"namespace {safe_namespace}")
        opened_namespaces = list(dict.fromkeys(opens_by_name.get(name, ())))
        if opened_namespaces:
            safe_opens: list[str] = []
            for opened in opened_namespaces:
                safe_open = _prompt_safe_inline_text(
                    opened,
                    limit=len(opened) + 8,
                    redact_solution_refs=False,
                    preserve_safe_lean_identifiers=True,
                    preserve_quoted_identifier_whitespace=True,
                    truncate=False,
                ).strip()
                if safe_open != opened:
                    record_omitted(name)
                    safe_opens = []
                    break
                safe_opens.append(safe_open)
            if not safe_opens:
                continue
            wrapper_lines.append(f"open {' '.join(safe_opens)} in")
        wrapper_lines.append(sanitized)
        if namespace_parts:
            wrapper_lines.append(f"end {'.'.join(namespace_parts)}")
        sanitized = "\n".join(wrapper_lines)
        sanitized_by_name[name] = sanitized
    complete_header = (
        "Official answer definitions (visible; already fixed in the Lean "
        "preamble). Plan with these concrete values — never redeclare "
        "the names:"
    )
    safe_omission_names: dict[str, str] = {}

    def safe_omission_name(item: str) -> str:
        raw = str(item or "")
        if raw not in safe_omission_names:
            safe_omission_names[raw] = _prompt_safe_inline_text(
                raw,
                limit=len(raw) + 32,
                redact_solution_refs=False,
                preserve_safe_lean_identifiers=True,
                preserve_quoted_identifier_whitespace=True,
                truncate=False,
            ).strip()
        return safe_omission_names[raw]

    def bounded_name_summary(items: Sequence[str], *, max_chars: int) -> str:
        safe_items = [safe_omission_name(str(item or "")) for item in items]
        unique = list(dict.fromkeys(safe_items))
        unique = [item for item in unique if item]
        kept: list[str] = []
        used_chars = 0
        for index, item in enumerate(unique):
            separator = ", " if kept else ""
            remaining = len(unique) - index - 1
            suffix = f" … (+{remaining} more)" if remaining else ""
            if used_chars + len(separator) + len(item) + len(suffix) > max_chars:
                break
            kept.append(item)
            used_chars += len(separator) + len(item)
        remaining = len(unique) - len(kept)
        if not kept:
            return f"(+{remaining} omitted definitions)"
        summary = ", ".join(kept)
        if remaining:
            summary += f" … (+{remaining} more)"
        # Individually safe identifiers can recompose into a prompt-control
        # phrase when joined (for example ``ignore, previous, instructions``).
        # Sanitize the complete composition as the actual trust boundary.
        return _prompt_safe_inline_text(
            summary,
            limit=len(summary) + 32,
            redact_solution_refs=False,
            preserve_safe_lean_identifiers=True,
            preserve_quoted_identifier_whitespace=True,
            truncate=False,
        ).strip()

    def omission_metadata(
        omitted_names: Sequence[str],
        required_omitted: Sequence[str],
    ) -> tuple[str, list[str]]:
        omitted_unique = list(dict.fromkeys(omitted_names))
        if not omitted_unique:
            return complete_header, []
        summary = bounded_name_summary(
            omitted_unique,
            max_chars=min(800, max(160, aggregate_budget // 5)),
        )
        header = (
            "Official answer definitions (visible; already fixed in the Lean "
            "preamble). Never redeclare the names. INCOMPLETE: "
            f"{len(omitted_unique)} definitions were omitted (size, depth, "
            "or unresolved scope); their values must not be assumed. "
            f"Omitted: {summary}."
        )
        markers: list[str] = []
        if required_omitted:
            size_omitted = [
                name for name in required_omitted if name in sanitized_by_name
            ]
            semantic_omitted = [
                name for name in required_omitted if name not in sanitized_by_name
            ]
            if size_omitted:
                markers.append(
                    f"[{len(size_omitted)} required solution definitions: "
                    "at least one exceeds the visible bound and is not shown]"
                )
            if semantic_omitted:
                markers.append(
                    f"[{len(semantic_omitted)} required solution definitions "
                    "could not be rendered without changing Lean semantics]"
                )
        return header, markers

    required_set = set(resolved_names)

    def render_for(admitted_names: AbstractSet[str]) -> str:
        omitted = list(closure_omitted)
        for name in ordered:
            if name not in admitted_names and name not in omitted:
                omitted.append(name)
        required_omitted = [
            name for name in resolved_names if name not in admitted_names
        ]
        header, markers = omission_metadata(omitted, required_omitted)
        metadata_text = "\n\n".join((header, *markers))
        rendered_blocks = [
            sanitized_by_name[name]
            for name in ordered
            if name in admitted_names and name in sanitized_by_name
        ]
        return "\n\n".join((metadata_text, *rendered_blocks))

    def transitive_dependencies(root_name: str) -> set[str]:
        needed: set[str] = set()
        pending = list(dependencies_by_name.get(root_name, ()))
        while pending:
            dependency = pending.pop()
            if dependency in needed or dependency == root_name:
                continue
            needed.add(dependency)
            pending.extend(dependencies_by_name.get(dependency, ()))
        return needed

    admitted: set[str] = set()
    fully_renderable = not closure_omitted and all(
        name in sanitized_by_name for name in ordered
    )
    if fully_renderable:
        complete_result = render_for(set(ordered))
        if len(complete_result) <= aggregate_budget:
            return complete_result

    # Required roots are the primary information. Admit all fitting root
    # declarations before spending any space on dependencies, and sort a
    # constrained root set by declaration size/name so equivalent conjunct
    # order cannot change which roots survive.
    renderable_roots = {name for name in resolved_names if name in sanitized_by_name}
    if len(render_for(renderable_roots)) <= aggregate_budget:
        admitted = set(renderable_roots)
    else:
        for root_name in sorted(
            renderable_roots,
            key=lambda item: (len(sanitized_by_name[item]), item),
        ):
            tentative = admitted | {root_name}
            if len(render_for(tentative)) <= aggregate_budget:
                admitted = tentative

    root_dependencies = {
        root_name: transitive_dependencies(root_name)
        for root_name in required_set & admitted
    }
    # Dependencies are useful only as complete executable closures. Allocate
    # each admitted root's entire remaining closure atomically; never spend
    # budget on a parent whose descendant is still omitted.
    pending_bundles = {
        root_name: {
            dependency for dependency in dependencies if dependency not in admitted
        }
        for root_name, dependencies in root_dependencies.items()
        if dependencies
        and all(dependency in sanitized_by_name for dependency in dependencies)
    }
    while pending_bundles:
        ranked = sorted(
            pending_bundles,
            key=lambda root_name: (
                sum(
                    len(sanitized_by_name[name])
                    for name in pending_bundles[root_name] - admitted
                ),
                root_name,
            ),
        )
        admitted_one = False
        for root_name in ranked:
            bundle = pending_bundles.pop(root_name) - admitted
            if not bundle:
                admitted_one = True
                break
            tentative = admitted | bundle
            if len(render_for(tentative)) <= aggregate_budget:
                admitted = tentative
                admitted_one = True
                break
        if not admitted_one:
            break

    result = render_for(admitted)
    if len(result) <= aggregate_budget:
        return result
    # ``render_for(set())`` contains bounded metadata only; this final guard
    # is defensive against future metadata changes, never a slicing repair.
    metadata_only = render_for(set())
    if len(metadata_only) <= aggregate_budget:
        return metadata_only
    return ""


def _active_target_goals_from_parsed(parsed: Any) -> list[dict[str, Any]]:
    goals: list[dict[str, Any]] = []
    for goal in list(getattr(parsed, "remaining_goals", []) or [])[:5]:
        target = normalize_subgoal_statement(str(getattr(goal, "target", "") or ""))
        if not target:
            continue
        hypotheses = [
            str(item or "").strip()
            for item in list(getattr(goal, "hypotheses", []) or [])[:12]
            if str(item or "").strip()
        ]
        goals.append({"target": target, "hypotheses": hypotheses})
    return goals


def _source_preserving_active_root_candidates(
    root_statement: str,
    *,
    solution_names: Sequence[str],
) -> list[str]:
    """Return source-shaped active-target candidates for ``P ↔ _solution``.

    Lean proof-state pretty-printing is not guaranteed to be reparseable
    source. In particular, finite big operators can lose binder annotations
    and reparse as sums over ``ℕ``.  When the original root statement has the
    usual PutnamBench shell shape, prefer source-preserved candidates and let
    Lean validate which polarity matches the visible answer value.
    """

    statement = _strip_balanced_outer_parens(
        normalize_subgoal_statement(str(root_statement or ""))
    )
    if not statement:
        return []
    names = [
        str(name or "").strip() for name in solution_names if str(name or "").strip()
    ]
    if not names:
        return []
    binders, body = _split_leading_forall_statement(statement)
    body = _strip_balanced_outer_parens(body)
    split = _split_top_level(body, "↔") or _split_top_level(body, "<->")
    if split is None:
        return []
    lhs, rhs = split

    def mentions_solution(text: str) -> bool:
        haystack = str(text or "")
        return any(
            re.search(
                rf"(?<![A-Za-z0-9_'.]){re.escape(name)}(?![A-Za-z0-9_'.])",
                haystack,
            )
            for name in names
        )

    if mentions_solution(rhs) and not mentions_solution(lhs):
        proposition = lhs
    elif mentions_solution(lhs) and not mentions_solution(rhs):
        proposition = rhs
    else:
        return []

    def with_binders(target: str) -> str:
        out = str(target or "").strip()
        for binder in reversed(binders):
            if str(binder or "").strip():
                out = f"∀ {binder}, {out}"
        return out

    candidates = [with_binders(proposition), with_binders(f"¬ ({proposition})")]
    out: list[str] = []
    seen: set[str] = set()
    for candidate in candidates:
        compact = " ".join(str(candidate or "").split()).strip()
        if compact and compact not in seen:
            seen.add(compact)
            out.append(compact)
    return out


def _recursive_lean_operation_timeout_s(
    lean: Any,
    requested_timeout_s: float,
) -> Optional[float]:
    """Resolve a Lean operation allowance without inventing a short cap.

    Positive recursive tactic allowances are authoritative and propagate
    exactly. A non-positive value means "use the verifier's configured
    operation allowance"; returning ``None`` delegates to the verifier when
    no positive runner setting is inspectable. In particular, zero must never
    turn into the historical hidden 8s/20s deadline.
    """

    requested = float(requested_timeout_s or 0.0)
    if requested > 0.0:
        return requested
    lean_cfg = getattr(lean, "cfg", None)
    configured = float(getattr(lean_cfg, "timeout_s", 0.0) or 0.0)
    return configured if configured > 0.0 else None


def _live_lean_capability_for_new_work(lean: Any) -> Any:
    """Retarget captured Lean handles onto the published generation.

    Recycle quiesces the captured runner so abandoned tails cannot hop onto
    the replacement process. New theorem operations must follow
    ``current_generation()``; otherwise they hit the retired runner and later
    claim typechecks become ``variant_type_inconclusive``.
    """

    if lean is None:
        return lean
    target = lean
    seen: set[int] = set()
    for _ in range(16):
        target_id = id(target)
        if target_id in seen:
            break
        seen.add(target_id)
        resolver = getattr(target, "_dispatch_capability_identity_token", None)
        if not callable(resolver):
            break
        try:
            resolved = resolver()
        except Exception:
            break
        if resolved is None or resolved is target:
            break
        if isinstance(resolved, (tuple, list, str, bytes, int, float, bool)):
            # Identity tokens must be live capability objects. A tuple would
            # replace the handle and later ``check`` calls would miss Lean.
            break
        target = resolved
    current_generation = getattr(target, "current_generation", None)
    if not callable(current_generation):
        return target
    try:
        live = current_generation()
    except Exception:
        return target
    return live if live is not None else target


async def _active_root_target_lifts_to_root(
    *,
    lean: Any,
    root_statement: str,
    target: str,
    preamble: str,
    helpers: Sequence[Any],
    solution_names: Sequence[str],
    timeout_s: float,
    record_event: Optional[RecordEvent] = None,
) -> Optional[bool]:
    lean = _live_lean_capability_for_new_work(lean)
    names = [
        str(name or "").strip() for name in solution_names if str(name or "").strip()
    ]
    target_text = " ".join(str(target or "").split()).strip()
    if not names or not target_text:
        return False
    lemma_name = "mini_active_root_candidate"
    lemma = f"axiom {lemma_name} : {target_text}"
    helper_blocks = [
        str(item or "") for item in (helpers or ()) if str(item or "").strip()
    ]
    proof = "by\n  simpa [" + ", ".join(names) + f"] using {lemma_name}"
    operation_timeout_s = _recursive_lean_operation_timeout_s(lean, timeout_s)
    try:
        result = await lean.check(
            root_statement,
            proof,
            [*helper_blocks, lemma],
            preamble_override=preamble,
            timeout_s=operation_timeout_s,
        )
    except TypeError:
        try:
            result = await lean.check(
                root_statement,
                proof,
                [*helper_blocks, lemma],
                preamble_override=preamble,
            )
        except Exception as exc:
            _record(
                record_event,
                {
                    "phase": "mini_recursive_active_target_lift",
                    "target": target_text,
                    "timeout_s": float(timeout_s or 0.0),
                    "operation_timeout_s": operation_timeout_s,
                    "error": f"{type(exc).__name__}: {exc}",
                    "verdict": "active_root_lift_infrastructure_unknown_retryable",
                },
            )
            return None
    except Exception as exc:
        _record(
            record_event,
            {
                "phase": "mini_recursive_active_target_lift",
                "target": target_text,
                "timeout_s": float(timeout_s or 0.0),
                "operation_timeout_s": operation_timeout_s,
                "error": f"{type(exc).__name__}: {exc}",
                "verdict": "active_root_lift_infrastructure_unknown_retryable",
            },
        )
        return None
    output = str(getattr(result, "output", "") or "")
    parsed = getattr(result, "parsed", None)
    if (
        bool(getattr(parsed, "timeout", False))
        or bool(getattr(parsed, "infra_failure", False))
        or has_timeout(output)
        or has_infra_failure(output)
    ):
        _record(
            record_event,
            {
                "phase": "mini_recursive_active_target_lift",
                "target": target_text,
                "timeout_s": float(timeout_s or 0.0),
                "operation_timeout_s": operation_timeout_s,
                "output": output[:OUTPUT_PREVIEW_CHARS],
                "verdict": "active_root_lift_infrastructure_unknown_retryable",
            },
        )
        return None
    return bool(getattr(result, "ok", False))


async def _validated_active_root_targets(
    *,
    lean: Any,
    root_statement: str,
    preamble: str,
    helpers: Sequence[Any],
    solution_names: Sequence[str],
    kernel_goals: Sequence[Mapping[str, Any]],
    timeout_s: float,
    record_event: Optional[RecordEvent] = None,
) -> list[dict[str, Any]]:
    kernel_target = ""
    for goal in kernel_goals or ():
        if not isinstance(goal, Mapping):
            continue
        candidate = " ".join(str(goal.get("target") or "").split()).strip()
        if candidate:
            kernel_target = candidate
            break

    for target in _source_preserving_active_root_candidates(
        root_statement,
        solution_names=solution_names,
    ):
        lift_result = await _active_root_target_lifts_to_root(
            lean=lean,
            root_statement=root_statement,
            target=target,
            preamble=preamble,
            helpers=helpers,
            solution_names=solution_names,
            timeout_s=timeout_s,
            record_event=record_event,
        )
        if lift_result is None:
            return []
        if lift_result is True:
            item: dict[str, Any] = {
                "target": target,
                "working_target": target,
                "hypotheses": [],
                "target_source": "root_statement",
                "validation": "active_root_axiom_lift",
            }
            if kernel_target and kernel_target != target:
                item["kernel_target"] = kernel_target
            return [item]

    validated: list[dict[str, Any]] = []
    for goal in kernel_goals or ():
        if not isinstance(goal, Mapping):
            continue
        hypotheses = [
            str(hyp or "").strip()
            for hyp in list(goal.get("hypotheses") or [])
            if str(hyp or "").strip()
        ]
        target = " ".join(str(goal.get("target") or "").split()).strip()
        if not target or hypotheses:
            continue
        lift_result = await _active_root_target_lifts_to_root(
            lean=lean,
            root_statement=root_statement,
            target=target,
            preamble=preamble,
            helpers=helpers,
            solution_names=solution_names,
            timeout_s=timeout_s,
            record_event=record_event,
        )
        if lift_result is None:
            return []
        if lift_result is True:
            validated.append(
                {
                    "target": target,
                    "working_target": target,
                    "hypotheses": [],
                    "target_source": "proof_state",
                    "validation": "active_root_axiom_lift",
                }
            )
    return validated


async def _probe_active_root_targets(
    *,
    lean: Any,
    root_statement: str,
    preamble: str,
    helpers: Sequence[Any],
    timeout_s: float,
    record_event: Optional[RecordEvent] = None,
) -> list[dict[str, Any]]:
    """Return Lean-derived active goals after visible solution simplification.

    In answer-safe mode the preamble contains opaque ``*_solution`` axioms, so
    this probe normally has no materialized name to unfold and returns nothing.
    In explicit visible-answer runs, however, the recursive planner must see
    the same polarity that direct proof turns see after ``simp``; otherwise it
    can spend the whole budget proving a counterexample to the wrong side of an
    equivalence.
    """

    names = tuple(
        name
        for name in _solution_names_in_text(root_statement)
        if _materialized_solution_name_visible(preamble, name)
    )
    if not names:
        return []
    lean = _live_lean_capability_for_new_work(lean)
    proof = "by\n  simp [" + ", ".join(names) + "]"
    operation_timeout_s = _recursive_lean_operation_timeout_s(lean, timeout_s)
    try:
        result = await lean.check(
            root_statement,
            proof,
            [str(item or "") for item in (helpers or ()) if str(item or "").strip()],
            preamble_override=preamble,
            timeout_s=operation_timeout_s,
        )
    except TypeError:
        try:
            result = await lean.check(
                root_statement,
                proof,
                [
                    str(item or "")
                    for item in (helpers or ())
                    if str(item or "").strip()
                ],
                preamble_override=preamble,
            )
        except Exception as exc:
            _record(
                record_event,
                {
                    "phase": "mini_recursive_active_target",
                    "timeout_s": float(timeout_s or 0.0),
                    "operation_timeout_s": operation_timeout_s,
                    "error": f"{type(exc).__name__}: {exc}",
                    "verdict": "active_root_probe_infrastructure_unknown_retryable",
                },
            )
            return []
    except Exception as exc:
        _record(
            record_event,
            {
                "phase": "mini_recursive_active_target",
                "timeout_s": float(timeout_s or 0.0),
                "operation_timeout_s": operation_timeout_s,
                "error": f"{type(exc).__name__}: {exc}",
                "verdict": "active_root_probe_infrastructure_unknown_retryable",
            },
        )
        return []
    if bool(getattr(result, "ok", False)):
        _record(
            record_event,
            {
                "phase": "mini_recursive_active_target",
                "proof": proof,
                "solution_names": list(names),
                "verdict": "active_root_simplification_proof_accepted",
            },
        )
        return []
    output = str(getattr(result, "output", "") or "")
    parsed = getattr(result, "parsed", None)
    if (
        bool(getattr(parsed, "timeout", False))
        or bool(getattr(parsed, "infra_failure", False))
        or has_timeout(output)
        or has_infra_failure(output)
    ):
        _record(
            record_event,
            {
                "phase": "mini_recursive_active_target",
                "timeout_s": float(timeout_s or 0.0),
                "operation_timeout_s": operation_timeout_s,
                "output": output[:OUTPUT_PREVIEW_CHARS],
                "verdict": "active_root_probe_infrastructure_unknown_retryable",
            },
        )
        return []
    kernel_goals = _active_target_goals_from_parsed(parsed)
    return await _validated_active_root_targets(
        lean=lean,
        root_statement=root_statement,
        preamble=preamble,
        helpers=helpers,
        solution_names=names,
        kernel_goals=kernel_goals,
        timeout_s=timeout_s,
        record_event=record_event,
    )


def _format_active_root_targets_for_planner(
    goals: Sequence[Mapping[str, Any]],
    *,
    suppress_solution_placeholders: Optional[bool] = None,
) -> str:
    active = [
        dict(goal)
        for goal in goals or ()
        if str(goal.get("working_target") or goal.get("target") or "").strip()
        and not is_answer_unsafe_statement_text(
            str(goal.get("working_target") or goal.get("target") or ""),
            suppress_solution_placeholders=suppress_solution_placeholders,
            opaque_mode=True,
            allow_official_answer_visibility=False,
        )
    ]
    if not active:
        return ""
    lines = [
        "Lean-derived active root target (authoritative working target):",
        (
            "The verifier has mechanically reduced the original `↔ _solution` "
            "shell. Decompose and prove the following remaining mathematical "
            "goal(s) directly. Do not plan a counterexample, negation, or "
            "opposite-polarity route unless the active target itself is a negation."
        ),
    ]
    for index, goal in enumerate(active[:3], start=1):
        hypotheses = [
            str(item or "").strip()
            for item in list(goal.get("hypotheses") or [])[:6]
            if str(item or "").strip()
        ]
        if hypotheses:
            lines.append(f"- goal {index} hypotheses: " + "; ".join(hypotheses))
        target = str(goal.get("working_target") or goal.get("target") or "").strip()
        lines.append(f"- goal {index} target: {target}")
    return "\n".join(lines)


def _active_root_statement_for_planner(
    active_root_targets: Sequence[Mapping[str, Any]],
    *,
    suppress_solution_placeholders: Optional[bool] = None,
) -> str:
    for item in list(active_root_targets or ()):
        if not isinstance(item, Mapping):
            continue
        target = " ".join(
            str(item.get("working_target") or item.get("target") or "").split()
        ).strip()
        if target and not is_answer_unsafe_statement_text(
            target,
            suppress_solution_placeholders=suppress_solution_placeholders,
            opaque_mode=True,
            allow_official_answer_visibility=False,
        ):
            return target
    return ""


def _active_root_target_contract_identities(
    active_root_targets: Sequence[Mapping[str, Any]],
    *,
    expected_environment_hash: str = "",
) -> tuple[str, ...]:
    """Return receipt-bound Lean identities for framed active target statements."""

    identities: list[str] = []
    for item in active_root_targets or ():
        if not isinstance(item, Mapping):
            continue
        statements = active_root_equivalence_statements([dict(item)])
        if not statements:
            continue
        identity = str(item.get("contract_identity") or "").strip()
        statement_key = str(item.get("contract_identity_statement_key") or "").strip()
        environment_hash = str(
            item.get("contract_identity_environment_hash") or ""
        ).strip()
        if (
            str(expected_environment_hash or "").strip()
            and environment_hash != str(expected_environment_hash or "").strip()
        ):
            continue
        receipt = str(item.get("contract_identity_evidence_receipt") or "").strip()
        if statement_key != graph_statement_key(statements[0]):
            continue
        if not lean_contract_evidence_receipt_matches(
            receipt,
            identity=identity,
            statement_key=statement_key,
            environment_hash=environment_hash,
        ):
            continue
        identities.append(identity)
    return tuple(identities)


def _active_root_target_contract_identity_map(
    active_root_targets: Sequence[Mapping[str, Any]],
    *,
    expected_environment_hash: str = "",
) -> dict[str, str]:
    """Return receipt-bound identities keyed by their closed statement."""

    result: dict[str, str] = {}
    for item in active_root_targets or ():
        if not isinstance(item, Mapping):
            continue
        statements = active_root_equivalence_statements([dict(item)])
        identities = _active_root_target_contract_identities(
            [item],
            expected_environment_hash=expected_environment_hash,
        )
        if not statements or not identities:
            continue
        key = graph_statement_key(statements[0])
        if key:
            result[key] = identities[0]
    return result


async def _await_with_planner_inflight_heartbeat(
    awaitable: Awaitable[Any],
    *,
    record_event: Optional[Callable[[dict[str, Any]], None]],
    event: Mapping[str, Any],
    interval_s: float = _PLANNER_INFLIGHT_HEARTBEAT_INTERVAL_S,
) -> Any:
    """Publish liveness while preserving the awaited operation's semantics."""

    if record_event is None:
        return await awaitable
    interval = max(0.001, float(interval_s or 0.001))
    started = time.monotonic()

    async def emit_heartbeats() -> None:
        heartbeat_index = 0
        while True:
            await asyncio.sleep(interval)
            heartbeat_index += 1
            try:
                _record(
                    record_event,
                    {
                        **dict(event),
                        "planner_inflight_elapsed_s": round(
                            max(0.0, time.monotonic() - started),
                            3,
                        ),
                        "planner_inflight_heartbeat_index": heartbeat_index,
                        "verdict": "plan_inflight",
                    },
                )
            except Exception:
                # Observability must never change the provider call's result,
                # retry policy, or cancellation behavior.
                return

    heartbeat_task = asyncio.create_task(emit_heartbeats())
    try:
        return await awaitable
    finally:
        heartbeat_task.cancel()
        try:
            await heartbeat_task
        except asyncio.CancelledError:
            pass
        except Exception:
            pass


async def _await_planner_job_or_yield(
    *,
    broker: Optional[PlannerJobBroker],
    identity: Optional[PlannerJobIdentity],
    run: Callable[[], Awaitable[Any]],
    before_yield: Optional[Callable[[PlannerJobIdentity], Awaitable[None]]] = None,
) -> Any:
    """Consume one exact raw planner receipt or transfer its pure I/O job.

    Prompt parsing, recursive statistics, graph filtering, and every proof
    mutation remain in the caller's action transaction.  The launch closure
    contains only provider/metering I/O and may therefore be owned by the
    session scheduler after this action returns.
    """

    if broker is None or identity is None:
        return await run()
    result = broker.peek(identity.job_id, identity.request_fingerprint)
    launch = PlannerJobLaunch(identity=identity, run=run)
    if result is None:
        if before_yield is not None:
            await before_yield(identity)
        raise PlannerJobYield(launch)
    if result.identity != identity:
        # A short-key collision is never authority to parse or publish a
        # response for a different frontier.  The stale one-shot receipt is
        # retired explicitly; a fresh exact request is transferred instead.
        broker.acknowledge(result.identity)
        if before_yield is not None:
            await before_yield(identity)
        raise PlannerJobYield(launch)
    if result.exception is not None:
        try:
            replay_exception = copy.copy(result.exception)
        except Exception:
            replay_exception = result.exception
        raise replay_exception.with_traceback(None)
    return result.value


def _planner_provider_lane_fingerprint(client: Any) -> str:
    cfg = getattr(client, "cfg", None)
    return text_hash(
        json.dumps(
            {
                "model": str(getattr(cfg, "model", "") or ""),
                "base_url": str(
                    getattr(cfg, "base_url", "")
                    or getattr(client, "base_url", "")
                    or ""
                ),
                "reasoning_effort": str(getattr(cfg, "reasoning_effort", "") or ""),
            },
            sort_keys=True,
            separators=(",", ":"),
        )
    )


def _planner_provider_lane_matches(client: Any, fingerprint: str) -> bool:
    """Whether a saved serving leaf belongs to this client capability."""

    return _planner_provider_lane_client(client, fingerprint) is not None


def _planner_provider_candidates(client: Any) -> list[Any]:
    """Return one bounded, cycle-safe traversal of a provider capability."""

    pending = [client]
    seen: set[int] = set()
    candidates: list[Any] = []
    while pending and len(seen) < 64:
        candidate = pending.pop(0)
        if candidate is None or id(candidate) in seen:
            continue
        seen.add(id(candidate))
        candidates.append(candidate)
        try:
            pending.extend(mini_request_wrapper_children(candidate))
        except Exception:
            continue
    return candidates


def _planner_provider_lane_client(client: Any, fingerprint: str) -> Optional[Any]:
    """Resolve the exact serving leaf named by a durable lane fingerprint."""

    expected = str(fingerprint or "").strip()
    if not expected:
        return None
    for candidate in _planner_provider_candidates(client):
        if _planner_provider_lane_fingerprint(candidate) == expected:
            return candidate
    return None


def _planner_material_fingerprint(material: Any) -> str:
    """Return the lane-independent identity of one logical planner request."""

    return text_hash(_planner_material_json(material))


def _planner_material_json(material: Any) -> str:
    """Canonical, checkpoint-safe encoding of public planner request material."""

    return json.dumps(
        material,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
        default=str,
    )


def _planner_material_checkpoint_json(
    material: Any,
    io_policy: Optional[Mapping[str, Any]] = None,
) -> str:
    """Versioned durable envelope for exact provider-free request material."""

    return _planner_material_json(
        {
            "schema_version": 1,
            "kind": "mini_recursive_planner_request_material",
            "material": material,
            "io_policy": dict(io_policy or {}),
        }
    )


def _planner_io_policy_record(
    *,
    max_tokens: int,
    reasoning_effort: Any,
    temperature: Any,
    provider_dispatch_max_attempts: int,
    request_timeout_s: float,
    operation_timeout_s: float,
    deadlines_enabled: bool,
) -> dict[str, Any]:
    """Durable logical bounds for one exact provider request."""

    return {
        "schema_version": 1,
        "max_tokens": max(1, int(max_tokens or 1)),
        "reasoning_effort": str(reasoning_effort or ""),
        "temperature": temperature,
        "provider_dispatch_max_attempts": max(
            0,
            int(provider_dispatch_max_attempts or 0),
        ),
        "request_timeout_s": float(request_timeout_s),
        "operation_timeout_s": float(operation_timeout_s),
        "deadlines_enabled": bool(deadlines_enabled),
    }


def _validated_planner_io_policy(
    policy: Optional[Mapping[str, Any]],
) -> Optional[dict[str, Any]]:
    """Normalize a persisted I/O policy without widening its saved bounds."""

    if not isinstance(policy, Mapping) or policy.get("schema_version") != 1:
        return None
    try:
        max_tokens = int(policy.get("max_tokens") or 0)
        attempts = int(policy.get("provider_dispatch_max_attempts") or 0)
        request_timeout_s = float(policy.get("request_timeout_s"))
        operation_timeout_s = float(policy.get("operation_timeout_s"))
    except (TypeError, ValueError, OverflowError):
        return None
    if not 1 <= max_tokens <= 10_000_000:
        return None
    if not 0 <= attempts <= 64:
        return None
    if not request_timeout_s > 0.0 or not operation_timeout_s > 0.0:
        return None
    deadlines_enabled = bool(policy.get("deadlines_enabled"))
    if deadlines_enabled and not (
        math.isfinite(request_timeout_s) and math.isfinite(operation_timeout_s)
    ):
        return None
    reasoning_effort = str(policy.get("reasoning_effort") or "")
    if len(reasoning_effort) > 64:
        return None
    temperature = policy.get("temperature")
    if temperature is not None:
        try:
            temperature = float(temperature)
        except (TypeError, ValueError, OverflowError):
            return None
        if not -2.0 <= temperature <= 2.0:
            return None
    return _planner_io_policy_record(
        max_tokens=max_tokens,
        reasoning_effort=reasoning_effort,
        temperature=temperature,
        provider_dispatch_max_attempts=attempts,
        request_timeout_s=request_timeout_s,
        operation_timeout_s=operation_timeout_s,
        deadlines_enabled=deadlines_enabled,
    )


def _planner_bound_request_fingerprint(
    identity: PlannerJobIdentity,
    *,
    job_id: str,
    stage: str,
    round_index: int,
    material_fingerprint: str,
    io_policy_fingerprint: str,
    request_context_fingerprint: str,
) -> str:
    """Fence request bytes against accidental/cross-job checkpoint drift.

    Driver checkpoints are trusted local state; this digest is an internal
    consistency key, not an authenticity claim against coordinated local
    checkpoint modification.
    """

    return _planner_material_fingerprint(
        {
            "schema_version": 1,
            "job_id": str(job_id or ""),
            "stage": str(stage or ""),
            "stage_round": max(0, int(round_index or 0)),
            "pass_index": int(identity.pass_index or 0),
            "root_statement_hash": str(identity.root_statement_hash or ""),
            "route_environment_hash": str(identity.route_environment_hash or ""),
            "proof_idea_cognition_hash": str(identity.proof_idea_cognition_hash or ""),
            "planner_frontier_signature": str(
                identity.planner_frontier_signature or ""
            ),
            "owner_lane_id": str(identity.owner_lane_id or ""),
            "answer_visibility_policy_hash": str(
                identity.answer_visibility_policy_hash or ""
            ),
            "active_target_statement_keys": list(identity.active_target_statement_keys),
            "helper_evidence_fingerprints": list(identity.helper_evidence_fingerprints),
            "request_material_fingerprint": str(material_fingerprint or ""),
            "request_io_policy_fingerprint": str(io_policy_fingerprint or ""),
            "request_context_fingerprint": str(request_context_fingerprint or ""),
        }
    )


def _saved_planner_request_envelope(
    identity: Optional[PlannerJobIdentity],
    *,
    expected_stages: AbstractSet[str],
) -> Optional[tuple[list[dict[str, Any]], dict[str, Any]]]:
    """Validate and restore exact public request bytes and logical I/O policy."""

    if identity is None or identity.stage not in expected_stages:
        return None
    material_json = str(identity.request_material_json or "")
    if not material_json or len(material_json) > 8 * 1024 * 1024:
        return None
    try:
        envelope = json.loads(material_json)
    except (TypeError, ValueError):
        return None
    if not isinstance(envelope, Mapping):
        return None
    if envelope.get("schema_version") != 1:
        return None
    if envelope.get("kind") != "mini_recursive_planner_request_material":
        return None
    material = envelope.get("material")
    io_policy = envelope.get("io_policy")
    if not isinstance(material, list) or len(material) > 64:
        return None
    if not all(isinstance(message, Mapping) for message in material):
        return None
    if not isinstance(io_policy, Mapping):
        return None
    normalized_io_policy = _validated_planner_io_policy(io_policy)
    if normalized_io_policy is None:
        return None
    if _planner_material_fingerprint(material) != (
        identity.request_material_fingerprint
    ):
        return None
    if _planner_material_fingerprint(normalized_io_policy) != (
        identity.request_io_policy_fingerprint
    ):
        return None
    if identity.request_fingerprint != _planner_bound_request_fingerprint(
        identity,
        job_id=identity.job_id,
        stage=identity.stage,
        round_index=identity.stage_round,
        material_fingerprint=identity.request_material_fingerprint,
        io_policy_fingerprint=identity.request_io_policy_fingerprint,
        request_context_fingerprint=identity.request_context_fingerprint,
    ):
        return None
    return (
        [dict(message) for message in material],
        normalized_io_policy,
    )


def _saved_planner_request_messages(
    identity: Optional[PlannerJobIdentity],
    *,
    expected_stages: AbstractSet[str],
) -> Optional[list[dict[str, Any]]]:
    envelope = _saved_planner_request_envelope(
        identity,
        expected_stages=expected_stages,
    )
    return envelope[0] if envelope is not None else None


def _planner_deliberation_material_fingerprint(
    *,
    planner_prompt: str,
    selected_parent_proof_idea_context: str,
    round_index: int,
) -> str:
    """Identify public deliberation content independently of its provider."""

    return _planner_material_fingerprint(
        {
            "planner_prompt": str(planner_prompt or ""),
            "selected_parent_proof_idea_context": str(
                selected_parent_proof_idea_context or ""
            ),
            "round_index": max(0, int(round_index or 0)),
        }
    )


def planner_job_identity_is_compatible(
    saved: PlannerJobIdentity,
    *,
    current_root_statement_hash: str,
    current_route_environment_hash: str,
    current_answer_visibility_policy_hash: str,
    current_active_target_statement_keys: Sequence[str],
    current_helper_evidence_fingerprints: Optional[Sequence[str]] = None,
    environment_is_compatible: Callable[[str, str], bool],
    current_owner_lane_id: Optional[str] = None,
    root_already_solved: bool = False,
) -> bool:
    """Admit a raw planner receipt under monotone current authority."""

    if saved.root_statement_hash != str(current_root_statement_hash or ""):
        return False
    if saved.answer_visibility_policy_hash != str(
        current_answer_visibility_policy_hash or ""
    ):
        return False
    if current_owner_lane_id is not None and saved.owner_lane_id != str(
        current_owner_lane_id or ""
    ):
        return False
    try:
        environment_compatible = bool(
            environment_is_compatible(
                saved.route_environment_hash,
                str(current_route_environment_hash or ""),
            )
        )
    except Exception:
        return False
    if not environment_compatible:
        return False
    if root_already_solved:
        return True
    if current_helper_evidence_fingerprints is not None:
        current_helper_evidence = {
            str(item or "")
            for item in current_helper_evidence_fingerprints
            if str(item or "")
        }
        if not set(saved.helper_evidence_fingerprints).issubset(
            current_helper_evidence
        ):
            return False
    current_targets = {
        str(item or "")
        for item in current_active_target_statement_keys
        if str(item or "")
    }
    return set(saved.active_target_statement_keys).issubset(current_targets)


def _planner_stage_job_identity(
    base: Optional[PlannerJobIdentity],
    *,
    stage: str,
    material: Any,
    round_index: int = 0,
    request_context_fingerprint: str = "",
    io_policy: Optional[Mapping[str, Any]] = None,
) -> Optional[PlannerJobIdentity]:
    if base is None:
        return None
    stage_key = str(stage or "planner")
    normalized_round = max(0, int(round_index or 0))
    material_fingerprint = _planner_material_fingerprint(material)
    normalized_io_policy = dict(io_policy or {})
    io_policy_fingerprint = _planner_material_fingerprint(normalized_io_policy)
    material_json = _planner_material_checkpoint_json(
        material,
        normalized_io_policy,
    )
    context_fingerprint = str(
        request_context_fingerprint or base.request_context_fingerprint or ""
    )
    same_stage = (
        base.stage == stage_key and int(base.stage_round or 0) == normalized_round
    )
    job_id = (
        base.job_id if same_stage else f"{base.job_id}:{stage_key}:{normalized_round}"
    )
    fingerprint = _planner_bound_request_fingerprint(
        base,
        job_id=job_id,
        stage=stage_key,
        round_index=normalized_round,
        material_fingerprint=material_fingerprint,
        io_policy_fingerprint=io_policy_fingerprint,
        request_context_fingerprint=context_fingerprint,
    )
    if (
        same_stage
        and base.request_fingerprint == fingerprint
        and base.request_material_fingerprint == material_fingerprint
        and base.request_io_policy_fingerprint == io_policy_fingerprint
        and base.request_material_json == material_json
        and base.request_context_fingerprint == context_fingerprint
    ):
        return base
    return dataclass_replace(
        base,
        job_id=job_id,
        request_fingerprint=fingerprint,
        stage=stage_key,
        stage_round=normalized_round,
        request_material_fingerprint=material_fingerprint,
        request_io_policy_fingerprint=io_policy_fingerprint,
        request_material_json=material_json,
        request_context_fingerprint=context_fingerprint,
    )


def _merge_positional_active_target_contract_identities(
    statements: Sequence[str],
    fresh_identities: Sequence[str],
    prior_identities_by_statement_key: Mapping[str, str],
) -> tuple[str, ...]:
    """Merge fresh/prior evidence without losing target positions."""

    merged: list[str] = []
    for index, statement in enumerate(statements):
        fresh = str(
            fresh_identities[index] if index < len(fresh_identities) else ""
        ).strip()
        merged.append(
            fresh
            if has_lean_contract_identity(fresh)
            else str(
                prior_identities_by_statement_key.get(
                    graph_statement_key(statement),
                    "",
                )
                or ""
            ).strip()
        )
    return tuple(merged)


_WRONG_POLARITY_ROOT_TARGET_SUBJECT = (
    r"(?:"
    r"(?:the\s+)?(?:root(?:\s+(?:target|claim|statement|property|theorem))?|target)|"
    r"(?:the\s+)?(?:active|checked|current)\s+"
    r"(?:root(?:\s+(?:target|claim|statement|property|theorem))?|"
    r"target|claim|statement|property|theorem)|"
    r"the\s+(?:claim|statement|property|theorem)"
    r")"
)
_WRONG_POLARITY_ROUTE_RE = re.compile(
    rf"\b(?:"
    rf"(?:disprov(?:e|es|ed|ing)|refut(?:e|es|ed|ing))\s+"
    rf"{_WRONG_POLARITY_ROOT_TARGET_SUBJECT}|"
    rf"prove(?:s|d|ing)?\s+(?:the\s+)?negation(?:\s+of)?\s+"
    rf"{_WRONG_POLARITY_ROOT_TARGET_SUBJECT}|"
    rf"show(?:s|ed|ing)?\s+{_WRONG_POLARITY_ROOT_TARGET_SUBJECT}\s+"
    rf"(?:is\s+)?false|"
    rf"{_WRONG_POLARITY_ROOT_TARGET_SUBJECT}\s+"
    rf"(?:(?:is\s+)?false|fails?(?:\s+in\s+general)?|does\s+not\s+hold)"
    rf")\b",
    re.IGNORECASE,
)


_COUNTEREXAMPLE_ROUTE_TERM_RE = (
    r"(?<![A-Za-z0-9])(?:counterexamples?|counter-examples?|"
    r"disprov(?:e|es|ed|ing)|refut(?:e|es|ed|ing|ation)|"
    r"falsif(?:y|ies|ied|ying))(?![A-Za-z0-9])"
)
_COUNTEREXAMPLE_TARGET_TERM_RE = (
    r"(?<![A-Za-z0-9])(?:left\s+side|right\s+side|root|solution\s+side|"
    r"solution\s+constant|(?:universal|quantified)\s+implication|property|"
    r"statement|theorem)(?![A-Za-z0-9])"
)
_COUNTEREXAMPLE_FALSE_TERM_RE = (
    r"(?<![A-Za-z0-9])(?:false|fails?|falsif(?:y|ies|ied|ying)|"
    r"refut(?:e|es|ed|ing|ation))"
    r"(?![A-Za-z0-9])"
)
_DECISIVE_UNCHECKED_COUNTEREXAMPLE_ROUTE_RE = re.compile(
    _COUNTEREXAMPLE_ROUTE_TERM_RE
    + r"[\s\S]{0,360}"
    + _COUNTEREXAMPLE_TARGET_TERM_RE
    + r"[\s\S]{0,240}"
    + _COUNTEREXAMPLE_FALSE_TERM_RE
    + r"|"
    + _COUNTEREXAMPLE_TARGET_TERM_RE
    + r"[\s\S]{0,240}"
    + _COUNTEREXAMPLE_FALSE_TERM_RE
    + r"[\s\S]{0,360}"
    + _COUNTEREXAMPLE_ROUTE_TERM_RE,
    re.IGNORECASE,
)


_SOLUTION_EQUIVALENCE_HINT_RE = re.compile(r"(?:↔|<->|\bIff\b)")


def _root_is_solution_placeholder_equivalence(root_statement: str) -> bool:
    text = str(root_statement or "")
    return bool(
        _solution_names_in_text(text) and _SOLUTION_EQUIVALENCE_HINT_RE.search(text)
    )


def _unchecked_counterexample_route_reason(
    plan: MiniSubgoalPlan,
    *,
    active_root_targets: Sequence[Mapping[str, Any]] = (),
) -> str:
    """Detect a decisive negative route when no checked active target exists.

    Counterexample search is a useful probe, and some yes/no problems are
    genuinely false.  The unsafe case is narrower: for an opaque
    ``P ↔ *_solution`` shell, a plan that has not proved a witness yet should
    not make "counterexample implies root/solution side false" the only
    recursive route.
    """

    if _active_targets_require_positive_route(active_root_targets):
        return ""
    if not _root_is_solution_placeholder_equivalence(plan.root_statement):
        return ""
    route_text = "\n".join(
        str(part or "")
        for part in (
            plan.strategy,
            " ".join(plan.notes or ()),
            *(
                "\n".join(
                    str(piece or "")
                    for piece in (
                        claim.name,
                        claim.statement,
                        claim.rationale,
                        claim.sanity_check,
                        claim.counting_classification,
                    )
                )
                for claim in plan.claims
            ),
        )
    )
    match = _DECISIVE_UNCHECKED_COUNTEREXAMPLE_ROUTE_RE.search(route_text)
    if not match:
        return ""
    if _claim_invalidity_context_is_negated_or_speculative(route_text, match):
        return ""
    return _compact_text(match.group(0), 220)


def _active_targets_require_positive_route(
    active_root_targets: Sequence[Mapping[str, Any]],
) -> bool:
    return bool(_positive_active_target_texts(active_root_targets))


def _positive_active_target_texts(
    active_root_targets: Sequence[Mapping[str, Any]],
) -> tuple[str, ...]:
    targets: list[str] = [
        normalize_subgoal_statement(
            str(goal.get("working_target") or goal.get("target") or "")
        )
        for goal in active_root_targets or ()
        if str(goal.get("working_target") or goal.get("target") or "").strip()
    ]
    positive: list[str] = []
    for target in targets:
        compact = " ".join(target.split()).strip()
        polarity_surface = _strip_balanced_outer_parens(compact)
        implication_parts = _split_top_level_implications(polarity_surface)
        implication_to_false = bool(
            len(implication_parts) == 2
            and _lean_compact_key(_strip_balanced_outer_parens(implication_parts[-1]))
            == "False"
        )
        if (
            polarity_surface == "False"
            or bool(_strip_leading_lean_negation(polarity_surface))
            or implication_to_false
        ):
            continue
        positive.append(target)
    return tuple(positive)


def _wrong_polarity_route_reason(text: str) -> str:
    raw = str(text or "")
    match = _WRONG_POLARITY_ROUTE_RE.search(raw)
    if not match:
        return ""
    if _claim_invalidity_context_is_negated_or_speculative(raw, match):
        return ""
    return _compact_text(match.group(0), 220)


def _statement_negates_active_target_reason(
    statement: str,
    active_root_targets: Sequence[Mapping[str, Any]],
) -> str:
    stmt = normalize_subgoal_statement(str(statement or "")).strip()
    if not stmt:
        return ""
    positive_targets = _positive_active_target_texts(active_root_targets)
    if not positive_targets:
        return ""
    compact_stmt = _strip_balanced_outer_parens(" ".join(stmt.split()).strip())
    # Uniform ``¬``/``Not ``/``Not(`` handling so a renamed-keyword negation is
    # not silently missed.
    negated = _strip_leading_lean_negation(compact_stmt)

    candidate_formulas: list[str] = []
    if negated:
        negated_formula = _strip_balanced_outer_parens(negated)
        if negated_formula:
            candidate_formulas.append(negated_formula)
    implication_parts = _split_top_level_implications(compact_stmt)
    if (
        len(implication_parts) == 2
        and _lean_compact_key(_strip_balanced_outer_parens(implication_parts[-1]))
        == "False"
    ):
        antecedent = _strip_balanced_outer_parens(implication_parts[0])
        if antecedent:
            candidate_formulas.append(antecedent)

    if not candidate_formulas:
        return ""
    for target in positive_targets:
        target_formula = _strip_balanced_outer_parens(target)
        if not target_formula:
            continue
        # Exact telescope-aware alpha-equivalence only. Raw substring containment wrongly flags
        # ``¬(n=0 ∧ P)`` and ``¬(n=01)`` as negations of ``n=0``, while
        # raw compact equality misses ``¬(∀ m, P m)`` against ``∀ n, P n``.
        # Comparing the non-proof binder profile also prevents the stripped
        # body from conflating ``Nat``/``Int`` domains or different arities.
        if any(
            _contract_alpha_matches_exact_telescope(candidate, target_formula)
            for candidate in candidate_formulas
        ):
            return "claim statement negates the checked active target"
    return ""


def _bounded_planner_proof_idea_projection(
    projection: ProofIdeaGlobalContextProjection,
    *,
    max_chars: int,
) -> ProofIdeaGlobalContextProjection:
    """Compact an advisory lifecycle without slicing evidence artifacts.

    Identity/strategy units and current semantic lifecycle records outrank
    historical observations. Observation recency is read from its explicit
    coordinates/source metadata; producer/hash order is never treated as
    chronology. Omitted original units are represented by one complete
    hash/length receipt, so compaction is explicit even when individual idea
    units cannot all fit.
    """

    limit = max(0, int(max_chars or 0))
    if limit <= 0 or len(projection.render()) <= limit:
        return projection

    evidence = tuple(projection.evidence)
    selected: dict[int, ProofIdeaContextEvidence] = {}

    def candidate_projection(
        items: Mapping[int, ProofIdeaContextEvidence],
    ) -> ProofIdeaGlobalContextProjection:
        return ProofIdeaGlobalContextProjection(
            audience=projection.audience,
            context_digest=projection.context_digest,
            evidence=tuple(items[index] for index in sorted(items)),
            proof_authority=False,
        )

    empty_projection = candidate_projection({})
    empty_chars = len(empty_projection.render())
    if empty_chars > limit:
        raise ValueError(
            "planner lifecycle context limit is smaller than its required header"
        )
    selected_chars = empty_chars

    def rendered_evidence_chars(item: ProofIdeaContextEvidence) -> int:
        header = (
            f"[{item.kind}; completeness={item.completeness}; "
            f"sha256={item.sha256}; chars={item.char_length}]"
        )
        body = (
            f"(withheld: {item.omitted_reason})"
            if item.completeness == "withheld"
            else item.content
        )
        return len(header) + len(body) + 2

    observation_prefixes = (
        "idea_observation_coordinates:",
        "idea_observation_summary:",
        "idea_near_theorems:",
        "idea_attempted_lean:",
        "idea_exact_lean_output:",
        "idea_lean_output_preview:",
        "idea_stored_lean_output_preview:",
        "idea_stored_lean_output_original_length:",
        "idea_observation_source:",
    )
    groups: dict[str, list[int]] = {}
    for index, item in enumerate(evidence):
        group_key = f"unit:{index}"
        if item.kind.startswith("idea_identity:"):
            group_key = "idea_core:" + item.kind[len("idea_identity:") :]
        elif item.kind.startswith("idea_strategy:"):
            group_key = "idea_core:" + item.kind[len("idea_strategy:") :]
        for prefix in observation_prefixes:
            if item.kind.startswith(prefix):
                group_key = "observation:" + item.kind[len(prefix) :]
                break
        groups.setdefault(group_key, []).append(index)

    def observation_newness(indices: Sequence[int]) -> tuple[int, int]:
        source_pass = -1
        turn_index = -1
        for index in indices:
            item = evidence[index]
            if item.completeness == "withheld" or not item.content:
                continue
            try:
                payload = json.loads(item.content)
            except (TypeError, ValueError, json.JSONDecodeError):
                continue
            if not isinstance(payload, Mapping):
                continue
            if item.kind.startswith("idea_observation_coordinates:"):
                try:
                    turn_index = max(
                        turn_index,
                        int(payload.get("turn_index", -1) or -1),
                    )
                except (TypeError, ValueError):
                    pass
            elif item.kind.startswith("idea_observation_source:"):
                try:
                    source_pass = max(
                        source_pass,
                        int(payload.get("pass_index", -1) or -1),
                    )
                except (TypeError, ValueError):
                    pass
        return source_pass, turn_index

    def group_priority(group_key: str, indices: Sequence[int]) -> tuple[Any, ...]:
        kinds = tuple(evidence[index].kind for index in indices)
        if group_key.startswith("idea_core:"):
            priority = 500
        elif any(kind.startswith("idea_status_history:") for kind in kinds):
            priority = 450
        elif any(kind.startswith("idea_claim_resolution:") for kind in kinds):
            priority = 425
        elif any(kind.startswith("idea_claim_intent:") for kind in kinds):
            priority = 400
        elif any(kind.startswith("idea_notes:") for kind in kinds):
            priority = 375
        elif group_key.startswith("observation:"):
            priority = 300
        elif any(kind.startswith("idea_branch_provenance:") for kind in kinds):
            priority = 200
        else:
            priority = 100
        source_pass, turn_index = observation_newness(indices)
        # The group key is a deterministic tie-breaker, not a chronology proxy.
        return priority, source_pass, turn_index, group_key

    ranked_groups = sorted(
        groups.items(),
        key=lambda entry: group_priority(entry[0], entry[1]),
        reverse=True,
    )
    selected_groups: list[tuple[str, tuple[int, ...]]] = []
    for group_key, raw_indices in ranked_groups:
        indices = tuple(raw_indices)
        group_chars = sum(rendered_evidence_chars(evidence[index]) for index in indices)
        if selected_chars + group_chars <= limit:
            for index in indices:
                selected[index] = evidence[index]
            selected_chars += group_chars
            selected_groups.append((group_key, indices))
            continue
        if not group_key.startswith("idea_core:"):
            continue
        # Keep an atomic per-unit receipt for core idea inventory when its
        # exact strategy/identity text is individually too large.
        receipts: dict[int, ProofIdeaContextEvidence] = {}
        for index in indices:
            item = evidence[index]
            receipts[index] = ProofIdeaContextEvidence.withheld_receipt(
                item.kind,
                sha256=item.sha256,
                char_length=item.char_length,
                reason="planner lifecycle context limit",
            )
        receipt_chars = sum(rendered_evidence_chars(item) for item in receipts.values())
        if selected_chars + receipt_chars <= limit:
            selected.update(receipts)
            selected_chars += receipt_chars
            selected_groups.append((group_key, indices))

    def omitted_records() -> list[dict[str, Any]]:
        return [
            item.to_record()
            for index, item in enumerate(evidence)
            if index not in selected or selected[index] != item
        ]

    def omission_receipt() -> Optional[ProofIdeaContextEvidence]:
        omitted = omitted_records()
        if not omitted:
            return None
        omitted_payload = json.dumps(
            omitted,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
        )
        return ProofIdeaContextEvidence.withheld(
            "lifecycle_history_compacted",
            omitted_payload,
            reason=f"planner context limit omitted {len(omitted)} whole units",
        )

    receipt_index = len(evidence)
    receipt = omission_receipt()
    while receipt is not None:
        with_receipt = dict(selected)
        with_receipt[receipt_index] = receipt
        receipt_chars = rendered_evidence_chars(receipt)
        if selected_chars + receipt_chars <= limit:
            selected = with_receipt
            selected_chars += receipt_chars
            break
        if not selected_groups:
            raise ValueError(
                "planner lifecycle context limit cannot fit its omission receipt"
            )
        _group_key, indices = selected_groups.pop()
        for index in indices:
            removed = selected.pop(index, None)
            if removed is not None:
                selected_chars -= rendered_evidence_chars(removed)
        receipt = omission_receipt()

    compact = candidate_projection(selected)
    if len(compact.render()) > limit:
        raise AssertionError("planner lifecycle projection exceeded its hard limit")
    return compact


def _project_planner_proof_idea_lifecycle_context(
    dossier: Any,
    *,
    max_chars: int = 98304,
) -> str:
    """Render every conserved strategy lifecycle for planner orientation.

    This is deliberately separate from selected-work resolution: planning may
    compare all active/retired mathematical routes, while execution must bind
    to exactly one route/claim/branch owner.  The dossier projector owns answer
    visibility, whole-unit integrity receipts, and advisory trust labeling.
    """

    projector = getattr(dossier, "project_global_proof_idea_context", None)
    if not callable(projector):
        return ""
    projection = projector(audience="planner")
    if not isinstance(projection, ProofIdeaGlobalContextProjection):
        render = getattr(projection, "render", None)
        if not callable(render):
            raise TypeError("global proof-idea projection has no render method")
        return str(render() or "")
    projection = _bounded_planner_proof_idea_projection(
        projection,
        max_chars=max_chars,
    )
    render = getattr(projection, "render", None)
    if not callable(render):
        raise TypeError("global proof-idea projection has no render method")
    return str(render() or "")


_SELF_REFUTING_SANITY_RE = re.compile(
    r"\b(?:would|is|was|seems|appears)\s+(?:be\s+)?false\b"
    r"|\b(?:claim|formula|identity|statement|target)\b[^.\n;]{0,120}"
    r"\b(?:false|refuted|contradicted|mismatch(?:es|ed)?)\b"
    r"|\b(?:refutes?|contradicts?)\b[^.\n;]{0,120}"
    r"\b(?:claim|formula|identity|statement|target|rhs|lhs)\b"
    r"|\b(?:rhs|lhs)\b[^.\n;]{0,120}\b(?:mismatch|does\s+not\s+match|not\s+equal)\b"
    r"|\b(?:mismatch|does\s+not\s+match|not\s+equal)\b[^.\n;]{0,120}\b(?:rhs|lhs)\b"
    r"|\b(?:need|needs|must|should)\s+to\s+(?:ensure|correct|adjust|fix)"
    r"[^.\n;]{0,120}\b(?:algebra|identity|formula|coefficient|coefficients)\b"
    r"|\b(?:need|needs|needed|requires?|requiring)?\s*"
    r"(?:corrected|adjusted|fixed)\s+"
    r"(?:algebra|identity|formula|coefficient|coefficients)\b"
    r"|\b(?:gives?|yields?|evaluates?\s+to|results?\s+in)\b"
    r"[^.\n;]{0,120}\bfalse\b"
    r"|\b(?:equality\s+)?conclusion\b[^.\n;]{0,120}"
    r"\b(?:fails?|false|refuted|contradicted)\b",
    re.IGNORECASE,
)

_SANITY_NUMERIC_BINDER_RE = re.compile(
    r"(?:∀|\bforall\b)[^,]{0,240}:\s*"
    r"(?:ℕ\+?|Nat|ℤ|Int|ℚ|Rat|ℝ|Real|Fin\b)",
    re.IGNORECASE,
)
_SANITY_NUMERIC_OPERATION_RE = re.compile(
    r"(?:\+|-|\*|/|\^|<|>|≤|≥|≠|=\s*[-+]?\d)"
    r"|\.succ\b|\b(?:Nat\.choose|Nat\.sqrt|Real\.sqrt|Finset\.(?:range|card)|"
    r"card|floor|ceil|Tendsto|sum|prod)\b|[∑∏]",
    re.IGNORECASE,
)
_SANITY_COUNTING_HINT_RE = re.compile(
    r"\b(?:count\w*|card\b|cardinal\w*|number\s+of|enumerat\w*|"
    r"extremal\w*|boundary\w*|closed[- ]form\w*|ratio\b|limit\w*|"
    r"coefficient\w*)\b",
    re.IGNORECASE,
)
_SANITY_OBVIOUS_NUMERIC_CONTRADICTION_RE = re.compile(
    r"\b([A-Za-z_][A-Za-z0-9_']*)\s*(?:\.succ|\+\s*[1-9][0-9]*)"
    r"\s*=\s*\1\b(?!\s*[+\-*/^])"
    r"|\b([A-Za-z_][A-Za-z0-9_']*)\s*=\s*\2\s*\+\s*[1-9][0-9]*\b",
    re.IGNORECASE,
)


@dataclass(frozen=True)
class _SanityRequirement:
    """Statement-derived planner-quality diagnostic with no proof authority."""

    triggers: tuple[str, ...] = ()
    evidence: tuple[str, ...] = ()

    @property
    def required(self) -> bool:
        return bool(self.triggers)


def _claim_sanity_requirement(claim: MiniSubgoalClaim) -> _SanityRequirement:
    """Classify sanity-check guidance from executable data only.

    Names and rationales are planner prose.  They must never alter whether a
    Lean proposition is scheduled.  Even statement-derived matches remain
    diagnostics: typechecking and certified falsification own mathematical
    rejection authority.
    """

    statement = str(getattr(claim, "statement", "") or "").strip()
    triggers: list[str] = []
    evidence: list[str] = []
    counting_classification = str(
        getattr(claim, "counting_classification", "") or ""
    ).strip()
    if counting_classification:
        triggers.append("explicit_counting_classification")
        evidence.append(_compact_text(counting_classification, 220))
    contradiction = _SANITY_OBVIOUS_NUMERIC_CONTRADICTION_RE.search(statement)
    if contradiction:
        triggers.append("obvious_numeric_contradiction_shape")
        evidence.append(_compact_text(contradiction.group(0), 220))
    formula_hint = _SANITY_COUNTING_HINT_RE.search(statement)
    if formula_hint:
        triggers.append("statement_formula_keyword")
        evidence.append(_compact_text(formula_hint.group(0), 220))
    numeric_binder = _SANITY_NUMERIC_BINDER_RE.search(statement)
    numeric_operation = _SANITY_NUMERIC_OPERATION_RE.search(statement)
    if numeric_binder and numeric_operation:
        triggers.append("numeric_binder_and_operation")
        evidence.append(
            _compact_text(
                f"{numeric_binder.group(0)}; {numeric_operation.group(0)}",
                220,
            )
        )
    return _SanityRequirement(
        triggers=tuple(dict.fromkeys(triggers)),
        evidence=tuple(dict.fromkeys(evidence)),
    )


def _self_refuting_sanity_reason(claim: MiniSubgoalClaim) -> str:
    sanity = str(getattr(claim, "sanity_check", "") or "").strip()
    if not sanity:
        return ""
    match = _SELF_REFUTING_SANITY_RE.search(sanity)
    if not match:
        return ""
    return _compact_text(match.group(0), 220)


# This is deliberately narrower than ``_SELF_REFUTING_SANITY_RE``.  That
# detector is a mathematical surface heuristic and therefore remains advisory
# in the live scheduler.  These patterns instead recognize an explicit
# *withdrawal of the proposed work item*: the planner explicitly says that it
# must replace/withdraw/correct this very claim.  Bare mathematical prose such
# as ``suppose the claim is false`` is intentionally excluded: antecedents,
# contradiction arguments, and comparisons with a naive formula are not
# planning-intent withdrawals.
_EXPLICIT_CLAIM_SELF_ABANDONMENT_RE = re.compile(
    r"\b(?:i|we)\s+(?:(?:hereby)\s+)?"
    r"(?:(?:must|need\s+to|should)\s+)?"
    r"(?:correct|fix|change|replace|withdraw)\s+"
    r"(?:this|the|that)\s+(?:claim|statement|formula|identity)\b"
    r"|(?:^|(?<=[.;\n]))\s*"
    r"(?:correct|fix|change|replace|withdraw)\s+"
    r"(?:this|the|that)\s+(?:claim|statement|formula|identity)\b"
    r"|\b(?:this|the|that|proposed|current)\s+"
    r"(?:claim|statement|formula|identity)\s+"
    r"(?:(?:must|needs?\s+to|should)\s+be\s+|is\s+)"
    r"(?:corrected|fixed|changed|replaced|withdrawn)\b",
    re.IGNORECASE,
)

_CONDITIONAL_WITHDRAWAL_CLAUSE_RE = re.compile(
    r"^\s*(?:if|unless|when|whenever|assuming|suppose|supposing|"
    r"in\s+case|to\s+(?:test|check|examine|assess))\b",
    re.IGNORECASE,
)

_AMBIGUOUS_WITHDRAWAL_CONTEXT_RE = re.compile(
    r"\b(?:but|however|while|whereas|another|other|different|latter|former)\b",
    re.IGNORECASE,
)

_EXPLICIT_PARTIAL_PLAN_NOTE_RE = re.compile(
    r"\b(?:the\s+)?(?:current\s+)?(?:json|plan|decomposition|tranche)\s+"
    r"(?:is|remains)\s+(?:an?\s+)?(?:partial|incomplete)\b"
    r"|\bnext\s+(?:durable\s+)?tranche\s+"
    r"(?:should|must|needs?\s+to|will)\b",
    re.IGNORECASE,
)

_NEGATED_PARTIAL_PLAN_NOTE_RE = re.compile(
    r"\bno\s+(?:next\s+|further\s+)?(?:durable\s+)?tranche\s+"
    r"(?:is|will\s+be|would\s+be|should\s+be)\s+"
    r"(?:needed|required|necessary)\b"
    r"|\b(?:the\s+)?next\s+(?:durable\s+)?tranche\s+"
    r"(?:will|would|should|is)\s+not\s+(?:be\s+)?"
    r"(?:needed|required|necessary)\b"
    r"|\b(?:the\s+)?next\s+(?:durable\s+)?tranche\s+"
    r"(?:is|will\s+be|would\s+be)\s+unnecessary\b"
    r"|\b(?:no|not)\s+(?:additional|further)\s+tranche\s+"
    r"(?:is|will\s+be|would\s+be)?\s*(?:needed|required|necessary)\b",
    re.IGNORECASE,
)


def _plan_completion_intent(
    plan: MiniSubgoalPlan,
) -> tuple[Optional[bool], str]:
    """Return the explicit completion contract and its provenance.

    New responses carry the typed schema field.  The narrow note recognizer is
    a compatibility bridge for paid responses generated before that field was
    introduced; it recognizes only an operative plan-level partial/tranche
    declaration and grants no mathematical authority.
    """

    if isinstance(plan.plan_complete, bool):
        return plan.plan_complete, "schema"
    for note in plan.notes:
        note_text = str(note or "")
        # Negation wins for the whole note. Legacy prose is only a liveness
        # compatibility hint; contradictory or negated language must remain
        # unspecified rather than manufacture another paid planner call.
        if _NEGATED_PARTIAL_PLAN_NOTE_RE.search(note_text):
            continue
        if _EXPLICIT_PARTIAL_PLAN_NOTE_RE.search(note_text):
            return False, "legacy_plan_note"
    return None, "unspecified"


def _explicit_withdrawal_match(text: str) -> Optional[re.Match[str]]:
    """Return an operative withdrawal, excluding hypothetical clauses."""

    raw = str(text or "")
    for match in _EXPLICIT_CLAIM_SELF_ABANDONMENT_RE.finditer(raw):
        clause_start = (
            max(
                raw.rfind(".", 0, match.start()),
                raw.rfind(";", 0, match.start()),
                raw.rfind("\n", 0, match.start()),
            )
            + 1
        )
        clause_prefix = raw[clause_start : match.start()]
        if _CONDITIONAL_WITHDRAWAL_CLAUSE_RE.match(clause_prefix):
            continue
        clause_end_candidates = tuple(
            position
            for delimiter in (".", ";", "\n")
            if (position := raw.find(delimiter, match.end())) >= 0
        )
        clause_end = min(clause_end_candidates, default=len(raw))
        clause_suffix = raw[match.end() : clause_end]
        # Free-form prose cannot reliably distinguish an operative planner
        # command from a counterfactual qualifier that follows it (``... if
        # h fails``, ``... in the h-free variant``).  The destructive gate is
        # therefore restricted to a performative that ends its clause.  Any
        # explanatory suffix remains advisory and the scheduler attempts the
        # claim, consistent with Mini's liveness bias.
        if clause_suffix.strip():
            continue
        return match
    return None


def _explicit_claim_self_abandonment_reason(
    claim: MiniSubgoalClaim,
    *,
    plan_notes: Sequence[str] = (),
    plan_claim_names: Sequence[str] = (),
) -> tuple[str, str]:
    """Return ``(source, excerpt)`` when the planner withdrew this target.

    Rationale and sanity text are claim-local by schema.  Plan notes are only
    considered when they explicitly name the claim, so a note rejecting some
    other route cannot suppress an unrelated obligation.
    """

    for source, value in (
        ("rationale", getattr(claim, "rationale", "")),
        ("sanity_check", getattr(claim, "sanity_check", "")),
    ):
        text = str(value or "").strip()
        match = _explicit_withdrawal_match(text)
        if match:
            return source, _compact_text(match.group(0), 220)

    claim_name = str(getattr(claim, "name", "") or "").strip()
    if not claim_name:
        return "", ""
    named_withdrawal = re.compile(
        rf"(?<![A-Za-z0-9_']){re.escape(claim_name)}(?![A-Za-z0-9_'])"
        r"[^.\n;]{0,120}\b(?:must|needs?\s+to|should)\s+be\s+"
        r"(?:corrected|fixed|changed|replaced|withdrawn)\b",
        re.IGNORECASE,
    )
    for note in plan_notes:
        note_text = str(note or "")
        match = named_withdrawal.search(note_text)
        if match:
            clause_end_candidates = tuple(
                position
                for delimiter in (".", ";", "\n")
                if (position := note_text.find(delimiter, match.end())) >= 0
            )
            clause_end = min(clause_end_candidates, default=len(note_text))
            if note_text[match.end() : clause_end].strip():
                continue
            return "plan_note", _compact_text(match.group(0), 220)
        # A direct same-clause antecedent such as ``name failed, so that claim
        # is not emitted`` is an unambiguous planning decision. Cross-sentence
        # anaphora is diagnosed separately and never suppresses paid work.
        named_non_emission = re.compile(
            rf"(?<![A-Za-z0-9_']){re.escape(claim_name)}"
            r"(?![A-Za-z0-9_'])"
            r"(?P<context>[^.;\n]{0,240}?\b"
            r"(?:this|that|the\s+proposed|the\s+current)\s+"
            r"claim\s+(?:is|was)\s+not\s+"
            r"(?:emitted|included|submitted)\b)",
            re.IGNORECASE,
        )
        non_emission_match = named_non_emission.search(note_text)
        if non_emission_match:
            if _AMBIGUOUS_WITHDRAWAL_CONTEXT_RE.search(
                non_emission_match.group("context")
            ):
                continue
            phrase_match = re.search(
                r"\b(?:this|that|the\s+proposed|the\s+current)\s+claim\s+"
                r"(?:is|was)\s+not\s+(?:emitted|included|submitted)\b",
                non_emission_match.group("context"),
                re.IGNORECASE,
            )
            phrase_start = non_emission_match.start("context") + (
                phrase_match.start() if phrase_match is not None else 0
            )
            claim_name_start = non_emission_match.start()
            intervening_name = any(
                re.search(
                    rf"(?<![A-Za-z0-9_']){re.escape(str(other_name))}"
                    r"(?![A-Za-z0-9_'])",
                    note_text[claim_name_start + len(claim_name) : phrase_start],
                    re.IGNORECASE,
                )
                for other_name in plan_claim_names
                if str(other_name or "").strip()
                and str(other_name).strip().lower() != claim_name.lower()
            )
            if intervening_name:
                continue
            clause_start = (
                max(
                    note_text.rfind(".", 0, phrase_start),
                    note_text.rfind(";", 0, phrase_start),
                    note_text.rfind("\n", 0, phrase_start),
                )
                + 1
            )
            if not _CONDITIONAL_WITHDRAWAL_CLAUSE_RE.match(
                note_text[clause_start:phrase_start]
            ):
                return "plan_note", _compact_text(non_emission_match.group(0), 220)
    return "", ""


def _ambiguous_claim_self_abandonment_reason(
    claim: MiniSubgoalClaim,
    *,
    plan_notes: Sequence[str] = (),
    plan_claim_names: Sequence[str] = (),
) -> tuple[str, str]:
    """Diagnose cross-sentence non-emission anaphora without suppressing work."""

    claim_name = str(getattr(claim, "name", "") or "").strip()
    if not claim_name:
        return "", ""
    pattern = re.compile(
        rf"(?<![A-Za-z0-9_']){re.escape(claim_name)}(?![A-Za-z0-9_'])"
        r"(?P<context>.{0,360}?\b"
        r"(?:this|that|the\s+proposed|the\s+current)\s+claim\s+"
        r"(?:is|was)\s+not\s+(?:emitted|included|submitted)\b)",
        re.IGNORECASE | re.DOTALL,
    )
    phrase_pattern = re.compile(
        r"\b(?:this|that|the\s+proposed|the\s+current)\s+claim\s+"
        r"(?:is|was)\s+not\s+(?:emitted|included|submitted)\b",
        re.IGNORECASE,
    )
    for note in plan_notes:
        note_text = str(note or "")
        match = pattern.search(note_text)
        if not match:
            continue
        context_is_ambiguous = bool(
            re.search(r"[.;\n]", match.group("context"))
            or _AMBIGUOUS_WITHDRAWAL_CONTEXT_RE.search(match.group("context"))
        )
        if not context_is_ambiguous:
            continue
        phrase_match = phrase_pattern.search(match.group("context"))
        phrase_start = match.start("context") + (
            phrase_match.start() if phrase_match is not None else 0
        )
        intervening_surface = note_text[match.start() + len(claim_name) : phrase_start]
        if any(
            re.search(
                rf"(?<![A-Za-z0-9_']){re.escape(str(other_name))}"
                r"(?![A-Za-z0-9_'])",
                intervening_surface,
                re.IGNORECASE,
            )
            for other_name in plan_claim_names
            if str(other_name or "").strip()
            and str(other_name).strip().lower() != claim_name.lower()
        ):
            continue
        clause_start = (
            max(
                note_text.rfind(".", 0, phrase_start),
                note_text.rfind(";", 0, phrase_start),
                note_text.rfind("\n", 0, phrase_start),
            )
            + 1
        )
        if _CONDITIONAL_WITHDRAWAL_CLAUSE_RE.match(
            note_text[clause_start:phrase_start]
        ):
            continue
        return "plan_note", _compact_text(match.group(0), 220)
    return "", ""


_DEPENDENCY_HANDWAVE_PATTERNS = (
    re.compile(r"\btypically\s+by\s+showing\b", re.IGNORECASE),
    re.compile(
        r"\bensur(?:e|es|ed|ing)\b.{0,120}\b(?:lies?|belongs?|in)\b", re.IGNORECASE
    ),
    re.compile(r"\bonce\b.{0,120}\bcontains?\s+all\b", re.IGNORECASE),
    re.compile(r"\bwill\s+be\s+obtained\b.{0,160}\b(?:then|by)\b", re.IGNORECASE),
    re.compile(r"\bremaining\s+work\b.{0,160}\bproduc", re.IGNORECASE),
    re.compile(r"\bchosen\s+witness\b.{0,120}\b(?:lies?|belongs?|in)\b", re.IGNORECASE),
)

_SQRT_RATIONALITY_ROLE_PATTERNS = (
    re.compile(
        r"\b(?:sqrt|square\s+root(?:s)?)\b.{0,140}\brational(?:ity)?\b"
        r"|\brational(?:ity)?\b.{0,140}\b(?:sqrt|square\s+root(?:s)?)\b",
        re.IGNORECASE,
    ),
    re.compile(
        r"\b(?:deduc|conclud|deriv|infer|obtain|show|prove)\w*\b"
        r".{0,120}\b(?:norm|value|quantity)\b.{0,80}\brational(?:ity)?\b"
        r".{0,160}\bfrom\b.{0,160}"
        r"(?:\brational(?:ity)?\b.{0,80})?"
        r"(?:\bsquare(?:d)?\b|\bnorm\s*\^\s*2\b|\bnorm\s*squared\b|"
        r"‖[^‖]+‖\s*\^\s*2|\^\s*2|²)",
        re.IGNORECASE,
    ),
    re.compile(
        r"\bfrom\b.{0,160}(?:\bsquare(?:d)?\b|\bnorm\s*\^\s*2\b|"
        r"\bnorm\s*squared\b|‖[^‖]+‖\s*\^\s*2|\^\s*2|²)"
        r".{0,160}\b(?:deduc|conclud|deriv|infer|obtain|show|prove)\w*\b"
        r".{0,120}\b(?:norm|value|quantity)\b.{0,80}\brational(?:ity)?\b",
        re.IGNORECASE,
    ),
)


_LEAN_CHAR_LITERAL_START_PRECEDERS = frozenset("([{⦃⟨,;:=<>+-*/^%&|!~?")
_LEAN_SURFACE_GROUP_OPEN_TO_CLOSE = {
    "(": ")",
    "[": "]",
    "{": "}",
    "⦃": "⦄",
    "⟨": "⟩",
}
_LEAN_IDENTIFIER_RE = r"[^\W\d][\w']*"
_LEAN_IDENTIFIER_PATTERN = re.compile(_LEAN_IDENTIFIER_RE)
_LEAN_RELATION_BINDER_TOKENS = (
    "∈",
    "∉",
    "≤",
    "≥",
    "≠",
    "<=",
    ">=",
    "=",
    "<",
    ">",
    "∣",
)


def _lean_surface_lexical_skip_end(text: str, idx: int) -> Optional[int]:
    raw = str(text or "")
    if idx < 0 or idx >= len(raw):
        return None
    if raw[idx] == "'":
        previous = raw[idx - 1] if idx > 0 else ""
        if (
            previous
            and not previous.isspace()
            and previous not in (_LEAN_CHAR_LITERAL_START_PRECEDERS)
        ):
            return None
    return _lean_lexical_skip_end(raw, idx)


def _lean_surface_noncode_skip_end(text: str, idx: int) -> Optional[int]:
    raw = str(text or "")
    if idx < 0 or idx >= len(raw):
        return None
    skip_to = _lean_surface_lexical_skip_end(raw, idx)
    if skip_to is None:
        return None
    if raw.startswith(("/-", "--"), idx) or raw[idx] in {'"', "'"}:
        return skip_to
    if raw[idx] == "r":
        hash_idx = idx + 1
        while hash_idx < len(raw) and raw[hash_idx] == "#":
            hash_idx += 1
        if hash_idx < len(raw) and raw[hash_idx] == '"':
            return skip_to
    return None


def _lean_code_for_identifier_scan(text: str) -> str:
    raw = str(text or "")
    if not raw:
        return ""
    out: list[str] = []
    index = 0
    while index < len(raw):
        skip_to = _lean_surface_noncode_skip_end(raw, index)
        if skip_to is not None:
            out.append(" ")
            index = skip_to
            continue
        out.append(raw[index])
        index += 1
    return "".join(out)


def _lean_ident_char(ch: str) -> bool:
    return bool(ch) and (ch.isalnum() or ch in "_'")


def _lean_identifier_tokens(text: str) -> tuple[str, ...]:
    raw = str(text or "")
    tokens: list[str] = []
    index = 0
    while index < len(raw):
        skip_to = _lean_surface_lexical_skip_end(raw, index)
        if skip_to is not None:
            if raw.startswith("«", index):
                tokens.append(raw[index:skip_to])
            index = skip_to
            continue
        match = _LEAN_IDENTIFIER_PATTERN.match(raw, index)
        if match is not None:
            tokens.append(match.group(0))
            index = match.end()
            continue
        index += 1
    return tuple(tokens)


def _top_level_quantifier_token_len(text: str, index: int) -> int:
    raw = str(text or "")
    ch = raw[index] if 0 <= index < len(raw) else ""
    if ch in {"∀", "∃"}:
        return 1
    for token in ("forall", "exists"):
        end = index + len(token)
        if not raw.startswith(token, index):
            continue
        before_ok = index == 0 or not _lean_ident_char(raw[index - 1])
        after_ok = end >= len(raw) or not _lean_ident_char(raw[end])
        if before_ok and after_ok:
            return len(token)
    return 0


def _strip_balanced_outer_parens(text: str) -> str:
    s = str(text or "").strip()
    while s.startswith("(") and s.endswith(")"):
        depth = 0
        balanced = True
        index = 0
        while index < len(s):
            skip_to = _lean_surface_lexical_skip_end(s, index)
            if skip_to is not None:
                index = skip_to
                continue
            ch = s[index]
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
                if depth == 0 and index != len(s) - 1:
                    balanced = False
                    break
                if depth < 0:
                    balanced = False
                    break
            index += 1
        if not balanced or depth != 0:
            break
        s = s[1:-1].strip()
    return s


def _find_top_level_comma(text: str) -> int:
    raw = str(text or "")
    depth = 0
    index = 0
    while index < len(raw):
        skip_to = _lean_surface_lexical_skip_end(raw, index)
        if skip_to is not None:
            index = skip_to
            continue
        ch = raw[index]
        if ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE:
            depth += 1
        elif ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE.values():
            depth = max(0, depth - 1)
        elif ch == "," and depth == 0:
            return index
        index += 1
    return -1


def _strip_leading_forall_binders(text: str) -> str:
    s, _names = _strip_leading_forall_binders_with_names(text)
    return s


def _binder_names_from_chunk(chunk: str) -> tuple[str, ...]:
    """Extract names from a simple Lean binder chunk.

    This is intentionally conservative.  It supports the planner's common
    shapes such as ``x : Nat``, ``(x y : Nat)``, and ``x ∈ S`` without trying
    to parse arbitrary Lean syntax.
    """

    raw = str(chunk or "").strip()
    if (
        (raw.startswith("(") and raw.endswith(")"))
        or (raw.startswith("{") and raw.endswith("}"))
        or (raw.startswith("[") and raw.endswith("]"))
        or (raw.startswith("⦃") and raw.endswith("⦄"))
    ):
        raw = raw[1:-1].strip()
    separator_index = _top_level_binder_separator_index(
        raw,
        (":", *_LEAN_RELATION_BINDER_TOKENS),
    )
    if separator_index >= 0:
        raw = raw[:separator_index]
    raw = raw.translate(str.maketrans({ch: " " for ch in "(){}[]⦃⦄⟨⟩"}))
    names: list[str] = []
    for name in _lean_identifier_tokens(raw):
        lowered = name.lower()
        if lowered in {"forall", "exists", "fun", "by", "let", "in"}:
            continue
        if name not in names:
            names.append(name)
    return tuple(names)


def _top_level_binder_separator_index(text: str, tokens: Sequence[str]) -> int:
    raw = str(text or "")
    depth = 0
    index = 0
    matches: list[int] = []
    while index < len(raw):
        skip_to = _lean_surface_lexical_skip_end(raw, index)
        if skip_to is not None:
            index = skip_to
            continue
        ch = raw[index]
        if ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE:
            depth += 1
        elif ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE.values():
            depth = max(0, depth - 1)
        elif depth == 0:
            for token in tokens:
                if raw.startswith(token, index):
                    matches.append(index)
                    break
        index += 1
    return min(matches) if matches else -1


def _top_level_colon_index(text: str) -> int:
    raw = str(text or "")
    depth = 0
    index = 0
    while index < len(raw):
        skip_to = _lean_surface_lexical_skip_end(raw, index)
        if skip_to is not None:
            index = skip_to
            continue
        ch = raw[index]
        if ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE:
            depth += 1
        elif ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE.values():
            depth = max(0, depth - 1)
        elif ch == ":" and depth == 0:
            return index
        index += 1
    return -1


def _surface_keyword_at(text: str, index: int, keyword: str) -> bool:
    raw = str(text or "")
    token = str(keyword or "")
    if not token or not raw.startswith(token, index):
        return False
    before_ok = index == 0 or not (raw[index - 1].isalnum() or raw[index - 1] in "_'.")
    after = index + len(token)
    after_ok = after >= len(raw) or not (raw[after].isalnum() or raw[after] in "_'.")
    return before_ok and after_ok


def _surface_starts_with_keyword(text: str, keyword: str) -> bool:
    raw = str(text or "")
    index = 0
    while index < len(raw):
        skip_to = _lean_surface_lexical_skip_end(raw, index)
        if skip_to is not None and raw.startswith(("/-", "--"), index):
            index = skip_to
            continue
        if raw[index].isspace():
            index += 1
            continue
        return _surface_keyword_at(raw, index, keyword)
    return False


def _strip_binder_default_assignment(type_text: str) -> str:
    raw = str(type_text or "").strip()
    if not raw or _surface_starts_with_keyword(raw, "let"):
        return raw
    depth = 0
    index = 0
    while index < len(raw) - 1:
        skip_to = _lean_surface_lexical_skip_end(raw, index)
        if skip_to is not None:
            index = skip_to
            continue
        if raw[index] == "«":
            end = raw.find("»", index + 1)
            if end >= 0:
                index = end + 1
                continue
        ch = raw[index]
        if ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE:
            depth += 1
        elif ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE.values():
            depth = max(0, depth - 1)
        elif depth == 0 and _surface_keyword_at(raw, index, "let"):
            return raw
        elif depth == 0 and ch == ":" and raw[index + 1] == "=":
            return raw[:index].strip()
        index += 1
    return raw


def _binder_group_chunks(chunk: str) -> tuple[str, ...]:
    raw = str(chunk or "").strip()
    if not raw:
        return ()
    binder_group_openers = {"(", "[", "{", "⦃"}
    chunks: list[str] = []
    index = 0
    while index < len(raw):
        while index < len(raw) and raw[index].isspace():
            index += 1
        if index >= len(raw):
            break
        opener = raw[index]
        if opener in binder_group_openers:
            expected_close = _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE.get(opener)
            start = index
            depth = 0
            closed = False
            while index < len(raw):
                skip_to = _lean_surface_lexical_skip_end(raw, index)
                if skip_to is not None:
                    index = skip_to
                    continue
                ch = raw[index]
                if ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE:
                    depth += 1
                elif ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE.values():
                    depth = max(0, depth - 1)
                    if depth == 0:
                        if ch != expected_close:
                            return (raw,)
                        chunks.append(raw[start : index + 1])
                        index += 1
                        closed = True
                        break
                index += 1
            if not closed:
                return (raw,)
            continue

        start = index
        while index < len(raw):
            skip_to = _lean_surface_lexical_skip_end(raw, index)
            if skip_to is not None:
                index = skip_to
                continue
            if any(
                raw.startswith(token, index)
                for token in (":", *_LEAN_RELATION_BINDER_TOKENS)
            ):
                return (raw,)
            if (
                raw[index].isspace()
                and index + 1 < len(raw)
                and raw[index + 1] in binder_group_openers
            ):
                break
            index += 1
        segment = raw[start:index].strip()
        if segment:
            chunks.append(segment)
    return tuple(chunks) if chunks else (raw,)


def _looks_like_proof_premise_type(type_text: str, binder_names: Sequence[str]) -> bool:
    clean = _strip_balanced_outer_parens(str(type_text or "").strip())
    if not clean:
        return False
    # A subtype/set-builder is a data type even if its predicate contains
    # proposition syntax such as a nested existential.
    if clean.startswith("{") and clean.endswith("}"):
        subtype_body = clean[1:-1].strip()
        if _top_level_binder_separator_index(subtype_body, ("//", "|")) >= 0:
            return False
    compact = " ".join(clean.split())
    compact = compact.strip("{}[]")
    lowered = compact.lower()
    hyp_like_name = any(
        str(name or "")
        .strip()
        .lower()
        .startswith(
            (
                "h",
                "hyp",
                "this",
                "proof",
                "assump",
                "premise",
                "cond",
                "given",
            )
        )
        for name in binder_names
    )
    if lowered in {
        "nat",
        "ℕ",
        "int",
        "ℤ",
        "rat",
        "ℚ",
        "real",
        "ℝ",
        "bool",
        "string",
        "char",
        "unit",
        "prop",
        "type",
    }:
        return False
    if re.fullmatch(r"(?:Type|Sort|Prop)(?:\s+\d+|\s+u)?", compact):
        return False
    if re.match(
        r"^(?:Set|Finset|List|Multiset|Option|Array|Seq|Fin|ZMod|Polynomial|"
        r"Matrix|Vector|Subtype|ULift|PLift|WithTop|WithBot|OrderDual|"
        r"Additive|Multiplicative|Ideal|Submodule|Subgroup|Subsemiring|"
        r"Subring|Subfield|Equiv|LinearEquiv|RingEquiv|OrderIso|Type|Sort)\b",
        compact,
    ):
        return False
    if re.match(
        r"^(?:Fintype|Finite|DecidableEq|Inhabited|Subsingleton|Unique|"
        r"Group|CommGroup|AddGroup|AddCommGroup|Monoid|CommMonoid|"
        r"AddMonoid|AddCommMonoid|Semigroup|CommSemigroup|Ring|CommRing|"
        r"Semiring|CommSemiring|Field|DivisionRing|LinearOrder|PartialOrder|"
        r"Preorder|Lattice|DistribLattice|LinearOrderedRing|"
        r"LinearOrderedField|OrderedRing|OrderedSemiring|TopologicalSpace|"
        r"MetricSpace|NormedRing|NormedField|NormedSpace|Module|Algebra)\b",
        compact,
    ):
        return False
    if "→" in compact or "->" in compact:
        arrow_parts = _split_top_level_implications(compact)
        codomain = arrow_parts[-1] if arrow_parts else compact
        codomain = _strip_balanced_outer_parens(codomain).strip()
        codomain_lower = codomain.lower()
        type_like_arrow = len(arrow_parts) >= 2 and all(
            _looks_like_parameter_type_part(part) for part in arrow_parts
        )
        if (
            type_like_arrow
            or codomain_lower in {"prop", "type", "sort"}
            or codomain_lower
            in {"nat", "int", "rat", "real", "bool", "string", "char", "unit"}
            or codomain
            in {
                "ℕ",
                "ℤ",
                "ℚ",
                "ℝ",
                "Nat",
                "Int",
                "Rat",
                "Real",
                "Bool",
                "String",
                "Char",
                "Unit",
            }
            or re.match(
                r"^(?:Set|Finset|List|Multiset|Option|Array|Seq|Fin|ZMod|"
                r"Polynomial|Matrix|Vector|Subtype|ULift|PLift|WithTop|WithBot|"
                r"OrderDual|Additive|Multiplicative|Ideal|Submodule|Subgroup|"
                r"Subsemiring|Subring|Subfield|Equiv|LinearEquiv|RingEquiv|"
                r"OrderIso)\b",
                codomain,
            )
            or re.fullmatch(r"(?:Type|Sort|Prop)(?:\s+\d+|\s+u)?", codomain)
            or (
                not hyp_like_name
                and re.fullmatch(r"[A-Za-z_][A-Za-z0-9_'.]*", codomain)
            )
        ):
            return False
    if any(
        symbol in compact for symbol in ("=", "<", ">", "≤", "≥", "≠", "∈", "∉", "∣")
    ):
        return True
    if any(symbol in compact for symbol in ("→", "->", "↔", "¬", "∧", "∨", "∀", "∃")):
        return True
    if re.search(
        r"\b(?:Odd|Even|Prime|Nat\.Prime|Irreducible|Nonempty|Pairwise|"
        r"Monotone|StrictMono|Injective|Surjective|Bijective|Continuous)\b",
        compact,
    ):
        return True
    if re.fullmatch(r"[A-Z][A-Za-z0-9_'.]*(?:\s+.+)?", compact):
        return True
    if hyp_like_name and re.fullmatch(
        r"[A-Za-z_][A-Za-z0-9_'.]*(?:\s+.+)+",
        compact,
    ):
        return True
    if (
        re.fullmatch(
            r"[a-z][A-Za-z0-9_'.]*(?:\s+[^:=,]+)+",
            compact,
        )
        and hyp_like_name
    ):
        return True
    if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_'.]*", compact):
        return hyp_like_name
    return False


def _looks_like_parameter_type_part(text: str) -> bool:
    compact = _strip_balanced_outer_parens(
        " ".join(str(text or "").split()).strip("{}[]")
    )
    lowered = compact.lower()
    if lowered in {
        "nat",
        "int",
        "rat",
        "real",
        "bool",
        "string",
        "char",
        "unit",
        "prop",
        "type",
        "sort",
    }:
        return True
    if compact in {
        "ℕ",
        "ℤ",
        "ℚ",
        "ℝ",
        "Nat",
        "Int",
        "Rat",
        "Real",
        "Bool",
        "String",
        "Char",
        "Unit",
    }:
        return True
    if re.fullmatch(r"(?:Type|Sort|Prop)(?:\s+\d+|\s+u)?", compact):
        return True
    return bool(
        re.match(
            r"^(?:Set|Finset|List|Multiset|Option|Array|Seq|Fin|ZMod|"
            r"Polynomial|Matrix|Vector|Subtype|ULift|PLift|WithTop|WithBot|"
            r"OrderDual|Additive|Multiplicative|Ideal|Submodule|Subgroup|"
            r"Subsemiring|Subring|Subfield|Equiv|LinearEquiv|RingEquiv|"
            r"OrderIso)\b",
            compact,
        )
    )


def _binder_premises_from_chunk(chunk: str) -> tuple[str, ...]:
    premises: list[str] = []
    for group in _binder_group_chunks(chunk):
        stripped_group = group.strip()
        body = _strip_balanced_outer_parens(stripped_group)
        expected_close = _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE.get(stripped_group[:1])
        if expected_close and stripped_group.endswith(expected_close):
            body = stripped_group[1:-1].strip()
        colon = _top_level_colon_index(body)
        if colon < 0:
            relation_premise = lean_relation_binder_premise(body)
            if relation_premise:
                premises.append(relation_premise)
            continue
        names = _binder_names_from_chunk(body[:colon])
        type_text = _strip_binder_default_assignment(body[colon + 1 :])
        if _looks_like_proof_premise_type(type_text, names):
            premises.append(_strip_balanced_outer_parens(type_text))
    return tuple(dict.fromkeys(premises))


def _strip_leading_forall_binders_with_names_and_premises(
    text: str,
) -> tuple[str, tuple[str, ...], tuple[str, ...]]:
    return graph_statement_leading_contract(text)


def _strip_leading_forall_binders_with_names(text: str) -> tuple[str, tuple[str, ...]]:
    s, names, _premises = _strip_leading_forall_binders_with_names_and_premises(text)
    return s, names


def _statement_premises_and_conclusion(
    statement: str,
) -> tuple[tuple[str, ...], str, tuple[str, ...]]:
    return graph_statement_premises_and_conclusion(statement)


def _quantifier_bound_names(text: str) -> tuple[str, ...]:
    names: list[str] = []
    for match in re.finditer(r"(?:[∀∃]|forall|exists)\s*([^,]+),", str(text or "")):
        names.extend(_binder_names_from_chunk(match.group(1)))
    return tuple(dict.fromkeys(names))


def _split_top_level_implications(statement: str) -> list[str]:
    """Split a Lean proposition on top-level implication arrows.

    This intentionally stays syntactic.  It catches planner assembly claims
    that add a new premise not present in the root hypotheses or dependency
    conclusions; it is not trying to prove general logical entailment.
    """

    return [
        _strip_balanced_outer_parens(part)
        for part in split_lean_top_level_implications(statement)
    ]


def _top_level_let_body_start_for_contract_split(text: str, index: int) -> int:
    raw = str(text or "")
    if not _is_keyword_at(raw, index, "let"):
        return -1
    equation_style_let_rec = False
    rec_index = index + len("let")
    while rec_index < len(raw) and raw[rec_index].isspace():
        rec_index += 1
    if _is_keyword_at(raw, rec_index, "rec"):
        equation_style_let_rec = True
    assign_idx = -1
    depth = 0
    i = index + len("let")
    while i < len(raw) - 1:
        skip_to = _lean_surface_lexical_skip_end(raw, i)
        if skip_to is not None:
            i = skip_to
            continue
        ch = raw[i]
        if ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE:
            depth += 1
        elif ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE.values():
            depth = max(0, depth - 1)
        elif ch == ":" and raw[i + 1] == "=" and depth == 0:
            assign_idx = i
            break
        elif equation_style_let_rec and depth == 0 and ch == ";":
            return i + 1
        elif equation_style_let_rec and depth == 0 and ch in "\r\n":
            line_end = (
                i + 2
                if ch == "\r" and i + 1 < len(raw) and raw[i + 1] == "\n"
                else i + 1
            )
            suffix = raw[line_end:]
            indent_len = len(suffix) - len(suffix.lstrip(" \t"))
            visible_suffix = suffix[indent_len:].lstrip()
            if (
                indent_len == 0
                and visible_suffix
                and not visible_suffix.startswith("|")
            ):
                return line_end
        i += 1
    if assign_idx < 0:
        return -1

    depth = 0
    i = assign_idx + 2
    while i < len(raw):
        skip_to = _lean_surface_lexical_skip_end(raw, i)
        if skip_to is not None:
            i = skip_to
            continue
        ch = raw[i]
        if ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE:
            depth += 1
        elif ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE.values():
            depth = max(0, depth - 1)
        elif depth == 0 and ch == ";":
            return i + 1
        elif depth == 0 and ch in "\r\n":
            line_end = (
                i + 2
                if ch == "\r" and i + 1 < len(raw) and raw[i + 1] == "\n"
                else i + 1
            )
            assigned_prefix = raw[assign_idx + 2 : i].strip()
            suffix = raw[line_end:].strip()
            if assigned_prefix and suffix:
                return line_end
        elif depth == 0 and _is_keyword_at(raw, i, "in"):
            if _let_in_candidate_is_body_separator(raw, assign_idx, i):
                return i + len("in")
        i += 1
    return -1


def _split_prefix_iff_args(text: str) -> list[str]:
    raw = str(text or "").strip()
    if not re.match(r"^Iff\b", raw):
        return []
    tail = raw[len("Iff") :].strip()
    if not tail:
        return []
    args: list[str] = []
    index = 0
    while index < len(tail) and len(args) < 2:
        while index < len(tail) and tail[index].isspace():
            index += 1
        if index >= len(tail):
            break
        if tail[index] == "(":
            end = _matching_paren_index(tail, index)
            if end < 0:
                return []
            args.append(_strip_balanced_outer_parens(tail[index : end + 1]))
            index = end + 1
            continue
        start = index
        while index < len(tail) and not tail[index].isspace():
            index += 1
        args.append(tail[start:index].strip())
    if len(args) == 2 and not tail[index:].strip():
        return args
    return []


def _split_top_level_iffs(statement: str) -> list[str]:
    text = str(statement or "")
    prefix_args = _split_prefix_iff_args(text)
    if prefix_args:
        return prefix_args
    parts: list[str] = []
    start = 0
    depth = 0
    index = 0
    while index < len(text):
        skip_to = _lean_surface_lexical_skip_end(text, index)
        if skip_to is not None:
            index = skip_to
            continue
        ch = text[index]
        if ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE:
            depth += 1
        elif ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE.values():
            depth = max(0, depth - 1)
        elif depth == 0:
            let_body_start = _top_level_let_body_start_for_contract_split(text, index)
            if let_body_start >= 0:
                if start > 0 or text[start:index].strip():
                    break
                index = let_body_start
                continue
            if _top_level_quantifier_token_len(text, index):
                break
            if ch == "↔":
                parts.append(text[start:index].strip())
                start = index + 1
            elif text.startswith("<->", index):
                parts.append(text[start:index].strip())
                start = index + 3
                index += 2
        index += 1
    parts.append(text[start:].strip())
    return [_strip_balanced_outer_parens(part) for part in parts if part.strip()]


def _is_complex_planner_premise(text: str) -> bool:
    """Return whether a premise is itself a substantial proof obligation.

    Simple conditional lemma hypotheses such as ``0 < n`` or ``Nat.Prime p``
    are legitimate assumptions.  Quantified/existential premises, however,
    are usually unproved intermediate lemmas when they appear inside a planned helper
    and are not supplied by the root, dependencies, or verified helpers.
    """

    stripped = _strip_balanced_outer_parens(text)
    while True:
        quantifier_match = re.match(r"^(?:∀|forall\b)\s*", stripped)
        if quantifier_match is None:
            break
        comma = _find_top_level_comma(stripped)
        if comma < 0:
            break
        rest = str(stripped[comma + 1 :]).strip()
        inner = _strip_balanced_outer_parens(rest)
        inner_lower = inner.lower()
        if (
            inner.startswith("∀")
            or inner.startswith("∃")
            or re.match(r"^(?:forall|exists)\b", inner_lower)
        ):
            return True
        stripped = inner
    lowered = stripped.lower()
    if "∃" in stripped or re.search(r"\bexists\b", lowered):
        return True
    if "∀" in stripped or re.search(r"\bforall\b", lowered):
        return True
    return "↔" in stripped or "<->" in stripped or re.match(r"^Iff\b", stripped)


def _strip_contract_comments(text: str) -> str:
    raw = str(text or "")
    out: list[str] = []
    index = 0
    while index < len(raw):
        skip_to = _lean_surface_lexical_skip_end(raw, index)
        if skip_to is not None:
            if raw.startswith(("/-", "--"), index):
                out.append(" ")
            else:
                out.append(raw[index:skip_to])
            index = skip_to
            continue
        out.append(raw[index])
        index += 1
    return "".join(out)


def _contract_compact_surface(text: str) -> str:
    raw = str(text or "")
    out: list[str] = []
    index = 0
    while index < len(raw):
        skip_to = _lean_surface_lexical_skip_end(raw, index)
        if skip_to is not None:
            if not raw.startswith(("/-", "--"), index):
                out.append(raw[index:skip_to])
            index = skip_to
            continue
        ch = raw[index]
        if not ch.isspace():
            out.append(ch)
            index += 1
            continue
        next_index = index + 1
        while next_index < len(raw) and raw[next_index].isspace():
            next_index += 1
        # Whitespace is insignificant around punctuation, but it is the token
        # boundary in applications such as ``P Set.Icc``.  Erasing it entirely
        # creates the synthetic identifier ``PSet.Icc`` and makes namespace
        # alias comparison (and ordinary contract identity) dependent on
        # surrounding punctuation.
        if (
            out
            and next_index < len(raw)
            and _lean_ident_char(out[-1])
            and _lean_ident_char(raw[next_index])
        ):
            out.append(" ")
        index = next_index
    return "".join(out)


def _contract_norm(text: str) -> str:
    stripped = _strip_leading_forall_binders(_strip_contract_comments(text))
    return _normalize_not_mem_contract_surface(_contract_compact_surface(stripped))


def _contract_identity_matches(left: str, right: str) -> bool:
    """Compare normalized contract surfaces without guessing name identity.

    Open namespaces, local declarations, and projections make an unqualified
    Lean identifier semantically ambiguous.  Production callers therefore
    elaborate complete statements with ``pp.fullNames`` before reaching this
    matcher.  The surface fallback is deliberately exact and fail-closed.
    """

    if not left or not right:
        return False
    if left == right:
        return True
    # Surface fallback may erase an explicit numeral cast only when the two
    # surfaces do not assert conflicting numeric types. This preserves legacy
    # matching of `7 / 4` against `(7 / 4 : ℚ)` while preventing Nat evidence
    # from satisfying an explicitly Int/Rat/Real obligation.
    numeric_type_pattern = re.compile(
        # Lean's pretty printer emits "(0 : ℕ)" with spaces around the colon;
        # the guard must catch both compact and pp-formatted casts or it is
        # dead for production display statements.
        r":\s*(?:ℚ|Rat|ℝ|Real|ℤ|Int|ℕ|Nat)(?=[\s)}\],→=<>≤≥+*/\-]|$)"
    )
    left_types = frozenset(
        match.replace(" ", "").replace("\t", "")
        for match in numeric_type_pattern.findall(left)
    )
    right_types = frozenset(
        match.replace(" ", "").replace("\t", "")
        for match in numeric_type_pattern.findall(right)
    )
    if left_types and right_types and left_types != right_types:
        return False
    return _normalize_numeric_casts_for_contract(
        left
    ) == _normalize_numeric_casts_for_contract(right)


def _normalize_not_mem_contract_surface(text: str) -> str:
    compact = str(text or "")
    if any(ch in compact for ch in ('"', "'", "«", "»")):
        return compact
    for prefix in ("¬", "Not"):
        wrapped_prefix = f"{prefix}("
        if not (compact.startswith(wrapped_prefix) and compact.endswith(")")):
            continue
        inner = compact[len(wrapped_prefix) : -1]
        depth = 0
        for index, ch in enumerate(inner):
            if ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE:
                depth += 1
            elif ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE.values():
                depth = max(0, depth - 1)
            elif ch == "∈" and depth == 0:
                left = inner[:index]
                right = inner[index + 1 :]
                if left and right:
                    return f"{left}∉{right}"
    compact = re.sub(
        r"(?:¬|Not)\(([^()∈∉→↔∧∨=<>≤≥,]+)∈([^()]+)\)",
        r"\1∉\2",
        compact,
    )
    return re.sub(r"¬([^∈∉→↔∧∨=<>≤≥,()]+)∈", r"\1∉", compact)


def _matching_paren_index(text: str, start: int) -> int:
    depth = 0
    for index in range(start, len(text)):
        ch = text[index]
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
            if depth == 0:
                return index
        if depth < 0:
            return -1
    return -1


def _normalize_numeric_casts_for_contract(text: str) -> str:
    numeric_type_re = re.compile(r"(?:ℚ|Rat|ℝ|Real|ℤ|Int|ℕ|Nat)")

    def normalize(value: str) -> str:
        out: list[str] = []
        index = 0
        while index < len(value):
            skip_to = _lean_surface_lexical_skip_end(value, index)
            if skip_to is not None:
                out.append(value[index:skip_to])
                index = skip_to
                continue
            if value[index] != "(":
                out.append(value[index])
                index += 1
                continue
            end = _matching_paren_index(value, index)
            if end < 0:
                out.append(value[index])
                index += 1
                continue
            body = normalize(value[index + 1 : end])
            colon = _top_level_colon_index(body)
            if colon >= 0:
                expr = body[:colon].strip()
                type_text = _strip_balanced_outer_parens(body[colon + 1 :].strip())
                if (
                    expr
                    and re.search(r"\d", expr)
                    and numeric_type_re.fullmatch(type_text)
                ):
                    out.append(_strip_balanced_outer_parens(expr))
                    index = end + 1
                    continue
            out.append("(")
            out.append(body)
            out.append(")")
            index = end + 1
        return "".join(out)

    return normalize(str(text or ""))


def _split_top_level_equality(text: str) -> tuple[str, str]:
    stripped = _strip_balanced_outer_parens(_strip_leading_forall_binders(text))
    depth = 0
    index = 0
    while index < len(stripped):
        skip_to = _lean_surface_lexical_skip_end(stripped, index)
        if skip_to is not None:
            index = skip_to
            continue
        ch = stripped[index]
        if ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE:
            depth += 1
        elif ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE.values():
            depth = max(0, depth - 1)
        elif ch == "=" and depth == 0:
            return stripped[:index].strip(), stripped[index + 1 :].strip()
        index += 1
    return "", ""


def _alias_rewrite_pairs_from_helpers(
    helpers: Sequence[Any],
    *,
    max_side_chars: int = 240,
    max_pairs: int = 24,
    suppress_solution_placeholders: Optional[bool] = None,
    opaque_mode: bool = True,
    allow_official_answer_visibility: bool = False,
) -> tuple[tuple[str, str], ...]:
    """Small equality aliases from already-proved helpers.

    This is intentionally syntactic and conservative. It is not a theorem
    prover; it only catches planner retries that swap a blocked target through
    a named equality already in the helper set.
    """

    pairs: list[tuple[str, str]] = []
    seen: set[tuple[str, str]] = set()
    for statement in _verified_helper_statements(
        helpers,
        suppress_solution_placeholders=suppress_solution_placeholders,
        opaque_mode=opaque_mode,
        allow_official_answer_visibility=allow_official_answer_visibility,
    ):
        statement_text = str(statement or "").strip()
        if (
            re.match(r"^\s*(?:∀|∃)(?:\s|[({⦃]|$)", statement_text)
            or re.match(r"^\s*(?:forall|exists)(?:\s|[({⦃]|$)", statement_text)
            or any(symbol in statement_text for symbol in ("→", "↔", "->", "<->"))
        ):
            continue
        lhs, rhs = _split_top_level_equality(statement)
        lhs = _strip_balanced_outer_parens(lhs)
        rhs = _strip_balanced_outer_parens(rhs)
        if not lhs or not rhs or lhs == rhs:
            continue
        if max(len(lhs), len(rhs)) > max_side_chars:
            continue
        if any(symbol in lhs + rhs for symbol in ("→", "↔", "∀", "∃")):
            continue
        for old, new in ((lhs, rhs), (rhs, lhs)):
            key = (old, new)
            if key in seen:
                continue
            seen.add(key)
            pairs.append(key)
            if len(pairs) >= max_pairs:
                return tuple(pairs)
    return tuple(pairs)


def _alias_binder_expression_end(text: str, index: int) -> int:
    raw = str(text or "")
    if index < 0 or index >= len(raw):
        return -1
    is_lambda = raw[index] == "λ" or _surface_keyword_at(raw, index, "fun")
    if not is_lambda:
        return -1
    arrow = _alias_lambda_arrow_index(raw, index)
    if arrow >= 0:
        boundary = _alias_expression_boundary(raw, arrow + 2)
        if boundary > index:
            return boundary
    return len(raw)


def _alias_lambda_arrow_index(text: str, start: int) -> int:
    raw = str(text or "")
    depth = 0
    index = max(0, int(start or 0))
    while index < len(raw):
        skip_to = _lean_surface_lexical_skip_end(raw, index)
        if skip_to is not None:
            index = skip_to
            continue
        ch = raw[index]
        if ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE:
            depth += 1
        elif ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE.values():
            depth = max(0, depth - 1)
        elif depth == 0 and raw.startswith("=>", index):
            return index
        index += 1
    return -1


def _alias_expression_boundary(text: str, start: int) -> int:
    raw = str(text or "")
    depth = 0
    index = max(0, int(start or 0))
    while index < len(raw):
        skip_to = _lean_surface_lexical_skip_end(raw, index)
        if skip_to is not None:
            index = skip_to
            continue
        ch = raw[index]
        if ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE:
            depth += 1
        elif ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE.values():
            depth = max(0, depth - 1)
        elif depth == 0 and ch in {",", ";"}:
            return index
        index += 1
    return len(raw)


def _alias_text_references_bound_name(text: str, bound_names: AbstractSet[str]) -> bool:
    if not bound_names:
        return False
    return any(token in bound_names for token in _lean_identifier_tokens(text))


def _rewrite_statement_alias_once(text: str, old: str, new: str) -> str:
    old = str(old or "").strip()
    new = str(new or "").strip()
    if not old or old == new:
        return str(text or "")
    ident_re = r"[A-Za-z_][A-Za-z0-9_'.]*"
    raw = str(text or "")
    old_is_ident = re.fullmatch(ident_re, old) is not None
    out: list[str] = []
    index = 0
    while index < len(raw):
        skip_to = _lean_surface_lexical_skip_end(raw, index)
        if skip_to is not None:
            out.append(raw[index:skip_to])
            index = skip_to
            continue
        lambda_rewrite = _rewrite_lambda_alias_once(raw, index, old, new)
        if lambda_rewrite is not None:
            rewritten_lambda, end_index = lambda_rewrite
            out.append(rewritten_lambda)
            index = end_index
            continue
        quantifier_len = _top_level_quantifier_token_len(raw, index)
        if quantifier_len:
            tail_start = index + quantifier_len
            comma = _find_top_level_comma(raw[tail_start:])
            if comma >= 0:
                binder_end = tail_start + comma
                binder = raw[tail_start:binder_end]
                body = raw[binder_end + 1 :]
                bound_names: set[str] = set()
                for binder_group in _binder_group_chunks(binder):
                    bound_names.update(_binder_names_from_chunk(binder_group))
                out.append(raw[index : binder_end + 1])
                if _alias_text_references_bound_name(
                    old,
                    bound_names,
                ) or _alias_text_references_bound_name(new, bound_names):
                    out.append(body)
                else:
                    out.append(_rewrite_statement_alias_once(body, old, new))
                index = len(raw)
                continue
        binder_end = _alias_binder_expression_end(raw, index)
        if binder_end > index:
            out.append(raw[index:binder_end])
            index = binder_end
            continue
        if raw[index] in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE:
            end = _matching_surface_group_index(raw, index)
            if end >= 0:
                group_body = raw[index + 1 : end]
                if raw[index] == "⟨":
                    out.append(raw[index : end + 1])
                    index = end + 1
                    continue
                out.append(raw[index])
                out.append(_rewrite_statement_alias_once(group_body, old, new))
                out.append(raw[end])
                index = end + 1
                continue
        if raw.startswith(old, index):
            before_ok = (
                index == 0
                or not old_is_ident
                or not re.match(r"[A-Za-z0-9_'.]", raw[index - 1])
            )
            after_index = index + len(old)
            after_ok = (
                after_index >= len(raw)
                or not old_is_ident
                or not re.match(r"[A-Za-z0-9_'.]", raw[after_index])
            )
            if before_ok and after_ok:
                out.append(new)
                index = after_index
                continue
        out.append(raw[index])
        index += 1
    return "".join(out)


def _rewrite_lambda_alias_once(
    text: str,
    index: int,
    old: str,
    new: str,
) -> tuple[str, int] | None:
    raw = str(text or "")
    if not (raw[index : index + 1] == "λ" or _surface_keyword_at(raw, index, "fun")):
        return None
    arrow = _alias_lambda_arrow_index(raw, index)
    if arrow < 0:
        return None
    boundary = _alias_expression_boundary(raw, arrow + 2)
    if boundary <= arrow:
        return None
    binder_prefix = raw[index : arrow + 2]
    body = raw[arrow + 2 : boundary]
    binder_chunk = raw[
        index + (1 if raw[index : index + 1] == "λ" else len("fun")) : arrow
    ]
    bound_names: set[str] = set()
    for binder_group in _binder_group_chunks(binder_chunk):
        bound_names.update(_binder_names_from_chunk(binder_group))
    if _alias_text_references_bound_name(
        old,
        bound_names,
    ) or _alias_text_references_bound_name(new, bound_names):
        return raw[index:boundary], boundary
    return (
        f"{binder_prefix}{_rewrite_statement_alias_once(body, old, new)}",
        boundary,
    )


def _statement_alias_keys(
    statement: str,
    *,
    helpers: Sequence[Any],
    max_rounds: int = 2,
    max_variants: int = 32,
    suppress_solution_placeholders: Optional[bool] = None,
    opaque_mode: bool = True,
    allow_official_answer_visibility: bool = False,
) -> frozenset[str]:
    """Canonical statement keys reachable by small proved-equality rewrites."""

    pairs = _alias_rewrite_pairs_from_helpers(
        helpers,
        suppress_solution_placeholders=suppress_solution_placeholders,
        opaque_mode=opaque_mode,
        allow_official_answer_visibility=allow_official_answer_visibility,
    )
    texts: set[str] = {str(statement or "").strip()}
    frontier: set[str] = set(texts)
    for _ in range(max(0, int(max_rounds or 0))):
        if not pairs or not frontier or len(texts) >= max_variants:
            break
        next_frontier: set[str] = set()
        for text in frontier:
            for old, new in pairs:
                rewritten = _rewrite_statement_alias_once(text, old, new).strip()
                if not rewritten or rewritten == text or rewritten in texts:
                    continue
                texts.add(rewritten)
                next_frontier.add(rewritten)
                if len(texts) >= max_variants:
                    break
            if len(texts) >= max_variants:
                break
        frontier = next_frontier
    return frozenset(
        key for text in texts if (key := canonical_dossier_statement_key(text))
    )


def _invalidated_statement_alias_keys(
    statement: str,
    *,
    helpers: Sequence[Any],
    suppress_solution_placeholders: Optional[bool] = None,
    opaque_mode: bool = True,
    allow_official_answer_visibility: bool = False,
) -> frozenset[str]:
    keys: set[str] = set(
        _statement_alias_keys(
            statement,
            helpers=helpers,
            suppress_solution_placeholders=suppress_solution_placeholders,
            opaque_mode=opaque_mode,
            allow_official_answer_visibility=allow_official_answer_visibility,
        )
    )
    direct_key = _invalidated_statement_key(statement)
    if direct_key:
        keys.add(direct_key)
    return frozenset(keys)


def _invalidated_statement_reason_for_statement(
    statement: str,
    invalidated_statement_reasons: Mapping[str, str],
    *,
    helpers: Sequence[Any],
    suppress_solution_placeholders: Optional[bool] = None,
    opaque_mode: bool = True,
    allow_official_answer_visibility: bool = False,
) -> tuple[str, str]:
    for key in _invalidated_statement_alias_keys(
        statement,
        helpers=helpers,
        suppress_solution_placeholders=suppress_solution_placeholders,
        opaque_mode=opaque_mode,
        allow_official_answer_visibility=allow_official_answer_visibility,
    ):
        reason = invalidated_statement_reasons.get(key)
        if reason:
            return key, reason
    return "", ""


def _root_conclusion_candidates(
    root_statement: str,
) -> tuple[tuple[str, tuple[str, ...]], ...]:
    candidates: list[tuple[str, tuple[str, ...]]] = []
    seen: set[str] = set()

    def add_candidate(
        candidate_text: str, candidate_bound_names: tuple[str, ...]
    ) -> None:
        used_identifiers = set(
            re.findall(_LEAN_IDENTIFIER_RE, str(candidate_text or ""))
        )
        candidate_bound_names = tuple(
            name for name in candidate_bound_names if name in used_identifiers
        )
        key = _contract_alpha_norm(
            candidate_text,
            context_bound_names=candidate_bound_names,
        )
        if key and key not in seen:
            seen.add(key)
            candidates.append((candidate_text, candidate_bound_names))

    body, bound_names = _strip_leading_forall_binders_with_names(
        str(root_statement or "")
    )
    implication_parts = _split_top_level_implications(body)
    conclusion = implication_parts[-1] if implication_parts else body
    conclusion_parts = _split_top_level_iffs(conclusion)
    for candidate in conclusion_parts or [conclusion]:
        candidate, candidate_names = _strip_leading_forall_binders_with_names(candidate)
        all_names = tuple(dict.fromkeys(bound_names + candidate_names))
        add_candidate(candidate, all_names)
        candidate_implications = _split_top_level_implications(candidate)
        if len(candidate_implications) >= 2:
            add_candidate(candidate_implications[-1], all_names)
    return tuple(candidates)


def _statements_root_adjacent(
    conclusion: str,
    root_statement: str,
    *,
    conclusion_bound_names: Sequence[str] = (),
) -> bool:
    conclusion_norm = _contract_alpha_norm(
        conclusion,
        context_bound_names=conclusion_bound_names,
    )
    if not conclusion_norm:
        return False
    for candidate, root_bound_names in _root_conclusion_candidates(root_statement):
        root_norm = _contract_alpha_norm(
            candidate,
            context_bound_names=root_bound_names,
        )
        if _contract_identity_matches(conclusion_norm, root_norm):
            return True
    return False


_ALPHA_BOUND_PLACEHOLDER_RE = re.compile(r"^__bound\d+__$")
_ALPHA_FREE_IDENTIFIER_ESCAPE_PREFIX = "\0mini-alpha-free-identifier:"


def _contract_alpha_identifier_token(
    token: str,
    mapping: Mapping[str, str],
) -> str:
    """Keep generated binder placeholders disjoint from free Lean names."""

    if token in mapping:
        return mapping[token]
    if _ALPHA_BOUND_PLACEHOLDER_RE.fullmatch(token):
        # NUL cannot occur in a Lean source identifier. Ordinary normalized
        # surfaces therefore remain byte-for-byte stable, while a legal free
        # name such as ``__bound0__`` cannot alias the generated binder token.
        return f"{_ALPHA_FREE_IDENTIFIER_ESCAPE_PREFIX}{token}\0"
    return token


def _contract_alpha_norm(
    text: str,
    *,
    context_bound_names: Sequence[str] = (),
) -> str:
    stripped, leading_names = _strip_leading_forall_binders_with_names(
        _strip_contract_comments(text)
    )
    bound_names = tuple(
        dict.fromkeys(
            tuple(
                str(name or "").strip()
                for name in context_bound_names
                if str(name or "").strip()
            )
            + leading_names
        )
    )

    def proof_like_bound_name(name: str) -> bool:
        lowered = str(name or "").strip().lower()
        return lowered.startswith(
            ("h", "hyp", "this", "proof", "assump", "premise", "cond", "given")
        )

    stripped_identifier_set = set(_lean_identifier_tokens(stripped))
    alpha_names = tuple(
        name
        for name in bound_names
        if name in stripped_identifier_set or not proof_like_bound_name(name)
    )
    mapping = {name: f"__bound{idx}__" for idx, name in enumerate(alpha_names)}

    normalized = _contract_alpha_replace_scoped(stripped, mapping)
    return _normalize_not_mem_contract_surface(_contract_compact_surface(normalized))


def _matching_surface_group_index(text: str, start: int) -> int:
    raw = str(text or "")
    opener = raw[start] if 0 <= start < len(raw) else ""
    expected = _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE.get(opener)
    if expected is None:
        return -1
    stack: list[str] = [expected]
    index = start + 1
    while index < len(raw):
        skip_to = _lean_surface_lexical_skip_end(raw, index)
        if skip_to is not None:
            index = skip_to
            continue
        ch = raw[index]
        if ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE:
            stack.append(_LEAN_SURFACE_GROUP_OPEN_TO_CLOSE[ch])
        elif stack and ch == stack[-1]:
            stack.pop()
            if not stack:
                return index
        elif ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE.values():
            return -1
        index += 1
    return -1


def _contract_alpha_replace_scoped(
    text: str,
    mapping: Mapping[str, str],
) -> str:
    raw = str(text or "")
    out: list[str] = []
    index = 0
    while index < len(raw):
        skip_to = _lean_surface_lexical_skip_end(raw, index)
        if skip_to is not None:
            token = raw[index:skip_to]
            out.append(
                mapping.get(token, token) if raw.startswith("«", index) else token
            )
            index = skip_to
            continue
        ch = raw[index]
        if ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE:
            end = _matching_surface_group_index(raw, index)
            if end >= 0:
                out.append(ch)
                out.append(
                    _contract_alpha_replace_scoped(raw[index + 1 : end], mapping)
                )
                out.append(raw[end])
                index = end + 1
                continue
        quantifier_len = _top_level_quantifier_token_len(raw, index)
        if quantifier_len:
            tail_start = index + quantifier_len
            comma = _find_top_level_comma(raw[tail_start:])
            if comma >= 0:
                binder = raw[tail_start : tail_start + comma]
                body = raw[tail_start + comma + 1 :]
                local_mapping = dict(mapping)
                next_index = len(local_mapping)
                for binder_group in _binder_group_chunks(binder):
                    for name in _binder_names_from_chunk(binder_group):
                        local_mapping[name] = f"__bound{next_index}__"
                        next_index += 1
                out.append(raw[index : index + quantifier_len])
                out.append(_contract_alpha_replace_scoped(binder, local_mapping))
                out.append(",")
                out.append(_contract_alpha_replace_scoped(body, local_mapping))
                return "".join(out)
        match = _LEAN_IDENTIFIER_PATTERN.match(raw, index)
        if match is not None:
            token = match.group(0)
            out.append(_contract_alpha_identifier_token(token, mapping))
            index = match.end()
            continue
        out.append(ch)
        index += 1
    return "".join(out)


def _split_top_level_conjunctions(text: str) -> list[str]:
    raw = str(text or "")
    parts: list[str] = []
    start = 0
    depth = 0
    index = 0
    while index < len(raw):
        skip_to = _lean_surface_lexical_skip_end(raw, index)
        if skip_to is not None:
            index = skip_to
            continue
        ch = raw[index]
        if ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE:
            depth += 1
        elif ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE.values():
            depth = max(0, depth - 1)
        elif depth == 0:
            let_body_start = _top_level_let_body_start_for_contract_split(raw, index)
            if let_body_start >= 0:
                if start > 0 or raw[start:index].strip():
                    break
                index = let_body_start
                continue
            if _top_level_quantifier_token_len(raw, index):
                break
            if ch == "∧":
                parts.append(raw[start:index].strip())
                start = index + 1
        index += 1
    parts.append(raw[start:].strip())
    return [_strip_balanced_outer_parens(part) for part in parts if part.strip()]


def _support_contract_candidates(
    statement: str,
    *,
    include_implication_premises: bool = False,
    premises_are_assumptions: bool = False,
) -> tuple[tuple[str, tuple[str, ...]], ...]:
    """Return top-level formulas that can actually supply a planner premise."""

    candidates: list[tuple[str, tuple[str, ...]]] = []
    seen: set[tuple[str, tuple[str, ...]]] = set()

    def add_candidate(statement_text: str, bound_names: Sequence[str]) -> None:
        candidate = (str(statement_text or "").strip(), tuple(bound_names or ()))
        if candidate[0] and candidate not in seen:
            seen.add(candidate)
            candidates.append(candidate)

    def add_assumption_candidate(
        statement_text: str, bound_names: Sequence[str]
    ) -> None:
        item_body, item_names = _strip_leading_forall_binders_with_names(statement_text)
        item_bound_names = tuple(dict.fromkeys(tuple(bound_names or ()) + item_names))
        add_candidate(item_body, item_bound_names)
        if (
            "→" in item_body
            or "->" in item_body
            or "∀" in item_body
            or "∃" in item_body
        ):
            items = [item_body]
        else:
            items = _split_top_level_conjunctions(item_body)
        for item in items:
            conjunct_body, conjunct_names = _strip_leading_forall_binders_with_names(
                item
            )
            add_candidate(
                conjunct_body,
                tuple(dict.fromkeys(item_bound_names + conjunct_names)),
            )

    body, statement_names, binder_premises = (
        _strip_leading_forall_binders_with_names_and_premises(str(statement or ""))
    )
    if premises_are_assumptions:
        for premise in binder_premises:
            add_assumption_candidate(premise, statement_names)
    implication_parts = _split_top_level_implications(body)
    conclusion = implication_parts[-1] if implication_parts else body
    if (
        premises_are_assumptions
        and include_implication_premises
        and len(implication_parts) >= 2
    ):
        selected = implication_parts[:-1]
    elif include_implication_premises:
        selected = []
    elif binder_premises:
        selected = []
    else:
        selected = [body]
    if premises_are_assumptions and include_implication_premises:
        iff_parts = _split_top_level_iffs(conclusion)
        if len(iff_parts) >= 2:
            selected.extend(iff_parts)
            for iff_part in iff_parts:
                iff_body, iff_names, iff_binder_premises = (
                    _strip_leading_forall_binders_with_names_and_premises(iff_part)
                )
                iff_bound_names = tuple(dict.fromkeys(statement_names + iff_names))
                for premise in iff_binder_premises:
                    add_assumption_candidate(premise, iff_bound_names)
                iff_implication_parts = _split_top_level_implications(iff_body)
                if len(iff_implication_parts) >= 2:
                    for premise in iff_implication_parts[:-1]:
                        premise_body, premise_names = (
                            _strip_leading_forall_binders_with_names(premise)
                        )
                        add_candidate(
                            premise_body,
                            tuple(dict.fromkeys(iff_bound_names + premise_names)),
                        )

    for item in selected:
        add_assumption_candidate(item, statement_names)
    return tuple(candidates)


def _support_contains_contract(
    premise: str,
    support_candidates: Sequence[tuple[str, tuple[str, ...]]],
    *,
    premise_bound_names: Sequence[str] = (),
) -> bool:
    premise_norm = _contract_norm(premise)
    if not premise_norm:
        return True
    premise_alpha_norm = _contract_alpha_norm(
        premise,
        context_bound_names=premise_bound_names,
    )
    for support, support_bound_names in support_candidates:
        support_norm = _contract_norm(support)
        # Preserve the exact surface fast path, but defer namespace aliasing to
        # the alpha-normalized comparison below.  Otherwise an unqualified
        # local binder named ``Icc`` could be confused with ``Set.Icc`` before
        # its scoped binder identity has been made explicit.
        if premise_norm == support_norm:
            return True
        support_alpha_norm = _contract_alpha_norm(
            support,
            context_bound_names=support_bound_names,
        )
        if _contract_identity_matches(premise_alpha_norm, support_alpha_norm):
            return True
    return False


@dataclass(frozen=True)
class _SupportContractSequent:
    """A proved theorem viewed as assumptions ``|-`` conclusion.

    Dependency statements must not be flattened into an unconditional bag of
    formulas.  In particular, a proved ``A -> B`` supplies ``B`` only in a
    context that already supplies ``A``.  Keeping the binder names alongside
    both sides preserves the alpha-equivalence behavior of the existing
    surface contract matcher.
    """

    assumptions: tuple[str, ...]
    conclusion: str
    bound_names: tuple[str, ...] = ()


def _support_contract_sequent(statement: str) -> _SupportContractSequent:
    premises, conclusion, bound_names = _statement_premises_and_conclusion(
        str(statement or "")
    )
    return _SupportContractSequent(
        assumptions=tuple(
            str(item or "").strip() for item in premises if str(item or "").strip()
        ),
        conclusion=str(conclusion or "").strip(),
        bound_names=tuple(bound_names or ()),
    )


def _close_contextual_support_contracts(
    support_candidates: Sequence[tuple[str, tuple[str, ...]]],
    support_statements: Sequence[str],
) -> tuple[tuple[str, tuple[str, ...]], ...]:
    """Compute the syntactic modus-ponens closure of proved support.

    This is deliberately not a theorem prover.  It only exposes a dependency
    conclusion after every antecedent has an exact/alpha-equivalent provenance
    in the current root context.  Consequently a drifted ``A' -> B`` cannot
    masquerade as root support for ``B`` when the root supplies ``A``.
    """

    closed: list[tuple[str, tuple[str, ...]]] = []
    seen: set[tuple[str, tuple[str, ...]]] = set()
    for statement, bound_names in support_candidates:
        candidate = (str(statement or "").strip(), tuple(bound_names or ()))
        if candidate[0] and candidate not in seen:
            seen.add(candidate)
            closed.append(candidate)

    # A proved conditional remains usable as a theorem-valued fact (for
    # example to discharge a consumer premise that is itself ``A -> B``).
    # Its conclusion is exposed separately below only after its antecedents
    # are available.
    for support_statement in support_statements:
        for candidate in _support_contract_candidates(support_statement):
            if candidate[0] and candidate not in seen:
                seen.add(candidate)
                closed.append(candidate)

    sequents = [
        _support_contract_sequent(statement)
        for statement in support_statements
        if str(statement or "").strip()
    ]
    changed = True
    while changed:
        changed = False
        for sequent in sequents:
            if not sequent.conclusion:
                continue
            if not all(
                _support_contains_contract(
                    assumption,
                    closed,
                    premise_bound_names=sequent.bound_names,
                )
                for assumption in sequent.assumptions
            ):
                continue
            candidate = (sequent.conclusion, sequent.bound_names)
            if candidate in seen:
                continue
            seen.add(candidate)
            closed.append(candidate)
            changed = True
    return tuple(closed)


def _split_top_level_disjunctions(statement: str) -> list[str]:
    text = str(statement or "")
    parts: list[str] = []
    start = 0
    depth = 0
    index = 0
    while index < len(text):
        skip_to = _lean_surface_lexical_skip_end(text, index)
        if skip_to is not None:
            index = skip_to
            continue
        ch = text[index]
        if ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE:
            depth += 1
        elif ch in _LEAN_SURFACE_GROUP_OPEN_TO_CLOSE.values():
            depth = max(0, depth - 1)
        elif depth == 0:
            let_body_start = _top_level_let_body_start_for_contract_split(text, index)
            if let_body_start >= 0:
                if start > 0 or text[start:index].strip():
                    break
                index = let_body_start
                continue
            if _top_level_quantifier_token_len(text, index):
                break
            if ch == "∨":
                parts.append(text[start:index].strip())
                start = index + 1
        index += 1
    parts.append(text[start:].strip())
    return [_strip_balanced_outer_parens(part) for part in parts if part.strip()]


def _contract_alpha_matches(
    left: str,
    right: str,
    *,
    left_bound_names: Sequence[str] = (),
    right_bound_names: Sequence[str] = (),
) -> bool:
    left_key = _contract_alpha_norm(left, context_bound_names=left_bound_names)
    right_key = _contract_alpha_norm(right, context_bound_names=right_bound_names)
    return _contract_identity_matches(left_key, right_key)


def _contract_alpha_matches_exact_telescope(left: str, right: str) -> bool:
    """Compare alpha-equivalent formulas without erasing parameter frames."""

    if graph_statement_nonproof_parameter_profile(
        left
    ) != graph_statement_nonproof_parameter_profile(right):
        return False
    # Graph contract equivalence retains proof-valued binder premises and
    # supports their implication reshapes while alpha-normalizing names.
    return graph_statement_root_equivalent(left, right)


def _branch_case_supports_premise(
    premise: str,
    support_candidates: Sequence[tuple[str, tuple[str, ...]]],
    *,
    premise_bound_names: Sequence[str] = (),
) -> bool:
    return bool(
        _branch_case_support_kind(
            premise,
            support_candidates,
            premise_bound_names=premise_bound_names,
        )
    )


def _branch_case_support_kind(
    premise: str,
    support_candidates: Sequence[tuple[str, tuple[str, ...]]],
    *,
    premise_bound_names: Sequence[str] = (),
    root_statement: str = "",
) -> str:
    """Return whether a route-local case split can supply ``premise``.

    A branch reducer such as ``P -> root`` should be Lean-checked as a global
    conditional theorem. Its premise ``P`` is not a missing global dependency
    when another dependency supplies ``P ∨ Q``; the route assembly performs
    the local elimination. This guard only accepts exact disjunct matches,
    leaving unsupported bridge premises rejected as before.
    """

    premise_text, premise_names = _strip_leading_forall_binders_with_names(premise)
    premise_names = tuple(dict.fromkeys(tuple(premise_bound_names) + premise_names))
    if not premise_text:
        return False
    for support, support_bound_names in support_candidates:
        support_body, support_names = _strip_leading_forall_binders_with_names(support)
        disjuncts = _split_top_level_disjunctions(support_body)
        if len(disjuncts) < 2:
            continue
        if any(
            _contract_norm(disjunct).lower() in {"true", "false"}
            for disjunct in disjuncts
        ):
            continue
        support_context = tuple(
            dict.fromkeys(tuple(support_bound_names) + tuple(support_names))
        )
        for disjunct in disjuncts:
            if _contract_alpha_matches(
                premise_text,
                disjunct,
                left_bound_names=premise_names,
                right_bound_names=support_context,
            ):
                return "case_assumption"
            inner_premises, inner_conclusion, inner_bound_names = (
                _statement_premises_and_conclusion(premise_text)
            )
            if not root_statement or len(inner_premises) != 1:
                continue
            if not _statements_root_adjacent(
                inner_conclusion,
                root_statement,
                conclusion_bound_names=tuple(
                    dict.fromkeys(premise_names + inner_bound_names)
                ),
            ):
                continue
            if _contract_alpha_matches(
                inner_premises[0],
                disjunct,
                left_bound_names=tuple(
                    dict.fromkeys(premise_names + inner_bound_names)
                ),
                right_bound_names=support_context,
            ):
                return "case_handler"
    return ""


def _is_assembly_like_claim(claim: MiniSubgoalClaim, *, root_statement: str) -> bool:
    # Downstream orphan/taint classifiers must not contradict a fresh Lean
    # route receipt merely because the executable source uses definitionally
    # equal syntax. Root recognition separately checks that the anchor is an
    # allowed root/active-target identity, so this cannot spoof a root route.
    relation_anchor = str(claim.contract_route_relation_anchor_identity or "").strip()
    relation_kind = str(claim.contract_route_relation_kind or "").strip()
    expected_relation_receipt = _make_contract_route_relation_receipt(
        claim,
        anchor_identity=relation_anchor,
        relation_kind=relation_kind,
    )
    if (
        _bound_claim_contract_identity(claim)
        and relation_kind in {"exact", "profile"}
        and expected_relation_receipt
        and secrets.compare_digest(
            str(claim.contract_route_relation_evidence_receipt or ""),
            expected_relation_receipt,
        )
    ):
        return True
    premises, conclusion, bound_names = _statement_premises_and_conclusion(
        str(claim.statement or "")
    )
    if not premises:
        return False
    return _statements_root_adjacent(
        conclusion,
        root_statement,
        conclusion_bound_names=bound_names,
    )


def _root_route_dependency_names(
    claims: Sequence[MiniSubgoalClaim],
    *,
    root_statement: str,
) -> set[str]:
    """Return plan-claim names on a dependency path into root assembly.

    A conditional bridge can be several helper edges away from the claim whose
    conclusion is root-adjacent.  Restrict provisional premise admission to
    this backwards dependency closure, then recompute the closure after
    filtering so a rejected consumer cannot leave an orphaned hollow bridge.
    External/verified dependency names are intentionally ignored here: they
    are support anchors, not claims that this plan may provisionally retain.
    """

    claims_by_name = {
        str(claim.name or "").strip(): claim
        for claim in claims
        if str(claim.name or "").strip()
    }
    pending = [
        str(dependency or "").strip()
        for claim in claims
        if _is_assembly_like_claim(claim, root_statement=root_statement)
        for dependency in tuple(claim.dependencies or ())
        if str(dependency or "").strip()
    ]
    route_dependencies: set[str] = set()
    while pending:
        name = pending.pop()
        if name in route_dependencies or name not in claims_by_name:
            continue
        route_dependencies.add(name)
        pending.extend(
            dependency_name
            for dependency in claims_by_name[name].dependencies
            for dependency_name in (str(dependency or "").strip(),)
            if dependency_name and dependency_name not in route_dependencies
        )
    return route_dependencies


def _claim_contract_analysis_statement(claim: MiniSubgoalClaim) -> str:
    """Return diagnostic syntax for analysis without mutating executable source."""

    return str(claim.contract_display_statement or claim.statement or "").strip()


def _claim_contract_source_statement(claim: MiniSubgoalClaim) -> str:
    """Return the preferred executable variant for Lean contract analysis."""

    for variant in claim.variants:
        statement = str(getattr(variant, "statement", "") or "").strip()
        if statement:
            return statement
    return str(claim.statement or "").strip()


def _claim_contract_source_statement_keys(
    claim: Any,
) -> frozenset[str]:
    """Return source keys to which claim/variant evidence may bind."""

    variants = tuple(getattr(claim, "variants", ()) or ())
    return frozenset(
        graph_statement_key(statement)
        for statement in (
            str(claim.statement or "").strip(),
            *(
                str(getattr(variant, "statement", "") or "").strip()
                for variant in variants
            ),
        )
        if statement
    )


def _prune_claims_depending_on_removed_names(
    claims: Sequence[MiniSubgoalClaim],
    removed_names: AbstractSet[str],
) -> tuple[tuple[MiniSubgoalClaim, ...], frozenset[str]]:
    """Drop claims transitively depending on removed planner obligations."""

    blocked = {str(name or "") for name in removed_names if str(name or "")}
    pending = list(claims)
    changed = True
    while changed:
        changed = False
        kept: list[MiniSubgoalClaim] = []
        for claim in pending:
            if any(
                str(dependency or "") in blocked for dependency in claim.dependencies
            ):
                name = str(claim.name or "").strip()
                if name and name not in blocked:
                    blocked.add(name)
                    changed = True
                continue
            kept.append(claim)
        pending = kept
    return tuple(pending), frozenset(blocked)


def _has_lean_structural_contract_evidence(identity: str) -> bool:
    return has_lean_contract_identity(identity)


def _bound_claim_contract_identity(claim: MiniSubgoalClaim) -> str:
    identity = str(claim.contract_identity or "").strip()
    statement_key = str(claim.contract_identity_statement_key or "").strip()
    environment_hash = str(claim.contract_identity_environment_hash or "").strip()
    if statement_key not in _claim_contract_source_statement_keys(
        claim
    ) or not lean_contract_evidence_receipt_matches(
        claim.contract_identity_evidence_receipt,
        identity=identity,
        statement_key=statement_key,
        environment_hash=environment_hash,
    ):
        return ""
    return identity


def _bound_variant_contract_identity(variant: SubgoalVariant) -> str:
    """Return receipt-bound Lean identity for one compiled claim variant."""

    identity = str(variant.contract_identity or "").strip()
    statement_key = str(variant.contract_identity_statement_key or "").strip()
    environment_hash = str(variant.contract_identity_environment_hash or "").strip()
    if statement_key != graph_statement_key(
        variant.statement
    ) or not lean_contract_evidence_receipt_matches(
        variant.contract_identity_evidence_receipt,
        identity=identity,
        statement_key=statement_key,
        environment_hash=environment_hash,
    ):
        return ""
    return identity


def _resolve_recursive_child_proof_idea_context(
    *,
    dossier: Any,
    planned_claim: Mapping[str, Any],
    target_statement: str,
    statement_identity: str,
) -> tuple[str, Any]:
    """Resolve one child target to its exact route/claim/branch lifecycle.

    Surface similarity and dossier cardinality are intentionally absent.  A
    child receives attempted Lean and residual evidence only when the durable
    mini-recursive route contract identifies one cognition owner and one
    branch.  Ambiguous or stale ownership fails closed with no advisory text.
    """

    if not isinstance(planned_claim, Mapping):
        return "", None
    idea_id = str(planned_claim.get("proof_idea_id") or "").strip()
    route_id = str(
        planned_claim.get("root_route_id") or planned_claim.get("route_id") or ""
    ).strip()
    claim_id = str(planned_claim.get("claim_node_id") or "").strip()
    branch_id = str(planned_claim.get("branch_id") or "").strip()
    if not (
        idea_id
        and route_id
        and claim_id
        and branch_id
        and str(statement_identity or "").strip()
    ):
        return "", None
    ideas = dict(getattr(dossier, "proof_ideas", {}) or {})
    idea = ideas.get(idea_id)
    if idea is None:
        return "", None

    provenance_branch_ids = {
        str(getattr(item, "branch_id", "") or "").strip()
        for item in tuple(getattr(idea, "branch_provenance", ()) or ())
        if str(getattr(item, "branch_id", "") or "").strip()
    }
    if branch_id not in provenance_branch_ids:
        return "", None

    envelope = ProofLineageEnvelope(
        proof_idea_id=idea_id,
        strategy_lineage_id=str(planned_claim.get("strategy_lineage_id") or "").strip(),
        route_id=route_id,
        claim_id=claim_id,
        statement_identity=str(statement_identity or "").strip(),
    )
    binding_id = stable_identity(
        "mini-recursive-child-proof-idea-binding",
        idea_id,
        route_id,
        claim_id,
        branch_id,
        statement_identity,
    )
    binding = {
        "consumer_binding_id": binding_id,
        "proof_lineage": envelope.to_record(),
        "branch_id": branch_id,
        "reason": "exact mini-recursive route-contract child",
        # Mini-recursive claim IDs are durable cognition coordinates but are
        # not necessarily materialized proof-graph nodes.  Adding one here
        # would make the exact resolver correctly classify the binding stale.
        "graph_node_id": "",
    }
    execution_environment_hash = str(
        planned_claim.get("contract_identity_environment_hash")
        or getattr(dossier, "current_lean_environment_hash", "")
        or ""
    ).strip()
    packet = {
        "execution_scope": {
            "target_statement": str(target_statement or ""),
            "statement_identity": str(statement_identity or "").strip(),
            "environment_hash": execution_environment_hash,
            "helper_context_hash": str(
                planned_claim.get("helper_context_hash") or ""
            ).strip(),
            "graph_revision": str(dossier.proof_idea_graph_revision() or ""),
        },
        "consumer_bindings": [binding],
        "primary_consumer_binding": binding,
    }
    resolver = getattr(dossier, "resolve_proof_idea_context", None)
    projector = getattr(dossier, "project_proof_idea_context", None)
    if not callable(resolver) or not callable(projector):
        return "", None
    resolution = resolver(packet, policy="exact_selected")
    if str(getattr(resolution, "status", "") or "") != "resolved":
        return "", resolution
    projection = projector(resolution, audience="child")
    return str(projection.render() or ""), resolution


def _append_recursive_child_proof_idea_context(
    conversation: Any,
    proof_idea_context: str,
) -> Optional[dict[str, Any]]:
    """Attach exact selected strategy state as atomic child input.

    The child lifecycle is execution context, not part of the natural-language
    problem.  Keeping it in its own required message makes its attempt and Lean
    residual indivisible at both conversation compaction and provider-budget
    boundaries.  An empty resolution deliberately creates no message.
    """

    rendered = str(proof_idea_context or "")
    if not rendered.strip():
        return None
    append_user = getattr(conversation, "append_user", None)
    if not callable(append_user):
        raise TypeError("recursive child conversation has no append_user method")
    message = append_user(
        "Untrusted conserved proof-strategy lifecycle for orientation only; "
        "Lean remains authoritative. This packet is scoped to the exact "
        "selected route, claim, and branch:\n"
        f"{rendered}"
    )
    if not isinstance(message, dict):
        raise TypeError("recursive child append_user did not return a message")
    message["pinned"] = True
    message["_required_prompt_context"] = {
        "kind": "mini_recursive_child_proof_idea_lifecycle",
        "units": [
            "selected_route",
            "selected_claim",
            "selected_branch",
            "current_attempt",
            "current_lean_residual",
        ],
    }
    return message


def _append_recursive_child_planner_handoff(
    conversation: Any,
    planner_handoff: Mapping[str, Any],
) -> dict[str, Any]:
    """Attach the lossless planner receipt and its executable interpretation.

    The raw field is the provider's exact *visible* response, not hidden model
    reasoning.  The compiled plan and selected claim are carried separately so
    deterministic parsing, filtering, or scheduling can never masquerade as
    the planner's own output.  Required-context transport is atomic: if the
    receiving model cannot fit the packet, dispatch fails explicitly instead
    of trimming or rewriting it.
    """

    append_user = getattr(conversation, "append_user", None)
    if not callable(append_user):
        raise TypeError("recursive child conversation has no append_user method")
    payload = copy.deepcopy(dict(planner_handoff or {}))
    raw_visible_response = str(
        payload.pop("raw_visible_planner_response", "") or ""
    )
    message = append_user(
        "Untrusted exact planner handoff for orientation only; Lean remains "
        "authoritative. The next section is the planner's exact visible "
        "response, preserved character-for-character and not rewritten by "
        "the controller. It contains exactly "
        f"{len(raw_visible_response)} Unicode code points.\n"
        "--- BEGIN EXACT VISIBLE PLANNER RESPONSE ---\n"
        + raw_visible_response
        + "\n--- END EXACT VISIBLE PLANNER RESPONSE ---\n"
        "The following JSON is the controller's explicitly labeled "
        "interpretation and execution state, not replacement planner output:\n"
        + json.dumps(
            payload,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        )
    )
    if not isinstance(message, dict):
        raise TypeError("recursive child append_user did not return a message")
    message["pinned"] = True
    message["_required_prompt_context"] = {
        "kind": "mini_recursive_child_planner_handoff",
        "units": [
            "raw_visible_planner_response",
            "compiled_originating_plan",
            "accepted_plan",
            "active_execution_frontier",
            "selected_claim",
            "selected_executable_variant",
        ],
    }
    return message


def _bound_claim_contract_telescope_evidence(
    claim: MiniSubgoalClaim,
) -> tuple[tuple[str, ...], str]:
    identity = _bound_claim_contract_identity(claim)
    premise_hashes = tuple(
        str(value or "").strip()
        for value in claim.contract_proof_binder_structural_hashes
    )
    conclusion_hash = str(claim.contract_conclusion_structural_hash or "").strip()
    if not lean_contract_telescope_evidence_receipt_matches(
        claim.contract_telescope_evidence_receipt,
        identity=identity,
        statement_key=claim.contract_identity_statement_key,
        environment_hash=claim.contract_identity_environment_hash,
        proof_binder_structural_hashes=premise_hashes,
        conclusion_structural_hash=conclusion_hash,
        binder_sorts=tuple(claim.contract_binder_sorts),
        proof_binder_types=tuple(claim.contract_proof_binder_types),
    ):
        return (), ""
    return premise_hashes, conclusion_hash


def _make_contract_route_relation_receipt(
    claim: MiniSubgoalClaim,
    *,
    anchor_identity: str,
    relation_kind: str,
) -> str:
    kind = str(relation_kind or "").strip().lower()
    anchor = str(anchor_identity or "").strip()
    claim_receipt = str(claim.contract_identity_evidence_receipt or "").strip()
    environment_hash = str(claim.contract_identity_environment_hash or "").strip()
    if kind not in {"exact", "profile"} or not anchor or not claim_receipt:
        return ""
    return "lean-contract-route-relation-v1:" + text_hash(
        json.dumps(
            {
                "anchor_identity": anchor,
                "claim_evidence_receipt": claim_receipt,
                "environment_hash": environment_hash,
                "kind": kind,
            },
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=True,
        )
    )


def _bound_contract_route_relation_anchor(
    claim: MiniSubgoalClaim,
    *,
    allowed_anchor_identities: AbstractSet[str],
) -> str:
    if not _bound_claim_contract_identity(claim):
        return ""
    kind = str(claim.contract_route_relation_kind or "").strip().lower()
    anchor = str(claim.contract_route_relation_anchor_identity or "").strip()
    if not anchor or anchor not in allowed_anchor_identities:
        return ""
    expected = _make_contract_route_relation_receipt(
        claim,
        anchor_identity=anchor,
        relation_kind=kind,
    )
    if not expected or not secrets.compare_digest(
        str(claim.contract_route_relation_evidence_receipt or ""),
        expected,
    ):
        return ""
    return anchor


def _bound_root_contract_identity(plan: MiniSubgoalPlan) -> str:
    identity = str(plan.root_contract_identity or "").strip()
    statement_key = str(plan.root_contract_identity_statement_key or "").strip()
    environment_hash = str(plan.root_contract_identity_environment_hash or "").strip()
    if statement_key != graph_statement_key(
        plan.root_statement
    ) or not lean_contract_evidence_receipt_matches(
        plan.root_contract_identity_evidence_receipt,
        identity=identity,
        statement_key=statement_key,
        environment_hash=environment_hash,
    ):
        return ""
    return identity


def _bound_root_contract_telescope_evidence(
    plan: MiniSubgoalPlan,
) -> tuple[tuple[str, ...], str]:
    identity = _bound_root_contract_identity(plan)
    premise_hashes = tuple(
        str(value or "").strip()
        for value in plan.root_contract_proof_binder_structural_hashes
    )
    conclusion_hash = str(plan.root_contract_conclusion_structural_hash or "").strip()
    if not lean_contract_telescope_evidence_receipt_matches(
        plan.root_contract_telescope_evidence_receipt,
        identity=identity,
        statement_key=plan.root_contract_identity_statement_key,
        environment_hash=plan.root_contract_identity_environment_hash,
        proof_binder_structural_hashes=premise_hashes,
        conclusion_structural_hash=conclusion_hash,
        binder_sorts=tuple(plan.root_contract_binder_sorts),
        proof_binder_types=tuple(plan.root_contract_proof_binder_types),
    ):
        return (), ""
    return premise_hashes, conclusion_hash


def _plan_root_assembly_claim_names(
    plan: MiniSubgoalPlan,
    *,
    selected_claims: Optional[Sequence[MiniSubgoalClaim]] = None,
    candidate_claims: Optional[Sequence[MiniSubgoalClaim]] = None,
    satisfied_dependency_names: AbstractSet[str] = frozenset(),
    active_target_statements: Sequence[str] = (),
    active_target_contract_identities: Sequence[str] = (),
) -> tuple[str, ...]:
    """Return claims that explicitly connect the plan back to its root.

    A collection of useful helper lemmas is not by itself a root-assembly
    contract.  The proof graph may only schedule an ``assemble_route`` action
    when the filtered/selected plan still contains an explicit terminal claim
    whose conclusion is the root (or is structurally root-equivalent).

    ``active_target_statements`` are the hash-vetted active-root frames (e.g.
    the opaque ``*_solution`` shell with the model's committed candidate value
    substituted). In opaque mode the answer-safety filter rejects a claim that
    restates the placeholder shell, so a candidate-substituted root_assembly is
    the ONLY winnable terminal claim — it must register as a root route here.
    Route classification is scheduling metadata; Lean verification and
    root_finalization still gate actual closure.
    """

    root_statement = str(plan.root_statement or "").strip()
    if not root_statement:
        return ()
    active_targets = tuple(
        target
        for target in (
            str(item or "").strip() for item in (active_target_statements or ())
        )
        if target
    )
    active_target_identity_profiles = {
        parsed[1]
        for identity in active_target_contract_identities or ()
        for parsed in (parse_lean_contract_identity(str(identity or "")),)
        if parsed is not None and parsed[1] != "dependent"
    }
    active_target_structural_identities = {
        parsed[0]
        for identity in active_target_contract_identities or ()
        for parsed in (parse_lean_contract_identity(str(identity or "")),)
        if parsed is not None
    }
    allowed_route_relation_anchors = {
        identity
        for identity in (
            _bound_root_contract_identity(plan),
            *(str(item or "").strip() for item in active_target_contract_identities),
        )
        if identity
    }
    claim_universe = tuple(
        plan.claims if candidate_claims is None else candidate_claims
    )
    claims_by_name: dict[str, list[MiniSubgoalClaim]] = {}
    for claim in claim_universe:
        name = str(claim.name or "").strip()
        if name:
            claims_by_name.setdefault(name, []).append(claim)
    selected_claim_ids = (
        {id(claim) for claim in selected_claims}
        if selected_claims is not None
        else None
    )

    def selected_dependency_closure_present(claim: MiniSubgoalClaim) -> bool:
        available_claim_ids = (
            selected_claim_ids
            if selected_claim_ids is not None
            else {id(candidate) for candidate in claim_universe}
        )
        if id(claim) not in available_claim_ids:
            return False
        pending = [claim]
        visited: set[int] = set()
        while pending:
            current_claim = pending.pop()
            current_id = id(current_claim)
            if current_id in visited:
                continue
            visited.add(current_id)
            for raw_dependency in current_claim.dependencies:
                dependency = str(raw_dependency or "").strip()
                if dependency in satisfied_dependency_names:
                    continue
                # Dependencies outside this plan name verified dossier helpers;
                # they are already available and need not be selected again.
                dependency_claims = claims_by_name.get(dependency, [])
                if not dependency_claims:
                    # External names are available only when the caller bound
                    # them to verified semantic facts. A nonexistent planner
                    # label must never make a root route look connected.
                    return False
                if any(
                    id(candidate) not in available_claim_ids
                    for candidate in dependency_claims
                ):
                    return False
                # Duplicate planner names are ambiguous. Requiring the closure
                # of every match is conservative and prevents one selected
                # sibling from laundering an unselected dependency.
                pending.extend(dependency_claims)
        return True

    names: list[str] = []
    for claim in claim_universe:
        statement = _claim_contract_analysis_statement(claim)
        if not statement:
            continue
        root_identity = parse_lean_contract_identity(
            _bound_root_contract_identity(plan)
        )
        claim_identity = parse_lean_contract_identity(
            _bound_claim_contract_identity(claim)
        )
        structural_root_match = bool(
            root_identity and claim_identity and root_identity[0] == claim_identity[0]
        )
        structural_contract_match = bool(
            root_identity
            and claim_identity
            and root_identity[1] != "dependent"
            and root_identity[1] == claim_identity[1]
        )
        active_target_structural_match = bool(
            claim_identity
            and (
                claim_identity[0] in active_target_structural_identities
                or (
                    claim_identity[1] != "dependent"
                    and claim_identity[1] in active_target_identity_profiles
                )
            )
        )
        lean_route_relation_match = bool(
            _bound_contract_route_relation_anchor(
                claim,
                allowed_anchor_identities=allowed_route_relation_anchors,
            )
        )
        # The Lean printer surface is diagnostic only.  In particular it may
        # qualify aliases (``dist`` -> ``Dist.dist``), while the active target
        # registry retains the exact hash-vetted executable proof-state source.
        # Compare both surfaces independently so attaching elaboration evidence
        # cannot make a previously recognized exact active route disappear.
        statement_keys = {
            graph_statement_key(source)
            for source in (claim.statement, statement)
            if str(source or "").strip()
        }
        active_target_match = bool(
            statement_keys
            and any(
                graph_statement_key(target) in statement_keys
                for target in active_targets
            )
        )
        active_target_conclusion_match = False
        if active_targets:
            active_target_keys = {
                graph_statement_key(target) for target in active_targets
            }
            for source in (claim.statement, statement):
                if not str(source or "").strip():
                    continue
                premises, conclusion, _bound_names = _statement_premises_and_conclusion(
                    str(source)
                )
                if premises and graph_statement_key(conclusion) in active_target_keys:
                    active_target_conclusion_match = True
                    break
        if root_identity and claim_identity:
            # Lean evidence is definitive when it exists on both sides.
            # The proof-erased profile admits genuine ``H → root``
            # assemblies while retaining data binders and conclusion types.
            root_connected = bool(
                structural_root_match
                or structural_contract_match
                or active_target_match
                or active_target_conclusion_match
                or active_target_structural_match
                or lean_route_relation_match
            )
        else:
            root_connected = bool(
                active_target_match
                or graph_statement_root_equivalent(
                    statement,
                    root_statement,
                    active_target_statements=(root_statement, *active_targets),
                )
                or _is_assembly_like_claim(
                    claim,
                    root_statement=root_statement,
                )
            )
        if not root_connected:
            continue
        name = str(claim.name or "").strip()
        if name and name not in names and selected_dependency_closure_present(claim):
            names.append(name)
    return tuple(names)


def _namespace_relaxed_graph_statement_key(statement: str) -> str:
    """Surface key used only to preserve candidates for Lean adjudication."""

    relaxed = re.sub(
        r"(?<![\w'])" r"(?:[A-Za-z_][A-Za-z0-9_']*\.)+" r"([A-Za-z_][A-Za-z0-9_']*)",
        r"\1",
        str(statement or ""),
    )
    return graph_statement_key(relaxed)


def _surface_supported_conditional_root_claim_names(
    plan: MiniSubgoalPlan,
    *,
    active_target_statements: Sequence[str] = (),
) -> tuple[str, ...]:
    """Recognize conditional roots whose emitted premise DAG is explicit.

    This is a pre-elaboration preservation rule, not proof authority. Exact
    Lean contract analysis still decides whether the route is schedulable.
    """

    claims_by_name: dict[str, list[MiniSubgoalClaim]] = {}
    for claim in plan.claims:
        name = str(claim.name or "").strip()
        if name:
            claims_by_name.setdefault(name, []).append(claim)
    root_premises, _root_conclusion, _root_bounds = _statement_premises_and_conclusion(
        plan.root_statement
    )
    contextual_premise_keys = {
        graph_statement_key(premise)
        for premise in root_premises
        if graph_statement_key(premise)
    }
    target_keys = {graph_statement_key(plan.root_statement)}
    relaxed_target_keys = {_namespace_relaxed_graph_statement_key(plan.root_statement)}
    for active_statement in active_target_statements:
        target_key = graph_statement_key(active_statement)
        if target_key:
            target_keys.add(target_key)
        relaxed_target = _namespace_relaxed_graph_statement_key(active_statement)
        if relaxed_target:
            relaxed_target_keys.add(relaxed_target)
        active_premises, _active_conclusion, _active_bounds = (
            _statement_premises_and_conclusion(active_statement)
        )
        contextual_premise_keys.update(
            graph_statement_key(premise)
            for premise in active_premises
            if graph_statement_key(premise)
        )
    recognized: list[str] = []
    for claim in plan.claims:
        premises, conclusion, _bound_names = _statement_premises_and_conclusion(
            claim.statement
        )
        if not premises or (
            graph_statement_key(conclusion) not in target_keys
            and _namespace_relaxed_graph_statement_key(conclusion)
            not in relaxed_target_keys
        ):
            continue
        dependency_statement_keys: set[str] = set()
        dependency_contract_unambiguous = True
        for dependency in claim.dependencies:
            matches = claims_by_name.get(str(dependency or "").strip(), [])
            if len(matches) != 1:
                dependency_contract_unambiguous = False
                break
            dependency_key = graph_statement_key(matches[0].statement)
            if dependency_key:
                dependency_statement_keys.add(dependency_key)
        premise_keys = {
            graph_statement_key(premise)
            for premise in premises
            if graph_statement_key(premise)
        }
        name = str(claim.name or "").strip()
        if (
            name
            and dependency_contract_unambiguous
            and premise_keys <= (contextual_premise_keys | dependency_statement_keys)
        ):
            recognized.append(name)
    return tuple(dict.fromkeys(recognized))


def _claim_square_root_role_text(
    claim: MiniSubgoalClaim,
    *,
    plan: MiniSubgoalPlan,
    assembly_like: bool,
) -> str:
    claim_role = " ".join(
        str(part or "")
        for part in (
            getattr(claim, "name", ""),
            getattr(claim, "rationale", ""),
            " ".join(getattr(claim, "invariant_refs", ()) or ()),
            getattr(claim, "sanity_check", ""),
        )
    )
    if not assembly_like:
        return claim_role
    return " ".join(
        str(part or "")
        for part in (
            claim_role,
            getattr(plan, "strategy", ""),
            " ".join(getattr(plan, "notes", ()) or ()),
        )
    )


def _statement_supplies_square_root_rationality_contract(statement: str) -> bool:
    raw = str(statement or "").strip()
    if not raw:
        return False
    norm = _contract_norm(raw)
    compact = re.sub(r"\s+", "", raw)
    has_implication = "→" in raw or "->" in raw
    has_existential = "∃" in raw or re.search(r"\bexists\b", norm) is not None
    has_rational_range = (
        "Set.range" in raw
        and "ℚ" in raw
        and ("∈" in raw or re.search(r"\bin\b", norm) is not None)
    )
    has_rational_marker = (
        "ℚ" in raw
        or re.search(r"\bRat(?:ional)?\b", raw, re.IGNORECASE) is not None
        or re.search(r"\bq\d*'?[:∈]", compact) is not None
        or has_rational_range
    )
    has_square_marker = (
        re.search(r"\^\s*(?:2|\(2\)|\(2\s*:\s*ℕ\))", raw) is not None
        or re.search(r"\bpow\s+2\b", norm) is not None
        or re.search(r"\bsq\b", norm) is not None
    )
    has_sqrt_marker = "sqrt" in norm
    if has_sqrt_marker and has_rational_marker and has_implication:
        return True
    return bool(
        has_square_marker
        and has_rational_marker
        and (has_existential or has_rational_range)
        and has_implication
    )


def _claim_semantic_role_contract_reasons(
    claim: MiniSubgoalClaim,
    *,
    plan: MiniSubgoalPlan,
    support_statements: Sequence[str],
    assembly_like: bool,
) -> tuple[str, ...]:
    role_text = _claim_square_root_role_text(
        claim,
        plan=plan,
        assembly_like=assembly_like,
    )
    if not any(
        pattern.search(role_text) for pattern in _SQRT_RATIONALITY_ROLE_PATTERNS
    ):
        return ()
    candidate_statements = (
        str(getattr(claim, "statement", "") or ""),
        *tuple(str(stmt or "") for stmt in support_statements),
    )
    if any(
        _statement_supplies_square_root_rationality_contract(statement)
        for statement in candidate_statements
    ):
        return ()
    return (
        "semantic_role_mismatch:"
        "sqrt_or_square_rationality_bridge_without_formal_contract",
    )


def _claim_dependency_contract_reasons(
    claim: MiniSubgoalClaim,
    *,
    plan: MiniSubgoalPlan,
    support_statements: Sequence[str] = (),
    support_structural_identities: Sequence[str] = (),
    support_structural_hashes: AbstractSet[str] = frozenset(),
    route_anchor_identities: Sequence[str] = (),
) -> tuple[str, ...]:
    root_contract_statement = str(
        plan.root_contract_display_statement or plan.root_statement or ""
    )
    analysis_claim = dataclass_replace(
        claim,
        statement=_claim_contract_analysis_statement(claim),
    )
    assembly_like = _is_assembly_like_claim(
        analysis_claim,
        root_statement=root_contract_statement,
    )

    # A receipt-bound FULL definitional-equality relation proves that Lean saw
    # the entire closed proposition—including every proof premise—as the root
    # or active target. Re-checking printer-rendered premise text would
    # false-reject aliases such as ``MyPremise x`` versus ``x = x``. Profile-
    # only relations do not receive this shortcut: their erased premises still
    # traverse the ordinary dependency contract below.
    relation_anchor = str(claim.contract_route_relation_anchor_identity or "").strip()
    allowed_relation_anchors = {
        identity
        for identity in (
            _bound_root_contract_identity(plan),
            *(str(item or "").strip() for item in route_anchor_identities),
        )
        if identity
    }
    if (
        str(claim.contract_route_relation_kind or "").strip().lower() == "exact"
        and relation_anchor
        and _bound_contract_route_relation_anchor(
            claim,
            allowed_anchor_identities=allowed_relation_anchors,
        )
    ):
        return ()

    name_to_claim = {str(item.name or ""): item for item in plan.claims}
    support_candidates = list(
        _support_contract_candidates(
            root_contract_statement,
            include_implication_premises=True,
            premises_are_assumptions=True,
        )
    )
    root_premises, _root_conclusion, root_bound_names = (
        _statement_premises_and_conclusion(root_contract_statement)
    )
    _root_telescope_hashes, root_telescope_conclusion = (
        _bound_root_contract_telescope_evidence(plan)
    )
    if (
        has_current_lean_contract_identity(_bound_root_contract_identity(plan))
        and root_telescope_conclusion
    ):
        # Compare Lean-elaborated premises on both sides. Comparing an
        # elaborated claim only with root source notation false-rejects
        # namespace aliases, coercions, and set/function notation that Lean
        # has already established are the same proposition.
        root_premises = tuple(plan.root_contract_proof_binder_types)
        support_candidates.extend(
            (premise, root_bound_names)
            for premise in root_premises
            if str(premise or "").strip()
        )
    contextual_support_statements: list[str] = []
    for dep in tuple(getattr(claim, "dependencies", ()) or ()):
        dep_claim = name_to_claim.get(str(dep or ""))
        if dep_claim is not None:
            contextual_support_statements.append(
                _claim_contract_analysis_statement(dep_claim)
            )
    for stmt in support_statements:
        text = str(stmt or "").strip()
        if text:
            contextual_support_statements.append(text)
    support_candidates = list(
        _close_contextual_support_contracts(
            support_candidates,
            contextual_support_statements,
        )
    )

    premises, _conclusion, claim_bound_names = _statement_premises_and_conclusion(
        _claim_contract_analysis_statement(claim)
    )
    _claim_telescope_hashes, claim_telescope_conclusion = (
        _bound_claim_contract_telescope_evidence(claim)
    )
    if (
        has_current_lean_contract_identity(_bound_claim_contract_identity(claim))
        and claim_telescope_conclusion
    ):
        # Lean's outer Pi telescope is authoritative after elaboration. This
        # avoids both dropping data binders printed with notation such as
        # ``ℝ[X]`` and accidentally treating a proposition-valued application
        # as data. Legacy v2 evidence used a conclusion-unfolding telescope and
        # therefore falls back to syntax rather than reviving stale phantom
        # premises from a checkpoint.
        premises = tuple(claim.contract_proof_binder_types)
    claim_parameter_profile = _canonical_nonproof_parameter_profile(
        analysis_claim.statement
    )
    root_parameter_profile = _canonical_nonproof_parameter_profile(
        root_contract_statement
    )
    parameter_profile_is_known = "__untyped_binder__" not in {
        *claim_parameter_profile,
        *root_parameter_profile,
    }
    root_drift_premises = (
        root_premises
        if parameter_profile_is_known
        and claim_parameter_profile == root_parameter_profile
        else ()
    )
    semantic_role_reasons = _claim_semantic_role_contract_reasons(
        claim,
        plan=plan,
        support_statements=support_statements,
        assembly_like=assembly_like,
    )
    if semantic_role_reasons:
        return semantic_role_reasons
    if not premises:
        return ()
    available_structural_hashes = {
        str(value or "").strip()
        for value in support_structural_hashes
        if re.fullmatch(r"[0-9a-f]{64}", str(value or "").strip())
    }
    available_structural_hashes.update(
        {
            parsed[0]
            for identity in support_structural_identities
            for parsed in (parse_lean_contract_identity(str(identity or "")),)
            if parsed is not None
        }
    )
    premise_structural_hashes, _claim_conclusion_hash = (
        _bound_claim_contract_telescope_evidence(claim)
    )
    unmatched: list[str] = []
    branch_supported_assumption_norms: set[str] = set()
    branch_supported_handler_norms: set[str] = set()
    for premise_index, premise in enumerate(premises):
        premise_structural_hash = str(
            premise_structural_hashes[premise_index]
            if premise_index < len(premise_structural_hashes)
            else ""
        ).strip()
        if (
            premise_structural_hash
            and premise_structural_hash in available_structural_hashes
        ):
            continue
        premise_complex = _is_complex_planner_premise(premise)
        premise_text, premise_leading_names = _strip_leading_forall_binders_with_names(
            premise
        )
        premise_norm = _contract_norm(premise_text)
        premise_bound_names = tuple(
            dict.fromkeys(claim_bound_names + premise_leading_names)
        )
        root_contract_drift = False
        for root_premise in root_drift_premises:
            if _support_contains_contract(
                premise_text,
                ((root_premise, root_bound_names),),
                premise_bound_names=premise_bound_names,
            ):
                continue
            premise_alpha = _contract_alpha_norm(
                premise_text,
                context_bound_names=premise_bound_names,
            )
            root_alpha = _contract_alpha_norm(
                root_premise,
                context_bound_names=root_bound_names,
            )
            if min(len(premise_alpha), len(root_alpha)) < 16:
                continue
            premise_relations = tuple(
                re.findall(r"<=|>=|!=|≤|≥|≠|=|<|>|∈|∣", premise_alpha)
            )
            root_relations = tuple(re.findall(r"<=|>=|!=|≤|≥|≠|=|<|>|∈|∣", root_alpha))
            if premise_relations != root_relations:
                continue
            similarity = difflib.SequenceMatcher(
                None,
                premise_alpha,
                root_alpha,
                autojunk=False,
            ).ratio()
            if similarity >= 0.78:
                root_contract_drift = True
                break
        if not assembly_like and not premise_complex and not root_contract_drift:
            continue
        if (
            len(premise_norm) < 8
            and not assembly_like
            and not premise_complex
            and not root_contract_drift
        ):
            continue
        if _support_contains_contract(
            premise_text,
            support_candidates,
            premise_bound_names=premise_bound_names,
        ):
            support_candidates.append((premise_text, premise_bound_names))
            support_candidates = list(
                _close_contextual_support_contracts(
                    support_candidates,
                    contextual_support_statements,
                )
            )
            continue
        branch_kind = (
            _branch_case_support_kind(
                premise_text,
                support_candidates,
                premise_bound_names=premise_bound_names,
                root_statement=str(plan.root_statement or ""),
            )
            if assembly_like
            else ""
        )
        if branch_kind:
            if branch_kind == "case_handler":
                branch_supported_handler_norms.add(premise_norm)
                continue
            if premise_norm in branch_supported_assumption_norms:
                continue
            if (
                not branch_supported_assumption_norms
                and not branch_supported_handler_norms
            ):
                branch_supported_assumption_norms.add(premise_norm)
                continue
        unmatched.append(
            ("root_contract_drift:" if root_contract_drift else "")
            + _compact_text(premise_text, 140)
        )

    if not unmatched:
        return ()

    reason_prefix = (
        "unmet_assembly_premise" if assembly_like else "unmet_complex_bridge_premise"
    )
    reasons = [f"{reason_prefix}:{item}" for item in unmatched[:3]]
    rationale = " ".join(
        str(part or "")
        for part in (
            claim.rationale,
            " ".join(getattr(claim, "invariant_refs", ()) or ()),
            plan.strategy,
            " ".join(plan.notes or ()),
        )
    )
    if any(pattern.search(rationale) for pattern in _DEPENDENCY_HANDWAVE_PATTERNS):
        reasons.append("handwaved_dependency_bridge")
    return tuple(dict.fromkeys(reasons))


def _has_unmet_assembly_premise_reason(reasons: Sequence[str]) -> bool:
    return any(
        str(reason or "").startswith("unmet_assembly_premise:")
        for reason in reasons or ()
    )


def _reasons_are_inline_dischargeable_route_premise(
    reasons: Sequence[str],
) -> bool:
    """True when a claim's ONLY issue is an undischarged route-local premise.

    Such a claim is a genuine conditional lemma ``H -> C``: proving it only
    *assumes* ``H``, and ``H`` is discharged while a downstream dependency
    chain applies it (Lean verifies every helper and the final assembly).
    Pre-rejecting it cascades to taint the root-assembly claim and blocks a
    Lean-provable proof, so a lemma on a live root route receives one bounded
    attempt rather than being statically gated out.

    Excludes ``root_contract_drift`` antecedents (the model mis-stating the root
    relation) and every other reason kind (``handwaved_dependency_bridge``,
    ``semantic_role_mismatch``, ambiguity, cycles, ...), which remain hard
    defects that stay rejected.  Both root-adjacent
    ``unmet_assembly_premise`` and transitive
    ``unmet_complex_bridge_premise`` are admissible because both denote local
    proposition binders; route connectivity and post-filter orphan pruning are
    the liveness guards, and Lean is the soundness authority.
    """

    saw_premise = False
    for reason in reasons or ():
        text = str(reason or "")
        prefix = next(
            (
                candidate
                for candidate in (
                    "unmet_assembly_premise:",
                    "unmet_complex_bridge_premise:",
                )
                if text.startswith(candidate)
            ),
            "",
        )
        if not prefix:
            return False
        payload = text[len(prefix) :]
        if payload.startswith("root_contract_drift:"):
            return False
        saw_premise = True
    return saw_premise


def _verified_helper_statements(
    helpers: Sequence[Any],
    *,
    suppress_solution_placeholders: Optional[bool] = None,
    opaque_mode: bool = True,
    allow_official_answer_visibility: bool = False,
    official_answer_payload_present: Optional[bool] = None,
) -> tuple[str, ...]:
    statements: list[str] = []
    seen: set[str] = set()
    answer_safety_kwargs = {
        "suppress_solution_placeholders": suppress_solution_placeholders,
        "opaque_mode": bool(opaque_mode),
        "allow_official_answer_visibility": bool(allow_official_answer_visibility),
        "official_answer_payload_present": official_answer_payload_present,
    }
    redact_solution_refs = (
        suppress_solution_placeholders is not False
        and bool(opaque_mode)
        and not bool(allow_official_answer_visibility)
    )
    for helper in helpers or ():
        if isinstance(helper, str):
            source = str(helper or "").strip()
        else:
            source = str(getattr(helper, "source", "") or "").strip()
        statement = str(getattr(helper, "statement", "") or "").strip()
        if source:
            statement = helper_decl_statement(source) or statement
        if not statement:
            if not source:
                source = str(helper or "").strip()
            signature = helper_prompt_signature(
                source,
                name=str(getattr(helper, "name", "") or ""),
                redact_solution_refs=redact_solution_refs,
            )
            statement = helper_decl_statement(signature) or signature
        statement = str(statement or "").strip()
        if (
            not statement
            or statement in seen
            or is_answer_unsafe_statement_text(statement, **answer_safety_kwargs)
        ):
            continue
        seen.add(statement)
        statements.append(statement)
    return tuple(statements)


def _verified_helper_declaration_blocks(
    helpers: Sequence[Any],
    *,
    suppress_solution_placeholders: Optional[bool] = None,
    opaque_mode: bool = True,
    allow_official_answer_visibility: bool = False,
    official_answer_payload_present: Optional[bool] = None,
) -> tuple[str, ...]:
    """Return answer-safe verified declarations needed to elaborate support."""

    answer_safety_kwargs = {
        "suppress_solution_placeholders": suppress_solution_placeholders,
        "opaque_mode": bool(opaque_mode),
        "allow_official_answer_visibility": bool(allow_official_answer_visibility),
        "official_answer_payload_present": official_answer_payload_present,
    }
    blocks: list[str] = []
    seen: set[str] = set()
    for helper in helpers or ():
        source = (
            str(helper or "").strip()
            if isinstance(helper, str)
            else str(getattr(helper, "source", "") or "").strip()
        )
        if (
            not source
            or source in seen
            or is_answer_unsafe_helper_source(source, **answer_safety_kwargs)
        ):
            continue
        seen.add(source)
        blocks.append(source)
    return tuple(blocks)


def _claim_premise_dependency_names(
    claim: MiniSubgoalClaim,
    provider_claims: Sequence[MiniSubgoalClaim],
    *,
    support_candidates: Sequence[tuple[str, tuple[str, ...]]] = (),
    support_statements: Sequence[str] = (),
) -> tuple[str, ...]:
    premises, _conclusion, _bound_names = _statement_premises_and_conclusion(
        str(claim.statement or "")
    )
    if not premises:
        return ()
    dependencies: list[str] = []
    contextual_support_statements: list[str] = [
        str(statement or "").strip()
        for statement in support_statements
        if str(statement or "").strip()
    ]
    closed_support_candidates = list(
        _close_contextual_support_contracts(
            support_candidates,
            contextual_support_statements,
        )
    )
    for premise in premises:
        premise_text, premise_leading_names = _strip_leading_forall_binders_with_names(
            premise
        )
        if not premise_text:
            continue
        premise_bound_names = tuple(dict.fromkeys(_bound_names + premise_leading_names))
        if _support_contains_contract(
            premise_text,
            closed_support_candidates,
            premise_bound_names=premise_bound_names,
        ):
            closed_support_candidates.append((premise_text, premise_bound_names))
            continue
        for prior in provider_claims:
            prior_name = str(prior.name or "").strip()
            if (
                not prior_name
                or prior_name == str(claim.name or "").strip()
                or prior_name in dependencies
            ):
                continue
            candidate_support_statements = [
                *contextual_support_statements,
                str(prior.statement or ""),
            ]
            prior_support_candidates = _close_contextual_support_contracts(
                closed_support_candidates,
                candidate_support_statements,
            )
            if _support_contains_contract(
                premise_text,
                prior_support_candidates,
                premise_bound_names=premise_bound_names,
            ):
                dependencies.append(prior_name)
                contextual_support_statements.append(str(prior.statement or ""))
                closed_support_candidates = list(prior_support_candidates)
                closed_support_candidates.append((premise_text, premise_bound_names))
                break
    return tuple(dependencies)


def _topologically_order_claims_by_dependencies(
    claims: Sequence[MiniSubgoalClaim],
) -> tuple[MiniSubgoalClaim, ...]:
    by_name = {
        str(claim.name or "").strip(): claim
        for claim in claims
        if str(claim.name or "").strip()
    }
    original_index = {
        str(claim.name or "").strip(): index for index, claim in enumerate(claims)
    }
    ordered: list[MiniSubgoalClaim] = []
    visiting: set[str] = set()
    visited: set[str] = set()

    def visit(claim: MiniSubgoalClaim) -> None:
        name = str(claim.name or "").strip()
        if not name or name in visited:
            return
        if name in visiting:
            return
        visiting.add(name)
        deps = [
            str(dep or "").strip()
            for dep in tuple(claim.dependencies or ())
            if str(dep or "").strip() in by_name
        ]
        deps.sort(key=lambda dep: original_index.get(dep, 10**9))
        for dep in deps:
            visit(by_name[dep])
        visiting.discard(name)
        visited.add(name)
        ordered.append(claim)

    for claim in claims:
        visit(claim)
    if len(ordered) != len(claims):
        seen = {id(claim) for claim in ordered}
        ordered.extend(claim for claim in claims if id(claim) not in seen)
    return tuple(ordered)


def _claim_semantic_statement_identity(claim: MiniSubgoalClaim) -> str:
    structural = _bound_claim_contract_identity(claim)
    if structural:
        return f"structural:{structural}"
    statement = str(getattr(claim, "statement", "") or "").strip()
    canonical = canonical_dossier_statement_key(statement)
    if canonical:
        return f"statement:{canonical}"
    return "source:" + text_hash(statement)


def _dependency_contract_suspension_key(claim: MiniSubgoalClaim) -> str:
    """Stable name/index-independent identity for a suspended obligation."""

    obligation_id = str(getattr(claim, "obligation_id", "") or "").strip()
    if obligation_id:
        return obligation_id
    # Legacy/unbound in-memory claims have no semantic persistence authority;
    # retain the label only to keep distinct local queue entries distinct.
    return text_hash(
        "mini_recursive_dependency_contract:v4\n"
        + str(getattr(claim, "name", "") or "").strip()
        + "\n"
        + _claim_semantic_statement_identity(claim)
    )[:24]


def _recursive_helper_evidence_fingerprints(
    helpers: Sequence[Any],
) -> set[str]:
    """Return mathematical, name-independent identities for helper evidence.

    ``ProofDossier`` deliberately retains same-statement helper aliases because
    Lean replay may still reference either declaration name.  Raw source hashes
    are therefore not a sound progress signal: a planner can emit ``h_1 : P``,
    then ``h_2 : P``, and manufacture an unbounded stream of apparently fresh
    passes without adding a proposition.  Failed-route memory has the same
    issue.  Canonical statement keys capture the evidence that changed; the
    raw-source fallback is reserved for duck-typed records whose proposition
    cannot be recovered.
    """

    fingerprints: set[str] = set()
    for helper in list(helpers or ()):
        # A self-premise projection remains available to Lean replay, but its
        # proof assumes exactly the proposition it returns.  Treating it as a
        # fresh evidence fingerprint would reopen empty/helper-only recovery
        # and buy continuation passes without any mathematical frontier change.
        if verified_helper_is_premise_projection(helper):
            continue
        structural_identity = verified_helper_bound_contract_identity(helper)
        if structural_identity:
            fingerprints.add(f"structural:{structural_identity}")
            continue
        source = (
            str(
                helper.get("source")
                or helper.get("declaration")
                or helper.get("code")
                or ""
            ).strip()
            if isinstance(helper, Mapping)
            else _helper_source_text(helper)
        )
        statement = helper_decl_statement(source) if source else ""
        if not statement:
            raw_statement = (
                helper.get("statement", "")
                if isinstance(helper, Mapping)
                else getattr(helper, "statement", "")
            )
            statement = str(raw_statement or "").strip()
        if statement:
            from .helper_quality import classify_auxiliary_statement_quality

            if not classify_auxiliary_statement_quality(statement).generic_novelty:
                continue
        statement_key = canonical_dossier_statement_key(statement)
        if statement_key:
            fingerprints.add(f"statement:{statement_key}")
            continue
        fallback = source or str(helper or "").strip()
        if fallback:
            fingerprints.add(
                "source:"
                + hashlib.sha256(fallback.encode("utf-8", errors="replace")).hexdigest()
            )
    return fingerprints


def _root_tactic_helper_environment_fingerprints(
    helpers: Sequence[Any],
) -> set[str]:
    """Return name-independent identities for tactic-visible declarations.

    Mathematical evidence alone is insufficient for root-tactic exhaustion:
    an ``instance`` or an attributed theorem can change elaboration and tactic
    search even when its proposition matches an ordinary theorem.  Preserve
    that declaration header while still erasing the arbitrary declaration
    name, so renamed theorem aliases cannot manufacture fresh scheduler work.
    """

    fingerprints: set[str] = set()
    for helper in list(helpers or ()):
        evidence = _recursive_helper_evidence_fingerprints((helper,))
        if not evidence:
            continue
        source = (
            str(
                helper.get("source")
                or helper.get("declaration")
                or helper.get("code")
                or ""
            ).strip()
            if isinstance(helper, Mapping)
            else _helper_source_text(helper)
        )
        kind = str(helper_decl_kind(source) or "").strip()
        name = str(helper_decl_name(source) or "").strip()
        header = kind or "unparsed"
        if kind:
            name_pattern = (
                rf"\b{re.escape(kind)}\s+{re.escape(name)}"
                rf"(?=\s|[:({{\[])"
                if name
                else rf"\b{re.escape(kind)}\b"
            )
            match = re.search(name_pattern, source)
            if match is not None:
                # Includes attributes, modifiers, and any scoped-open wrapper,
                # but stops before the declaration's arbitrary alias name.
                header = source[: match.start()] + kind
        normalized_header = " ".join(str(header or "").split())
        for item in evidence:
            encoded = json.dumps(
                {"declaration_header": normalized_header, "evidence": item},
                ensure_ascii=True,
                separators=(",", ":"),
                sort_keys=True,
            )
            fingerprints.add(
                "environment:"
                + hashlib.sha256(encoded.encode("utf-8")).hexdigest()
            )
    return fingerprints


def _verified_helper_dependency_identities(
    helpers: Sequence[Any],
    *,
    structural_identities_by_statement_key: Optional[Mapping[str, str]] = None,
) -> dict[str, str]:
    """Resolve helper declaration names to name-independent proposition keys."""

    identities_by_name: dict[str, set[str]] = {}
    for helper in list(helpers or ()):
        source = (
            str(
                helper.get("source")
                or helper.get("declaration")
                or helper.get("code")
                or ""
            ).strip()
            if isinstance(helper, Mapping)
            else _helper_source_text(helper)
        )
        name = str(
            (
                helper.get("name", "")
                if isinstance(helper, Mapping)
                else getattr(helper, "name", "")
            )
            or helper_decl_name(source)
            or ""
        ).strip()
        if not name:
            continue
        structural_identity = verified_helper_bound_contract_identity(helper)
        statement = helper_decl_statement(source) if source else ""
        if not statement:
            statement = str(
                helper.get("statement", "")
                if isinstance(helper, Mapping)
                else getattr(helper, "statement", "") or ""
            ).strip()
        if not structural_identity and statement:
            structural_identity = str(
                (structural_identities_by_statement_key or {}).get(
                    canonical_dossier_statement_key(statement),
                    "",
                )
                or ""
            ).strip()
        if structural_identity:
            identities_by_name.setdefault(name, set()).add(
                f"structural:{structural_identity}"
            )
            continue
        identity = canonical_dossier_statement_key(statement)
        if not identity:
            fallback = statement or source
            if not fallback:
                continue
            identity = (
                "source:"
                + hashlib.sha256(fallback.encode("utf-8", errors="replace")).hexdigest()
            )
        identities_by_name.setdefault(name, set()).add(identity)
    resolved: dict[str, str] = {}
    for name, identities in identities_by_name.items():
        ordered = sorted(identities)
        resolved[name] = (
            ordered[0]
            if len(ordered) == 1
            else "ambiguous:" + text_hash("\n".join(ordered))
        )
    return resolved


def _recursive_claim_failed_route_identity(
    claim: MiniSubgoalClaim,
    *,
    dependency_identities: Optional[Mapping[str, str]] = None,
) -> str:
    """Name/alpha-independent identity for one mathematical proof route.

    Proposition identity prevents the same failed bridge from being retried
    under fresh planner labels or binder names.  Route metadata remains part
    of the key because two claims with the same proposition but materially
    different proof strategies are legitimate alternatives; collapsing those
    made a scoped/provider miss suppress its sibling and made deferred search
    mathematically incomplete.
    """

    statement = str(
        _bound_claim_contract_identity(claim) or getattr(claim, "statement", "") or ""
    ).strip()
    canonical_statement = (
        canonical_dossier_statement_key(statement)
        or normalize_subgoal_statement(statement).strip()
        or statement
    )
    route_record = {
        "statement": canonical_statement,
        "role": str(getattr(claim, "role", "") or "").strip().lower(),
        "rationale": " ".join(
            str(getattr(claim, "rationale", "") or "").split()
        ).lower(),
        "sanity_check": " ".join(
            str(getattr(claim, "sanity_check", "") or "").split()
        ).lower(),
        "counting_classification": " ".join(
            str(getattr(claim, "counting_classification", "") or "").split()
        ).lower(),
        "dependencies": sorted(
            str((dependency_identities or {}).get(name) or f"unresolved:{name}")
            for dependency in tuple(getattr(claim, "dependencies", ()) or ())
            for name in (str(dependency or "").strip(),)
            if name
        ),
    }
    basis = "mini_recursive_failed_route:v4\n" + json.dumps(
        route_record,
        sort_keys=True,
        ensure_ascii=False,
        separators=(",", ":"),
    )
    return hashlib.sha256(basis.encode("utf-8", errors="replace")).hexdigest()[:16]


def _plan_claim_route_identity_map(
    plan: MiniSubgoalPlan,
    *,
    dependency_identities: Optional[Mapping[str, str]] = None,
) -> dict[str, str]:
    """Return stable full-DAG identities for every unambiguous plan label."""

    claims_by_name: dict[str, list[MiniSubgoalClaim]] = {}
    for claim in plan.claims:
        name = str(claim.name or "").strip()
        if name:
            claims_by_name.setdefault(name, []).append(claim)

    memo: dict[int, str] = {}

    def route_identity(claim: MiniSubgoalClaim, stack: frozenset[int]) -> str:
        claim_id = id(claim)
        if claim_id in memo:
            return memo[claim_id]
        structural_identity = _bound_claim_contract_identity(claim)
        statement = str(claim.statement or "").strip()
        canonical_statement = (
            f"structural:{structural_identity}"
            if structural_identity
            else (
                canonical_dossier_statement_key(statement)
                or normalize_subgoal_statement(statement).strip()
                or statement
            )
        )
        if claim_id in stack:
            return "cycle:" + text_hash(canonical_statement)
        nested_stack = stack | {claim_id}
        dependencies: list[str] = []
        for dependency in claim.dependencies:
            name = str(dependency or "").strip()
            if not name:
                continue
            internal = claims_by_name.get(name, ())
            if internal:
                alternatives = sorted(
                    route_identity(candidate, nested_stack) for candidate in internal
                )
                dependencies.append("internal:" + text_hash("\n".join(alternatives)))
            else:
                dependencies.append(
                    str((dependency_identities or {}).get(name) or f"unresolved:{name}")
                )
        identity = text_hash(
            json.dumps(
                {
                    "statement": canonical_statement,
                    "dependencies": sorted(dependencies),
                },
                sort_keys=True,
                separators=(",", ":"),
                ensure_ascii=True,
                default=str,
            )
        )
        memo[claim_id] = identity
        return identity

    identities_by_name: dict[str, str] = {}
    for name, claims in claims_by_name.items():
        alternatives = sorted(route_identity(claim, frozenset()) for claim in claims)
        identities_by_name[name] = (
            alternatives[0]
            if len(alternatives) == 1
            else "ambiguous-internal:" + text_hash("\n".join(alternatives))
        )
    return identities_by_name


def _plan_origin_fingerprint(
    plan: MiniSubgoalPlan,
    *,
    route_by_name: Optional[Mapping[str, str]] = None,
) -> str:
    routes = dict(route_by_name or _plan_claim_route_identity_map(plan))
    return text_hash(
        "mini_recursive_plan:v1\n"
        + json.dumps(
            {
                "root": canonical_dossier_statement_key(plan.root_statement)
                or str(plan.root_statement or "").strip(),
                "routes": sorted(routes.values()),
            },
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=True,
        )
    )[:24]


def _fresh_plan_obligation_id(
    *,
    plan_fingerprint: str,
    route_identity: str,
    version: int = 2,
    rationale: str = "",
    sanity_check: str = "",
) -> str:
    if int(version or 0) <= 1:
        payload = (
            "mini_recursive_obligation:v1\n"
            + str(plan_fingerprint or "")
            + "\n"
            + str(route_identity or "")
            + "\n"
            + " ".join(str(rationale or "").split()).lower()
            + "\n"
            + " ".join(str(sanity_check or "").split()).lower()
        )
    else:
        payload = (
            "mini_recursive_obligation:v2\n"
            + str(plan_fingerprint or "")
            + "\n"
            + str(route_identity or "")
        )
    return text_hash(payload)[:24]


def _claim_obligation_id_aliases(
    claim: MiniSubgoalClaim,
    *,
    plan_fingerprint: str,
    route_identity: str,
) -> tuple[str, ...]:
    existing = str(getattr(claim, "obligation_id", "") or "").strip()
    v2 = _fresh_plan_obligation_id(
        plan_fingerprint=plan_fingerprint,
        route_identity=route_identity,
        version=2,
    )
    v1 = _fresh_plan_obligation_id(
        plan_fingerprint=plan_fingerprint,
        route_identity=route_identity,
        version=1,
        rationale=str(getattr(claim, "rationale", "") or ""),
        sanity_check=str(getattr(claim, "sanity_check", "") or ""),
    )
    return tuple(dict.fromkeys(item for item in (existing, v2, v1) if item))


def _plan_claims_by_obligation_alias(
    plan: MiniSubgoalPlan,
) -> dict[str, tuple[MiniSubgoalClaim, ...]]:
    route_by_name = _plan_claim_route_identity_map(plan)
    plan_fingerprint = _plan_origin_fingerprint(plan, route_by_name=route_by_name)
    indexed: dict[str, list[MiniSubgoalClaim]] = {}
    for claim in plan.claims:
        name = str(claim.name or "").strip()
        route_identity = route_by_name.get(name) or text_hash(
            _claim_semantic_statement_identity(claim)
        )
        fingerprint = (
            str(claim.origin_plan_fingerprint or "").strip() or plan_fingerprint
        )
        for alias in _claim_obligation_id_aliases(
            claim,
            plan_fingerprint=fingerprint,
            route_identity=route_identity,
        ):
            indexed.setdefault(alias, []).append(claim)
    return {alias: tuple(claims) for alias, claims in indexed.items()}


def _claim_by_obligation_alias(
    indexed: Mapping[str, Sequence[MiniSubgoalClaim]],
    obligation_id: str,
    *,
    reference_claim: MiniSubgoalClaim,
) -> Optional[MiniSubgoalClaim]:
    candidates = tuple(indexed.get(str(obligation_id or "").strip(), ()))
    if not candidates:
        return None
    reference_key = _contract_claim_surface_match_key(reference_claim)
    matches = tuple(
        claim
        for claim in candidates
        if _contract_claim_surface_match_key(claim) == reference_key
    )
    if matches:
        return matches[0]
    return candidates[0] if len(candidates) == 1 else None


def _bind_plan_obligation_identities(plan: MiniSubgoalPlan) -> MiniSubgoalPlan:
    """Bind immutable persistence IDs before labels or positions can drift.

    The plan fingerprint names the originating mathematical DAG.  Individual
    obligation IDs additionally bind the claim's full semantic route, so a
    same-label claim from another plan cannot inherit repair, suspension, or
    proved-fact authority.
    """

    route_by_name = _plan_claim_route_identity_map(plan)
    plan_fingerprint = _plan_origin_fingerprint(plan, route_by_name=route_by_name)
    claims_by_name: dict[str, list[MiniSubgoalClaim]] = {}
    for claim in plan.claims:
        name = str(claim.name or "").strip()
        if name:
            claims_by_name.setdefault(name, []).append(claim)
    bound: list[MiniSubgoalClaim] = []
    for claim in plan.claims:
        name = str(claim.name or "").strip()
        route_identity = route_by_name.get(name) or text_hash(
            _claim_semantic_statement_identity(claim)
        )
        obligation_id = str(
            claim.obligation_id or ""
        ).strip() or _fresh_plan_obligation_id(
            plan_fingerprint=plan_fingerprint,
            route_identity=route_identity,
            version=2,
        )
        dependency_identities: list[tuple[str, str]] = []
        for raw_dependency in claim.dependencies:
            dependency = str(raw_dependency or "").strip()
            if not dependency:
                continue
            internal = claims_by_name.get(dependency, ())
            identity = route_by_name.get(dependency, "") if len(internal) == 1 else ""
            dependency_identities.append(
                (dependency, identity or f"unresolved:{dependency}")
            )
        bound.append(
            dataclass_replace(
                claim,
                obligation_id=obligation_id,
                origin_plan_fingerprint=(
                    str(claim.origin_plan_fingerprint or "").strip() or plan_fingerprint
                ),
                dependency_semantic_identities=(
                    tuple(claim.dependency_semantic_identities)
                    or tuple(dependency_identities)
                ),
            )
        )
    return dataclass_replace(plan, claims=tuple(bound))


def _plan_root_route_identity_set(
    plan: MiniSubgoalPlan,
    root_names: Sequence[str],
    *,
    dependency_identities: Optional[Mapping[str, str]] = None,
) -> frozenset[str]:
    """Return name-independent identities for executable root-route branches."""

    route_identity_by_name = _plan_claim_route_identity_map(
        plan,
        dependency_identities=dependency_identities,
    )
    return frozenset(
        route_identity_by_name[name]
        for raw_name in root_names
        for name in (str(raw_name or "").strip(),)
        if name in route_identity_by_name
    )


def _recursive_lean_library_hash(project_roots: Sequence[str] | str) -> str:
    """Hash the Lean project inputs that can change theorem availability."""

    raw_roots = (
        [project_roots] if isinstance(project_roots, str) else list(project_roots or ())
    )
    roots = [Path(str(item)).expanduser() for item in raw_roots if str(item).strip()]
    if not roots:
        return ""
    hasher = hashlib.sha256()
    found = False
    for root_index, project in enumerate(dict.fromkeys(roots)):
        candidates = [
            project / name
            for name in (
                "lean-toolchain",
                "lake-manifest.json",
                "lakefile.lean",
                "lakefile.toml",
            )
        ]
        if project.is_dir():
            try:
                candidates.extend(
                    path
                    for pattern in ("*.lean", "*.olean")
                    for path in project.rglob(pattern)
                    if ".lake" not in path.relative_to(project).parts
                )
            except (OSError, ValueError):
                pass
        for path in sorted(set(candidates)):
            try:
                if not path.is_file():
                    continue
                relative = path.relative_to(project)
                content = path.read_bytes()
            except (OSError, ValueError):
                continue
            found = True
            hasher.update(str(root_index).encode())
            hasher.update(b":")
            hasher.update(str(relative).encode("utf-8", errors="replace"))
            hasher.update(b"\0")
            hasher.update(content)
            hasher.update(b"\0")
    return hasher.hexdigest() if found else ""


def _recursive_runtime_component_identity(component: Any) -> dict[str, Any]:
    """Immutable/configured identity for route-memory compatibility."""

    cfg_obj = getattr(component, "cfg", None)
    fields = (
        "name",
        "model",
        "base_url",
        "temperature",
        "top_p",
        "max_tokens",
        "context_window",
        "reasoning_effort",
        "reasoning_control_required",
        "thinking_enabled",
        "request_timeout_s",
        "request_timeout_disabled",
        "llm_deadline_policy",
        "model_revision",
        "revision",
        "deployment_revision",
        "weights_hash",
        "model_hash",
        "project_dir",
        "preamble_import",
        "extra_imports",
        "module_search_paths",
        "resolved_lean_path",
        "resolved_lean_executable",
        "support_project_builds",
    )

    def stable_value(value: Any) -> Any:
        if value is None or isinstance(value, (str, int, float, bool)):
            return value
        if isinstance(value, Mapping):
            return {
                str(key): stable_value(item)
                for key, item in sorted(value.items(), key=lambda pair: str(pair[0]))
            }
        if isinstance(value, (list, tuple, set, frozenset)):
            return [stable_value(item) for item in value]
        return str(value)

    def configured_record(config: Any) -> dict[str, Any]:
        return {
            field: stable_value(getattr(config, field, None))
            for field in fields
            if getattr(config, field, None) not in (None, "", (), [])
        }

    configs = getattr(component, "configs", None)
    configured_chain = (
        [configured_record(config) for config in configs]
        if isinstance(configs, (list, tuple)) and configs
        else [configured_record(cfg_obj)]
    )
    configured = configured_chain[0]
    runtime_clients = getattr(component, "clients", None)
    executable_chain = (
        [
            {
                "configured": configured_record(getattr(client, "cfg", None)),
                "base_url": str(getattr(client, "base_url", "") or ""),
            }
            for client in runtime_clients
        ]
        if isinstance(runtime_clients, (list, tuple))
        else []
    )
    library_roots = [str(getattr(cfg_obj, "project_dir", "") or "")]
    library_roots.extend(
        str(item) for item in (getattr(cfg_obj, "module_search_paths", ()) or ())
    )
    support_builds = dict(getattr(cfg_obj, "support_project_builds", {}) or {})
    library_roots.extend(str(item) for item in support_builds)
    return {
        "class": (
            f"{type(component).__module__}.{type(component).__qualname__}"
            if component is not None
            else ""
        ),
        "configured": configured,
        "configured_chain": configured_chain,
        "executable_chain": executable_chain,
        "library_hash": _recursive_lean_library_hash(library_roots),
        "retrieval_snapshot_id": str(
            getattr(component, "compatibility_snapshot_id", "")
            or getattr(component, "index_snapshot_id", "")
            or ""
        ),
    }


def _recursive_route_environment_hash(
    *,
    theorem_name: str,
    root_statement: str,
    lean_signature: str,
    answer_safe_preamble: str,
    client: Any,
    config: MiniRecursiveConfig,
    proof_environment_fingerprint: str,
    selected_parent_proof_idea_context: str = "",
    proof_idea_lifecycle_context: str = "",
    suppress_solution_placeholders: bool = True,
    opaque_mode: bool = True,
    allow_official_answer_visibility: bool = False,
    official_answer_payload_present: Optional[bool] = None,
) -> str:
    """Stable scope for durable recursive facts and failed-route memory.

    The answer-visibility policy is part of the identity (RS-7 / MP-FU-007):
    the planner-visible official-answer definitions are derived from the
    preamble AND these flags, so a frame persisted under one policy must not
    resume under another even when the preamble text is unchanged.
    """

    payload = {
        "theorem_name": str(theorem_name or ""),
        "root_statement": str(root_statement or ""),
        "lean_signature": str(lean_signature or ""),
        "answer_safe_preamble": str(answer_safe_preamble or ""),
        "answer_visibility_policy": {
            "effective_suppression": bool(
                effective_solution_placeholder_suppression(
                    suppress_solution_placeholders=(suppress_solution_placeholders),
                    opaque_mode=opaque_mode,
                    allow_official_answer_visibility=(allow_official_answer_visibility),
                    official_answer_payload_present=(official_answer_payload_present),
                )
            ),
            "opaque_mode": bool(opaque_mode),
            "allow_official_answer_visibility": bool(allow_official_answer_visibility),
            "official_answer_payload_present": (
                None
                if official_answer_payload_present is None
                else bool(official_answer_payload_present)
            ),
        },
        # Recursive plans are paid for under one exact mathematical strategy
        # snapshot.  Lean/tool capability equality alone does not authorize a
        # plan produced for another route, branch, or lifecycle revision.
        "selected_parent_proof_idea_context": str(
            selected_parent_proof_idea_context or ""
        ),
        "proof_idea_lifecycle_context": str(proof_idea_lifecycle_context or ""),
        "client": _recursive_runtime_component_identity(client),
        "proof_environment_fingerprint": str(proof_environment_fingerprint or ""),
        "recursive_config": json.loads(
            json.dumps(
                mini_recursive_semantic_config_record(config),
                sort_keys=True,
                default=str,
            )
        ),
        "turns_per_claim": int(getattr(config, "turns_per_claim", 0) or 0),
        "tactic_timeout_s": float(getattr(config, "tactic_timeout_s", 0.0) or 0.0),
        "tactic_max_candidates": int(getattr(config, "tactic_max_candidates", 0) or 0),
    }
    return hashlib.sha256(
        json.dumps(
            payload,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=True,
        ).encode("utf-8")
    ).hexdigest()[:16]


def _dependency_contract_reasons_are_suspensible(
    reasons: Sequence[str],
) -> bool:
    for reason in reasons or ():
        text = str(reason or "")
        if text.startswith(
            (
                "unmet_assembly_premise:",
                "unmet_complex_bridge_premise:",
                "depends_on_contract_rejected:",
                "declared_dependency_cycle:",
            )
        ):
            return True
    return False


def _record_suspended_dependency_claim(
    suspended_claims: Optional[dict[str, SuspendedDependencyClaim]],
    claim: MiniSubgoalClaim,
    *,
    reasons: Sequence[str],
    pass_index: int,
    verdict: str,
) -> bool:
    if suspended_claims is None:
        return False
    if not _dependency_contract_reasons_are_suspensible(reasons):
        return False
    key = _dependency_contract_suspension_key(claim)
    if not key:
        return False
    was_new = key not in suspended_claims
    suspended_claims[key] = SuspendedDependencyClaim(
        claim=claim,
        reasons=tuple(str(reason or "") for reason in reasons if str(reason or "")),
        pass_index=int(pass_index or 0),
        verdict=str(verdict or ""),
        obligation_id=str(claim.obligation_id or ""),
        origin_plan_fingerprint=str(claim.origin_plan_fingerprint or ""),
        dependency_semantic_identities=tuple(
            claim.dependency_semantic_identities or ()
        ),
    )
    # Checkpoints must remain bounded. Prefer the newest observations while
    # retaining deterministic ordering for replay and tests.
    while len(suspended_claims) > 256:
        oldest_key = min(
            suspended_claims,
            key=lambda item_key: (
                suspended_claims[item_key].pass_index,
                item_key,
            ),
        )
        suspended_claims.pop(oldest_key, None)
    return was_new


def _ready_suspended_dependency_claims(
    suspended_claims: dict[str, SuspendedDependencyClaim],
    *,
    root_statement: str,
    helpers: Sequence[Any],
    proved_claim_names: set[str],
    proved_claim_obligation_ids: frozenset[str] = frozenset(),
    proved_claim_statement_keys: frozenset[str] = frozenset(),
    suppress_solution_placeholders: Optional[bool] = None,
    opaque_mode: bool = True,
    allow_official_answer_visibility: bool = False,
    max_claims: int,
    skip_keys: Sequence[str] = (),
    verified_support_statements_override: Optional[Sequence[str]] = None,
) -> list[MiniSubgoalClaim]:
    if not suspended_claims:
        return []
    ready: list[tuple[str, MiniSubgoalClaim]] = []
    skipped = {
        str(key or "").strip()
        for key in list(skip_keys or ())
        if str(key or "").strip()
    }
    support_statements = (
        tuple(
            str(statement or "") for statement in verified_support_statements_override
        )
        if verified_support_statements_override is not None
        else _verified_helper_statements(
            helpers,
            suppress_solution_placeholders=suppress_solution_placeholders,
            opaque_mode=opaque_mode,
            allow_official_answer_visibility=allow_official_answer_visibility,
        )
    )
    helper_names = _verified_helper_names(helpers)
    cap = max(1, int(max_claims or 1))
    for key, item in list(suspended_claims.items()):
        if key in skipped:
            continue
        claim = item.claim
        claim_name = str(getattr(claim, "name", "") or "").strip()
        obligation_id = str(getattr(claim, "obligation_id", "") or "").strip()
        statement_key = canonical_dossier_statement_key(claim.statement)
        if (
            (obligation_id and obligation_id in proved_claim_obligation_ids)
            or (statement_key and statement_key in proved_claim_statement_keys)
            or (not obligation_id and claim_name and claim_name in proved_claim_names)
        ):
            suspended_claims.pop(key, None)
            continue
        if _missing_claim_dependencies(
            claim,
            proved_claim_names=proved_claim_names,
            helpers=helpers,
        ):
            continue
        else:
            probe_plan = MiniSubgoalPlan(
                root_statement=root_statement,
                claims=(claim,),
                strategy="suspended dependency-contract claim readiness probe",
                notes=(),
                raw_response="",
            )
            reasons = _claim_dependency_contract_reasons(
                claim,
                plan=probe_plan,
                support_statements=support_statements,
            )
            if reasons:
                declared_deps = tuple(
                    str(dep or "").strip()
                    for dep in tuple(getattr(claim, "dependencies", ()) or ())
                    if str(dep or "").strip()
                )
                if (
                    declared_deps
                    and all(
                        dep in proved_claim_names or dep in helper_names
                        for dep in declared_deps
                    )
                    and all(
                        str(reason or "").startswith("unmet_assembly_premise:")
                        for reason in reasons
                    )
                ):
                    ready.append((key, claim))
                    if len(ready) >= cap:
                        break
                    continue
                continue
            ready.append((key, claim))
        if len(ready) >= cap:
            break
    out: list[MiniSubgoalClaim] = []
    for key, claim in ready:
        suspended_claims.pop(key, None)
        claim_name = str(getattr(claim, "name", "") or "").strip()
        obligation_id = str(getattr(claim, "obligation_id", "") or "").strip()
        statement_key = canonical_dossier_statement_key(claim.statement)
        if (
            (obligation_id and obligation_id in proved_claim_obligation_ids)
            or (statement_key and statement_key in proved_claim_statement_keys)
            or (not obligation_id and claim_name and claim_name in proved_claim_names)
        ):
            continue
        out.append(claim)
    return out


def _contract_claim_surface_match_key(claim: MiniSubgoalClaim) -> tuple[Any, ...]:
    """Identity fields unchanged by contract filtering and elaboration."""

    return (
        str(claim.name or ""),
        str(claim.role or ""),
        str(claim.rationale or ""),
        tuple(claim.invariant_refs or ()),
        str(claim.sanity_check or ""),
        str(claim.counting_classification or ""),
        int(claim.source_index or 0),
        bool(claim.source_arbitration_provisional),
    )


def _restore_contract_claim_surfaces(
    claims: Sequence[MiniSubgoalClaim],
    *,
    original_plan: MiniSubgoalPlan,
    canonical_plan: MiniSubgoalPlan,
) -> tuple[MiniSubgoalClaim, ...]:
    """Project filtered metadata back onto the planner's executable sources."""

    pairs = list(zip(canonical_plan.claims, original_plan.claims))
    used: set[int] = set()
    restored: list[MiniSubgoalClaim] = []
    for claim in claims:
        match_index: Optional[int] = None
        claim_key = _contract_claim_surface_match_key(claim)
        for index, (canonical_claim, _original_claim) in enumerate(pairs):
            if index in used:
                continue
            if _contract_claim_surface_match_key(canonical_claim) == claim_key and str(
                canonical_claim.statement or ""
            ) == str(claim.statement or ""):
                match_index = index
                break
        if match_index is None:
            # A strict name/source-index fallback keeps restoration robust to a
            # filter that normalizes harmless whitespace in a future revision.
            for index, (canonical_claim, _original_claim) in enumerate(pairs):
                if index in used:
                    continue
                if _contract_claim_surface_match_key(canonical_claim) == claim_key:
                    match_index = index
                    break
        if match_index is None:
            # Audit residual R-A (2026-07-30): even without a canonical pair,
            # prefer an original-plan surface over keeping the incoming
            # (potentially printer-rendered) statement.
            fallback_original = next(
                (
                    original_claim
                    for original_claim in original_plan.claims
                    if _contract_claim_surface_match_key(original_claim) == claim_key
                ),
                None,
            )
            if fallback_original is not None:
                restored.append(
                    dataclass_replace(
                        claim,
                        statement=fallback_original.statement,
                        variants=fallback_original.variants,
                    )
                )
                continue
            restored.append(claim)
            continue
        used.add(match_index)
        original_claim = pairs[match_index][1]
        # MP-FU-010: the ``original_plan`` passed here already carries the
        # recovered (repaired/substituted) EXECUTABLE sources — repair and
        # substitution edit it in place before canonicalization. Restoring
        # ``original_claim`` therefore restores the recovered source too;
        # keeping ``claim.statement`` for recovered claims would leak the
        # canonicalizer's PRINTER rendering back into executable positions,
        # which re-elaborates with unresolved metavariables.
        restored.append(
            dataclass_replace(
                claim,
                statement=original_claim.statement,
                variants=original_claim.variants,
            )
        )
    return tuple(restored)


def _restore_contract_plan_surfaces(
    filtered_plan: MiniSubgoalPlan,
    *,
    original_plan: MiniSubgoalPlan,
    canonical_plan: MiniSubgoalPlan,
) -> MiniSubgoalPlan:
    # Deliberate three-source merge, based on ``filtered_plan`` so any field not
    # named below is carried rather than reset to its default.  Enumerating
    # every field instead means a new one is silently dropped here, which is the
    # same evidence-loss shape the filters themselves had.
    return dataclass_replace(
        filtered_plan,
        root_statement=original_plan.root_statement,
        claims=_restore_contract_claim_surfaces(
            filtered_plan.claims,
            original_plan=original_plan,
            canonical_plan=canonical_plan,
        ),
        root_contract_identity=canonical_plan.root_contract_identity,
        root_contract_identity_statement_key=(
            canonical_plan.root_contract_identity_statement_key
        ),
        root_contract_identity_environment_hash=(
            canonical_plan.root_contract_identity_environment_hash
        ),
        root_contract_identity_evidence_receipt=(
            canonical_plan.root_contract_identity_evidence_receipt
        ),
        root_contract_display_statement=(
            canonical_plan.root_contract_display_statement
        ),
        root_contract_binder_sorts=canonical_plan.root_contract_binder_sorts,
        root_contract_proof_binder_types=(
            canonical_plan.root_contract_proof_binder_types
        ),
        root_contract_proof_binder_structural_hashes=(
            canonical_plan.root_contract_proof_binder_structural_hashes
        ),
        root_contract_conclusion_structural_hash=(
            canonical_plan.root_contract_conclusion_structural_hash
        ),
        root_contract_telescope_evidence_receipt=(
            canonical_plan.root_contract_telescope_evidence_receipt
        ),
    )


def _restore_suspended_contract_claim_surfaces(
    suspended_claims: dict[str, SuspendedDependencyClaim],
    *,
    original_plan: MiniSubgoalPlan,
    canonical_plan: MiniSubgoalPlan,
) -> int:
    """Restore only obligations explicitly belonging to this exact plan.

    Older code fuzzy-matched every durable suspension against the current
    plan. A reused planner name could therefore rewrite an unrelated, older
    obligation. Unmatched records now remain byte-for-byte untouched.
    """

    original_by_id = _plan_claims_by_obligation_alias(original_plan)
    canonical_by_id = _plan_claims_by_obligation_alias(canonical_plan)
    rebuilt: dict[str, SuspendedDependencyClaim] = dict(suspended_claims)
    collisions = 0
    for old_key, item in tuple(suspended_claims.items()):
        obligation_id = str(
            item.obligation_id or item.claim.obligation_id or ""
        ).strip()
        plan_fingerprint = str(
            item.origin_plan_fingerprint or item.claim.origin_plan_fingerprint or ""
        ).strip()
        original_claim = _claim_by_obligation_alias(
            original_by_id,
            obligation_id,
            reference_claim=item.claim,
        )
        canonical_claim = (
            _claim_by_obligation_alias(
                canonical_by_id,
                obligation_id,
                reference_claim=original_claim,
            )
            if original_claim is not None
            else None
        )
        if original_claim is not None and canonical_claim is None:
            canonical_claim = _claim_by_obligation_alias(
                canonical_by_id,
                str(original_claim.obligation_id or "").strip(),
                reference_claim=original_claim,
            )
        if (
            not obligation_id
            or original_claim is None
            or canonical_claim is None
            or not plan_fingerprint
            or plan_fingerprint
            != str(original_claim.origin_plan_fingerprint or "").strip()
        ):
            continue
        restored_claim = _restore_contract_claim_surfaces(
            (item.claim,),
            original_plan=dataclass_replace(original_plan, claims=(original_claim,)),
            canonical_plan=dataclass_replace(canonical_plan, claims=(canonical_claim,)),
        )[0]
        restored_item = dataclass_replace(item, claim=restored_claim)
        key = _dependency_contract_suspension_key(restored_claim)
        rebuilt.pop(old_key, None)
        if key in rebuilt and key != old_key:
            collisions += 1
            rebuilt[old_key] = restored_item
            continue
        rebuilt[key] = restored_item
    suspended_claims.clear()
    suspended_claims.update(rebuilt)
    return collisions


def _adjudicate_source_arbitration_provisional_claims(
    *,
    original_plan: MiniSubgoalPlan,
    canonical_plan: MiniSubgoalPlan,
    coverage: _ContractIdentityCoverage,
    active_target_statements: Sequence[str] = (),
    active_target_contract_identities: Sequence[str] = (),
) -> tuple[
    MiniSubgoalPlan,
    MiniSubgoalPlan,
    _ContractIdentityCoverage,
    tuple[str, ...],
    tuple[str, ...],
]:
    """Promote or discard pre-Lean source-arbitration route DAGs.

    The compiler retains surface-unrecognized alternatives provisionally
    because arbitrary Lean aliases cannot be classified from text.  Once the
    shared analyzer has attached structural identities, only provisional root
    routes structurally connected to the active root are promoted.  Their
    internal dependency closure is promoted atomically; every other
    provisional claim is removed before repair, dependency filtering, claim
    caps, or scheduling.
    """

    if not coverage.usable:
        return original_plan, canonical_plan, coverage, (), ()

    root_identity = parse_lean_contract_identity(
        _bound_root_contract_identity(canonical_plan)
    )
    active_identities = tuple(
        parsed
        for raw_identity in active_target_contract_identities
        for parsed in (parse_lean_contract_identity(str(raw_identity or "")),)
        if parsed is not None
    )
    active_structural_identities = {parsed[0] for parsed in active_identities}
    active_profiles = {
        parsed[1] for parsed in active_identities if parsed[1] != "dependent"
    }
    # Read the batch offset the analyzer actually used.  Re-deriving it from
    # claim/support counts mirrors the producer's arithmetic as an unchecked
    # cross-function contract, and the rehydration path violates it: it
    # canonicalizes with NO analysis statements and then adjudicates with a
    # non-empty active-target set, so the mirrored offset lands past the end of
    # the batch.  Those anchors can never be satisfied, adjudication never
    # completes, and nothing is ever discarded.
    recorded_analysis_start = int(getattr(coverage, "analysis_batch_start", -1) or -1)
    analyzed_active_count = min(
        len(active_target_statements),
        len(coverage.analysis_elaborated),
    )
    # The batch carried no active-target entries; mint no anchors rather than
    # inventing indices for statements the analyzer never saw.
    active_analysis_start = (
        recorded_analysis_start
        if recorded_analysis_start >= 0 and analyzed_active_count > 0
        else -1
    )
    active_anchor_indices = (
        set(
            range(
                active_analysis_start,
                active_analysis_start + analyzed_active_count,
            )
        )
        if active_analysis_start >= 0
        else set()
    )
    anchor_identity_by_index: dict[int, str] = {}
    bound_root_identity = _bound_root_contract_identity(canonical_plan)
    if bound_root_identity:
        anchor_identity_by_index[0] = bound_root_identity
    if active_analysis_start >= 0:
        for offset, identity in enumerate(coverage.analysis_structural_identities):
            if has_lean_contract_identity(identity):
                anchor_identity_by_index[active_analysis_start + offset] = str(identity)
        # Back-filled dossier identities may cover targets the CURRENT batch did
        # not elaborate.  Bind only within the analyzed span, or the surplus
        # becomes another unreachable anchor.
        if len(active_target_contract_identities) == len(active_target_statements):
            for offset, identity in enumerate(
                active_target_contract_identities[:analyzed_active_count]
            ):
                if has_lean_contract_identity(identity):
                    anchor_identity_by_index.setdefault(
                        active_analysis_start + offset,
                        str(identity),
                    )
    recognized_root_indices: set[int] = set()
    route_relation_by_index: dict[int, tuple[str, str, str]] = {}
    for index, claim in enumerate(canonical_plan.claims):
        if (
            str(claim.role or "").strip().lower() != "root_assembly"
            or index >= len(coverage.claim_elaborated)
            or not coverage.claim_elaborated[index]
        ):
            continue
        claim_identity = parse_lean_contract_identity(
            _bound_claim_contract_identity(claim)
        )
        if claim_identity is None:
            continue
        root_match = bool(
            root_identity
            and (
                claim_identity[0] == root_identity[0]
                or (
                    claim_identity[1] != "dependent"
                    and root_identity[1] != "dependent"
                    and claim_identity[1] == root_identity[1]
                )
            )
        )
        active_match = bool(
            claim_identity[0] in active_structural_identities
            or (
                claim_identity[1] != "dependent"
                and claim_identity[1] in active_profiles
            )
        )
        exact_defeq_indices = set(
            coverage.claim_defeq_indices[index]
            if index < len(coverage.claim_defeq_indices)
            else ()
        )
        contract_defeq_indices = set(
            coverage.claim_contract_defeq_indices[index]
            if index < len(coverage.claim_contract_defeq_indices)
            else ()
        )
        lean_root_relation = bool(
            0 in exact_defeq_indices or 0 in contract_defeq_indices
        )
        lean_active_relation = bool(
            active_anchor_indices & (exact_defeq_indices | contract_defeq_indices)
        )
        if root_match or active_match or lean_root_relation or lean_active_relation:
            recognized_root_indices.add(index)
            exact_anchor_indices = {0, *active_anchor_indices} & exact_defeq_indices
            profile_anchor_indices = {
                0,
                *active_anchor_indices,
            } & contract_defeq_indices
            relation_kind = ""
            relation_anchor_identity = ""
            for candidate_kind, candidate_indices in (
                ("exact", exact_anchor_indices),
                ("profile", profile_anchor_indices),
            ):
                for anchor_index in sorted(candidate_indices):
                    anchor_identity = anchor_identity_by_index.get(
                        anchor_index,
                        "",
                    )
                    if anchor_identity:
                        relation_kind = candidate_kind
                        relation_anchor_identity = anchor_identity
                        break
                if relation_anchor_identity:
                    break
            if relation_anchor_identity:
                receipt = _make_contract_route_relation_receipt(
                    claim,
                    anchor_identity=relation_anchor_identity,
                    relation_kind=relation_kind,
                )
                if receipt:
                    route_relation_by_index[index] = (
                        relation_kind,
                        relation_anchor_identity,
                        receipt,
                    )
    claims_by_name: dict[str, list[int]] = {}
    for index, claim in enumerate(canonical_plan.claims):
        name = str(claim.name or "").strip()
        if name:
            claims_by_name.setdefault(name, []).append(index)

    active_identity_adjudication_complete = bool(
        root_identity is not None
        and (
            len(active_identities) == len(active_target_statements)
            or (
                len(coverage.analysis_structural_identities)
                == len(active_target_statements)
                and all(
                    has_lean_contract_identity(identity)
                    for identity in coverage.analysis_structural_identities
                )
            )
        )
    )
    required_anchor_indices = set(anchor_identity_by_index)
    adjudication_complete_indices: set[int] = set()
    if active_identity_adjudication_complete and required_anchor_indices:
        for index, claim in enumerate(canonical_plan.claims):
            if str(claim.role or "").strip().lower() != "root_assembly":
                continue
            exact_checked = set(
                coverage.claim_defeq_checked_indices[index]
                if index < len(coverage.claim_defeq_checked_indices)
                else ()
            )
            profile_checked = set(
                coverage.claim_contract_defeq_checked_indices[index]
                if index < len(coverage.claim_contract_defeq_checked_indices)
                else ()
            )
            claim_identity = parse_lean_contract_identity(
                _bound_claim_contract_identity(claim)
            )
            exact_comparison_complete = bool(required_anchor_indices <= exact_checked)
            profile_required_anchors = {
                anchor_index
                for anchor_index in required_anchor_indices
                if (
                    claim_identity is not None
                    and claim_identity[1] != "dependent"
                    and (
                        (
                            anchor_identity := parse_lean_contract_identity(
                                anchor_identity_by_index.get(anchor_index, "")
                            )
                        )
                        is not None
                        and anchor_identity[1] != "dependent"
                    )
                )
            }
            # Proof-erased profile comparison is semantically unavailable for
            # dependent propositions whose conclusion references an erased
            # proof binder. In that case a completed negative full-Expr check
            # is already complete evidence; waiting for a profile row would
            # replay forever because Lean can never construct that profile.
            profile_comparison_complete = bool(
                profile_required_anchors <= profile_checked
            )
            if exact_comparison_complete and profile_comparison_complete:
                adjudication_complete_indices.add(index)
    # A planner may label an internal prerequisite ``root_assembly``. Protect
    # the entire declared dependency closure of every Lean-recognized terminal
    # route before classifying other root-role claims as unrelated junk.
    # Otherwise the prerequisite becomes a taint seed and deletes its own
    # valid consumer.
    recognized_dependency_indices = set(recognized_root_indices)
    pending_recognized_dependencies = list(recognized_root_indices)
    while pending_recognized_dependencies:
        recognized_index = pending_recognized_dependencies.pop()
        for dependency in canonical_plan.claims[recognized_index].dependencies:
            for dependency_index in claims_by_name.get(
                str(dependency or "").strip(),
                (),
            ):
                if dependency_index not in recognized_dependency_indices:
                    recognized_dependency_indices.add(dependency_index)
                    pending_recognized_dependencies.append(dependency_index)
    # An elaboration diagnostic is repair input, not evidence that a
    # secondary-source route is mathematically unrelated. Keep it through the
    # bounded statement-repair transaction and adjudicate the mutated Expr.
    deterministic_failed_provisional_root_names: set[str] = set()
    unrecognized_root_names = deterministic_failed_provisional_root_names | {
        str(claim.name or "").strip()
        for index, claim in enumerate(canonical_plan.claims)
        if str(claim.role or "").strip().lower() == "root_assembly"
        and index not in recognized_root_indices
        and index not in recognized_dependency_indices
        and index in adjudication_complete_indices
        # A provisional route always needs Lean arbitration. For an ordinary
        # single-source plan, preserve the existing repair/substitution path
        # when *no* root is recognized; once Lean recognizes at least one root
        # route, however, every fully checked unrelated root DAG is competing
        # junk and must not survive merely because it came from the selected
        # transport source.
        and (
            claim.source_arbitration_provisional
            or bool(recognized_root_indices)
            # A completed negative exact/profile comparison is authoritative
            # evidence that an elaborated root-role proposition is not this
            # root/active target, even when surface namespace relaxation had
            # mistakenly treated it as connected (e.g. A.P versus B.P).
            or (
                index < len(coverage.claim_elaborated)
                and coverage.claim_elaborated[index]
            )
        )
        and str(claim.name or "").strip()
    }
    # Removing an unrecognized root must also remove every consumer that
    # declares it (directly or transitively).  Otherwise an unrelated ordinary
    # helper can seed promotion backwards and launder invalid provisional
    # roots into the repair/scheduling frontier.
    tainted_indices: set[int] = set()
    tainted_names = set(unrecognized_root_names)
    # When the planner supplied no valid terminal route, retain the elaborated
    # non-root prerequisite closure of its mismatched terminal as provisional
    # mathematical progress.  The existing bounded helper-only lane will
    # still require every claim to be proved in Lean before banking it.  This
    # is deliberately disabled when another recognized terminal route exists:
    # in that case competing-route prerequisites are arbitration noise, not
    # the only available mathematical plan.
    salvage_dependency_indices: set[int] = set()
    if unrecognized_root_names and not recognized_root_indices:
        pending_salvage_names = list(unrecognized_root_names)
        visited_salvage_names = set(unrecognized_root_names)
        while pending_salvage_names:
            consumer_name = pending_salvage_names.pop()
            for consumer_index in claims_by_name.get(consumer_name, ()):
                for dependency in canonical_plan.claims[consumer_index].dependencies:
                    dependency_name = str(dependency or "").strip()
                    if not dependency_name:
                        continue
                    for dependency_index in claims_by_name.get(
                        dependency_name,
                        (),
                    ):
                        dependency_claim = canonical_plan.claims[dependency_index]
                        if (
                            str(dependency_claim.role or "").strip().lower()
                            == "root_assembly"
                        ):
                            continue
                        salvage_dependency_indices.add(dependency_index)
                        if dependency_name not in visited_salvage_names:
                            visited_salvage_names.add(dependency_name)
                            pending_salvage_names.append(dependency_name)
    changed = True
    while changed:
        changed = False
        for index, claim in enumerate(canonical_plan.claims):
            if index in tainted_indices:
                continue
            name = str(claim.name or "").strip()
            dependencies = {
                str(dependency or "").strip()
                for dependency in claim.dependencies
                if str(dependency or "").strip()
            }
            if name in tainted_names or dependencies & tainted_names:
                tainted_indices.add(index)
                if name:
                    tainted_names.add(name)
                changed = True

    promoted_indices: set[int] = {
        index for index in recognized_root_indices if index not in tainted_indices
    }
    promoted_indices.update(
        index for index in salvage_dependency_indices if index not in tainted_indices
    )
    pending = list(promoted_indices)
    while pending:
        index = pending.pop()
        for dependency in canonical_plan.claims[index].dependencies:
            for dependency_index in claims_by_name.get(
                str(dependency or "").strip(),
                (),
            ):
                if (
                    dependency_index not in promoted_indices
                    and dependency_index not in tainted_indices
                ):
                    promoted_indices.add(dependency_index)
                    pending.append(dependency_index)

    kept_indices = tuple(
        index
        for index, claim in enumerate(canonical_plan.claims)
        if (
            index not in tainted_indices
            and (
                not claim.source_arbitration_provisional
                or index in promoted_indices
                or index not in adjudication_complete_indices
            )
        )
    )
    promoted_names = tuple(
        str(canonical_plan.claims[index].name or "")
        for index in kept_indices
        if canonical_plan.claims[index].source_arbitration_provisional
        and index in promoted_indices
    )
    discarded_names = tuple(
        str(claim.name or "")
        for index, claim in enumerate(canonical_plan.claims)
        if index not in kept_indices
    )

    def relation_fields_for_index(
        index: int,
        claim: MiniSubgoalClaim,
    ) -> dict[str, str]:
        if index in route_relation_by_index:
            return {
                "contract_route_relation_kind": (route_relation_by_index[index][0]),
                "contract_route_relation_anchor_identity": (
                    route_relation_by_index[index][1]
                ),
                "contract_route_relation_evidence_receipt": (
                    route_relation_by_index[index][2]
                ),
            }
        existing_kind = str(claim.contract_route_relation_kind or "").strip().lower()
        existing_anchor = str(
            claim.contract_route_relation_anchor_identity or ""
        ).strip()
        allowed_anchors = {
            identity for identity in anchor_identity_by_index.values() if identity
        }
        if (
            existing_kind in {"exact", "profile"}
            and existing_anchor
            and _bound_contract_route_relation_anchor(
                claim,
                allowed_anchor_identities=allowed_anchors,
            )
        ):
            matching_anchor_indices = {
                anchor_index
                for anchor_index, identity in anchor_identity_by_index.items()
                if identity == existing_anchor
            }
            checked_rows = (
                coverage.claim_defeq_checked_indices
                if existing_kind == "exact"
                else coverage.claim_contract_defeq_checked_indices
            )
            checked_indices = set(
                checked_rows[index] if index < len(checked_rows) else ()
            )
            if not (matching_anchor_indices & checked_indices):
                # No current verdict exists for this already-certified
                # relation. Preserve it through a truncated comparison batch;
                # only a completed negative may revoke durable evidence.
                return {
                    "contract_route_relation_kind": str(
                        claim.contract_route_relation_kind or ""
                    ),
                    "contract_route_relation_anchor_identity": existing_anchor,
                    "contract_route_relation_evidence_receipt": str(
                        claim.contract_route_relation_evidence_receipt or ""
                    ),
                }
        return {
            "contract_route_relation_kind": "",
            "contract_route_relation_anchor_identity": "",
            "contract_route_relation_evidence_receipt": "",
        }

    def rebuilt_plan(plan: MiniSubgoalPlan) -> MiniSubgoalPlan:
        return dataclass_replace(
            plan,
            claims=tuple(
                dataclass_replace(
                    plan.claims[index],
                    source_arbitration_provisional=bool(
                        plan.claims[index].source_arbitration_provisional
                        and index not in promoted_indices
                    ),
                    **relation_fields_for_index(index, plan.claims[index]),
                )
                for index in kept_indices
            ),
            notes=(
                *plan.notes,
                "planner_source_provisional_routes_lean_adjudicated",
                *(
                    ("planner_source_provisional_helper_closure_salvaged",)
                    if salvage_dependency_indices
                    else ()
                ),
            ),
        )

    index_map = {
        old_index: new_index for new_index, old_index in enumerate(kept_indices)
    }
    rebuilt_coverage = dataclass_replace(
        coverage,
        claim_elaborated=tuple(
            coverage.claim_elaborated[index]
            for index in kept_indices
            if index < len(coverage.claim_elaborated)
        ),
        claim_analysis_statements=tuple(
            coverage.claim_analysis_statements[index]
            for index in kept_indices
            if index < len(coverage.claim_analysis_statements)
        ),
        # Batch indices become stale as soon as claims are removed. Durable
        # root-route relation receipts above replace them; clear the transient
        # matrix rather than publishing a false remapped-index contract.
        claim_defeq_indices=(),
        claim_contract_defeq_indices=(),
        claim_defeq_checked_indices=(),
        claim_contract_defeq_checked_indices=(),
        per_claim_diagnostics={
            index_map[old_index]: diagnostic
            for old_index, diagnostic in coverage.per_claim_diagnostics.items()
            if old_index in index_map
        },
    )
    return (
        rebuilt_plan(original_plan),
        rebuilt_plan(canonical_plan),
        rebuilt_coverage,
        tuple(dict.fromkeys(promoted_names)),
        tuple(dict.fromkeys(discarded_names)),
    )


def _defer_unresolved_source_arbitration_claims(
    *,
    original_plan: MiniSubgoalPlan,
    canonical_plan: MiniSubgoalPlan,
    coverage: _ContractIdentityCoverage,
) -> tuple[
    MiniSubgoalPlan,
    MiniSubgoalPlan,
    _ContractIdentityCoverage,
    tuple[str, ...],
]:
    """Remove unresolved provisional DAGs from executable publication.

    A missing/partial Lean identity result is transient infrastructure state,
    not authority to promote or refute a route.  Such claims remain in the
    already-durable paid-plan receipt, but neither they nor their consumers may
    enter claim caps, ``plan_ready``, or resume scheduling. Claims with a
    concrete elaboration diagnostic are retained only long enough for the
    bounded statement-repair transaction; the mutated plan is then fully
    readjudicated before publication.
    """

    repairable_indices = {
        index
        for index, claim in enumerate(canonical_plan.claims)
        if claim.source_arbitration_provisional
        and index < len(coverage.claim_elaborated)
        and not coverage.claim_elaborated[index]
        and bool(str(coverage.per_claim_diagnostics.get(index, "") or "").strip())
    }
    blocked_names = {
        str(claim.name or "").strip()
        for index, claim in enumerate(canonical_plan.claims)
        if claim.source_arbitration_provisional
        and index not in repairable_indices
        and str(claim.name or "").strip()
    }
    if not blocked_names:
        return original_plan, canonical_plan, coverage, ()
    blocked_indices: set[int] = set()
    changed = True
    while changed:
        changed = False
        for index, claim in enumerate(canonical_plan.claims):
            if index in blocked_indices:
                continue
            name = str(claim.name or "").strip()
            dependencies = {
                str(dependency or "").strip()
                for dependency in claim.dependencies
                if str(dependency or "").strip()
            }
            if name in blocked_names or dependencies & blocked_names:
                blocked_indices.add(index)
                if name:
                    blocked_names.add(name)
                changed = True
    kept_indices = tuple(
        index
        for index in range(len(canonical_plan.claims))
        if index not in blocked_indices
    )

    def rebuild(plan: MiniSubgoalPlan) -> MiniSubgoalPlan:
        return dataclass_replace(
            plan,
            claims=tuple(plan.claims[index] for index in kept_indices),
            notes=(
                *plan.notes,
                "planner_source_provisional_routes_identity_pending",
            ),
        )

    index_map = {
        old_index: new_index for new_index, old_index in enumerate(kept_indices)
    }
    rebuilt_coverage = dataclass_replace(
        coverage,
        claim_elaborated=tuple(
            coverage.claim_elaborated[index]
            for index in kept_indices
            if index < len(coverage.claim_elaborated)
        ),
        claim_analysis_statements=tuple(
            coverage.claim_analysis_statements[index]
            for index in kept_indices
            if index < len(coverage.claim_analysis_statements)
        ),
        claim_defeq_indices=(),
        claim_contract_defeq_indices=(),
        claim_defeq_checked_indices=(),
        claim_contract_defeq_checked_indices=(),
        per_claim_diagnostics={
            index_map[old_index]: diagnostic
            for old_index, diagnostic in coverage.per_claim_diagnostics.items()
            if old_index in index_map
        },
    )
    return (
        rebuild(original_plan),
        rebuild(canonical_plan),
        rebuilt_coverage,
        tuple(
            str(canonical_plan.claims[index].name or "")
            for index in sorted(blocked_indices)
        ),
    )


_CONTRACT_IDENTITY_CANCEL_CLEANUP_S = 5.0


async def _await_contract_identity_operation(
    awaitable: Awaitable[Any],
    *,
    timeout_s: float,
) -> Any:
    """Apply a recoverable operation timeout with cleanup-only containment."""

    timeout = max(0.001, float(timeout_s or 0.001))
    cleanup_allowance = max(
        0.0,
        float(_CONTRACT_IDENTITY_CANCEL_CLEANUP_S or 0.0),
    )
    expires_at = time.monotonic() + timeout
    completed_at = 0.0

    async def tracked_operation() -> Any:
        nonlocal completed_at
        try:
            return await awaitable
        finally:
            completed_at = time.monotonic()

    task = asyncio.create_task(tracked_operation())

    async def cancel_and_settle(
        caller_cancellation: Optional[asyncio.CancelledError],
    ) -> Optional[asyncio.CancelledError]:
        task.cancel()
        cleanup_deadline = time.monotonic() + cleanup_allowance
        while not task.done():
            remaining = cleanup_deadline - time.monotonic()
            if remaining <= 0.0:
                break
            try:
                await asyncio.wait({task}, timeout=remaining)
            except asyncio.CancelledError as cancellation:
                caller_cancellation = caller_cancellation or cancellation
        if not task.done():
            # Contract analysis is result-only: after cancellation its late
            # result has no publication authority. Observe eventual settlement
            # without blocking this session or arming a process-kill lease.
            from .mini_session.session import (
                _observe_and_detach_operation_tail,
            )

            _observe_and_detach_operation_tail(task)
            return caller_cancellation
        try:
            task.result()
        except BaseException:
            # The operation result is outside its authority after cancellation.
            pass
        return caller_cancellation

    try:
        done, _pending = await asyncio.wait({task}, timeout=timeout)
    except asyncio.CancelledError as cancellation:
        cancellation = await cancel_and_settle(cancellation) or cancellation
        raise cancellation
    if task in done:
        if completed_at > expires_at:
            # A synchronous adapter can block the event loop beyond the local
            # allowance and return before the timer callback runs. Its task is
            # already settled, so discard the late result without escalating
            # to a process kill.
            try:
                task.result()
            except BaseException:
                pass
            raise asyncio.TimeoutError
        return task.result()
    caller_cancellation = await cancel_and_settle(None)
    if caller_cancellation is not None:
        raise caller_cancellation
    raise asyncio.TimeoutError


async def _canonicalize_dependency_contract_inputs(
    *,
    lean: Any,
    plan: MiniSubgoalPlan,
    support_statements: Sequence[str],
    preamble: str,
    timeout_s: float,
    pass_index: int,
    record_event: Optional[RecordEvent],
    declaration_context: Sequence[str] = (),
    analysis_statements: Sequence[str] = (),
    environment_hash: str = "",
) -> tuple[MiniSubgoalPlan, tuple[str, ...], _ContractIdentityCoverage]:
    """Use Lean declaration identity as the contract-analysis boundary."""

    analyzer = getattr(lean, "analyze_statement_contracts", None)
    canonicalizer = getattr(lean, "canonicalize_statement_types", None)
    use_structural_analysis = callable(analyzer)
    if not use_structural_analysis and not callable(canonicalizer):
        _record(
            record_event,
            {
                "phase": "mini_recursive_plan_dependency_contract_identity",
                "pass_index": pass_index,
                "verdict": "contract_identity_service_unavailable_surface_strict",
            },
        )
        return plan, tuple(support_statements), _ContractIdentityCoverage()
    claim_analysis_statements = tuple(
        _claim_contract_source_statement(claim) for claim in plan.claims
    )
    statements = (
        str(plan.root_statement or ""),
        *claim_analysis_statements,
        *(str(statement or "") for statement in support_statements),
        *(str(statement or "") for statement in analysis_statements),
    )
    started = time.monotonic()
    operation_timeout_s = max(1.0, float(timeout_s))
    runner_operation_telemetry: dict[str, Any] = {}

    def operation_telemetry(output_text: str = "") -> dict[str, Any]:
        operation_elapsed_s = max(0.0, time.monotonic() - started)
        rendered_output = str(output_text or "")
        output_lines = rendered_output.splitlines()
        return {
            "operation_elapsed_s": round(operation_elapsed_s, 6),
            "operation_deadline_s": operation_timeout_s,
            "operation_deadline_overrun_s": round(
                max(0.0, operation_elapsed_s - operation_timeout_s),
                6,
            ),
            "deadline_invariant_violated": operation_elapsed_s > operation_timeout_s,
            **runner_operation_telemetry,
            "output_bytes": len(rendered_output.encode("utf-8", errors="replace")),
            "output_max_line_bytes": max(
                (len(line.encode("utf-8", errors="replace")) for line in output_lines),
                default=0,
            ),
        }

    _record(
        record_event,
        {
            "phase": "mini_recursive_plan_dependency_contract_identity",
            "pass_index": pass_index,
            "requested": len(statements),
            "timeout_s": operation_timeout_s,
            **_contract_identity_runtime_provenance(lean),
            "verdict": "contract_identity_started",
        },
    )

    class _IdentityServiceTimeout(Exception):
        def __init__(self, cause: asyncio.TimeoutError) -> None:
            super().__init__(str(cause))
            self.cause = cause

    try:
        identity_operation = analyzer if use_structural_analysis else canonicalizer
        identity_kwargs: dict[str, Any] = {
            "preamble_override": "\n\n".join(
                part
                for part in (
                    str(preamble or "").strip(),
                    *(str(block or "").strip() for block in declaration_context),
                )
                if part
            ),
            "timeout_s": operation_timeout_s,
        }
        if (
            use_structural_analysis
            and _callable_accepts_keyword(
                identity_operation,
                "defeq_anchor_indices",
            )
            and _callable_accepts_keyword(
                identity_operation,
                "defeq_candidate_indices",
            )
        ):
            analysis_start_index = 1 + len(plan.claims) + len(support_statements)
            identity_kwargs.update(
                {
                    "defeq_anchor_indices": (
                        0,
                        *range(
                            analysis_start_index,
                            analysis_start_index + len(analysis_statements),
                        ),
                    ),
                    "defeq_candidate_indices": tuple(range(1, 1 + len(plan.claims))),
                }
            )

        async def invoke_identity_operation():
            try:
                return await identity_operation(
                    statements,
                    **identity_kwargs,
                )
            except asyncio.TimeoutError as exc:
                raise _IdentityServiceTimeout(exc) from exc

        analyzed, output, returncode = await _await_contract_identity_operation(
            invoke_identity_operation(),
            timeout_s=operation_timeout_s,
        )
        if use_structural_analysis and analyzed:
            try:
                candidate_telemetry = getattr(
                    analyzed[0],
                    "operation_telemetry",
                    {},
                )
            except Exception:
                candidate_telemetry = {}
            if isinstance(candidate_telemetry, Mapping):
                runner_operation_telemetry.update(
                    {
                        str(key): value
                        for key, value in candidate_telemetry.items()
                        if str(key).startswith("runner_")
                        and isinstance(value, (str, int, float, bool))
                    }
                )
        completion_telemetry = operation_telemetry(str(output or ""))
        if completion_telemetry["deadline_invariant_violated"]:
            infrastructure_error = (
                "contract identity result arrived after its "
                f"{operation_timeout_s:.3f}s publication deadline"
            )
            _record(
                record_event,
                {
                    "phase": "mini_recursive_plan_dependency_contract_identity",
                    "pass_index": pass_index,
                    **completion_telemetry,
                    "returncode": int(returncode or 0),
                    "error": infrastructure_error,
                    "verdict": "contract_identity_deadline_invariant_violated",
                },
            )
            return (
                plan,
                tuple(support_statements),
                _ContractIdentityCoverage(
                    service_available=True,
                    infrastructure_error=infrastructure_error,
                    returncode=1,
                ),
            )
    except _IdentityServiceTimeout as wrapped:
        exc = wrapped.cause
        _record(
            record_event,
            {
                "phase": "mini_recursive_plan_dependency_contract_identity",
                "pass_index": pass_index,
                "elapsed_s": round(time.monotonic() - started, 3),
                **operation_telemetry(),
                "error": f"{type(exc).__name__}: {exc}",
                "verdict": "contract_identity_infrastructure_unknown_retryable",
            },
        )
        return (
            plan,
            tuple(support_statements),
            _ContractIdentityCoverage(
                service_available=True,
                infrastructure_error=f"{type(exc).__name__}: {exc}",
            ),
        )
    except asyncio.TimeoutError:
        infrastructure_error = (
            "contract identity operation exceeded its "
            f"{operation_timeout_s:.3f}s wall-clock deadline"
        )
        _record(
            record_event,
            {
                "phase": "mini_recursive_plan_dependency_contract_identity",
                "pass_index": pass_index,
                "elapsed_s": round(time.monotonic() - started, 3),
                "timeout_s": operation_timeout_s,
                **operation_telemetry(),
                "error": infrastructure_error,
                "verdict": "contract_identity_infrastructure_unknown_retryable",
            },
        )
        return (
            plan,
            tuple(support_statements),
            _ContractIdentityCoverage(
                service_available=True,
                infrastructure_error=infrastructure_error,
                returncode=1,
            ),
        )
    except Exception as exc:
        _record(
            record_event,
            {
                "phase": "mini_recursive_plan_dependency_contract_identity",
                "pass_index": pass_index,
                "elapsed_s": round(time.monotonic() - started, 3),
                **operation_telemetry(),
                "error": f"{type(exc).__name__}: {exc}",
                "verdict": "contract_identity_infrastructure_unknown_retryable",
            },
        )
        return (
            plan,
            tuple(support_statements),
            _ContractIdentityCoverage(
                service_available=True,
                infrastructure_error=f"{type(exc).__name__}: {exc}",
            ),
        )
    normalized_returncode = int(returncode or 0)
    termination_signal = termination_signal_from_returncode(normalized_returncode)
    if termination_signal or (
        normalized_returncode != 0
        and (has_timeout(str(output or "")) or has_infra_failure(str(output or "")))
    ):
        infrastructure_error = (
            f"contract identity verifier terminated by signal {termination_signal}"
            if termination_signal
            else _compact_text(str(output or ""), 360)
            or (
                "contract identity verifier failed with returncode "
                f"{normalized_returncode}"
            )
        )
        _record(
            record_event,
            {
                "phase": "mini_recursive_plan_dependency_contract_identity",
                "pass_index": pass_index,
                "elapsed_s": round(time.monotonic() - started, 3),
                **operation_telemetry(str(output or "")),
                "returncode": normalized_returncode,
                "error": infrastructure_error,
                "verdict": "contract_identity_infrastructure_unknown_retryable",
            },
        )
        return (
            plan,
            tuple(support_statements),
            _ContractIdentityCoverage(
                service_available=True,
                infrastructure_error=infrastructure_error,
                returncode=normalized_returncode,
            ),
        )
    if use_structural_analysis:
        analysis_items = tuple(analyzed or ())
        rendered_items = tuple(
            str(getattr(item, "display_type", "") or "").strip()
            for item in analysis_items
        )
        structural_identities = tuple(
            str(getattr(item, "structural_identity", "") or "").strip()
            for item in analysis_items
        )
        binder_sorts = tuple(
            tuple(str(value or "") for value in getattr(item, "binder_sorts", ()) or ())
            for item in analysis_items
        )
        proof_binder_types = tuple(
            tuple(
                str(value or "")
                for value in getattr(item, "proof_binder_types", ()) or ()
            )
            for item in analysis_items
        )
        proof_binder_structural_hashes = tuple(
            tuple(
                str(value or "")
                for value in (
                    getattr(
                        item,
                        "proof_binder_structural_hashes",
                        (),
                    )
                    or ()
                )
            )
            for item in analysis_items
        )
        conclusion_structural_hashes = tuple(
            str(
                getattr(
                    item,
                    "contract_conclusion_structural_hash",
                    "",
                )
                or ""
            ).strip()
            for item in analysis_items
        )
        definitionally_equal_indices = tuple(
            tuple(
                int(value)
                for value in (getattr(item, "definitionally_equal_indices", ()) or ())
            )
            for item in analysis_items
        )
        contract_definitionally_equal_indices = tuple(
            tuple(
                int(value)
                for value in (
                    getattr(
                        item,
                        "contract_definitionally_equal_indices",
                        (),
                    )
                    or ()
                )
            )
            for item in analysis_items
        )
        definitionally_checked_indices = tuple(
            tuple(
                int(value)
                for value in (getattr(item, "definitionally_checked_indices", ()) or ())
            )
            for item in analysis_items
        )
        contract_definitionally_checked_indices = tuple(
            tuple(
                int(value)
                for value in (
                    getattr(
                        item,
                        "contract_definitionally_checked_indices",
                        (),
                    )
                    or ()
                )
            )
            for item in analysis_items
        )
        elaborated_items = tuple(
            bool(display or identity)
            for display, identity in zip(rendered_items, structural_identities)
        )
    else:
        rendered_items = tuple(str(item or "").strip() for item in analyzed or ())
        structural_identities = tuple("" for _ in rendered_items)
        binder_sorts = tuple(() for _ in rendered_items)
        proof_binder_types = tuple(() for _ in rendered_items)
        proof_binder_structural_hashes = tuple(() for _ in rendered_items)
        conclusion_structural_hashes = tuple("" for _ in rendered_items)
        definitionally_equal_indices = tuple(() for _ in rendered_items)
        contract_definitionally_equal_indices = tuple(() for _ in rendered_items)
        definitionally_checked_indices = tuple(() for _ in rendered_items)
        contract_definitionally_checked_indices = tuple(() for _ in rendered_items)
        elaborated_items = tuple(bool(item) for item in rendered_items)
    if len(rendered_items) != len(statements) or not elaborated_items[0]:
        _record(
            record_event,
            {
                "phase": "mini_recursive_plan_dependency_contract_identity",
                "pass_index": pass_index,
                "elapsed_s": round(time.monotonic() - started, 3),
                **operation_telemetry(str(output or "")),
                "returncode": int(returncode or 0),
                "canonicalized": sum(bool(item) for item in rendered_items),
                "requested": len(statements),
                "diagnostic_preview": _compact_text(str(output or ""), 360),
                "verdict": "contract_identity_root_unavailable_surface_strict",
            },
        )
        return (
            plan,
            tuple(support_statements),
            _ContractIdentityCoverage(
                service_available=True,
                returncode=int(returncode or 0),
            ),
        )
    claim_end = 1 + len(plan.claims)
    claim_elaborated = tuple(elaborated_items[index] for index in range(1, claim_end))
    claim_defeq_indices = tuple(
        definitionally_equal_indices[index] for index in range(1, claim_end)
    )
    claim_contract_defeq_indices = tuple(
        contract_definitionally_equal_indices[index] for index in range(1, claim_end)
    )
    claim_defeq_checked_indices = tuple(
        definitionally_checked_indices[index] for index in range(1, claim_end)
    )
    claim_contract_defeq_checked_indices = tuple(
        contract_definitionally_checked_indices[index] for index in range(1, claim_end)
    )
    support_elaborated = tuple(
        elaborated_items[claim_end + index] for index in range(len(support_statements))
    )
    support_structural_identities = tuple(
        str(structural_identities[claim_end + index] or "").strip()
        for index in range(len(support_statements))
    )
    analysis_start = claim_end + len(support_statements)
    analysis_elaborated = tuple(
        elaborated_items[analysis_start + index]
        for index in range(len(analysis_statements))
    )
    analysis_structural_identities = tuple(
        str(structural_identities[analysis_start + index] or "").strip()
        for index in range(len(analysis_statements))
    )
    canonical_claims: list[MiniSubgoalClaim] = []
    for index, claim in enumerate(plan.claims, start=1):
        identity = str(structural_identities[index] or "").strip()
        analyzed_statement = claim_analysis_statements[index - 1]
        statement_key = graph_statement_key(analyzed_statement) if identity else ""
        evidence_environment_hash = str(environment_hash or "").strip()
        canonical_claims.append(
            dataclass_replace(
                claim,
                contract_identity=identity,
                contract_identity_statement_key=statement_key,
                contract_identity_environment_hash=(
                    evidence_environment_hash if identity else ""
                ),
                contract_identity_evidence_receipt=(
                    make_lean_contract_evidence_receipt(
                        identity,
                        statement_key,
                        evidence_environment_hash,
                    )
                    if identity and statement_key
                    else ""
                ),
                contract_display_statement=rendered_items[index],
                contract_binder_sorts=binder_sorts[index],
                contract_proof_binder_types=proof_binder_types[index],
                contract_proof_binder_structural_hashes=(
                    proof_binder_structural_hashes[index]
                ),
                contract_conclusion_structural_hash=(
                    conclusion_structural_hashes[index]
                ),
                contract_telescope_evidence_receipt=(
                    make_lean_contract_telescope_evidence_receipt(
                        identity,
                        statement_key,
                        evidence_environment_hash,
                        proof_binder_structural_hashes[index],
                        conclusion_structural_hashes[index],
                        binder_sorts=binder_sorts[index],
                        proof_binder_types=proof_binder_types[index],
                    )
                    if identity and statement_key
                    else ""
                ),
            )
        )
    # Support declarations obey the same source/identity separation. This
    # tuple is an analysis-only view; the dossier retains original executable
    # helper sources.
    canonical_support = tuple(
        rendered_items[claim_end + index] or str(statement or "")
        for index, statement in enumerate(support_statements)
    )
    root_identity = str(structural_identities[0] or "").strip()
    root_statement_key = (
        graph_statement_key(plan.root_statement) if root_identity else ""
    )
    evidence_environment_hash = str(environment_hash or "").strip()
    canonical_plan = dataclass_replace(
        plan,
        claims=tuple(canonical_claims),
        strategy=plan.strategy,
        notes=plan.notes,
        raw_response=plan.raw_response,
        answer_safe_preamble_used=plan.answer_safe_preamble_used,
        root_contract_identity=root_identity,
        root_contract_identity_statement_key=root_statement_key,
        root_contract_identity_environment_hash=(
            evidence_environment_hash if root_identity else ""
        ),
        root_contract_identity_evidence_receipt=(
            make_lean_contract_evidence_receipt(
                root_identity,
                root_statement_key,
                evidence_environment_hash,
            )
            if root_identity and root_statement_key
            else ""
        ),
        root_contract_display_statement=rendered_items[0],
        root_contract_binder_sorts=binder_sorts[0],
        root_contract_proof_binder_types=proof_binder_types[0],
        root_contract_proof_binder_structural_hashes=(
            proof_binder_structural_hashes[0]
        ),
        root_contract_conclusion_structural_hash=(conclusion_structural_hashes[0]),
        root_contract_telescope_evidence_receipt=(
            make_lean_contract_telescope_evidence_receipt(
                root_identity,
                root_statement_key,
                evidence_environment_hash,
                proof_binder_structural_hashes[0],
                conclusion_structural_hashes[0],
                binder_sorts=binder_sorts[0],
                proof_binder_types=proof_binder_types[0],
            )
            if root_identity and root_statement_key
            else ""
        ),
    )
    _record(
        record_event,
        {
            "phase": "mini_recursive_plan_dependency_contract_identity",
            "pass_index": pass_index,
            "elapsed_s": round(time.monotonic() - started, 3),
            **operation_telemetry(str(output or "")),
            "returncode": int(returncode or 0),
            "canonicalized": sum(elaborated_items),
            "structural_identities": sum(bool(item) for item in structural_identities),
            "requested": len(statements),
            "claim_failures": sum(not item for item in claim_elaborated),
            "support_failures": sum(not item for item in support_elaborated),
            "failed_claim_indices": [
                index for index, ok in enumerate(claim_elaborated) if not ok
            ],
            "failed_support_indices": [
                index for index, ok in enumerate(support_elaborated) if not ok
            ],
            "diagnostic_preview": (
                _compact_text(str(output or ""), 360)
                if not all(claim_elaborated) or not all(support_elaborated)
                else ""
            ),
            "verdict": (
                "contract_identity_elaborated"
                if all(claim_elaborated) and all(support_elaborated)
                else "contract_identity_partially_elaborated"
            ),
        },
    )
    return (
        canonical_plan,
        canonical_support,
        _ContractIdentityCoverage(
            service_available=True,
            root_elaborated=True,
            claim_elaborated=claim_elaborated,
            claim_analysis_statements=claim_analysis_statements,
            support_elaborated=support_elaborated,
            support_structural_identities=support_structural_identities,
            support_proof_binder_structural_hashes=tuple(
                proof_binder_structural_hashes[claim_end + index]
                for index in range(len(support_statements))
            ),
            support_conclusion_structural_hashes=tuple(
                conclusion_structural_hashes[claim_end + index]
                for index in range(len(support_statements))
            ),
            analysis_batch_start=analysis_start,
            analysis_elaborated=analysis_elaborated,
            analysis_structural_identities=analysis_structural_identities,
            claim_defeq_indices=claim_defeq_indices,
            claim_contract_defeq_indices=(claim_contract_defeq_indices),
            claim_defeq_checked_indices=claim_defeq_checked_indices,
            claim_contract_defeq_checked_indices=(claim_contract_defeq_checked_indices),
            returncode=int(returncode or 0),
            elaboration_diagnostics=(
                _compact_lean_elaboration_diagnostics(str(output or ""))
                if not (all(claim_elaborated) and all(support_elaborated))
                else ""
            ),
            per_claim_diagnostics=(
                _contract_identity_diagnostics_by_claim(str(output or ""))
                if not all(claim_elaborated)
                else {}
            ),
        ),
    )


def _adjudicate_and_defer_contract_plan(
    *,
    original_plan: MiniSubgoalPlan,
    canonical_plan: MiniSubgoalPlan,
    coverage: _ContractIdentityCoverage,
    active_target_statements: Sequence[str] = (),
    active_target_contract_identities: Sequence[str] = (),
) -> tuple[
    MiniSubgoalPlan,
    MiniSubgoalPlan,
    _ContractIdentityCoverage,
    tuple[str, ...],
    tuple[str, ...],
    tuple[str, ...],
]:
    """Complete the mandatory post-elaboration contract transaction.

    Canonicalization deliberately invalidates every prior route-relation
    receipt.  Therefore every caller—including statement repair, root
    substitution, replan, and suspension rehydration—must immediately run
    same-batch Lean relation adjudication and typed deferral before any route
    classifier or dependency filter consumes the plan.
    """

    promoted: tuple[str, ...] = ()
    discarded: tuple[str, ...] = ()
    if coverage.usable:
        (
            original_plan,
            canonical_plan,
            coverage,
            promoted,
            discarded,
        ) = _adjudicate_source_arbitration_provisional_claims(
            original_plan=original_plan,
            canonical_plan=canonical_plan,
            coverage=coverage,
            active_target_statements=active_target_statements,
            active_target_contract_identities=(active_target_contract_identities),
        )
    (
        original_plan,
        canonical_plan,
        coverage,
        pending,
    ) = _defer_unresolved_source_arbitration_claims(
        original_plan=original_plan,
        canonical_plan=canonical_plan,
        coverage=coverage,
    )
    return (
        original_plan,
        canonical_plan,
        coverage,
        promoted,
        discarded,
        pending,
    )


_CONTRACT_IDENTITY_PROBE_NAME_RE = re.compile(r"mini_contract_identity_[0-9a-f]+_\d+")
_CONTRACT_IDENTITY_ATTRIBUTED_DIAGNOSTIC_RE = re.compile(
    r"^MINI_CONTRACT_DIAGNOSTIC_(\d+):\s*(.*)$"
)
_LEAN_DIAGNOSTIC_NOISE_RE = re.compile(
    r"^(Additional diagnostic information|Note:|Hint:|info:|trace:|"
    r"Some diagnostics)",
    re.IGNORECASE,
)


def _compact_lean_elaboration_diagnostics(output: str, *, limit: int = 500) -> str:
    """Distil the salient Lean error messages from a canonicalize run.

    Keeps the ``error:``/``unknown``/``failed to synthesize``/``type mismatch``
    lines (plus one indented continuation each) so the planner sees the concrete
    defect, while dropping file-path noise and the internal probe declaration
    names (``mini_contract_identity_<nonce>_<i>``).
    """

    lines = str(output or "").splitlines()
    snippets: list[str] = []
    keep_next = 0
    for raw in lines:
        if raw.lstrip().startswith("MINI_CONTRACT_ANALYSIS_"):
            continue
        line = _CONTRACT_IDENTITY_PROBE_NAME_RE.sub("<claim>", raw).rstrip()
        # Preserve ordinary Lean identifiers as actionable repair evidence
        # without exposing arbitrary model-controlled quoted names. Unsafe
        # guillemet/backtick payloads still flow through the prompt sanitizer.
        line = re.sub(
            r"`([A-Za-z_][A-Za-z0-9_'.]*)`",
            r"\1",
            line,
        )
        stripped = line.strip()
        if not stripped or _LEAN_DIAGNOSTIC_NOISE_RE.search(stripped):
            keep_next = 0
            continue
        marker = re.search(
            r"\b(error|unknown identifier|unknown constant|failed to synthesize|"
            r"type mismatch|unexpected token|unsolved goals|"
            r"function expected|not a proposition|unresolved metavariables)\b",
            stripped,
            re.IGNORECASE,
        )
        if marker:
            # Strip the "<path>:line:col: error:" prefix, keep from the message.
            message = (
                re.sub(r"^.*?\berror:\s*", "", stripped)
                if "error" in marker.group(0).lower()
                else stripped
            )
            snippet = message.strip() or stripped
            if snippet not in snippets:
                snippets.append(snippet)
            keep_next = 6
        elif keep_next > 0:
            # Continuation: the offending term, its actual type, expected type.
            if snippets and stripped not in snippets[-1]:
                snippets[-1] = f"{snippets[-1]} {stripped}"
            keep_next -= 1
    joined = "; ".join(snippets)
    return _compact_text(joined, limit)


def _contract_identity_diagnostics_by_claim(output: str) -> dict[int, str]:
    """Extract claim-local diagnostics from one batched identity probe."""

    by_statement: dict[int, list[str]] = {}
    legacy_header_re = re.compile(
        r"mini_contract_identity_[0-9a-f]+_(\d+)"
        r"\.lean:\d+:\d+:\s+error:\s*(.*)$"
    )
    active_index: Optional[int] = None
    active_lines: list[str] = []

    def flush() -> None:
        nonlocal active_index, active_lines
        if active_index is not None and active_index > 0:
            diagnostic = _compact_lean_elaboration_diagnostics(
                "\n".join(active_lines),
                limit=320,
            )
            if diagnostic:
                by_statement.setdefault(active_index - 1, []).append(diagnostic)
        active_index = None
        active_lines = []

    # Line parsing is deliberately bounded.  Production analysis output can
    # contain many megabytes of one-line Expr JSON; the former multiline
    # compatibility regex repeatedly backtracked through those marker lines
    # and added another ~20 minutes after each already-slow partial batch.
    for line in str(output or "").splitlines():
        attributed = _CONTRACT_IDENTITY_ATTRIBUTED_DIAGNOSTIC_RE.match(line)
        legacy = legacy_header_re.search(line[:8192])
        if attributed is not None:
            flush()
            active_index = int(attributed.group(1))
            active_lines = [attributed.group(2)]
            continue
        if legacy is not None:
            flush()
            active_index = int(legacy.group(1))
            active_lines = [f"error: {legacy.group(2)}"]
            continue
        if line.lstrip().startswith("MINI_CONTRACT_ANALYSIS_"):
            flush()
            continue
        if active_index is not None:
            active_lines.append(line)
    flush()
    return {
        index: _compact_text("; ".join(dict.fromkeys(items)), 320)
        for index, items in by_statement.items()
        if items
    }


def _claim_with_recompiled_statement(
    claim: MiniSubgoalClaim,
    statement: str,
    *,
    root_statement: str,
    repaired: bool = False,
    root_substituted: bool = False,
) -> MiniSubgoalClaim:
    """Replace executable source and keep its compiled variants coherent.

    Every evidence field is cleared together.  Callers immediately re-run the
    contract analyzer, which is the only authority allowed to bind evidence to
    the newly compiled source.
    """

    normalized = normalize_subgoal_statement(str(statement or "").strip())
    source = normalized or str(statement or "").strip()
    transformed = dataclass_replace(
        claim,
        statement=source,
        variants=tuple(
            build_subgoal_variants(
                source,
                root_statement=root_statement,
                max_variants=4,
            )
        ),
        contract_identity="",
        contract_identity_statement_key="",
        contract_identity_environment_hash="",
        contract_identity_evidence_receipt="",
        contract_route_relation_kind="",
        contract_route_relation_anchor_identity="",
        contract_route_relation_evidence_receipt="",
        contract_display_statement="",
        contract_binder_sorts=(),
        contract_proof_binder_types=(),
        contract_proof_binder_structural_hashes=(),
        contract_conclusion_structural_hash="",
        contract_telescope_evidence_receipt="",
        contract_identity_repaired=bool(repaired or claim.contract_identity_repaired),
        root_assembly_statement_substituted=bool(
            root_substituted or claim.root_assembly_statement_substituted
        ),
    )
    return dataclass_replace(
        transformed,
        planner_transformation_receipt_id=(
            _planner_claim_transformation_receipt_id(transformed)
        ),
    )


def _contract_statement_repair_content(raw: Any) -> str:
    response = _planner_raw_response(raw)
    content = str(response.content or "").strip()
    fence = re.search(r"```(?:lean)?\s*(.*?)```", content, re.DOTALL | re.IGNORECASE)
    if fence:
        content = str(fence.group(1) or "").strip()
    # This lane accepts one proposition only. Obvious prose/multi-command
    # replies are left for Lean to reject rather than heuristically rewritten.
    return content[:4000].strip()


async def _repair_contract_identity_statements(
    *,
    plan: MiniSubgoalPlan,
    coverage: _ContractIdentityCoverage,
    client: Any,
    cost_controller: Any,
    pass_index: int,
    stats: MiniRecursiveStats,
    record_event: Optional[RecordEvent],
    operation_timeout_s: float,
    max_repairs: int = 4,
    max_empty_retries: int = 2,
    suppress_solution_placeholders: Optional[bool] = None,
    opaque_mode: bool = True,
    allow_official_answer_visibility: bool = False,
    official_answer_payload_present: Optional[bool] = None,
    completed_repair_indices: AbstractSet[int] = frozenset(),
    completed_repair_attempts: int = 0,
    repair_retry_counts: Optional[Mapping[str, int]] = None,
    progress_callback: Optional[
        Callable[
            [MiniSubgoalPlan, Sequence[int], int, Mapping[str, int]],
            Awaitable[None],
        ]
    ] = None,
) -> MiniSubgoalPlan:
    """Make bounded, cost-metered statement repairs for failed claims."""

    repaired_claims = list(plan.claims)
    attempts = max(
        len(completed_repair_indices),
        max(0, int(completed_repair_attempts or 0)),
    )
    completed_indices = set(int(index) for index in completed_repair_indices)
    repair_indices = [
        index
        for index, elaborated in enumerate(coverage.claim_elaborated)
        if not elaborated
        and index not in completed_indices
        and index < len(repaired_claims)
    ]
    aggregate_repair_budget = max(0, int(max_repairs or 0))
    empty_retry_budget = max(0, int(max_empty_retries or 0))
    # A reasoning model can successfully consume a response budget while
    # returning no visible proposition. Keep those claims in a FIFO retry lane
    # behind all as-yet-unattempted failed claims. The aggregate cap remains
    # authoritative: large bad plans must not turn contract repair into 20
    # sequential minute-long calls.
    root_route_names = set(
        _root_route_dependency_names(
            plan.claims,
            root_statement=plan.root_statement,
        )
    )
    claims_by_name = {
        str(claim.name or "").strip(): claim
        for claim in plan.claims
        if str(claim.name or "").strip()
    }
    declared_root_pending = [
        str(dependency or "").strip()
        for claim in plan.claims
        if str(claim.role or "").strip().lower() == "root_assembly"
        for dependency in tuple(claim.dependencies or ())
        if str(dependency or "").strip()
    ]
    while declared_root_pending:
        dependency_name = declared_root_pending.pop()
        if dependency_name in root_route_names:
            continue
        dependency_claim = claims_by_name.get(dependency_name)
        if dependency_claim is None:
            continue
        root_route_names.add(dependency_name)
        declared_root_pending.extend(
            str(dependency or "").strip()
            for dependency in tuple(dependency_claim.dependencies or ())
            if str(dependency or "").strip()
        )
    repair_indices.sort(
        key=lambda index: (
            not (
                str(repaired_claims[index].name or "").strip() in root_route_names
                or _is_assembly_like_claim(
                    repaired_claims[index],
                    root_statement=plan.root_statement,
                )
                or str(repaired_claims[index].role or "").strip().lower()
                == "root_assembly"
            ),
            index,
        )
    )
    repair_key_by_index = {
        index: _dependency_contract_suspension_key(repaired_claims[index])
        for index in repair_indices
    }
    valid_repair_keys = set(repair_key_by_index.values())
    retry_counts: dict[str, int] = {
        str(key): max(0, int(value or 0))
        for key, value in dict(repair_retry_counts or {}).items()
        if str(key or "") in valid_repair_keys and max(0, int(value or 0)) > 0
    }
    # Retry phase belongs to the obligation that produced the empty response.
    # Aggregate attempts are only a global budget counter: inferring retry debt
    # from ``attempts - completed`` makes the next unfinished claim inherit a
    # previous claim's visible-output retry phase after checkpoint/resume.
    resumed_retry_indices = {
        index
        for index in repair_indices
        if retry_counts.get(repair_key_by_index[index], 0) > 0
    }
    pending_indices = [
        (index, False) for index in repair_indices if index not in resumed_retry_indices
    ]
    pending_indices.extend(
        (index, True) for index in repair_indices if index in resumed_retry_indices
    )
    empty_retries_used = 0
    initially_attempted_indices: set[int] = set(resumed_retry_indices)
    empty_response_telemetry: dict[int, dict[str, Any]] = {}
    redact_solution_refs = effective_solution_placeholder_suppression(
        suppress_solution_placeholders=suppress_solution_placeholders,
        opaque_mode=opaque_mode,
        allow_official_answer_visibility=allow_official_answer_visibility,
        official_answer_payload_present=official_answer_payload_present,
    )
    while pending_indices and attempts < aggregate_repair_budget:
        index, empty_retry = pending_indices.pop(0)
        if empty_retry:
            empty_retries_used += 1
        else:
            initially_attempted_indices.add(index)
        diagnostic = str(coverage.per_claim_diagnostics.get(index, "")).strip()
        if not diagnostic:
            continue
        claim = repaired_claims[index]
        analyzed_statement = (
            coverage.claim_analysis_statements[index]
            if index < len(coverage.claim_analysis_statements)
            else _claim_contract_source_statement(claim)
        )
        attempts += 1
        stats.contract_identity_statement_repairs_attempted += 1
        prompt_safe_diagnostic = _prompt_safe_lean_diagnostic_text(
            diagnostic,
            limit=1800,
            redact_solution_refs=redact_solution_refs,
            preserve_line_breaks=True,
        )
        messages = [
            {
                "role": "system",
                "content": (
                    "Repair one Lean proposition's type syntax. Return ONLY the "
                    "corrected bare proposition: no declaration, proof, markdown, "
                    "or explanation. Preserve its mathematical meaning and binders. "
                    "Never add assumptions. Never pass implicit/instance arguments "
                    "explicitly; for example use Function.Injective f."
                ),
            },
            {
                "role": "user",
                "content": (
                    f"Original proposition:\n{analyzed_statement}\n\n"
                    f"Lean diagnostic:\n{prompt_safe_diagnostic}\n\n"
                    "Return the minimally corrected Lean proposition."
                ),
            },
        ]
        call_completed = False
        repair_response = _PlannerRawResponse()
        try:
            repair_timeout_s = max(1.0, float(operation_timeout_s or 1.0))
            raw = await _await_with_hard_timeout(
                metered_or_plain_call(
                    cost_controller=cost_controller,
                    client=client,
                    messages=messages,
                    role="planner",
                    scope="mini_recursive",
                    action_id=(f"mini_contract_identity_repair_{pass_index}_{index}"),
                    call_kind="chat_contract_identity_statement_repair",
                    max_tokens_override=512,
                    metadata={
                        "temperature": 0.0,
                        "phase": "contract_identity_statement_repair",
                        "claim_index": index,
                    },
                    invoke=lambda usage_callback, repair_messages=messages: (
                        call_with_optional_usage_callback(
                            client.chat_raw,
                            repair_messages,
                            required_keywords=(
                                "max_tokens_override",
                                "reasoning_effort_override",
                                "operation_timeout_override_s",
                            ),
                            temperature_override=0.0,
                            max_tokens_override=512,
                            reasoning_effort_override=(
                                mini_bounded_visible_output_reasoning_effort(
                                    client,
                                    effort=("none" if empty_retry else "low"),
                                )
                            ),
                            operation_timeout_override_s=repair_timeout_s,
                            usage_callback=usage_callback,
                        )
                    ),
                ),
                timeout=repair_timeout_s,
            )
            call_completed = True
            repair_response = _planner_raw_response(raw)
            candidate = _contract_statement_repair_content(raw)
        except Exception as exc:
            candidate = ""
            _record(
                record_event,
                {
                    "phase": "mini_recursive_plan_dependency_contract_identity",
                    "pass_index": pass_index,
                    "claim_name": claim.name,
                    "claim_index": index,
                    "error": f"{type(exc).__name__}: {exc}",
                    "verdict": "contract_identity_statement_repair_call_failed",
                },
            )
        if not candidate:
            if not call_completed:
                if progress_callback is not None:
                    await progress_callback(
                        dataclass_replace(plan, claims=tuple(repaired_claims)),
                        tuple(sorted(completed_indices)),
                        attempts,
                        dict(retry_counts),
                    )
                continue
            empty_response_telemetry[index] = {
                "visible_content_chars": len(repair_response.content),
                "reasoning_content_chars": len(repair_response.reasoning_content),
                "finish_reason": repair_response.finish_reason,
            }
            repair_key = repair_key_by_index[index]
            retry_available = bool(
                retry_counts.get(repair_key, 0) < empty_retry_budget
                and attempts < aggregate_repair_budget
            )
            if retry_available:
                pending_indices.append((index, True))
                retry_counts[repair_key] = retry_counts.get(repair_key, 0) + 1
            _record(
                record_event,
                {
                    "phase": "mini_recursive_plan_dependency_contract_identity",
                    "pass_index": pass_index,
                    "claim_name": claim.name,
                    "claim_index": index,
                    "attempts_used": attempts,
                    "empty_retry": bool(empty_retry),
                    "empty_retries_used": empty_retries_used,
                    "empty_retry_budget": empty_retry_budget,
                    **empty_response_telemetry[index],
                    "verdict": (
                        "contract_identity_statement_repair_empty_response_retry_queued"
                        if retry_available
                        else "contract_identity_statement_repair_empty_response_exhausted"
                    ),
                },
            )
            if not retry_available:
                completed_indices.add(index)
                retry_counts.pop(repair_key_by_index[index], None)
            if progress_callback is not None:
                await progress_callback(
                    dataclass_replace(plan, claims=tuple(repaired_claims)),
                    tuple(sorted(completed_indices)),
                    attempts,
                    dict(retry_counts),
                )
            continue
        normalized_candidate = (
            normalize_subgoal_statement(candidate) or candidate.strip()
        )
        normalized_analyzed = (
            normalize_subgoal_statement(analyzed_statement)
            or analyzed_statement.strip()
        )
        if normalized_candidate == normalized_analyzed:
            _record(
                record_event,
                {
                    "phase": "mini_recursive_plan_dependency_contract_identity",
                    "pass_index": pass_index,
                    "claim_name": claim.name,
                    "claim_index": index,
                    "verdict": "contract_identity_statement_repair_no_change",
                },
            )
            completed_indices.add(index)
            retry_counts.pop(repair_key_by_index[index], None)
            if progress_callback is not None:
                await progress_callback(
                    dataclass_replace(plan, claims=tuple(repaired_claims)),
                    tuple(sorted(completed_indices)),
                    attempts,
                    dict(retry_counts),
                )
            continue
        if is_answer_unsafe_statement_text(
            candidate,
            suppress_solution_placeholders=suppress_solution_placeholders,
            opaque_mode=opaque_mode,
            allow_official_answer_visibility=allow_official_answer_visibility,
            official_answer_payload_present=official_answer_payload_present,
        ):
            _record(
                record_event,
                {
                    "phase": "mini_recursive_plan_answer_safety",
                    "pass_index": pass_index,
                    "claim_name": claim.name,
                    "claim_index": index,
                    "verdict": (
                        "contract_identity_statement_repair_answer_unsafe_rejected"
                    ),
                },
            )
            completed_indices.add(index)
            retry_counts.pop(repair_key_by_index[index], None)
            if progress_callback is not None:
                await progress_callback(
                    dataclass_replace(plan, claims=tuple(repaired_claims)),
                    tuple(sorted(completed_indices)),
                    attempts,
                    dict(retry_counts),
                )
            continue
        repaired_claims[index] = _claim_with_recompiled_statement(
            claim,
            candidate,
            root_statement=plan.root_statement,
            repaired=True,
        )
        _record(
            record_event,
            {
                "phase": "mini_recursive_plan_dependency_contract_identity",
                "pass_index": pass_index,
                "claim_name": claim.name,
                "claim_index": index,
                "original_statement": claim.statement,
                "repaired_statement": candidate,
                "verdict": "contract_identity_statement_repair_proposed",
            },
        )
        completed_indices.add(index)
        retry_counts.pop(repair_key_by_index[index], None)
        if progress_callback is not None:
            await progress_callback(
                dataclass_replace(plan, claims=tuple(repaired_claims)),
                tuple(sorted(completed_indices)),
                attempts,
                dict(retry_counts),
            )
    pending_empty_indices = {
        index for index, empty_retry in pending_indices if empty_retry
    }
    for index in sorted(pending_empty_indices):
        if index in completed_indices:
            continue
        claim = repaired_claims[index]
        _record(
            record_event,
            {
                "phase": "mini_recursive_plan_dependency_contract_identity",
                "pass_index": pass_index,
                "claim_name": claim.name,
                "claim_index": index,
                "attempts_used": attempts,
                "empty_retries_used": empty_retries_used,
                "empty_retry_budget": empty_retry_budget,
                "aggregate_repair_budget": aggregate_repair_budget,
                **empty_response_telemetry.get(index, {}),
                "verdict": (
                    "contract_identity_statement_repair_empty_response_exhausted"
                ),
            },
        )
        completed_indices.add(index)
        retry_counts.pop(repair_key_by_index[index], None)
        if progress_callback is not None:
            await progress_callback(
                dataclass_replace(plan, claims=tuple(repaired_claims)),
                tuple(sorted(completed_indices)),
                attempts,
                dict(retry_counts),
            )
    skipped_indices = [
        index for index in repair_indices if index not in initially_attempted_indices
    ]
    if skipped_indices:
        _record(
            record_event,
            {
                "phase": "mini_recursive_plan_dependency_contract_identity",
                "pass_index": pass_index,
                "max_repairs": aggregate_repair_budget,
                "attempts_used": attempts,
                "skipped_claim_indices": skipped_indices,
                "skipped_claim_names": [
                    repaired_claims[index].name for index in skipped_indices
                ],
                "verdict": "contract_identity_statement_repair_cap_exhausted",
            },
        )
    return dataclass_replace(plan, claims=tuple(repaired_claims))


def _filter_plan_contract_identity_failures(
    plan: MiniSubgoalPlan,
    *,
    claim_elaborated: Sequence[bool],
    pass_index: int,
    record_event: Optional[RecordEvent],
    stats: MiniRecursiveStats,
    planner_feedback: list[str],
    elaboration_diagnostics: str = "",
    per_claim_diagnostics: Optional[Mapping[int, str]] = None,
) -> MiniSubgoalPlan:
    """Reject claims Lean could not elaborate before semantic matching."""

    failed = {
        index: "statement did not elaborate as one Lean type"
        for index, ok in enumerate(claim_elaborated)
        if not ok and index < len(plan.claims)
    }
    if not failed:
        return plan
    dependency_reasons = _fixed_point_plan_dependency_rejections(
        plan,
        failed,
        dependency_reason=lambda tainted: (
            f"depends on contract-identity-unelaborated claim(s): {', '.join(tainted)}"
        ),
    )
    kept: list[MiniSubgoalClaim] = []
    elaboration_failed_names: list[str] = []
    tainted_names: list[str] = []
    for index, claim in enumerate(plan.claims):
        if index not in failed and index not in dependency_reasons:
            kept.append(claim)
            continue
        if index in failed:
            reason = failed[index]
            tainted: tuple[str, ...] = ()
            verdict = "claim_rejected_contract_identity_elaboration"
            elaboration_failed_names.append(
                str(claim.name or "").strip() or f"#{index}"
            )
        else:
            reason, tainted = dependency_reasons[index]
            verdict = "claim_rejected_contract_identity_tainted_dependency"
            tainted_names.append(str(claim.name or "").strip() or f"#{index}")
        stats.plans_contract_identity_elaboration_rejected += 1
        _record(
            record_event,
            {
                "phase": "mini_recursive_plan_dependency_contract_identity",
                "pass_index": pass_index,
                "claim_name": claim.name,
                "dependencies": list(claim.dependencies),
                "tainted_dependencies": list(tainted),
                "reason": reason,
                "elaboration_diagnostic": (
                    str((per_claim_diagnostics or {}).get(index, "") or "")
                    if index in failed
                    else ""
                ),
                "verdict": verdict,
            },
        )

    # One consolidated, ACTIONABLE feedback entry for the elaboration failures.
    # Claim NAMES are stripped by the answer-safe feedback sanitizer (backtick
    # spans -> code_hidden_<hash>), so naming them is useless — instead we lead
    # with the type-coherence guidance (which always survives the 700-char cap)
    # and append the concrete Lean errors, whose identifiers survive intact and
    # let the planner locate the offending claim itself. A tainted claim only
    # depends on a rejected one, so fixing the root cause repairs it too.
    if elaboration_failed_names:
        count = len(elaboration_failed_names)
        claim_local = "; ".join(
            str((per_claim_diagnostics or {}).get(index, "") or "").strip()
            for index in sorted(failed)
            if str((per_claim_diagnostics or {}).get(index, "") or "").strip()
        )
        diagnostics = _compact_text(
            claim_local or str(elaboration_diagnostics or "").strip(),
            240,
        )
        message = (
            f"Lean could NOT elaborate {count} of your claim statements as closed "
            "Mathlib propositions, so they (and anything depending on them) were "
            "dropped — an ill-typed claim has no goal to prove."
        )
        if diagnostics:
            message += f" Lean reported: {diagnostics}"
        message += (
            " Rewrite each so it "
            "elaborates. Never pass implicit or instance arguments explicitly: "
            "write Function.Injective f, NOT Injective (Fin 5) Int f. Use ℤ "
            "or ℝ (never ℕ) wherever you need subtraction, "
            "negation, absolute value, or division that can be negative or "
            "fractional; cast Fin/ℕ values explicitly, e.g. ((i : ℕ) : ℤ), before "
            "arithmetic; and reference ONLY declarations that exist in Mathlib — "
            "if you need a new notion, introduce it as its own def/abbrev claim "
            "that later claims depend on, never an invented identifier."
        )
        _add_planner_feedback(planner_feedback, message)
    elif tainted_names:
        _add_planner_feedback(
            planner_feedback,
            f"{len(tainted_names)} claim(s) were dropped because they depend on a "
            "claim Lean could not elaborate. Repair the prerequisite claim's types "
            "(or inline it) so the dependent claims and the root assembly survive.",
        )

    return dataclass_replace(plan, claims=tuple(kept))


def _structural_support_hash_closure(
    plan: MiniSubgoalPlan,
    *,
    support_structural_identities: Sequence[str] = (),
    support_proof_binder_structural_hashes: Sequence[Sequence[str]] = (),
    support_conclusion_structural_hashes: Sequence[str] = (),
    proved_claims: Sequence[MiniSubgoalClaim] = (),
) -> frozenset[str]:
    """Lean-evidence closure for closed proof-only support sequents."""

    root_premise_hashes, _root_conclusion_hash = (
        _bound_root_contract_telescope_evidence(plan)
    )
    available: set[str] = {
        str(value or "").strip()
        for value in root_premise_hashes
        if re.fullmatch(r"[0-9a-f]{64}", str(value or "").strip())
    }
    rules: list[tuple[tuple[str, ...], str]] = []
    for index, identity in enumerate(support_structural_identities):
        parsed = parse_lean_contract_identity(str(identity or ""))
        if parsed is not None:
            # A verified theorem always supplies its complete proposition.
            available.add(parsed[0])
        premise_row_present = index < len(support_proof_binder_structural_hashes)
        raw_premises = tuple(
            str(value or "").strip()
            for value in (
                support_proof_binder_structural_hashes[index]
                if index < len(support_proof_binder_structural_hashes)
                else ()
            )
        )
        premises = tuple(
            str(value or "").strip()
            for value in raw_premises
            if re.fullmatch(r"[0-9a-f]{64}", str(value or "").strip())
        )
        conclusion = str(
            support_conclusion_structural_hashes[index]
            if index < len(support_conclusion_structural_hashes)
            else ""
        ).strip()
        if (
            parsed is not None
            and premise_row_present
            and conclusion
            and re.fullmatch(r"[0-9a-f]{64}", conclusion)
            and len(premises) == len(raw_premises)
        ):
            rules.append((premises, conclusion))
    for claim in proved_claims:
        parsed = parse_lean_contract_identity(_bound_claim_contract_identity(claim))
        if parsed is not None:
            available.add(parsed[0])
        raw_premises, bound_conclusion = _bound_claim_contract_telescope_evidence(claim)
        premises = tuple(
            str(value or "").strip()
            for value in raw_premises
            if re.fullmatch(r"[0-9a-f]{64}", str(value or "").strip())
        )
        conclusion = str(bound_conclusion or "").strip()
        if (
            parsed is not None
            and len(raw_premises)
            == sum(
                str(sort or "").strip().lower() == "proof"
                for sort in claim.contract_binder_sorts
            )
            and conclusion
            and re.fullmatch(r"[0-9a-f]{64}", conclusion)
            and len(premises) == len(raw_premises)
        ):
            rules.append((premises, conclusion))
    changed = True
    while changed:
        changed = False
        for premises, conclusion in rules:
            if conclusion not in available and all(
                premise in available for premise in premises
            ):
                available.add(conclusion)
                changed = True
    return frozenset(available)


def _filter_plan_dependency_contract(
    plan: MiniSubgoalPlan,
    *,
    pass_index: int,
    record_event: Optional[RecordEvent],
    stats: MiniRecursiveStats,
    planner_feedback: list[str],
    helpers: Sequence[Any] = (),
    suppress_solution_placeholders: Optional[bool] = None,
    opaque_mode: bool = True,
    allow_official_answer_visibility: bool = False,
    suspended_claims: Optional[dict[str, SuspendedDependencyClaim]] = None,
    verified_support_statements_override: Optional[Sequence[str]] = None,
    verified_support_structural_identities_override: Optional[Sequence[str]] = None,
    verified_support_proof_binder_structural_hashes_override: Optional[
        Sequence[Sequence[str]]
    ] = None,
    verified_support_conclusion_structural_hashes_override: Optional[
        Sequence[str]
    ] = None,
    route_anchor_identities: Sequence[str] = (),
) -> MiniSubgoalPlan:
    """Reject plans whose final assembly introduces unsupported premises.

    A plan can contain true helper lemmas and still fail to assemble the root.
    Letting those helpers become durable child work burns the run on irrelevant
    hard lemmas.  This gate keeps the plan-level contract honest before any
    child proof budget is spent.
    """

    base_support_statements = (
        tuple(
            str(statement or "") for statement in verified_support_statements_override
        )
        if verified_support_statements_override is not None
        else _verified_helper_statements(
            helpers,
            suppress_solution_placeholders=suppress_solution_placeholders,
            opaque_mode=opaque_mode,
            allow_official_answer_visibility=allow_official_answer_visibility,
        )
    )
    base_support_candidates = list(
        _support_contract_candidates(
            str(plan.root_statement or ""),
            include_implication_premises=True,
            premises_are_assumptions=True,
        )
    )
    for statement in base_support_statements:
        base_support_candidates.extend(_support_contract_candidates(statement))
    base_support_structural_identities = tuple(
        str(identity or "").strip()
        for identity in (
            verified_support_structural_identities_override
            if verified_support_structural_identities_override is not None
            else tuple(_verified_helper_dependency_identities(helpers).values())
        )
    )
    base_support_proof_binder_structural_hashes = tuple(
        tuple(str(value or "").strip() for value in values)
        for values in (verified_support_proof_binder_structural_hashes_override or ())
    )
    base_support_conclusion_structural_hashes = tuple(
        str(value or "").strip()
        for value in (verified_support_conclusion_structural_hashes_override or ())
    )
    kept: list[MiniSubgoalClaim] = []
    plan_changed = False
    rejected_names: dict[str, tuple[str, ...]] = {}
    unmet_assembly_bridge_rejected_names: set[str] = set()
    prepared_claims: list[MiniSubgoalClaim] = []
    for claim in plan.claims:
        claim_name = str(claim.name or "").strip()
        ambiguous_binder_types = (
            ()
            if _has_lean_structural_contract_evidence(
                _bound_claim_contract_identity(claim)
            )
            else graph_statement_contract_ambiguities(
                _claim_contract_analysis_statement(claim)
            )
        )
        if ambiguous_binder_types:
            reasons = tuple(
                f"ambiguous_proof_binder:{binder_type}"
                for binder_type in ambiguous_binder_types
            )
            rejected_names[claim_name] = reasons
            plan_changed = True
            stats.plans_dependency_contract_rejected += 1
            suspended = _record_suspended_dependency_claim(
                suspended_claims,
                claim,
                reasons=reasons,
                pass_index=pass_index,
                verdict="claim_rejected_ambiguous_proof_binder",
            )
            if suspended:
                stats.dependency_contract_claims_suspended += 1
            _add_planner_feedback(
                planner_feedback,
                f"Planner claim `{claim.name}` was rejected before proving "
                "because its external application-shaped binder contract "
                "cannot be classified as proof or data from syntax alone: "
                f"{', '.join(ambiguous_binder_types)}. Declare the predicate "
                "or type family in the theorem binders so the contract is explicit.",
            )
            _record(
                record_event,
                {
                    "phase": "mini_recursive_plan_dependency_contract",
                    "pass_index": pass_index,
                    "claim_name": claim.name,
                    "reasons": list(reasons),
                    "ambiguous_binder_types": list(ambiguous_binder_types),
                    "dependency_contract_suspended": bool(suspended),
                    "verdict": "claim_rejected_ambiguous_proof_binder",
                },
            )
            continue
        existing_deps = _unique_nonempty_names(tuple(claim.dependencies or ()))
        premise_deps = _claim_premise_dependency_names(
            claim,
            plan.claims,
            support_candidates=base_support_candidates,
            support_statements=base_support_statements,
        )
        merged_deps = _unique_nonempty_names(existing_deps + premise_deps)
        if merged_deps != existing_deps:
            claim = dataclass_replace(claim, dependencies=merged_deps)
            plan_changed = True
            added_premise_deps = [
                name for name in premise_deps if name not in existing_deps
            ]
            if added_premise_deps:
                stats.plan_premise_dependencies_inferred += len(added_premise_deps)
                _record(
                    record_event,
                    {
                        "phase": "mini_recursive_plan_dependency_contract",
                        "pass_index": pass_index,
                        "claim_name": claim.name,
                        "dependencies": list(claim.dependencies),
                        "inferred_dependencies": list(added_premise_deps),
                        "verdict": "claim_premise_dependencies_inferred",
                    },
                )
        prepared_claims.append(claim)
    declared_cycle_reasons = _declared_dependency_cycle_reasons(prepared_claims)
    if declared_cycle_reasons:
        plan_changed = True
        cycle_rejected_names = set(declared_cycle_reasons)
        for claim in prepared_claims:
            claim_name = str(claim.name or "").strip()
            if claim_name not in declared_cycle_reasons:
                continue
            reasons = declared_cycle_reasons[claim_name]
            rejected_names[claim_name] = reasons
            stats.plans_dependency_contract_rejected += 1
            suspended = _record_suspended_dependency_claim(
                suspended_claims,
                claim,
                reasons=reasons,
                pass_index=pass_index,
                verdict="claim_rejected_declared_dependency_cycle",
            )
            if suspended:
                stats.dependency_contract_claims_suspended += 1
            _add_planner_feedback(
                planner_feedback,
                f"Planner claim `{claim.name}` was rejected before proving "
                "because its declared dependencies form a cycle: "
                f"{'; '.join(reasons)}. Replace the cyclic dependency "
                "contract with an acyclic setup/bridge order.",
            )
            _record(
                record_event,
                {
                    "phase": "mini_recursive_plan_dependency_contract",
                    "pass_index": pass_index,
                    "claim_name": claim.name,
                    "dependencies": list(claim.dependencies),
                    "reasons": list(reasons),
                    "dependency_contract_suspended": bool(suspended),
                    "verdict": "claim_rejected_declared_dependency_cycle",
                },
            )
        prepared_claims = [
            claim
            for claim in prepared_claims
            if str(claim.name or "").strip() not in cycle_rejected_names
        ]
    ordered_claims = _topologically_order_claims_by_dependencies(prepared_claims)
    if tuple(claim.name for claim in ordered_claims) != tuple(
        claim.name for claim in plan.claims
    ):
        plan_changed = True
        _record(
            record_event,
            {
                "phase": "mini_recursive_plan_dependency_contract",
                "pass_index": pass_index,
                "claim_order": [claim.name for claim in ordered_claims],
                "verdict": "claims_reordered_for_inferred_dependencies",
            },
        )
    # Names consumed directly by an ASSEMBLY-LIKE claim (one whose conclusion
    # is root-adjacent), retained for telemetry that distinguishes the original
    # one-edge exception from a transitive route admission.
    assembly_consumed_claim_names = {
        dep
        for claim in ordered_claims
        if _is_assembly_like_claim(claim, root_statement=plan.root_statement)
        for dep in _unique_nonempty_names(tuple(claim.dependencies or ()))
    }
    # A valid conditional bridge may sit several helper edges before root
    # assembly (for example generic well-founded descent -> no-solution -> set
    # inclusion -> equality).  Admit pure local-premise claims only on that
    # backwards dependency closure.  After filtering, recompute the closure so
    # a rejected consumer cannot leave a provisionally kept hollow route.
    root_route_dependency_names = _root_route_dependency_names(
        ordered_claims,
        root_statement=plan.root_statement,
    )
    inline_premise_kept_names: set[str] = set()
    for claim in ordered_claims:
        claim_name = str(claim.name or "").strip()
        candidate_dependencies = _unique_nonempty_names(tuple(claim.dependencies or ()))
        tainted = [dep for dep in candidate_dependencies if dep in rejected_names]
        if tainted:
            reasons = tuple(f"depends_on_contract_rejected:{name}" for name in tainted)
            unmet_assembly_bridge = any(
                dep in unmet_assembly_bridge_rejected_names for dep in tainted
            )
            if claim_name:
                rejected_names[claim_name] = reasons
                if unmet_assembly_bridge:
                    unmet_assembly_bridge_rejected_names.add(claim_name)
            stats.plans_dependency_contract_rejected += 1
            if unmet_assembly_bridge:
                stats.plans_unmet_assembly_bridge_rejected += 1
            suspended = _record_suspended_dependency_claim(
                suspended_claims,
                claim,
                reasons=reasons,
                pass_index=pass_index,
                verdict="claim_rejected_dependency_contract_tainted_dependency",
            )
            if suspended:
                stats.dependency_contract_claims_suspended += 1
            _add_planner_feedback(
                planner_feedback,
                f"Planner claim `{claim.name}` was rejected before proving because "
                f"it depends on dependency-contract-rejected claim(s): "
                f"{', '.join(tainted)}. Plan the missing contract bridge first.",
            )
            _record(
                record_event,
                {
                    "phase": "mini_recursive_plan_dependency_contract",
                    "pass_index": pass_index,
                    "claim_name": claim.name,
                    "dependencies": list(claim.dependencies),
                    "tainted_dependencies": tainted,
                    "reasons": list(reasons),
                    "unmet_assembly_bridge": bool(unmet_assembly_bridge),
                    "dependency_contract_suspended": bool(suspended),
                    "verdict": "claim_rejected_dependency_contract_tainted_dependency",
                },
            )
            continue
        declared_dependency_names = {
            str(dependency or "").strip()
            for dependency in claim.dependencies
            if str(dependency or "").strip()
        }
        structural_dependency_names = set(declared_dependency_names)
        dependency_claims_by_name: dict[str, list[MiniSubgoalClaim]] = {}
        for item in kept:
            item_name = str(item.name or "").strip()
            if item_name:
                dependency_claims_by_name.setdefault(item_name, []).append(item)
        pending_dependency_names = list(structural_dependency_names)
        while pending_dependency_names:
            dependency_name = pending_dependency_names.pop()
            for dependency_claim in dependency_claims_by_name.get(
                dependency_name,
                (),
            ):
                for ancestor in dependency_claim.dependencies:
                    ancestor_name = str(ancestor or "").strip()
                    if (
                        ancestor_name
                        and ancestor_name not in structural_dependency_names
                    ):
                        structural_dependency_names.add(ancestor_name)
                        pending_dependency_names.append(ancestor_name)
        support_statements = tuple(
            list(base_support_statements)
            + [
                str(item.statement or "")
                for item in kept
                if str(item.name or "").strip() in structural_dependency_names
            ]
        )
        support_structural_identities = (
            *base_support_structural_identities,
            *(
                identity
                for item in kept
                if str(item.name or "").strip() in structural_dependency_names
                for identity in (_bound_claim_contract_identity(item),)
                if has_lean_contract_identity(identity)
            ),
        )
        support_structural_hashes = _structural_support_hash_closure(
            plan,
            support_structural_identities=(base_support_structural_identities),
            support_proof_binder_structural_hashes=(
                base_support_proof_binder_structural_hashes
            ),
            support_conclusion_structural_hashes=(
                base_support_conclusion_structural_hashes
            ),
            proved_claims=tuple(
                item
                for item in kept
                if str(item.name or "").strip() in structural_dependency_names
            ),
        )
        reasons = _claim_dependency_contract_reasons(
            claim,
            plan=plan,
            support_statements=support_statements,
            support_structural_identities=support_structural_identities,
            support_structural_hashes=support_structural_hashes,
            route_anchor_identities=route_anchor_identities,
        )
        if not reasons:
            kept.append(claim)
            continue
        if (
            claim_name in root_route_dependency_names
            and _reasons_are_inline_dischargeable_route_premise(reasons)
        ):
            # Attempt-don't-pre-gate: a conditional lemma `H -> C` on a live
            # dependency route only *assumes* `H`; downstream helper/root
            # assembly discharges `H`, and Lean verifies the composed route.
            # Pre-rejecting it here taints every consumer before any proof is
            # attempted. Keep it provisionally, then prune below if no
            # assembly-connected consumer survives this filter pass.
            kept.append(claim)
            if claim_name:
                inline_premise_kept_names.add(claim_name)
            stats.dependency_contract_inline_premise_attempts_granted += 1
            _add_planner_feedback(
                planner_feedback,
                f"Planner claim `{claim.name}` has a route-local antecedent "
                f"premise no declared dependency supplies ({'; '.join(reasons)}), "
                "but is kept and will be attempted because a surviving dependency "
                "path reaches root assembly and can discharge the antecedent while "
                "composing the route. If composition cannot discharge it, add an "
                "explicit Lean-checkable bridge theorem whose conclusion supplies "
                "that premise.",
            )
            _record(
                record_event,
                {
                    "phase": "mini_recursive_plan_dependency_contract",
                    "pass_index": pass_index,
                    "claim_name": claim.name,
                    "dependencies": list(claim.dependencies),
                    "reasons": list(reasons),
                    "route_connected": True,
                    "direct_assembly_consumer": (
                        claim_name in assembly_consumed_claim_names
                    ),
                    "verdict": "claim_kept_inline_dischargeable_premise_attempt",
                },
            )
            continue
        stats.plans_dependency_contract_rejected += 1
        unmet_assembly_bridge = _has_unmet_assembly_premise_reason(reasons)
        if unmet_assembly_bridge:
            stats.plans_unmet_assembly_bridge_rejected += 1
            if claim_name:
                unmet_assembly_bridge_rejected_names.add(claim_name)
        if claim_name:
            rejected_names[claim_name] = reasons
        reason_text = "; ".join(reasons)
        suspended = _record_suspended_dependency_claim(
            suspended_claims,
            claim,
            reasons=reasons,
            pass_index=pass_index,
            verdict="plan_rejected_dependency_contract",
        )
        if suspended:
            stats.dependency_contract_claims_suspended += 1
        if any(
            str(reason or "").startswith("semantic_role_mismatch:")
            for reason in reasons
        ):
            _add_planner_feedback(
                planner_feedback,
                f"Planner claim `{claim.name}` was rejected before proving because "
                "its prose role describes a square-root/rationality bridge "
                "that is not present in the formal Lean statement or its "
                f"dependencies: {reason_text}. Add an explicit Lean-checkable "
                "bridge theorem, or remove the square-root bridge role from "
                "this claim.",
            )
        elif unmet_assembly_bridge:
            _add_planner_feedback(
                planner_feedback,
                f"Planner claim `{claim.name}` was rejected before proving because "
                "it is a root-assembly branch/reducer with local premise(s) "
                f"that no current dependency supplies; unmet premise(s): "
                f"{reason_text}. First "
                "emit a Lean-checkable coverage or normalization bridge "
                "(for example an explicit disjunction/case split, or a theorem "
                "deriving the needed branch premises from the original root "
                "hypotheses), then make the branch reducer depend on that bridge. "
                "Do not repeat this conditional branch claim by itself.",
            )
        else:
            _add_planner_feedback(
                planner_feedback,
                f"Planner claim `{claim.name}` was rejected before proving because "
                "its assembly contract has unmet premise(s): "
                f"{reason_text}. Add the missing premise as an explicit "
                "Lean-checkable prerequisite claim, or choose a bridge whose "
                "conclusion directly supplies the downstream premise.",
            )
        _record(
            record_event,
            {
                "phase": "mini_recursive_plan_dependency_contract",
                "pass_index": pass_index,
                "claim_name": claim.name,
                "dependencies": list(claim.dependencies),
                "reasons": list(reasons),
                "unmet_assembly_bridge": bool(unmet_assembly_bridge),
                "dependency_contract_suspended": bool(suspended),
                "verdict": "plan_rejected_dependency_contract",
            },
        )
    # Drop orphaned inline-premise keeps: a conditional lemma kept only because
    # it was on a root route is unjustified if that route did not survive (its
    # antecedent is then discharged by nobody). Recompute the full transitive
    # root dependency closure over `kept` and prune to a fixpoint, since removing
    # one provisional lemma can orphan another.
    while inline_premise_kept_names:
        surviving_route_dependencies = _root_route_dependency_names(
            kept,
            root_statement=plan.root_statement,
        )
        orphans = [
            claim
            for claim in kept
            if str(claim.name or "").strip() in inline_premise_kept_names
            and str(claim.name or "").strip() not in surviving_route_dependencies
        ]
        if not orphans:
            break
        for claim in orphans:
            claim_name = str(claim.name or "").strip()
            kept.remove(claim)
            inline_premise_kept_names.discard(claim_name)
            plan_changed = True
            stats.dependency_contract_inline_premise_attempts_granted = max(
                0, stats.dependency_contract_inline_premise_attempts_granted - 1
            )
            stats.plans_dependency_contract_rejected += 1
            if claim_name:
                rejected_names[claim_name] = (
                    "orphaned_inline_premise_no_surviving_assembly_consumer",
                )
            _record(
                record_event,
                {
                    "phase": "mini_recursive_plan_dependency_contract",
                    "pass_index": pass_index,
                    "claim_name": claim.name,
                    "dependencies": list(claim.dependencies),
                    "verdict": "claim_dropped_orphaned_inline_premise",
                },
            )
        # Orphan removal runs after the ordinary topological taint pass.
        # Propagate each newly rejected internal dependency through every
        # surviving consumer; otherwise this filter publishes a plan with a
        # dangling dependency. Names that never belonged to this plan remain
        # external support anchors and are intentionally unaffected.
        while True:
            dangling = [
                claim
                for claim in kept
                if any(
                    str(dependency or "").strip() in rejected_names
                    for dependency in tuple(claim.dependencies or ())
                    if str(dependency or "").strip()
                )
            ]
            if not dangling:
                break
            for claim in dangling:
                claim_name = str(claim.name or "").strip()
                tainted = [
                    str(dependency or "").strip()
                    for dependency in tuple(claim.dependencies or ())
                    if str(dependency or "").strip() in rejected_names
                ]
                kept.remove(claim)
                if claim_name in inline_premise_kept_names:
                    inline_premise_kept_names.discard(claim_name)
                    stats.dependency_contract_inline_premise_attempts_granted = max(
                        0,
                        stats.dependency_contract_inline_premise_attempts_granted - 1,
                    )
                reasons = tuple(
                    f"depends_on_contract_rejected:{name}" for name in tainted
                )
                if claim_name:
                    rejected_names[claim_name] = reasons
                stats.plans_dependency_contract_rejected += 1
                unmet_assembly_bridge = any(
                    name in unmet_assembly_bridge_rejected_names for name in tainted
                )
                if unmet_assembly_bridge:
                    stats.plans_unmet_assembly_bridge_rejected += 1
                    if claim_name:
                        unmet_assembly_bridge_rejected_names.add(claim_name)
                suspended = _record_suspended_dependency_claim(
                    suspended_claims,
                    claim,
                    reasons=reasons,
                    pass_index=pass_index,
                    verdict="claim_dropped_orphaned_inline_premise_dependent",
                )
                if suspended:
                    stats.dependency_contract_claims_suspended += 1
                _add_planner_feedback(
                    planner_feedback,
                    f"Planner claim `{claim.name}` was removed because its "
                    "dependency route became orphaned after contract filtering: "
                    f"{', '.join(tainted)}. Rebuild the missing premise route "
                    "before retrying this consumer.",
                )
                _record(
                    record_event,
                    {
                        "phase": "mini_recursive_plan_dependency_contract",
                        "pass_index": pass_index,
                        "claim_name": claim.name,
                        "dependencies": list(claim.dependencies),
                        "tainted_dependencies": tainted,
                        "reasons": list(reasons),
                        "dependency_contract_suspended": bool(suspended),
                        "verdict": ("claim_dropped_orphaned_inline_premise_dependent"),
                    },
                )
    if len(kept) == len(ordered_claims):
        if plan_changed:
            return dataclass_replace(plan, claims=tuple(kept))
        return plan
    return dataclass_replace(plan, claims=tuple(kept))


def _filter_plan_self_refuting_sanity_checks(
    plan: MiniSubgoalPlan,
    *,
    pass_index: int,
    record_event: Optional[RecordEvent],
    stats: MiniRecursiveStats,
    planner_feedback: list[str],
) -> MiniSubgoalPlan:
    """Reject claims whose own sanity prose says the claim is false."""

    if not plan.claims:
        return plan
    kept: list[MiniSubgoalClaim] = []
    rejected_names: set[str] = set()
    for claim in plan.claims:
        reason = _self_refuting_sanity_reason(claim)
        if not reason:
            kept.append(claim)
            continue
        claim_name = str(claim.name or "").strip()
        if claim_name:
            rejected_names.add(claim_name)
        stats.plans_self_refuting_sanity_rejected += 1
        _add_planner_feedback(
            planner_feedback,
            (
                f"Planner claim `{claim.name}` was rejected before proving "
                f"because its own sanity_check says the formula is inconsistent "
                f"with a tiny instance (`{reason}`). Do not emit the same "
                "known-bad statement as a proof target; plan the corrected "
                "structural bridge or a smaller checkable prerequisite instead."
            ),
        )
        _record(
            record_event,
            {
                "phase": "mini_recursive_plan_sanity",
                "pass_index": pass_index,
                "claim_name": claim.name,
                "statement": claim.statement,
                "sanity_check": claim.sanity_check,
                "sanity_status": getattr(claim, "sanity_status", ""),
                "reason": reason,
                "verdict": "claim_rejected_self_refuting_sanity",
            },
        )
    if len(kept) == len(plan.claims):
        return plan
    while rejected_names:
        next_kept: list[MiniSubgoalClaim] = []
        changed = False
        for claim in kept:
            tainted = [
                dep
                for dep in claim.dependencies
                if str(dep or "").strip() in rejected_names
            ]
            if not tainted:
                next_kept.append(claim)
                continue
            changed = True
            claim_name = str(claim.name or "").strip()
            if claim_name:
                rejected_names.add(claim_name)
            stats.plans_self_refuting_sanity_rejected += 1
            _add_planner_feedback(
                planner_feedback,
                (
                    f"Planner claim `{claim.name}` was rejected because it "
                    f"depends on self-refuting rejected claim(s): "
                    f"{', '.join(tainted)}. Replace the dependency chain with "
                    "true Lean-checkable bridge claims."
                ),
            )
            _record(
                record_event,
                {
                    "phase": "mini_recursive_plan_sanity",
                    "pass_index": pass_index,
                    "claim_name": claim.name,
                    "statement": claim.statement,
                    "dependencies": list(claim.dependencies),
                    "tainted_dependencies": tainted,
                    "verdict": "claim_rejected_self_refuting_sanity_dependency",
                },
            )
        kept = next_kept
        if not changed:
            break
    return dataclass_replace(plan, claims=tuple(kept))


_CONTROLLER_ROOT_ASSEMBLY_RATIONALE = (
    "Controller-restored authoritative root-route schema after "
    "syntax-only plan normalization omitted this active goal."
)
_CONTROLLER_ROOT_ASSEMBLY_NAME_RE = re.compile(
    r"controller_root_assembly(?:_(?:[2-9]|[1-9][0-9]+))?\Z"
)
# v1 recorded diagnostic-only sanity auditing. v2 records the first
# work-admission policy that withholds incomplete required checks.
_PLAN_DIAGNOSTICS_RECEIPT_VERSION = 2


def _claim_has_controller_sanity_exemption(
    claim: MiniSubgoalClaim,
    *,
    root_statement: str = "",
    active_target_statements: Sequence[str] = (),
) -> bool:
    """Revalidate the exact local constructor shape before policy exemption."""

    if not bool(getattr(claim, "controller_synthesized", False)):
        return False
    if (
        _CONTROLLER_ROOT_ASSEMBLY_NAME_RE.fullmatch(
            str(getattr(claim, "name", "") or "").strip()
        )
        is None
        or str(getattr(claim, "role", "") or "").strip().lower() != "root_assembly"
        or tuple(getattr(claim, "dependencies", ()) or ())
        or str(getattr(claim, "rationale", "") or "").strip()
        != _CONTROLLER_ROOT_ASSEMBLY_RATIONALE
    ):
        return False
    root = str(root_statement or "").strip()
    return not root or graph_statement_root_equivalent(
        str(getattr(claim, "statement", "") or ""),
        root,
        active_target_statements=active_target_statements,
    )


def _quantified_equality_sanity_is_adversarial(
    claim: MiniSubgoalClaim,
) -> bool:
    """Require explicit distinct assignments for an implication equality.

    This is a work-admission receipt check, not mathematical validation. It
    prevents an equal-input example from satisfying the planner protocol that
    specifically asks it to try falsifying a quantified equality conclusion.
    Lean and certified falsification retain all proof authority.
    """

    statement = str(getattr(claim, "statement", "") or "").strip()
    body, bound_names = _strip_leading_forall_binders_with_names(statement)
    implication_parts = _split_top_level_implications(body)
    if len(bound_names) < 2 or len(implication_parts) < 2:
        return True
    conclusion = str(implication_parts[-1] or "")
    if not re.search(r"(?<![<>=!≠≤≥])=(?!=|>)", conclusion):
        return True
    conclusion_names = [
        name
        for name in bound_names
        if re.search(rf"(?<![\w']){re.escape(name)}(?![\w'])", conclusion)
    ]
    if len(conclusion_names) < 2:
        return True
    sanity = str(getattr(claim, "sanity_check", "") or "")
    assigned_values: list[str] = []
    for name in conclusion_names:
        match = re.search(
            rf"(?<![\w']){re.escape(name)}(?![\w'])\s*(?::=|=)\s*"
            r"([-+]?\d+(?:\.\d+)?)",
            sanity,
        )
        if match:
            assigned_values.append(match.group(1))
    return len(assigned_values) >= 2 and len(set(assigned_values)) >= 2


def _claim_declared_sanity_contract_reason(
    claim: MiniSubgoalClaim,
    *,
    require_complete: bool = False,
    root_statement: str = "",
    active_target_statements: Sequence[str] = (),
) -> str:
    """Return a diagnostic reason for one typed planner sanity receipt."""

    check = str(getattr(claim, "sanity_check", "") or "").strip()
    raw_status = str(getattr(claim, "sanity_status", "") or "").strip().lower()
    status = {
        "pass": "passes",
        "passed": "passes",
        "ok": "passes",
        "valid": "passes",
        "fail": "fails",
        "failed": "fails",
        "invalid": "fails",
        "n/a": "not_applicable",
        "na": "not_applicable",
        "none": "not_applicable",
    }.get(raw_status, raw_status)
    controller_exempt = _claim_has_controller_sanity_exemption(
        claim,
        root_statement=root_statement,
        active_target_statements=active_target_statements,
    )
    sanity_required = (
        _claim_sanity_requirement(claim).required and not controller_exempt
    )
    if status == "fails":
        return "declared_failed"
    if sanity_required and not check:
        return "sanity_check_required"
    if require_complete and not controller_exempt and not status:
        return "missing_sanity_status"
    if (
        require_complete
        and sanity_required
        and status == "passes"
        and not _quantified_equality_sanity_is_adversarial(claim)
    ):
        return "non_adversarial_equality_sanity_check"
    if check and status != "passes":
        return "missing_or_invalid_status"
    if not check and status not in {"", "not_applicable"}:
        return "status_without_check"
    if check and _self_refuting_sanity_reason(claim):
        return "passes_conflicts_with_check"
    return ""


def _filter_plan_declared_sanity_contract(
    plan: MiniSubgoalPlan,
    *,
    pass_index: int,
    record_event: Optional[RecordEvent],
    stats: MiniRecursiveStats,
    planner_feedback: list[str],
    require_complete: bool = False,
    active_target_statements: Sequence[str] = (),
    withhold_missing_required_checks: bool = False,
) -> MiniSubgoalPlan:
    """Audit receipts and optionally withhold protocol-incomplete fresh work.

    Withholding requests replanning; it is never a mathematical rejection.
    Lean and certified falsification remain the only proof authorities.
    """

    if not plan.claims:
        return plan
    diagnostics = {
        index: reason
        for index, claim in enumerate(plan.claims)
        if (
            reason := _claim_declared_sanity_contract_reason(
                claim,
                require_complete=require_complete,
                root_statement=plan.root_statement,
                active_target_statements=active_target_statements,
            )
        )
    }
    if not diagnostics:
        return plan
    withheld_names: set[str] = set()
    kept: list[MiniSubgoalClaim] = []
    for index, claim in enumerate(plan.claims):
        reason = diagnostics.get(index)
        if not reason:
            kept.append(claim)
            continue
        requirement = _claim_sanity_requirement(claim)
        withhold = bool(
            withhold_missing_required_checks
            and require_complete
            and reason
            in {
                "sanity_check_required",
                "non_adversarial_equality_sanity_check",
                "passes_conflicts_with_check",
            }
            and int(getattr(claim, "sanity_contract_version", 0) or 0) >= 1
        )
        stats.plans_sanity_contract_diagnostics += 1
        if reason == "sanity_check_required":
            stats.plans_sanity_missing_check_diagnostics += 1
        elif reason == "missing_sanity_status":
            stats.plans_sanity_missing_status_diagnostics += 1
        elif reason == "declared_failed":
            stats.plans_sanity_declared_failure_diagnostics += 1
        else:
            stats.plans_sanity_status_conflict_diagnostics += 1
        _record(
            record_event,
            {
                "phase": "mini_recursive_plan_sanity_contract",
                "pass_index": pass_index,
                "claim_name": claim.name,
                "statement": claim.statement,
                "sanity_check": claim.sanity_check,
                "sanity_status": getattr(claim, "sanity_status", ""),
                "counting_classification": getattr(
                    claim, "counting_classification", ""
                ),
                "rationale": claim.rationale,
                "dependencies": list(claim.dependencies),
                "reason": reason,
                "classification_triggers": list(requirement.triggers),
                "classification_evidence": list(requirement.evidence),
                "policy_disposition": (
                    "withhold_for_replan" if withhold else "diagnostic_only"
                ),
                "verdict": (
                    "claim_withheld_incomplete_sanity_contract"
                    if withhold
                    else "claim_sanity_contract_diagnostic"
                ),
            },
        )
        if withhold:
            claim_name = str(claim.name or "").strip()
            if claim_name:
                withheld_names.add(claim_name)
            stats.plans_sanity_contract_withheld += 1
            _add_planner_feedback(
                planner_feedback,
                (
                    f"Fresh planner claim `{claim.name}` was withheld because "
                    "its statement requires an independent sanity check but "
                    "the typed receipt supplied none. Replan with a non-vacuous "
                    "boundary or adversarial check that attempts every premise. "
                    "This is protocol admission, not a mathematical refutation."
                ),
            )
            continue
        kept.append(claim)
        trigger_text = ", ".join(requirement.triggers) or "receipt consistency"
        _add_planner_feedback(
            planner_feedback,
            (
                f"Sanity metadata diagnostic for `{claim.name}`: {reason} "
                f"(trigger: {trigger_text}). Preserve the Lean-checkable claim "
                "unless formal evidence refutes it; make the next receipt "
                "internally consistent and include an independent check when "
                "the statement classification requests one."
            ),
        )
    if not withheld_names:
        return plan
    while withheld_names:
        next_kept: list[MiniSubgoalClaim] = []
        newly_withheld: set[str] = set()
        for claim in kept:
            tainted = [
                str(dependency or "").strip()
                for dependency in claim.dependencies
                if str(dependency or "").strip() in withheld_names
            ]
            if not tainted:
                next_kept.append(claim)
                continue
            claim_name = str(claim.name or "").strip()
            if claim_name:
                newly_withheld.add(claim_name)
            stats.plans_sanity_contract_withheld += 1
            _record(
                record_event,
                {
                    "phase": "mini_recursive_plan_sanity_contract",
                    "pass_index": pass_index,
                    "claim_name": claim.name,
                    "statement": claim.statement,
                    "dependencies": list(claim.dependencies),
                    "tainted_dependencies": tainted,
                    "reason": "depends_on_incomplete_sanity_contract",
                    "policy_disposition": "withhold_for_replan",
                    "verdict": (
                        "claim_withheld_incomplete_sanity_contract_dependency"
                    ),
                },
            )
            _add_planner_feedback(
                planner_feedback,
                (
                    f"Planner claim `{claim.name}` was withheld because it "
                    f"depends on sanity-incomplete claim(s): {', '.join(tainted)}. "
                    "Rebuild the route after supplying the missing independent "
                    "check."
                ),
            )
        kept = next_kept
        withheld_names = newly_withheld
    return dataclass_replace(plan, claims=tuple(kept))


def _statement_matches_positive_active_target(
    statement: str,
    active_root_targets: Sequence[Mapping[str, Any]],
) -> bool:
    """Return whether ``statement`` is a checked positive remaining Lean goal."""

    stmt = normalize_subgoal_statement(str(statement or "")).strip()
    if not stmt or not active_root_targets:
        return False
    compact = _strip_balanced_outer_parens(" ".join(stmt.split()).strip())
    if not compact:
        return False
    for target in _positive_active_target_texts(active_root_targets):
        target_formula = _strip_balanced_outer_parens(target)
        if target_formula and _contract_alpha_matches_exact_telescope(
            compact,
            target_formula,
        ):
            return True
    return False


def _filter_plan_structurally_vacuous_auxiliary_claims(
    plan: MiniSubgoalPlan,
    *,
    pass_index: int,
    record_event: Optional[RecordEvent],
    stats: MiniRecursiveStats,
    planner_feedback: list[str],
    active_root_targets: Sequence[Mapping[str, Any]] = (),
) -> MiniSubgoalPlan:
    """Reject auxiliary targets whose right-spine conclusion adds no fact.

    Kernel validity is not usefulness.  The Erdos run spent a falsification
    campaign, tactic pass, cache/graph admission, and root-close attempt on a
    planner claim of the form ``hypotheses → True``.  Apply this stable
    structural gate before graph materialization; an exact root claim or a
    claim that restates a checked positive active target remains eligible so
    genuinely trivial remaining goals can still finalize normally.
    """

    from .helper_quality import (
        HELPER_ADMISSION_QUALITY_SCHEMA_VERSION,
        classify_auxiliary_statement_quality,
    )

    if not plan.claims:
        return plan
    exact_root_statement = str(plan.root_statement or "").strip()
    rejected: dict[int, str] = {}
    for index, claim in enumerate(plan.claims):
        exact_root = bool(
            exact_root_statement
            and str(claim.statement or "").strip() == exact_root_statement
        )
        active_close = _statement_matches_positive_active_target(
            claim.statement,
            active_root_targets,
        )
        quality = classify_auxiliary_statement_quality(claim.statement)
        if exact_root or active_close or quality.auxiliary_target_admissible:
            continue
        rejected[index] = quality.classification
    if not rejected:
        return plan
    dependency_rejections = _fixed_point_plan_dependency_rejections(
        plan,
        rejected,
        dependency_reason=lambda tainted: (
            "depends on structurally vacuous auxiliary claim(s): " + ", ".join(tainted)
        ),
    )
    kept: list[MiniSubgoalClaim] = []
    for index, claim in enumerate(plan.claims):
        if index not in rejected and index not in dependency_rejections:
            kept.append(claim)
            continue
        if index in rejected:
            classification = rejected[index]
            tainted: tuple[str, ...] = ()
            verdict = "claim_rejected_structurally_vacuous_auxiliary"
            reason = classification
        else:
            reason, tainted = dependency_rejections[index]
            classification = "dependent"
            verdict = "claim_rejected_vacuous_auxiliary_dependency"
        stats.plans_structurally_vacuous_auxiliary_rejected += 1
        _record(
            record_event,
            {
                "phase": "mini_recursive_plan_helper_quality",
                "pass_index": pass_index,
                "claim_name": claim.name,
                "statement": claim.statement,
                "dependencies": list(claim.dependencies),
                "quality_schema_version": (HELPER_ADMISSION_QUALITY_SCHEMA_VERSION),
                "quality_classification": classification,
                "tainted_dependencies": list(tainted),
                "reason": reason,
                "verdict": verdict,
            },
        )
    _add_planner_feedback(
        planner_feedback,
        "Auxiliary claims whose conclusion is structurally vacuous (for "
        "example hypotheses implying True, a premise restated as its own "
        "conclusion, or a reflexive equality) are not proof-plan progress. "
        "Replace them with a Lean-checkable conclusion used by the root route.",
    )
    return dataclass_replace(plan, claims=tuple(kept))


def _filter_plan_explicitly_withdrawn_claims(
    plan: MiniSubgoalPlan,
    *,
    pass_index: int,
    record_event: Optional[RecordEvent],
    stats: MiniRecursiveStats,
    planner_feedback: list[str],
) -> MiniSubgoalPlan:
    """Withhold targets that the planner explicitly withdrew in its own JSON.

    This does not assert that the Lean proposition is false.  It enforces the
    structured-planning contract: a claim cannot simultaneously be submitted
    for paid execution and be marked by its producer as needing correction.
    """

    if not plan.claims:
        return plan
    kept: list[MiniSubgoalClaim] = []
    withheld_names: set[str] = set()
    plan_claim_names = tuple(
        str(item.name or "").strip()
        for item in plan.claims
        if str(item.name or "").strip()
    )
    for claim in plan.claims:
        source, reason = _explicit_claim_self_abandonment_reason(
            claim,
            plan_notes=plan.notes,
            plan_claim_names=plan_claim_names,
        )
        if not reason:
            diagnostic_source, diagnostic_reason = (
                _ambiguous_claim_self_abandonment_reason(
                    claim,
                    plan_notes=plan.notes,
                    plan_claim_names=plan_claim_names,
                )
            )
            kept.append(claim)
            if diagnostic_reason:
                stats.plans_planner_withdrawn_claims_diagnostics += 1
                _add_planner_feedback(
                    planner_feedback,
                    (
                        f"Planner note contained ambiguous cross-sentence "
                        f"non-emission language near `{claim.name}` "
                        f"(`{diagnostic_reason}`). It is diagnostic only: "
                        "use a direct claim-local or same-clause withdrawal "
                        "to change the executable plan."
                    ),
                )
                _record(
                    record_event,
                    {
                        "phase": "mini_recursive_plan_intent_contract",
                        "pass_index": pass_index,
                        "claim_name": claim.name,
                        "statement": claim.statement,
                        "withdrawal_source": diagnostic_source,
                        "reason": diagnostic_reason,
                        "authority": "planner_intent_diagnostic",
                        "policy_disposition": "diagnostic_only",
                        "mathematical_invalidity_asserted": False,
                        "verdict": (
                            "claim_diagnosed_ambiguous_planner_self_abandonment"
                        ),
                    },
                )
            continue
        claim_name = str(claim.name or "").strip()
        if claim_name:
            withheld_names.add(claim_name)
        stats.plans_planner_withdrawn_claims_withheld += 1
        _add_planner_feedback(
            planner_feedback,
            (
                f"Planner claim `{claim.name}` was withheld from execution "
                f"because its own {source} withdrew the proposed target "
                f"(`{reason}`). This is a planning-intent conflict, not a "
                "mathematical falsity verdict. Emit only the corrected "
                "Lean-checkable target on the next plan."
            ),
        )
        _record(
            record_event,
            {
                "phase": "mini_recursive_plan_intent_contract",
                "pass_index": pass_index,
                "claim_name": claim.name,
                "statement": claim.statement,
                "withdrawal_source": source,
                "reason": reason,
                "authority": "planner_intent_protocol",
                "mathematical_invalidity_asserted": False,
                "verdict": "claim_withheld_planner_self_abandonment",
            },
        )
    if len(kept) == len(plan.claims):
        return plan

    # A consumer of a withdrawn producer is not an executable DAG node even if
    # its own prose looks clean.  Propagate by exact dependency names until the
    # remaining graph is closed.
    while withheld_names:
        next_kept: list[MiniSubgoalClaim] = []
        changed = False
        newly_withheld: set[str] = set()
        for claim in kept:
            tainted = [
                dep
                for dep in claim.dependencies
                if str(dep or "").strip() in withheld_names
            ]
            if not tainted:
                next_kept.append(claim)
                continue
            changed = True
            claim_name = str(claim.name or "").strip()
            if claim_name:
                newly_withheld.add(claim_name)
            stats.plans_planner_withdrawn_claims_withheld += 1
            _add_planner_feedback(
                planner_feedback,
                (
                    f"Planner claim `{claim.name}` was withheld because its "
                    "dependency contract consumes withdrawn target(s): "
                    f"{', '.join(tainted)}. Rebuild the corrected dependency "
                    "chain before scheduling this consumer."
                ),
            )
            _record(
                record_event,
                {
                    "phase": "mini_recursive_plan_intent_contract",
                    "pass_index": pass_index,
                    "claim_name": claim.name,
                    "statement": claim.statement,
                    "dependencies": list(claim.dependencies),
                    "tainted_dependencies": tainted,
                    "authority": "planner_intent_protocol",
                    "mathematical_invalidity_asserted": False,
                    "verdict": ("claim_withheld_planner_self_abandonment_dependency"),
                },
            )
        kept = next_kept
        if not changed:
            break
        withheld_names.update(newly_withheld)
    return dataclass_replace(plan, claims=tuple(kept))


def _filter_plan_answer_unsafe_claims(
    plan: MiniSubgoalPlan,
    *,
    pass_index: int,
    record_event: Optional[RecordEvent],
    stats: MiniRecursiveStats,
    planner_feedback: list[str],
    suppress_solution_placeholders: Optional[bool] = None,
    opaque_mode: bool = True,
    allow_official_answer_visibility: bool = False,
    official_answer_payload_present: Optional[bool] = None,
) -> MiniSubgoalPlan:
    """Reject helper claims that try to make answer placeholders reusable."""

    if not plan.claims:
        return plan
    kept: list[MiniSubgoalClaim] = []
    rejected_names: set[str] = set()
    for claim in plan.claims:
        if not is_answer_unsafe_statement_text(
            claim.statement,
            suppress_solution_placeholders=suppress_solution_placeholders,
            opaque_mode=opaque_mode,
            allow_official_answer_visibility=allow_official_answer_visibility,
            official_answer_payload_present=official_answer_payload_present,
        ):
            kept.append(claim)
            continue
        claim_name = str(claim.name or "").strip()
        if claim_name:
            rejected_names.add(claim_name)
        stats.plans_answer_unsafe_rejected += 1
        # NOTE: feedback passes through the answer-safe sanitizer, which hashes
        # backtick spans and any literal solution-suffix token — phrase the
        # guidance in plain words so it survives intact.
        if str(claim.role or "").strip() == "root_assembly":
            # A root_assembly restating the opaque placeholder is the planner
            # obeying "conclude the supplied root" — tell it the WINNABLE form
            # (root with its own determined value substituted) instead of the
            # generic helper-bookkeeping message, or every opaque-mode plan
            # collapses to helper-only.
            _add_planner_feedback(
                planner_feedback,
                (
                    "Your root_assembly claim restated the opaque answer "
                    "placeholder from the root, so it was rejected and the plan "
                    "lost its root route. Determine the concrete answer from "
                    "your own mathematical analysis and re-emit root_assembly "
                    "as the root proposition with that concrete value "
                    "substituted for the placeholder (for example an explicit "
                    "numeral or closed form such as a = 2), listing the claims "
                    "that force that value in dependencies. No claim statement "
                    "may mention the answer placeholder name."
                ),
            )
        else:
            _add_planner_feedback(
                planner_feedback,
                (
                    f"Planner claim `{claim.name}` was rejected because its "
                    "statement mentions an answer placeholder. Do not turn "
                    "answer-placeholder bookkeeping facts into helper "
                    "obligations; prove the active mathematical target instead."
                ),
            )
        _record(
            record_event,
            {
                "phase": "mini_recursive_plan_answer_safety",
                "pass_index": pass_index,
                "claim_name": claim.name,
                "statement": claim.statement,
                "verdict": "claim_rejected_answer_unsafe_statement",
            },
        )
    if len(kept) == len(plan.claims):
        return plan
    while rejected_names:
        next_kept: list[MiniSubgoalClaim] = []
        changed = False
        for claim in kept:
            tainted = [
                dep
                for dep in claim.dependencies
                if str(dep or "").strip() in rejected_names
            ]
            if not tainted:
                next_kept.append(claim)
                continue
            changed = True
            claim_name = str(claim.name or "").strip()
            if claim_name:
                rejected_names.add(claim_name)
            stats.plans_answer_unsafe_rejected += 1
            _add_planner_feedback(
                planner_feedback,
                (
                    f"Planner claim `{claim.name}` was rejected because it "
                    f"depends on answer-placeholder claim(s): "
                    f"{', '.join(tainted)}. Replace the dependency chain with "
                    "true Lean-checkable mathematical bridge claims."
                ),
            )
            _record(
                record_event,
                {
                    "phase": "mini_recursive_plan_answer_safety",
                    "pass_index": pass_index,
                    "claim_name": claim.name,
                    "statement": claim.statement,
                    "dependencies": list(claim.dependencies),
                    "tainted_dependencies": tainted,
                    "verdict": "claim_rejected_answer_unsafe_dependency",
                },
            )
        kept = next_kept
        if not changed:
            break
    return dataclass_replace(plan, claims=tuple(kept))


def _filter_plan_active_target_polarity(
    plan: MiniSubgoalPlan,
    *,
    active_root_targets: Sequence[Mapping[str, Any]],
    pass_index: int,
    record_event: Optional[RecordEvent],
    stats: MiniRecursiveStats,
    planner_feedback: list[str],
) -> MiniSubgoalPlan:
    """Reject routes that contradict a checked positive active root target."""

    if not plan.claims or not _active_targets_require_positive_route(
        active_root_targets
    ):
        return plan
    active_targets = [
        str(goal.get("target") or "").strip()
        for goal in active_root_targets or ()
        if str(goal.get("target") or "").strip()
    ]
    plan_reason = _wrong_polarity_route_reason(
        "\n".join([plan.strategy, *[str(note or "") for note in plan.notes]])
    )
    if plan_reason:
        stats.plans_wrong_polarity_rejected += len(plan.claims)
        _add_planner_feedback(
            planner_feedback,
            (
                "Rejected the previous recursive plan because Lean had already "
                "reduced the root to a positive active target, but the plan "
                f"described an opposite-polarity route (`{plan_reason}`). "
                "Plan bridge claims for the active target instead."
            ),
        )
        _record(
            record_event,
            {
                "phase": "mini_recursive_plan_polarity",
                "pass_index": pass_index,
                "active_targets": active_targets,
                "reason": plan_reason,
                "claims_rejected": len(plan.claims),
                "verdict": "plan_rejected_active_target_polarity",
            },
        )
        return dataclass_replace(plan, claims=())

    kept: list[MiniSubgoalClaim] = []
    rejected_names: set[str] = set()
    for claim in plan.claims:
        reason = _statement_negates_active_target_reason(
            claim.statement,
            active_root_targets,
        ) or _wrong_polarity_route_reason(
            _strip_trailing_lean_ws_comments(
                _strip_leading_lean_ws_comments(str(claim.statement or ""))
            )
        )
        if not reason:
            kept.append(claim)
            continue
        claim_name = str(claim.name or "").strip()
        if claim_name:
            rejected_names.add(claim_name)
        stats.plans_wrong_polarity_rejected += 1
        _add_planner_feedback(
            planner_feedback,
            (
                f"Planner claim `{claim.name}` was rejected because Lean had "
                "already exposed a positive active target, but the claim "
                f"metadata describes an opposite-polarity route (`{reason}`). "
                "Replace it with a bridge toward the active target."
            ),
        )
        _record(
            record_event,
            {
                "phase": "mini_recursive_plan_polarity",
                "pass_index": pass_index,
                "claim_name": claim.name,
                "statement": claim.statement,
                "active_targets": active_targets,
                "reason": reason,
                "verdict": "claim_rejected_active_target_polarity",
            },
        )
    while rejected_names:
        next_kept: list[MiniSubgoalClaim] = []
        changed = False
        for claim in kept:
            tainted = [
                dep
                for dep in claim.dependencies
                if str(dep or "").strip() in rejected_names
            ]
            if not tainted:
                next_kept.append(claim)
                continue
            changed = True
            claim_name = str(claim.name or "").strip()
            if claim_name:
                rejected_names.add(claim_name)
            stats.plans_wrong_polarity_rejected += 1
            _record(
                record_event,
                {
                    "phase": "mini_recursive_plan_polarity",
                    "pass_index": pass_index,
                    "claim_name": claim.name,
                    "statement": claim.statement,
                    "dependencies": list(claim.dependencies),
                    "tainted_dependencies": tainted,
                    "active_targets": active_targets,
                    "verdict": "claim_rejected_active_target_polarity_dependency",
                },
            )
        kept = next_kept
        if not changed:
            break
    if len(kept) == len(plan.claims):
        return plan
    return dataclass_replace(plan, claims=tuple(kept))


def _filter_plan_unchecked_counterexample_routes(
    plan: MiniSubgoalPlan,
    *,
    active_root_targets: Sequence[Mapping[str, Any]],
    pass_index: int,
    record_event: Optional[RecordEvent],
    stats: MiniRecursiveStats,
    planner_feedback: list[str],
) -> MiniSubgoalPlan:
    """Reject decisive counterexample routes without checked polarity evidence."""

    if not plan.claims:
        return plan
    reason = _unchecked_counterexample_route_reason(
        plan,
        active_root_targets=active_root_targets,
    )
    if not reason:
        return plan
    stats.plans_unchecked_counterexample_rejected += len(plan.claims)
    _add_planner_feedback(
        planner_feedback,
        (
            "Rejected the previous recursive plan because it made an unchecked "
            "counterexample/refutation route decisive for an opaque "
            "`↔ *_solution` shell before any witness or negation had been "
            f"Lean-verified (`{reason}`). Counterexample search is allowed as "
            "a probe, but do not promote it to the only root route until the "
            "concrete witness itself has checked. Replan from the visible "
            "mathematical structure, or isolate a small concrete witness check "
            "without downstream claims that assert the root/solution side is "
            "False."
        ),
    )
    _record(
        record_event,
        {
            "phase": "mini_recursive_plan_counterexample_route",
            "pass_index": pass_index,
            "reason": reason,
            "claims_rejected": len(plan.claims),
            "verdict": "plan_rejected_unchecked_counterexample_route",
        },
    )
    return dataclass_replace(plan, claims=())


